window.ATLAS_I18N_LOR={"01IO012":["Disciplina delle lame gemelle","Fornisci +3|+0 o +0|+3 a un alleato per questo turno.","","\"Non temere il cambiamento. Ti metterà in discussione, spingerà i tuoi limiti. È il più grande dei maestri.\" - Karma","Incantesimo",[],["Ionia"],"COMUNE"],"01IO015":["Yasuo","Quando stordisci o richiami un nemico, io gli infliggo 2.","Hai stordito o richiamato 5+ unità.","\"La morte è come il vento...\"","Unità",[],["Ionia"],"Campione"],"01IO020":["Custode delle maschere","Quando vengo evocata, fornisci +1|+0 agli altri alleati per questo turno.","","\"Oggi il tuo diventerà il volto della disciplina, dell'abnegazione, dell'umiltà e dell'equilibrio. Oggi diventi una Kinkou.\"","Unità",[],["Ionia"],"COMUNE"],"01IO045":["Messaggero della primavera","Supporto: Fornisci Rubavita al mio alleato supportato per questo turno.","","\"Durante il regno dell'inverno sentimmo\nPassi sul manto innevato.\nSi lasciava alle spalle foglie e arbusti per cambiar\nLa foresta e annunciar la nuova stagione.\"\n- Poesia Shon-Xan","Unità",[],["Ionia"],"COMUNE"],"01IO008":["Spadaccina agguerrita","Quando stordisci o richiami un'unità, conferiscimi +2|+0.","","\"Ah, mi credi carina? Tenera? Vediamo se trovi adorabile anche QUESTO!\"","Unità",["YORDLE"],["Ionia"],"RARA"],"01IO040":["Lama vitale Kinkou","","","\"Un tempo qui c'erano le nostre scuole, i nostri templi, le nostre case. Ora siamo costretti a camminare tra rovine infestate dall'ombra. L'Ordine di Zed ha profanato questo luogo sacro. Li farò pentire.\"","Unità",[],["Ionia"],"COMUNE"],"01IO041":["Karma","Fine del turno: Crea nella mano un incantesimo casuale delle tue regioni.","Sei Illuminato.","\"Con la riflessione possiamo concentrare la mente e aggirare ogni ostacolo.\"","Unità",[],["Ionia"],"Campione"],"01IO011":["Richiamo","Richiama un alleato.","","Il saggio combattente sa quando la battaglia è persa. Una buona ritirata è la via verso una vittoria futura. ","Incantesimo",[],["Ionia"],"COMUNE"],"01IO009":["Zed","Attacca: Evoca 1 Ombra vivente attaccante con le mie statistiche.","Ho visto me stesso o le mie Ombre viventi alleate colpire il Nexus nemico due volte.","\"L'equilibrio è il padrone degli sciocchi. L'ombra mi ha mostrato il vero potere.\"","Unità",[],["Ionia"],"Campione"],"01IO014":["Anziano di Boscoverde","Quando vengo evocato, conferisci +1|+1 agli alleati nella tua mano.","","Il sapere ioniano è tramandato dai testi, ma sono i racconti e gli insegnamenti dei venerabili anziani a dargli nuova vita.","Unità",[],["Ionia"],"COMUNE"],"01IO005":["Poro agile","","","\"Potrebbe sembrare assurdo, ma l'ultima cosa che ricordo è... del soffice pelo?\" - Brigante di Navori","Unità",["PORO"],["Ionia"],"COMUNE"],"01IO044":["Cospiratore di Navori","Per giocarmi, richiama un alleato.","","\"Presto, dobbiamo andarcene! Come mi chiamo? Te lo spiegherò più tardi, promesso...\"","Unità",[],["Ionia"],"COMUNE"],"01IO023":["Protettore prezioso","Gioca: Conferisci +3|+3 a un alleato nella tua mano.","","\"In tempo di guerra, gli abitanti invocavano l'antica guardiana di Val d'Autunno. Coloro che smuovevano il suo cuore ricevevano benedizioni in grado di vincere una battaglia.\"\n- Saga delle Terre Antiche","Unità",[],["Ionia"],"RARA"],"01IO029":["Semi del Domani","Conferisci +1|+0 agli alleati nella tua mano.","","\"Non sono solo semi, bimbi miei. Sono l'eredità della terra, la promessa di un futuro di prosperità.\" - Karma","Incantesimo",[],["Ionia"],"RARA"],"01IO003":["Marchio della morte","Rimuovi lo stato Effimero da un alleato e conferiscilo a un nemico.","","\"Sono la lama dell'oscurità.\" - Zed","Incantesimo",[],["Ionia"],"RARA"],"01IO047":["Furia delle ombre","Conferisci Effimero a TUTTI i seguaci in battaglia.","","Quando i flussi della magia vengono deviati dal loro stato di equilibrio, sgorgano dal mondo degli spiriti in quello dei mortali, spesso con risultati spaventosi.","Incantesimo",[],["Ionia"],"EPICO"],"01IO026":["Mentore motivante","Gioca: Conferisci +1|+0 a un alleato nella tua mano.","","\"Ci sono voluti anni per plasmare questo fisico! Giorni infiniti a osservare gli uccelli, a descrivere le nuvole e a sollevare vassoi su vassoi di panini al vapore! Chi altro ha una simile dedizione?\"","Unità",[],["Ionia"],"COMUNE"],"01IO024":["Alba e crepuscolo","Evoca 2 copie esatte di un alleato. Sono Effimere.","","\"Shen è un uomo colto tra i pericoli di due mondi che saranno la sua fine. Io sono devoto solo a Ionia.\" - Zed","Incantesimo",[],["Ionia"],"RARA"],"01IO028":["Squamasauro","Gioca: Conferiscimi +3|+0 o +0|+3.","","Uno dei più vecchi abitanti di Boscoverde, sopravvissuto alla prova del tempo grazie alla sua capacità di adattarsi.","Unità",["RETTILE"],["Ionia"],"COMUNE"],"01IO057":["Assassina dell'ombra","Quando vengo evocata, pesca 1 carta.","","Con grazia si libra\nSilente nell'ombra\nGli artigli... la sua unica traccia.","Unità",[],["Ionia"],"COMUNE"],"01IO032":["Shen","Supporto: Fornisci Barriera al mio alleato supportato per questo turno.","Ho visto alleati ottenere Barriera 5 volte.","\"I reami dei mortali e dello spirito si stringono e si intrecciano come due mani...\" ","Unità",[],["Ionia"],"Campione"],"01IO013":["Demone delle tenebre","","","\"Cosa sacrificheresti per il potere? La trasformazione comincia con un giuramento firmato nella carne...\" - Zed","Unità",[],["Ionia"],"COMUNE"],"01IO018":["Scatto","Fornisci +1|+0 e Attacco rapido a un alleato per questo turno.","","Il combattimento è solo una gara a chi ruba per primo una vita.","Incantesimo",[],["Ionia"],"COMUNE"],"01IO056":["Yone, Cacciatore del Vento","Gioca: Stordisci 2 nemici.","","\"Quando ero piccolo, ho chiesto a mio fratello: –Il vento scappa o insegue? Mi seguiva per guidarmi. Io lo seguo per la giustizia.\"","Unità",[],["Ionia"],"RARA"],"01IO016":["Lungimirante dello Zefiro","Gioca: Crea una copia esatta di una carta nella tua mano, diversa da Lungimirante dello Zefiro.","","\"Mentre il guerriero piangeva per il suo lutto, l'anziano lo consolava: 'Cerca il saggio dei cieli. Solo lui può ridare ciò che è perso in questo mondo, ma che ancora risiede nei ricordi.'\"\n- Saga delle Terre Antiche","Unità",["VOLATILE"],["Ionia"],"RARA"],"01IO036":["Vedetta di Boscoverde","Colpisci: Riduci di 1 il costo dell'unità più costosa che hai in mano.","","\"Pattuglia, abbiamo una... Anzi DUE enormi creature pelose in arrivo! Chiamate i rinfo... oh. Un momento. Avevo puntato il cannocchiale dalla parte sbagliata...\"","Unità",["YORDLE"],["Ionia"],"COMUNE"],"01IO033":["Minah Piè veloce","Gioca: Richiama 3 nemici.","","\"Stavamo attraversando il prato, quando all'improvviso è spuntata dal nulla una ragazzina, e BAM, BAM, BAM... ci ha stesi tutti!\" - Brigante di Navori","Unità",[],["Ionia"],"EPICO"],"01IO001":["Rito del rinnovamento","Cura un alleato o il tuo Nexus di 4. Pesca 1 carta.","","\"Solo quando la mente si eleva il corpo è una cosa sola.\" \n- Karma","Incantesimo",[],["Ionia"],"RARA"],"01IO010":["Uniti nelle difficoltà","Scambia 2 alleati. Fornisci loro Barriera per questo turno.","","\"Cammino con passi misurati.\" - Shen\n","Incantesimo",[],["Ionia"],"RARA"],"01IO022":["Spettralità","Fornisci Elusione a un alleato per questo turno.","","\"Va', non farti scoprire... e non tornare finché non sarà finita.\" - Zed","Incantesimo",[],["Ionia"],"COMUNE"],"01IO021":["Cucciolo di Solcavento","Quando vengo evocato, fornisci +2|+2 agli altri alleati per questo turno.","","\"La primavera sboccia sui colli ioniani, dove il battito delle neonate ali sfiora le acque, cullato dalla dolce brezza.\"\n- Saga delle Terre Antiche","Unità",[],["Ionia"],"EPICO"],"01IO054":["Sapere dell'eternità","Crea nella mano un altro incantesimo casuale delle tue regioni.\nIlluminato: Creane 2.","","\"Quando la speranza vacilla, sappi che non siamo mai soli. Il passato è sempre al nostro fianco. Ha conosciuto una miriade di domani e conosce la speranza che racchiudono.\" - Karma","Incantesimo",[],["Ionia"],"RARA"],"01IO027":["Veggente dell'ombra silente","Colpisci il Nexus: Crea una mia copia nella tua mano.","","\"La carne è fragile, inaffidabile. Delicata come il confine tra luce e ombra.\"","Unità",[],["Ionia"],"EPICO"],"01IO031":["Bevitore delle nuvole","I tuoi incantesimi con Raffica e Concentrazione costano 1 in meno.","","Il suo canto si udiva dal villaggio, con lunghe e basse onde di suono che scrosciavano dal cielo ai colli, strane e informi come le nubi del pomeriggio.","Unità",[],["Ionia"],"RARA"],"01IO002":["Volontà di Ionia","Richiama un'unità.","","Quando gli invasori misero piede in territorio ioniano, scoprirono che conquistare la terra e i suoi abitanti non sarebbe bastato.","Incantesimo",[],["Ionia"],"COMUNE"],"01IO017":["Lamalesta di Navori","Quando vengo evocato, forniscimi Elusione per questo turno.","","\"Lo troverò, non c'è problema. Portami là e dividerò il bottino con te. Ne varrà la pena, vedrai!\"","Unità",["YORDLE"],["Ionia"],"COMUNE"],"01IO042":["Apprendista in Allenamento","Quando evochi un altro alleato, forniscimi +1|+1 per questo turno.","","\"Che senso ha combattere, se nessuno può vedere le tue mosse?\"","Unità",[],["Ionia"],"COMUNE"],"01IO006":["Duo di Boscoverde","Quando evochi un altro alleato, forniscimi +1|+0 per questo turno.","","\"Ehi, occhio a quei rami! Sinistra, SINISTRA!\" \"Quando sarò io sulle tue spalle, palla di pelo, potremo andare dove vuoi. Fino ad allora, decido io!\"","Unità",[],["Ionia"],"RARA"],"01IO050":["Guida Kinkou","Fedeltà: Evoca un alleato di costo 1 dal tuo mazzo.","","Ovunque lei vada, fa in modo che gli altri la possano seguire.","Unità",[],["Ionia"],"RARA"],"01IO048":["Yusari","","","\"Il tuo ordine ci ha cacciato dalle nostre terre. Hai dimostrato il tuo potere, maestro Zed. Ora lascia che ti dimostri che anch'io sono degno dei tuoi insegnamenti.\"","Unità",[],["Ionia"],"RARA"],"01IO007":["Ren Lama d'ombra","Colpisci: Crea 1 Demone delle tenebre nella tua mano.","","\"Scappa. Combatti. Riparati. Fai quel che vuoi, ma le ombre sono qui per te.\"","Unità",[],["Ionia"],"EPICO"],"01IO053":["Smeraldovivo","Illuminato: Ho +4|+4.","","\"La guerra è alimentata dai nostri istinti più bassi. Ma l'istinto non ha potere sulle nostre virtù: fiducia, pazienza e contemplazione.\"","Unità",[],["Ionia"],"COMUNE"],"01IO004":["Pozione di salute","Cura un alleato o il tuo Nexus di 3.","","Ogni generazione, regione e famiglia ha i propri rimedi abituali. Tuttavia, alcuni sono senza dubbio più efficaci di altri.","Incantesimo",[],["Ionia"],"COMUNE"],"01IO049":["Negazione","Blocca un incantesimo Veloce, un incantesimo Lento o un'abilità.","","No.","Incantesimo",[],["Ionia"],"RARA"],"01IO052":["Bandito di Navori","Quando vengo evocato, evoca 1 Brigante di Navori con le mie statistiche.","","\"Ero un musicista noto in ogni villaggio da qui al Placidium, prima che arrivassero i noxiani. Ora tiro avanti rubando gli spiccioli. Aveva ragione la mamma, dovevo fare il guaritore...\"","Unità",[],["Ionia"],"COMUNE"],"01IO030":["L'Empireo","","","\"Il cielo si infuriò e turbini di nuvole e vento schiacciarono la nostra brigata. Provammo a seguirlo, ma chi può rincorrere il vento?\" - Generale della Legione","Unità",["DRAGO"],["Ionia"],"EPICO"],"01IO019":["Guardiana di Boscoverde","Quando un alleato ottiene Barriera, conferiscimi +2|+0.","","\"La radura protegge i suoi. E tu... tu non sei di qui...\"","Unità",[],["Ionia"],"COMUNE"],"01IO046":["Tempesta d'acciaio","Stordisci un nemico attaccante.","","\"Hasagi!\" - Yasuo","Incantesimo",["ELEMENTALE"],["Ionia"],"RARA"],"01IO037":["Rifugio spirituale","Fornisci Barriera e Rubavita a un alleato per questo turno.","","\"Questa lama apparteneva a mio padre. Che possa darti la forza che un tempo mi mancò.\" - Shen","Incantesimo",[],["Ionia"],"COMUNE"],"01IO043":["Dominatore del fiume","Colpisci: Pesca un incantesimo.","","\"Siamo i fieri figli delle Terre Antiche, e i flussi della loro magia ora scorrono nel nostro sangue vastayano, così come scorrono nel nostro regno.\"","Unità",[],["Ionia"],"RARA"],"01IO038":["Asceta Solitaria","Gioca: Richiama tutti gli altri alleati.","","\"Riflessi e istinto sono gli unici compagni che desidero.\"","Unità",[],["Ionia"],"RARA"],"01IO039":["Passo dell'ombra","Richiama un alleato per evocare 1 Ombra vivente al suo posto.","","Affronti il nemico che credi di vedere? O è l'inganno delle ombre?","Incantesimo",[],["Ionia"],"COMUNE"],"01IO055":["Guardiano del Ki","Conferisci Barriera a un alleato nella tua mano.\nPesca 1 carta.","","\"Chi mantiene l'equilibrio conoscerà la protezione dei Kinkou.\" - Shen\n","Incantesimo",[],["Ionia"],"COMUNE"],"01NX020":["Draven","Quando vengo evocato o colpisco: Crea 1 Ascia rotante nella tua mano.","Ho colpito con un totale di 2+ Asce rotanti.","\"Vuoi un autografo? Mettiti in fila.\"","Unità",[],["Noxus"],"Campione"],"01NX006":["Vladimir","Gioca: Infliggi 1 a un qualsiasi numero di alleati per infliggere la stessa quantità di danni a un nemico.","Hai visto 5+ alleati sopravvivere ai danni.","Feroce. Freddo. Crudele. Intrigante. Attento. Affascinante.\nIrresistibile...","Unità",[],["Noxus"],"Campione"],"01NX004":["Colpo letale","Uccidi un'unità con 3 o meno Potere.","","Tutti muoiono. Alcuni prima di altri.","Incantesimo",[],["Noxus"],"RARA"],"01NX048":["Curatore Cremisi","Quando sopravvivo ai danni, crea un'unità Cremisi casuale nella tua mano.","","\"Amati compagni!\" \"Ci sei mai stato? Beh, ho ricevuto un invito.\" \"—Ballo dei Gaudenti! Sì!\" \"Allora dobbiamo andarci! Ti presenterò la mia famiglia.\" \"Antipasti prima del dolce, mia cara. E tu, Kye? Ci sarai?\"","Unità",[],["Noxus"],"COMUNE"],"01NX038":["Darius","","Vedo che il Nexus nemico ha la metà della sua Salute iniziale o meno.","\"Volontà di ferro e forza da titano. Non c'è generale migliore per la Legione Trifariana.\" - Swain\n","Unità",[],["Noxus"],"Campione"],"01NX023":["Orda aracnide","Quando vengo evocata, conferisci +2|+0 agli altri alleati Ragno.","","Un singolo sguardo e sei suo. Un singolo morso e sei loro.","Unità",["RAGNO"],["Noxus"],"RARA"],"01NX013":["Stratagemma decisivo","Stordisci un nemico. Fornisci +2|+0 agli alleati per questo turno.","","\"Non ci vuole un genio per soverchiare il nemico con la forza. È per nascondere la forza fino all'ultimo momento che ci vuole una visione.\" - Swain","Incantesimo",[],["Noxus"],"RARA"],"01NX046":["Sentinella aracnide","Gioca: Stordisci un nemico.","","\"Oh, quanto mi piace! Quelle gambe senza fine, quella dolcezza paralizzante nella voce, quegli occhi rossi come una rosa. E pensare che ha deciso di cenare con me, questa sera!\" \n- Nobile sventurato","Unità",["RAGNO"],["Noxus"],"COMUNE"],"01NX047":["Trasfusione","Infliggi 1 a un alleato e fornisci +2|+2 a un altro alleato per questo turno.","","\"C'è chi dà e c'è chi prende. Tu dai, io prendo.\" - Vladimir","Incantesimo",[],["Noxus"],"COMUNE"],"01NX040":["Sabotatrice della Legione","Attacca: Infliggi 1 al Nexus nemico.","","\"I nostri Spaccascudo sono in grado di tagliare in due un uomo. Ma la Legione ha altri talenti a disposizione, quando ci vuole... un tocco più discreto.\" - Swain","Unità",[],["Noxus"],"COMUNE"],"01NX025":["Legame fraterno","Conferisci +2|+0 a due alleati.","","\"Nella guerra si creano legami forti come la fratellanza. In entrambi i casi c'è di mezzo il sangue.\" - Veterano della Legione","Incantesimo",[],["Noxus"],"COMUNE"],"01NX055":["Ragno domestico","Quando vengo evocato, evoca 1 Ragnetto.","","\"I miei ragnetti amano la compagnia. È un peccato che non vengano ricambiati.\" - Elise","Unità",["RAGNO"],["Noxus"],"COMUNE"],"01NX030":["Adepta Cremisi","Quando sopravvivo ai danni, infliggi 1 al Nexus nemico.","","\"Edvin! Eccoti, bello! Proprio a te pensavo!\" \"E allora possiamo andare.\" \"Reggimi e scortami, su. Ci sarà da divertirsi.\" \"O magari no?\"","Unità",[],["Noxus"],"RARA"],"01NX007":["Annunciatore dell'Arena","Attacca: Fornisci +1|+0 agli altri alleati attaccanti per questo turno.","","Ruggì di gioia, perché in quel momento il cuore dell'arena batteva a tempo col suo. Aveva in pugno l'emozione della folla.","Unità",[],["Noxus"],"RARA"],"01NX021":["Predone della Legione","Attacca: Conferisci +1|+1 a tutti i Predoni della Legione alleati ovunque.","","La Legione Trifariana è seguita da briganti opportunisti, che colpiscono i feriti e i deboli che si lascia alle spalle.","Unità",[],["Noxus"],"COMUNE"],"01NX009":["Beniamino della folla","Quando vengo evocato, conferiscimi +1|+1 per ogni altro alleato che possiedi.","","Alcuni gladiatori sono adorati per il loro carisma, altri per la loro tecnica. Vessid non ha nessuna delle due cose, ma quando si tratta di maciullare un avversario non lo batte nessuno.","Unità",[],["Noxus"],"RARA"],"01NX011":["Morte turbinante","Un alleato in battaglia colpisce un nemico in battaglia.","","\"Io amo il mio lavoro.\" -Draven","Incantesimo",[],["Noxus"],"COMUNE"],"01NX053":["Resa dei conti","Se hai un alleato con 5+ Potere, uccidi TUTTE le unità con 4 o meno Potere.","","\"CHI È PRONTO PER LA RESA DEI CONTI?\" \n- Annunciatore dell'Arena","Incantesimo",[],["Noxus"],"EPICO"],"01NX054":["Ruggito intimidatorio","Stordisci tutti i nemici con 4 o meno Potere.","","\"Sta prendendo fiato... potremmo assistere a... sì, eccolo qui, gente! Il famoso urlo da guerra del Tuono! Non vediamo l'ora, Tuoonooo!\" - Annunciatore dell'Arena","Incantesimo",[],["Noxus"],"RARA"],"01NX029":["Veterano della Legione","Quando un altro alleato sopravvive ai danni, conferiscigli +1|+0.","","È tornato dalla guerra sull'orlo della morte, dove è stato salvato solo dal tocco del marito e dagli unguenti del guaritore. Dopo i tanti anni di servizio, Noxus non ha badato a spese per farlo curare al meglio.","Unità",[],["Noxus"],"EPICO"],"01NX014":["Shiraza la Lama","Infliggo danni doppi al Nexus.","","\"Cos'ha detto? Quello ha i mattoni nel cervello. Quelle spalle, in compenso...\"","Unità",[],["Noxus"],"EPICO"],"01NX042":["Katarina","Quando vengo evocata, crea 1 Filo della lama Fugace nella tua mano.","Ho colpito una volta. Quando aumento di livello, richiamami.","\"Niente di meglio di un piccolo bersaglio demaciano per affilare i sensi...\"","Unità",[],["Noxus"],"Campione"],"01NX051":["Capitan Farron","Quando vengo evocato, crea 2 Decimare nella tua mano.","","Nel profondo del Sump di Zaun, il giovane Benn Farron era considerato una minaccia. Instabile, inaccettabile. Nei ranghi di Noxus è stato apprezzato. Premiato, perché inarrestabile.","Unità",[],["Noxus"],"EPICO"],"01NX012":["Retroguardia della Legione","","","A Noxus, dove i soldati sono riveriti per l'audacia in battaglia, il lavoro di retroguardia è una vera e propria punizione.","Unità",[],["Noxus"],"COMUNE"],"01NX043":["Filo della lama","Infliggi 1 a un bersaglio.","","\"Una lama può tagliare qualsiasi cosa, se sai come fare... e intendo qualsiasi cosa.\" - Katarina","Incantesimo",[],["Noxus"],"COMUNE"],"01NX037":["Granatiere della Legione","Ultimo respiro: Infliggi 1 al Nexus nemico.","","A Noxus si insegna che una vita al servizio dell'impero è una vita ben spesa, ma pochi vivono in modo spettacolare come i Granatieri della Legione.","Unità",[],["Noxus"],"COMUNE"],"01NX010":["Generale della Legione","Quando vengo evocato, conferiscimi +1|+1 per ogni unità che hai stordito o che hai richiamato in questa partita.","","Ogni noxiano conosce i tre Principi della forza, ma i soldati che vogliono fare carriera devono interiorizzarli completamente.","Unità",[],["Noxus"],"COMUNE"],"01NX017":["Tamburina della Legione","Supporto: Fornisci Attacco rapido al mio alleato supportato per questo turno.","","La Legione espande i confini dell'impero con ogni colpo di tamburo. Niente la può fermare. Nessuno ce l'ha mai fatta.","Unità",[],["Noxus"],"COMUNE"],"01NX003":["Allibratore dell'Arena","Inizio del turno: Scarta la tua carta dal costo più basso per pescare 1 carta.","","\"Hai scommesso su Shiraza come UNICA SOPRAVVISSUTA, e quel ragazzino ioniano... certo, gli manca un braccio, ma non è morto. Conta come sopravvissuto, capisci? Ovviamente puoi recuperare raddoppiando...\"","Unità",["YORDLE"],["Noxus"],"RARA"],"01NX039":["Visione","Quando questo incantesimo viene giocato o scartato, conferisci +1|+0 agli alleati.","","\"Chi non vede il futuro non ha diritto di farne parte.\" - Jericho Swain","Incantesimo",[],["Noxus"],"RARA"],"01NX041":["Spaccascudo Trifariano","","","\"Non ho tempo per un assedio. Mandate gli Spaccascudo.\" \n- Darius","Unità",[],["Noxus"],"COMUNE"],"01NX036":["Gladiatore Minotauro","Inizio del turno: Stordisci il nemico più debole.","","\"Non mi interessa chi ti abbia fatto un torto o cosa ti abbiano fatto. Se vuoi vendicarti nell'arena, paga subito. Niente sconti per le storie strappalacrime.\"","Unità",[],["Noxus"],"RARA"],"01NX044":["Ariete d'assedio","Attacca: Conferiscimi +4|+0.","","\"Signore, si rifiutano di aprire i cancelli. Esigono di parlare con Darius, ma è a due giorni di cavalcata. Mandiamo i nostri cavalieri?\"\n\"Oh, non sarà necessario.\"","Unità",[],["Noxus"],"EPICO"],"01NX005":["Nobile Cremisi","Gioca: Infliggi 1 a un alleato e conferiscigli +1|+0 e Sopraffare.","","\"Ah, anche tu? Al Ballo dei Gaudenti...\" \"Come posso tollerare il mio?\" \"Rispettosamente, mia cara, mio padre mi rinnegherebbe ... forse dovremmo indossare abiti coordinati.\"","Unità",[],["Noxus"],"COMUNE"],"01NX016":["Aspirante Trifariano","Quando vengo evocato, conferiscimi +2|+0 se hai un altro alleato di Noxus.","","\"Avrai il titolo quando la battaglia avrà tolto il filo alla tua ascia e i tuoi stivali saranno rossi come il sangue.\" - Veterano della Legione","Unità",[],["Noxus"],"COMUNE"],"01NX019":["Potenza","Fornisci a un alleato +3|+0 e Sopraffare per questo turno.","","\"Quando dico che la sottigliezza è sopravvalutata, non dico che non vada bene. Dico solo che è sopravvalutata.\" - Darius","Incantesimo",[],["Noxus"],"COMUNE"],"01NX015":["Animaletto prediletto","","","Sono tutti i suoi preferiti. Ma questo è il suo più preferito.","Unità",["RAGNO"],["Noxus"],"COMUNE"],"01NX050":["Loto mortale","Infliggi 1 a TUTTE le unità in battaglia.","","\"Balla con me.\" - Katarina","Incantesimo",[],["Noxus"],"RARA"],"01NX056":["Shunpo","Infliggi 2 a un nemico, poi prepara l'assalto.","","Quando vedi la lama, è già troppo tardi.","Incantesimo",[],["Noxus"],"COMUNE"],"01NX033":["Esperta Trifariana","Quando vengo evocata, pesca 1 carta per ogni alleato che possiedi con 5+ Potere.","","\"Ci vuole un occhio attento per selezionare chi ha la stoffa per entrare nella Legione Trifariana, ma lei sa distinguere le pecore dai lupi a chilometri di distanza.\" - Generale della Legione","Unità",[],["Noxus"],"RARA"],"01NX052":["Sangue per sangue","Infliggi 1 a un seguace alleato. Se sopravvive, crea una sua copia nella tua mano.","","Non c'è niente di più sanguinoso della prima lezione di un emomante.","Incantesimo",[],["Noxus"],"COMUNE"],"01NX045":["Gladiatore brutale","","","\"E ora, ARTIGLIO! L'ultima volta abbiamo visto un SANGUINOSO abbattimento contro i Cinque Folli... ora noti come Tre Folli. Molto bene! Accetto scommesse sulla vittima di oggi! Quattro a uno!\" - Karl, Allibratore dell'Arena","Unità",[],["Noxus"],"RARA"],"01NX031":["Trifariana Assetata di Gloria","","","Ottenere un posto nella Legione Trifariana è un traguardo che soddisfa i più, ma c'è chi non si accontenta.","Unità",[],["Noxus"],"RARA"],"01NX002":["Decimare","Infliggi 4 al Nexus nemico.","","\"A volte ci vuole un genio tattico per distruggere una fortezza. Altre volte basta colpirla con violenza.\" - Darius","Incantesimo",[],["Noxus"],"RARA"],"01NX008":["Cavaliere del Basilisco","Fedeltà: Conferiscimi +1|+1 e Sopraffare.","","Questa particolare unità usa i cavalli, ma non per cavalcarli. Le bestie li trovano deliziosi.","Unità",[],["Noxus"],"RARA"],"01NX034":["Poro affettuoso","","","\"A Noxus non c'è spazio per... per la debol... Qualcuno mi TOGLIE QUESTO COSO DI DOSSO?\" - Darius","Unità",["PORO"],["Noxus"],"COMUNE"],"01NX035":["Superfan di Draven","Quando vengo evocato, sposta Draven in cima al tuo mazzo se non lo hai già in mano o in gioco.","","\"Vuoi un autografo? Su... Mettiti in fila.\"","Unità",[],["Noxus"],"COMUNE"],"01NX026":["Trifariano temerario","","","\"L'imprudenza è un difetto. Con la Legione diventa uno strumento.\" - Swain","Unità",[],["Noxus"],"COMUNE"],"01NX027":["Elisir dell'ira","Fornisci +3|+0 a un alleato per questo turno.","","\"Quando la mano tesa viene rifiutata, poi viene il pugno.\"\n- Assioma noxiano","Incantesimo",[],["Noxus"],"COMUNE"],"01NX022":["Ghigliottina di Noxus","Uccidi un'unità danneggiata per creare 1 Ghigliottina di Noxus Fugace nella tua mano.","","Per Darius, la pietà è un colpo netto e deciso.","Incantesimo",[],["Noxus"],"RARA"],"01NX032":["Risvegliatore Cremisi","Quando vengo evocato, infliggi 1 a tutti gli altri alleati.","","\"Anche se dicessi di no, mi trascineresti. Quindi... va bene.\"","Unità",[],["Noxus"],"RARA"],"01NX024":["Kato il Braccio destro","Supporto: Fornisci Sopraffare e +3|+0 al mio alleato supportato.","","\"Shiraza è una compagna fantastica, intendo amica, perché non stiamo assolutamente uscendo insieme. Tuttavia, se uscissi con lei, vorrei augurarle buon anniversario. Grazie, questa era l'ultima domanda.\"","Unità",[],["Noxus"],"EPICO"],"01NX049":["Astuzia","Stordisci un nemico.","","\"Lascia abbastanza corda al nemico e si impiccherà da solo.\" - LeBlanc","Incantesimo",[],["Noxus"],"COMUNE"],"01DE031":["Oratori dell'alba","Fine del turno: Conferisci +1|+1 agli altri alleati se è morto un alleato durante questo turno.","","\"Il male ha vinto una battaglia, ma non la guerra. Celebriamo i nostri caduti, che il loro ricordo sia la vostra corazza!\"","Unità",[],["Demacia"],"EPICO"],"01DE022":["Lucian","","Ho visto 4+ alleati o una Senna alleata morire.","\"Andrà tutto bene, Senna, finché sei al mio fianco.\"","Unità",[],["Demacia"],"Campione"],"01DE019":["Leva","Riduci di 1 il costo degli alleati nella tua mano.","","\"Dai campi alla prima linea in due settimane. Ecco cosa ci aspettiamo da ogni demaciano in salute.\" - Garen","Incantesimo",[],["Demacia"],"RARA"],"01DE042":["Lux","","Ti ho visto spendere 6+ mana giocando incantesimi. Quando aumento di livello, crea 1 Scintilla finale nella tua mano.","\"Ho sempre saputo di avere qualcosa di diverso... una luce interiore. Non so cosa sia, ma lo scoprirò!\" ","Unità",[],["Demacia"],"Campione"],"01DE010":["Lanciere Ala lesta","Ultimo respiro: Crea un'unità Élite casuale nella tua mano.","","\"Ci vuole un cuore coraggioso per affidare la propria vita a un'ala d'argento, lottando ad alta quota. Un cuore coraggioso e resistente.\" - Garen","Unità",["ÉLITE","VOLATILE"],["Demacia"],"RARA"],"01DE020":["Difensore dell'Avanguardia","","","\"Non sapevamo chi o cosa fossero quelle creature. Sapevamo chi erano i soldati al nostro fianco e non ci serviva altro.\"","Unità",["ÉLITE"],["Demacia"],"COMUNE"],"01DE034":["Fabbro della guerra","Quando evochi un'unità Élite, conferiscile +1|+1.","","Le guerre si vincono nelle fucine.","Unità",[],["Demacia"],"RARA"],"01DE002":["Tianna Crownguard","Quando vengo evocata, prepara l'assalto.","","\"La nostra casata ha sofferto per questo regno. Non getterai alle ortiche l'onore della famiglia per qualche trucchetto di luce.\"","Unità",[],["Demacia"],"EPICO"],"01DE012":["Garen","Quando vengo evocato, fornisci +1|+1 agli altri alleati per questo turno","Ho colpito due volte.","Addestramento e resilienza sono la via del soldato. Anche davanti al più grande pericolo, non ci arrenderemo.","Unità",["ÉLITE"],["Demacia"],"Campione"],"01DE017":["Eroe Solitario","Se hai esattamente 1 alleato, conferiscigli +3|+3.","","Quando gli altri falliscono, sta ai veri eroi trovare la via verso la vittoria.","Incantesimo",[],["Demacia"],"RARA"],"01DE045":["Fiora","","Ho ucciso 2 nemici.","\"Dalle arene ai tornei, dai campi di addestramento a quelli di battaglia, cerco un degno avversario. Non avrò pace finché non saprò di essere la più grande.\"","Unità",[],["Demacia"],"Campione"],"01DE052":["Formazione di Brillacciaio","Quando vengo evocato o attacco: Fornisci Barriera agli alleati per questo turno.","","\"Questa formazione è la base della nostra tattica. Richiede la fede di ogni soldato nel suo scudo e in quelli dei suoi compagni. Finché resistono i soldati, resisterà anche il nostro regno.\" - Garen\n","Unità",[],["Demacia"],"EPICO"],"01DE021":["Determinazione","Prepara l'assalto.",""," \"Tutti devono affrontare le loro paure. Per tua fortuna, ci sono qua io.\" - Lucian\n","Incantesimo",[],["Demacia"],"COMUNE"],"01DE025":["Incarcerazione","Un alleato cattura un'unità.","","\"Inchinatevi a noi. Siamo la legge e voi i sudditi. Non c'è altro da aggiungere.\" - Persuasore dei Cercatori di magia","Incantesimo",[],["Demacia"],"COMUNE"],"01DE007":["Giudizio","Un alleato in battaglia colpisce tutti i nemici in battaglia.","","La giustizia non sbaglia mai.","Incantesimo",[],["Demacia"],"EPICO"],"01DE055":["Duellante dei Laurent","Gioca: Conferisci Sfidante a un alleato in mano.","","\"Sembrava un damerino agghindato con una spada costosa, ma era uno schermidore provetto! Gli chiederei una rivincita, ma con quello stupido accento non ho capito il suo nome.\" - Guardia demaciana","Unità",[],["Demacia"],"COMUNE"],"01DE048":["Istigatore dei Cercatori di magia","Conferiscimi +2|+2 dopo aver giocato un incantesimo di costo 6+ in questa partita.","","\"Tempo fa, la magia selvaggia della Guerra delle Rune ha ridotto in ginocchio Runeterra. Per questo, il nostro ordine è nato per proteggere il regno, liberandolo dalla magia.\" \n- Manuale dei Cercatori di magia","Unità",[],["Demacia"],"RARA"],"01DE001":["Stendardo dell'Avanguardia","Fedeltà: Conferisci +1|+1 agli altri alleati.","","\"Devi capire il peso del nostro stendardo. Garrisce per il nostro re, le nostre casate, i nostri cittadini. È la nostra fede incrollabile in Demacia. Tienilo alto. Che vedano il nostro orgoglio.\" - Tianna Crownguard ","Unità",["ÉLITE"],["Demacia"],"RARA"],"01DE043":["Cuochi di guerra","Supporto: Fornisci +1|+1 al mio alleato supportato per questo turno.","","Nell'esercito di Demacia non c'è nessuno da sottovalutare.","Unità",[],["Demacia"],"COMUNE"],"01DE049":["Poro impavido","","","\"La nuova recluta ha la resistenza e il coraggio dei nostri migliori soldati. Riuscirà a entrare nell'Avanguardia, un giorno? È... più piccolo degli altri, ma si vedrà.\" - Sergente dell'Avanguardia","Unità",["PORO"],["Demacia"],"COMUNE"],"01DE053":["Chevalier dei Laurent","Colpisci: Crea nella mano un altro seguace Sfidante casuale delle tue regioni.","","\"Santo cielo.\" - Fiora","Unità",[],["Demacia"],"EPICO"],"01DE033":["Ricordo","Costo 1 in meno per ogni alleato morto in questo turno. Evoca un seguace casuale di costo 5 di Demacia.","","\"Oggi ci eleviamo per combattere l'ingiustizia che ha ucciso i nostri predecessori. Il sacrificio dei nostri compagni non sarà invano.\" - Guardiana Radiosa","Incantesimo",[],["Demacia"],"RARA"],"01DE044":["Doppio valore","Cura completamente un alleato, poi raddoppia il suo Potere e la sua Salute.","","A Demacia, dire di valere come due dei nemici non è un vanto.","Incantesimo",[],["Demacia"],"RARA"],"01DE024":["Custode dei Cercatori di magia","Ultimo respiro: Crea nella mano un incantesimo casuale di costo 6+ di una regione diversa da Demacia.","","\"Gli oggetti arcani hanno un fascino innegabile. Ma questi oggetti vanno lasciati alle mani dei nostri esperti e tenuti alla larga dalla benintenzionata ignoranza dei nostri cittadini.\"\n- Manuale dei Cercatori di magia","Unità",[],["Demacia"],"COMUNE"],"01DE004":["Avanguardia Ala d'argento","Gioca: Evoca una mia copia esatta.","","Sono caduti dal cielo come lampi d'argento, rapidi e sicuri, verso i loro bersagli. Poi sono spariti all'improvviso, proprio come erano apparsi. ","Unità",["ÉLITE","VOLATILE"],["Demacia"],"COMUNE"],"01DE011":["Protetto dei Laurent","","","\"Cosa ha fatto? Gli ho affidato l'inestimabile sciabola a doppio bilanciamento di Pierre de Guillard! Ha detto che l'avrebbe usata solo per allenarsi!\" - Guardiaspada dei Laurent","Unità",[],["Demacia"],"COMUNE"],"01DE047":["Successione","Evoca 1 Indomita Avanguardia.","","I paramenti dell'Indomita Avanguardia vengono tramandati da soldato a soldato, in modo che le nuove reclute avvertano il peso e l'orgoglio della loro responsabilità.","Incantesimo",[],["Demacia"],"COMUNE"],"01DE046":["Vedetta dell'Avanguardia","","","Il fatto che sia tutto tranquillo non vuol dire che siamo al sicuro.","Unità",["ÉLITE"],["Demacia"],"COMUNE"],"01DE050":["Purificare","Silenzia un seguace.","","\"Il vostro Marchio grigio è la prima difesa contro la magia. È un simbolo delle nostre responsabilità, ma anche della nostra autorità. Onoratelo più di ogni altra cosa.\"\n- Manuale dei Cercatori di magia","Incantesimo",[],["Demacia"],"COMUNE"],"01DE040":["Persuasore dei Cercatori di magia","Conferiscimi +1|+1 e Sfidante dopo aver giocato un incantesimo di costo 6+ in questa partita.","","\"Cittadini di Demacia, proteggervi è un onore. Dobbiamo però chiedervi il vostro supporto incondizionato, perché persino tra le mura della città si nascondono dei maghi!\"\n","Unità",[],["Demacia"],"RARA"],"01DE036":["Scudiera dell'Avanguardia","Quando evochi un'unità Élite, riduci il mio costo di 1.","","\"Tutte le persone che ho incontrato e ogni viaggio che ho fatto mi hanno insegnato qualcosa. Più imparavo e più diventavo forte e più ho capito che dovevo spingermi oltre.\" \n- Cithria, Scudiera dell'Avanguardia\n","Unità",["ÉLITE"],["Demacia"],"COMUNE"],"01DE037":["Contrattacco","Fornisci a un alleato +3|+0 e Barriera per questo turno.","","\"Molto appropriato. Combatti come un poro!\" - Fiora","Incantesimo",[],["Demacia"],"RARA"],"01DE014":["Rinforzi","Evoca 2 Indomita Avanguardia, poi conferisci +1|+1 alle unità Élite alleate.","","\"I nostri rivali sanno che colpire uno di noi è come colpirci tutti.\"\n- Codice dell'Avanguardia\n","Incantesimo",[],["Demacia"],"RARA"],"01DE015":["Guardiana Radiosa","Quando vengo evocata, conferiscimi Rubavita e Tenacia se è morto un alleato durante questo turno.","","\"Ondate di fredde mani non morte avevano abbattuto i suoi compagni. Rimaneva solo lei, come un faro di luce e giustizia, la cui lama cantava il nome dei caduti a ogni colpo.\" - Guardia demaciana","Unità",[],["Demacia"],"RARA"],"01DE003":["Guardiaspada dei Laurent","Gioca: Conferisci +2|+2 a un alleato.","","\"Sì, sono una meraviglia. Ma come i migliori strumenti, rivelano la loro bellezza solo nelle mani di un maestro.\" ","Unità",[],["Demacia"],"RARA"],"01DE026":["Singolar tenzone","Un alleato e un nemico si colpiscono a vicenda.","","\"Niente chiacchiere: qui si parla con le spade.\" - Fiora","Incantesimo",[],["Demacia"],"COMUNE"],"01DE032":["Barriera prismatica","Fornisci Barriera a un alleato per questo turno.","","\"Il mondo è capace di voltarti le spalle quando sei diverso. Ti diranno che la differenza è una debolezza, ma in realtà ci rende più forti e caritatevoli. Ti proteggerò anche nei momenti più bui!\" - Lux","Incantesimo",[],["Demacia"],"COMUNE"],"01DE027":["En garde","Fornisci Sfidante agli alleati per questo turno.","","\"Non esiste demaciano che rifiuterebbe una lezione di spada da un Laurent. Né uno che ne uscirebbe vivo, del resto.\"\n- Fiora","Incantesimo",[],["Demacia"],"RARA"],"01DE006":["Sergente dell'Avanguardia","Quando vengo evocato, crea 1 Per Demacia! nella tua mano.","","\"Ci guida negli addestramenti da mattina a sera, ed è sempre il primo a gettarsi nella mischia. Duro come il ferro e solido come la pietra. Non potevamo scegliere un capo migliore.\" - Guardia demaciana","Unità",["ÉLITE"],["Demacia"],"RARA"],"01DE038":["Senna, Sentinella della Luce","La prima volta che un Lucian alleato muore, conferiscimi +1|+1 e Attacco doppio.","","\"Le nostre Sentinelle sono la prima linea di difesa tra le ondate irrequiete di non morti e i regni dell'uomo. Colpiamo per primi, duramente, e non ci arrendiamo MAI quando ci sono in gioco le vite dei compagni.\"","Unità",[],["Demacia"],"RARA"],"01DE041":["Fianco a fianco","Fornisci +3|+3 a due alleati per questo turno.","","\"Coprimi, io vado!\"\n\"Strano, stavo per dirti la stessa cosa.\"\n- Lorn e Dax del battaglione orientale","Incantesimo",[],["Demacia"],"RARA"],"01DE035":["Per Demacia!","Fornisci +3|+3 agli alleati per questo turno.","","\"È la nostra casa, la nostra famiglia, i nostri fratelli d'armi. Il nostro orgoglio, il nostro onore, la nostra forza. Per questo oggi, combattendo per difenderla, urliamo il suo nome: DEMACIA!\" - Sergente dell'Avanguardia","Incantesimo",[],["Demacia"],"RARA"],"01DE018":["Colpo splendente","Fornisci +1|+1 a un alleato per questo turno.","","\"I non morti combattono come se non ci fosse un domani. Faremo in modo che non lo abbiano, un domani.\" - Lucian","Incantesimo",[],["Demacia"],"COMUNE"],"01DE009":["Protettrice di Brillacciaio","Gioca: Fornisci Barriera a un alleato per questo turno.","","\"Siamo una nazione prosperosa perché il destino di ogni guerriero è una moneta che non spendiamo mai a cuor leggero.\" - Re Jarvan III","Unità",[],["Demacia"],"COMUNE"],"01DE039":["Cithria di Cloudfield","","","\"Ogni notte, per farmi addormentare, mia madre mi raccontava le storie dei grandi eroi di Demacia mentre affilava la sua spada. Sognavo mille avventure, e oggi inizierò la mia.\"","Unità",["ÉLITE"],["Demacia"],"COMUNE"],"01DE056":["Primalama dell'Avanguardia","Attacca: Conferiscimi +2|+2.","","Il grido di battaglia risuona e i miei piedi stanno già battendo sul suolo. Non mi serve nulla, se non l'ordine della mia signora per conoscere il mio destino e mettere in atto la sua volontà.","Unità",["ÉLITE"],["Demacia"],"COMUNE"],"01DE029":["Segugio Piumalesta","Quando evochi un altro alleato, conferiscimi Sfidante.","","Questi parenti dei lamabecchi ala d'argento hanno l'istinto predatore dei cugini, unito a una caparbia inconsapevolezza delle loro ridotte dimensioni.","Unità",["VOLATILE"],["Demacia"],"COMUNE"],"01DE028":["Cavalleria dell'Avanguardia","","","L'Avanguardia non ha bisogno di musica o tamburi, per marciare. Il ritmo degli zoccoli è più che sufficiente.","Unità",["ÉLITE"],["Demacia"],"COMUNE"],"01DE013":["Cotta di maglia","Conferisci Tenacia a un alleato.","","L'acciaio di Demacia è noto in tutto il mondo per la sua eccezionale resistenza e può essere forgiato solo da illustri e potenti fabbri.","Incantesimo",[],["Demacia"],"COMUNE"],"01DE023":["Investigatrice dei Cercatori di magia","Crea 1 Incarcerazione nella tua mano dopo aver giocato un incantesimo di costo 6+ in questa partita.","","\"Perdoni l'intrusione, ma avremo bisogno della sua completa collaborazione. Ci hanno segnalato di alcuni... 'strani eventi'...\"","Unità",[],["Demacia"],"COMUNE"],"01DE051":["Cithria l'Audace","Attacca: Fornisci +1|+1 e Temibile agli altri alleati attaccanti per questo turno.","","\"Le leggende degli eroi... per me non sono mai state semplici racconti. Erano avventure che mi chiamavano per nome. Ho lasciato Cloudfield per scoprire la mia avventura, ma ne ho trovate molte. Ed è soltanto l'inizio.\"\n","Unità",["ÉLITE"],["Demacia"],"EPICO"],"01DE054":["Redentrice dell'Avanguardia","Quando vengo evocata, pesca un'unità se è morto un alleato durante questo turno.","","\"I nostri caduti verranno ricordati nelle nostre grida di battaglia, nei colpi delle nostre spade, nel frastuono dei nostri scudi! Oggi la vittoria sarà nostra!\"","Unità",["ÉLITE"],["Demacia"],"COMUNE"],"01DE030":["Assalitore Ala d'argento","","","Dalla fortezza piovevano frecce, ma nessuna riusciva a sfiorare quel lampo argenteo che sfrecciava nel cielo. ","Unità",["VOLATILE"],["Demacia"],"COMUNE"],"01PZ040":["Jinx","","Vedo che la tua mano è vuota.","\"Che c'è, Fishbones?\"\n\"Mi preoccupo per te, Jinx! Quando ti annoi...\"\n\"...mi viene voglia di far esplodere qualcosa! Ottima idea, Fishbones!\"","Unità",[],["Piltover e Zaun"],"Campione"],"01PZ008":["Teemo","Colpisci il Nexus: Piazza 5 Scoppiettini velenosi su carte casuali nel mazzo del nemico.","Hai piazzato 15+ Scoppiettini velenosi.","\"Regola 154 del codice degli scout di Bandle: mai temere l'ignoto! Regola 276: gli abitanti delle foreste sono nostri amici! Regola 354: se è peloso, si può accarezzare ma non mangiare! Regola 417...\"","Unità",["YORDLE"],["Bandle City","Piltover e Zaun"],"Campione"],"01PZ056":["Heimerdinger","Quando giochi un incantesimo, crea una Torretta Fugace dello stesso costo nella tua mano. Ha costo 0.","Ti ho visto evocare alleati con Tecnologia per un totale di 12+ Potere.","\"Scienziato Pazzo? Ma per piacere... Sono chiaramente uno scienziato sanissimo-anche-se-un-po'-eclettico-e-disorganizzato, ecco tutto!\"","Unità",["YORDLE"],["Bandle City","Piltover e Zaun"],"Campione"],"01PZ013":["Sperimentatore potenziato","Gioca: Scarta la tua mano. Pesca 3 carte. Infliggi 3 a un nemico.","","I suoi sogni gli hanno fatto perdere le mani, ma non ha mollato. Nulla poteva fermarlo.","Unità",[],["Piltover e Zaun"],"EPICO"],"01PZ007":["Elettrocarro da parata","Supporto: Crea nel tuo mazzo 4 copie dell'alleato supportato.","","Il boato dei cannoni attira la folla verso la piazza, dove sta per svolgersi lo spettacolo. A volte ci vogliono settimane per togliersi i coriandoli dai capelli.","Unità",[],["Piltover e Zaun"],"COMUNE"],"01PZ018":["Prodigio dell'Accademia","","","Come fa a mirare? Ottima domanda.","Unità",[],["Piltover e Zaun"],"COMUNE"],"01PZ019":["Avido apprendista","Quando vengo evocato, ripristino 2 mana incantesimo.","","Non tutti hanno i numeri per portare avanti il progresso di Piltover da soli. C'è chi ha bisogno di una guida, di un aiuto per guardare le invenzioni dalla giusta prospettiva.","Unità",[],["Piltover e Zaun"],"COMUNE"],"01PZ025":["Venditore di Scoppiettini","Quando giochi un incantesimo, piazza 3 Scoppiettini velenosi nel mazzo nemico.","","\"Sono buoni?\"\n\"Ma certo! Prima qualità! Ho parlato con tutti, dal primo all'ultimo!\"\n\"Bene, allora ne prendo... come ha detto, scusi?\"\n\"Mmm, questo si sposa!\"\n\"Quanti ne hai presi?\"\n\"...con una patella!\"","Unità",[],["Piltover e Zaun"],"COMUNE"],"01PZ048":["Corina Veraza","Gioca: Annienta le prime 5 carte del tuo mazzo per infliggere 1 a tutti i nemici e al Nexus nemico per ogni incantesimo annientato.","","\"I piltoveriani sono chiusi, capiscono solo di ingranaggi e metallo. Non sanno apprezzare l'arte delicata dei petali, degli steli, di ogni cellula delle mie piante. Preparerò loro una fine immeritatamente aggraziata.\"","Unità",[],["Piltover e Zaun"],"EPICO"],"01PZ028":["Arrangiamento","Quando vengo giocato o scartato, evoca 1 Argogranchio rottamino.","","Con pochi secondi a disposizione e pochi materiali, la giovane inventrice ricordò un'inusuale fonte di ispirazione: una creatura che aveva visto lungo i fiumi di una giungla lontana.","Incantesimo",[],["Piltover e Zaun"],"COMUNE"],"01PZ050":["Forza dell'incantesimo nascente","Fornisci +4|+0 e Attacco rapido a un alleato per questo turno.","","\"Fa un po' di solletico quando inizia a brillare. Sarà normale, vero?\" - Ezreal","Incantesimo",[],["Piltover e Zaun"],"COMUNE"],"01PZ054":["Recluta della Ciurma Boom","Attacca: Infliggi 2 al Nexus nemico.","","\"Siamo sicuri?\"\n\"No.\"\n\"Dovevi rispondere di sì.\"\n\"Sei tu che non dovevi chiedere.\"","Unità",[],["Piltover e Zaun"],"COMUNE"],"01PZ030":["Tipo losco","Gioca: Scegli un seguace. Trasformami in una sua copia esatta.","","\"Salve, amici baroni chimici!\"","Unità",["YORDLE"],["Piltover e Zaun"],"RARA"],"01PZ017":["Venditore di Barili usati","Quando vengo evocato, evoca 2 Barili caustici.","","\"Ti manda Ziel? Gli ho detto che quel che è suo è suo. Non posso rimborsare qualcosa che non ho mai visto prima, no?  Detto questo, ho appena ricevuto una partita di barili nuovi dai quali potrei separarmi...\"","Unità",[],["Piltover e Zaun"],"COMUNE"],"01PZ038":["Draga del Sump","Gioca: Scarta una carta per pescare 1 carta.","","Nel Sump non si butta nulla.","Unità",[],["Piltover e Zaun"],"COMUNE"],"01PZ036":["Ezreal","Colpisci il Nexus: Crea 1 Colpo mistico Fugace nella tua mano.","Hai scelto come bersaglio dei nemici per 8+ volte.","\"Occhiali? Ci sono. Sciarpa? Pure. Guanti fortissimi con proprietà magiche che capisco proprio alla perfezione? Ci puoi giurare!\"","Unità",[],["Piltover e Zaun"],"Campione"],"01PZ035":["Jae Medarda","Quando sono il bersaglio, pesca 1.","","Erede del prestigioso clan Medarda, Jae preferiva cercare antichi artefatti anziché gestire gli affari di famiglia... con sommo scorno di suo padre.","Unità",[],["Piltover e Zaun"],"EPICO"],"01PZ010":["Nubespora","Piazza 5 Scoppiettini velenosi nel mazzo nemico.","","Prima si sente il lieve rumore del fungo scoppiettino. Poi un dolore bruciante e debilitante. Infine si sente una risatina lontana...","Incantesimo",[],["Piltover e Zaun"],"COMUNE"],"01PZ045":["Furfantella Zaunita","Gioca: Scarta una carta per pescare 1 carta.","","\"I topi del Sump dovrebbero prendersi cura gli uni degli altri.\"\n\"Sono troppo impegnati a piangersi addosso, fratello.\"\n\"Davvero. Ah... hai visto il mio borsello?\"","Unità",[],["Piltover e Zaun"],"COMUNE"],"01PZ002":["Oste del vicoletto","Quando vengo evocato, crea nella mano 1 carta casuale per ogni Oste del vicoletto che hai evocato in questa partita.","","\"Sì, amico. Ha un lieve retrogusto, un po' come il Sump ha un leggero odorino. Il secchio è vicino al giracanzoni.\"","Unità",[],["Piltover e Zaun"],"COMUNE"],"01PZ004":["Sbarramento energetico","Infliggi 3 a un nemico o al Nexus nemico, poi 2 a un altro e 1 a un altro ancora.","","\"Quando hai talento, non esistono i colpi di fortuna.\" - Ezreal","Incantesimo",[],["Piltover e Zaun"],"EPICO"],"01PZ020":["Poro audace","","","Il primo lancio fu un incidente: era scivolata in un cannone del Giorno del Progresso mentre si faceva bella. Ora è l'idolo di Piltover, che sfreccia nel cielo sopra le folle adoranti.","Unità",["PORO"],["Piltover e Zaun"],"COMUNE"],"01PZ046":["Copie contraffatte","Scegli una carta che hai in mano. Creane 4 copie esatte nel tuo mazzo.","","L'imitazione è la più sincera forma di furto.","Incantesimo",[],["Piltover e Zaun"],"RARA"],"01PZ052":["Colpo mistico","Infliggi 2 a un bersaglio.","","\"Non sbaglio mai. Ma a volte sparo un paio di colpi di avvertimento...\" - Ezreal","Incantesimo",[],["Piltover e Zaun"],"COMUNE"],"01PZ033":["Caccia alla perfezione","Se in questa partita hai giocato 20 carte con nomi diversi, evoca Catastrofe.","","\"Alla fine, tutti noi che abbiamo lavorato alla visione di Von Yipp siamo stati ingannati. Non potevamo immaginare... il potere terribile che avremmo scatenato.\" - Ingegnere progettista piltoveriano","Incantesimo",[],["Piltover e Zaun"],"EPICO"],"01PZ005":["Trasmorfatore hextech","Trasforma un seguace in una copia esatta di un altro seguace.","","\"DICEVI SEMPRE CHE VOLEVI PERDERE PESO.\"\n\"QUINDI MI HAI TRASFORMATO IN UNO YORDLE?\"\n\"HAI PERSO PESO!\"\n\"MA SONO ANCHE UNO YORDLE!\"","Incantesimo",[],["Piltover e Zaun"],"RARA"],"01PZ021":["Scagnozzo di Midenstokke","Colpisci il Nexus: Evoca una mia copia esatta.","","\"Signor Berz, l'abbiamo trovata DENTRO al caveau, coperto di ingranaggi d'oro, aggrappato alla porta della cassaforte distrutta.\"\n\"Non ero io. Solo un sosia.\"\n\"È ancora aggrappato alla porta.\"\n\"Dimostratelo.\"","Unità",[],["Piltover e Zaun"],"RARA"],"01PZ031":["Shock di Statikk","Infliggi 1 a un nemico o al Nexus nemico e 1 a un altro.\nPesca 1 carta.","","\"Ed è così che abbiamo scoperto l'arco elettrico! Ovviamente, il mio predecessore aveva già teorizzato un evento del genere, ma aveva sottovalutato la gittata della scarica. Poveraccio...\" - Heimerdinger","Incantesimo",[],["Piltover e Zaun"],"RARA"],"01PZ059":["Schiacciabot d'oro","","","UCCIDI. SCHIACCIA. DISTRUGGI. RIPETI.","Unità",["TECNOLOGIA"],["Piltover e Zaun"],"COMUNE"],"01PZ001":["Rovistare","Per giocare, scarta fino a 2 carte. Pesca 1 carta per ogni carta scartata.","","\"Oooooh, mamma! CINQUE SICARI E UN GOLEM? Un momento! Ho proprio quel che ci vuole! Da qualche parte...\"\n- Jinx","Incantesimo",[],["Piltover e Zaun"],"COMUNE"],"01PZ057":["Riunione di rottami","Evoca 2 Argogranchi rottamini.","","Due amichevoli creature, un tempo separate da un territorio invalicabile, si riunirono finalmente nelle tiepide acque del Sump.","Incantesimo",[],["Piltover e Zaun"],"COMUNE"],"01PZ027":["Raggio Termogenico","Per giocare, spendi tutto il mana.\nInfliggi danni a un'unità pari alla quantità di mana spesa.","","\"Abbiamo finito il tempo e i fondi e, anche se il raggio funziona, non siamo riusciti a regolare i suoi consumi di energia.\" - Sperimentatore zaunita","Incantesimo",[],["Piltover e Zaun"],"RARA"],"01PZ055":["Studiosa astuta","Quando peschi una carta, forniscimi +1|+0 per questo turno.","","L'immaginazione è la scintilla di ogni grande invenzione, ma è la ricerca che rende il fuoco un incendio.","Unità",[],["Piltover e Zaun"],"COMUNE"],"01PZ014":["Innovazione Non Autorizzata","Evoca 1 Marchingegno illegale.","","\"I loro incidenti hanno sintomi diversi: tremori di esplosioni, fumi putridi che emergono dalle crepe, e così via. Presto uno di quei folli distruggerà la città.\" - Filantropo piltoveriano","Incantesimo",[],["Piltover e Zaun"],"COMUNE"],"01PZ034":["Rovistatore del Sump","Fedeltà: Crea 1 Mappa del Sump nella tua mano. Costa 0 per questo turno.","","I bambini zauniti iniziarono a esplorare le vecchie miniere e i piani bassi delle Vie. Scoprirono un mondo incredibile e si fecero molti amici.\n","Unità",[],["Piltover e Zaun"],"RARA"],"01PZ003":["Roboassemblatore","Quando giochi un incantesimo, conferiscimi +1|+1.","","\"Qualsiasi imbecille può costruire una macchina, ma ci vuole un'arguzia straordinaria per incanalare il VERO progresso in una mente meccanica! Quei maledetti burocrati torneranno qui strisciando...\" - Klas Henwick","Unità",[],["Piltover e Zaun"],"RARA"],"01PZ044":["Rockettaro Chempunk","Gioca: Infliggi 1 a tutti i nemici.","","\"...il suo assolo si lancia in una scala minore, per poi arpeggiare (sì, è una parola vera) nella trasposizione di un bridge. Immagino tu non possa capire il suo lavoro.\" - Max Bliff, sorvegliante","Unità",[],["Piltover e Zaun"],"RARA"],"01PZ029":["Illustre benefattore","Gioca: Manifesta una carta epica delle tue regioni.","","\"Ero un uomo rabbioso, ai tempi, e spazzai via la concorrenza in cerca di gloria e denaro. Ora investo la mia fortuna nell'altruismo, sperando che il mio inverno penitente mi assolva dai miei peccati.\"","Unità",[],["Piltover e Zaun"],"RARA"],"01PZ051":["Forgiatrice pazzoide","Tutti i tuoi incantesimi e abilità infliggono 1 danno in più.","","\"Vuoi fare un botto più grosso? Beh, sei nel posto giusto!\"","Unità",[],["Piltover e Zaun"],"RARA"],"01PZ023":["Professor von Yipp","Quando evochi un alleato di costo 1, conferiscigli +2|+2.","","\"Oggi presento al comitato la mia nuova invenzione, mostrata dal mio stimato collega...\"","Unità",["FELINO"],["Piltover e Zaun"],"RARA"],"01PZ024":["Voltista Instabile","Conferiscimi +4|+0 e Attacco rapido dopo aver giocato un incantesimo di costo 6+ in questa partita.","","Nome: Klas Henwick, Età: 51, Licenza: Classe 2, condizionale, Stato: Revocato, Commenti: Ignorava i ripetuti avvertimenti di ridurre la potenza dopo l'esplosione del laboratorio (Caso 13X764NM). VIETARE L'INGRESSO.","Unità",[],["Piltover e Zaun"],"RARA"],"01PZ049":["Giorno del Progresso!","Pesca 3 carte e riduci di 1 il loro costo.","","GIORNO DEL PROGRESSO!\nFesteggiate alla PIAZZA DEI CANCELLI DEL SOLE!\nAmmirate le MERAVIGLIE HEXTECH!\nStupitevi con il PORO AUDACE!\nAscoltate l'UOMO DEL DOMANI parlare dello STATO DEL PRESENTE!\nIngresso GRATUITO!\nSono ammessi anche i bambini piltoveriani!","Incantesimo",[],["Piltover e Zaun"],"EPICO"],"01PZ006":["Guardiano della piazza","Costo 1 in meno per ogni incantesimo che hai giocato in questa partita.","","Hai venti secondi per obbedire.","Unità",[],["Piltover e Zaun"],"RARA"],"01PZ053":["Colonia di rodicchietti","Quando vengo evocata, crea 1 Nubespora nella tua mano.","","\"Sì, è così! Ce ne sono tantissimi, in giro! SEMBRANO pazzi, ma non capisci. Io sì. Io li capisco! Hanno un piano. Un grande piano. Scoppiettini. Formaggio... sorbetti. Dov'ero rimasto?\"\n- Venditore di Scoppiettini","Unità",[],["Piltover e Zaun"],"COMUNE"],"01PZ012":["Fuochino fuochino!","Quando mi scarti, evocami.","","\"ADDOSSO, BELLO!\" - Jinx","Unità",[],["Piltover e Zaun"],"COMUNE"],"01PZ039":["Che emozione!","Per giocare, scarta 1 carta.\nInfliggi 3 a un bersaglio.","","\"BOMBA IN BADABUCA!\" - Jinx","Incantesimo",[],["Piltover e Zaun"],"RARA"],"01PZ016":["Lampo di genio","Crea nella mano un incantesimo casuale di costo 6+ delle tue regioni.\nRipristina il tuo mana incantesimo.","","Basta un'epifania per cambiare la storia.","Incantesimo",[],["Piltover e Zaun"],"COMUNE"],"01PZ058":["Rodicchietta Bisteccona","Quando vengo evocata, crea 2 Nubispore nella tua mano.","","\"Ne ho vista una grossa! Grossa come un cavallo ed è sveglia come un krug. Tienila ben d'occhio, ti dico io. Ci sarà un motivo se quella pomodorona è la regina del branco!\"\n- Venditore di Scoppiettini","Unità",["YORDLE"],["Piltover e Zaun"],"RARA"],"01PZ009":["Aviatore amatoriale","","","\"Macchine volanti personali? Un sogno irrealizzabile! Ho appena fatto buttare l'ultimo prototipo al mio apprendista. A proposito, dov'è finito?\" - Ingegnere piltoveriano","Unità",[],["Piltover e Zaun"],"COMUNE"],"01PZ042":["Avventuriera intrepida","Supporto: Fornisci Elusione al mio alleato supportato per questo turno.","","Per molti piltoveriani, l'ignoto si esplora con la scienza e l'invenzione, al sicuro nella loro Città del Progresso. Alcuni, invece, navigano oltre l'orizzonte, alla scoperta dell'altro ignoto: il mondo.","Unità",[],["Piltover e Zaun"],"RARA"],"01PZ026":["Mappa del Sump","Conferisci Elusione a un alleato.","","\"I piltovini credono sempre di sapere tutto, ma sulle loro mappe ci sono solo i posti di cui abbiamo parlato! Non c'è niente come il sapere locale. Puoi averlo... pagando.\" - Ajuna Lem, Rovistatore del Sump","Incantesimo",[],["Piltover e Zaun"],"COMUNE"],"01PZ043":["Borseggiatore Chempunk","Colpisci il Nexus: Crea nella tua mano una copia esatta di un incantesimo casuale nel mazzo del nemico.","","Ci si aspettava che i reietti sotto la Città del Progresso si mettessero l'uno contro l'altro. Invece hanno formato un'alleanza, trovato un'unità e creato una nuova casa. Non era granché, ma era casa loro: Zaun.","Unità",[],["Piltover e Zaun"],"RARA"],"01PZ047":["Barile caustico","Ultimo respiro: Infliggi 1 a ENTRAMBI i Nexus.","","\"Ti direi di metterti una tuta, ma là sotto si suda come sotto le ascelle di un gladiatore. I guanti sì, però... Se ti finisce qualcosa di tossico addosso, prega che non sia su qualcosa di importante.\" - Ziel, capomastro zaunita","Unità",[],["Piltover e Zaun"],"COMUNE"],"01FR024":["Anivia","Attacca: Infliggi 1 a tutti i nemici e al Nexus nemico.\nUltimo respiro: Rianimami sotto forma di Anivia Uovo.","Sei Illuminato.","\"Sono nata in queste terre spietate ed è mio compito proteggerle. Né il tempo, né la guerra, né la morte mi faranno desistere.\"","Unità",["VOLATILE"],["Freljord"],"Campione"],"01FR039":["Tryndamere","","Invece di morire, aumento di livello.","\"Non morire per la nostra causa. Vivi per essa...\"","Unità",[],["Freljord"],"Campione"],"01FR006":["Retaggio dei Figli del gelo","Conferisci +2|+2 a un alleato e a tutte le sue copie alleate ovunque.","","\"Noi siamo Figli del gelo, nel nostro sangue scorre la magia del Freljord. I nostri avi hanno confinato il male antico e ora noi montiamo la guardia contro il suo ritorno.\" - Gregor il Guardiano","Incantesimo",[],["Freljord"],"COMUNE"],"01FR022":["Falco del presagio","Quando vengo evocato, conferisci +1|+1 ai primi due alleati del tuo mazzo.","","\"Tre volte i nostri Predatori hanno raggiunto i cancelli avarosani, e ogni volta sono stati accolti da archi già tesi. Come fanno a prevedere i nostri attacchi?\" - Steffen, Signore delle cicatrici","Unità",["VOLATILE"],["Freljord"],"COMUNE"],"01FR042":["Venti gelidi","Congela 2 nemici.","","\"Osi sfidarmi nelle mie terre? Non sei pronto, piccoletto.\" \n- Anivia","Incantesimo",["ELEMENTALE"],["Freljord"],"RARA"],"01FR009":["Braum","La prima volta che sopravvivo ai danni, evoca 1 Poro possente.","Sono sopravvissuto a 10+ danni totali.","\"Papà, raccontami quella di Braum e della sua porta!\"\n\"O di quando è caduto e ha spaccato in due una montagna!\"\n\"Oh! Quella di quando ha salvato la taverna dallo yeti!\"","Unità",[],["Freljord"],"Campione"],"01FR018":["Lupo Zannabrina","Colpisci: Se ho colpito un'unità con 0 Potere, uccidila.","","I predatori delle terre del nord sanno che la preda più facile è quella ferita dal morso dell'inverno.","Unità",["CANIDE"],["Freljord"],"RARA"],"01FR036":["Tiratore Avarosano","Gioca: Infliggi 1 a un nemico.","","Nel Freljord puoi cacciare o morire di fame.","Unità",[],["Freljord"],"COMUNE"],"01FR045":["Steffen, Signore delle cicatrici","Quando sopravvivo ai danni, conferiscimi +3|+0.","","\"Ho giurato la mia fedeltà all'Artiglio d'Inverno quando Sejuani mi ha dato la mia prima cicatrice. Da allora, ogni cicatrice l'ho guadagnata al suo servizio.\"","Unità",[],["Freljord"],"COMUNE"],"01FR008":["Poro solitario","Quando vengo evocato, crea nella mano un altro Poro casuale di costo 1.","","\"Ho passato una vita nel Freljord, ma nulla mi gela il cuore come questo triste piccoletto.\" - Allevatore di Poro","Unità",["PORO"],["Freljord"],"COMUNE"],"01FR055":["Frantumazione","Infliggi 4 a un nemico se ha 0 Potere. Altrimenti lo Congeli.","","\"L'inverno umilia i forti e abbatte i deboli quando cavalca tra le terre.\" - Steffen, Signore delle cicatrici","Incantesimo",["ELEMENTALE"],["Freljord"],"COMUNE"],"01FR038":["Ashe","Attacca: Congela il nemico più forte.","Hai ridotto il Potere di 5+ nemici a 0. Quando aumento di livello, crea 1 Freccia di Cristallo in cima al mazzo.","\"Quando guardo casa mia, vedo cos'è ma anche cosa potrebbe essere. Prosperosa e abbondante, non solo per il mio popolo, ma per tutti quelli che vogliono la pace. Il Freljord, unito.\"","Unità",[],["Freljord"],"Campione"],"01FR029":["Supplica","Pesca un campione.","","\"Predatori in vista! Suonate l'adunata e accendete i fuochi, avremo bisogno di tutto l'aiuto possibile.\" - Sentinella avarosana","Incantesimo",[],["Freljord"],"RARA"],"01FR035":["Predatrice senza Cicatrici","Quando sopravvivo ai danni, conferiscimi +3|+0.","","\"I figli degli avarosani vengono cresciuti cercando la vecchiaia, diventando deboli e impreparati alla battaglia. I nostri nascono nel fuoco della guerra.\" - Vrynna, Madre delle cicatrici\n","Unità",[],["Freljord"],"COMUNE"],"01FR020":["Valanga","Infliggi 2 a TUTTE le unità.","","Nel cuore di ogni valanga c'è una piccola palla di neve che non voleva stare al suo posto.","Incantesimo",["ELEMENTALE"],["Freljord"],"RARA"],"01FR014":["Cucciolo di Yeti","Ultimo respiro: Crea 2 Yeti furiosi nel tuo mazzo.","","\"Era così piccolo e pacifico! Chi avrebbe immaginato che sarebbe diventato... beh... uno yeti.\" - Cacciatore avarosano","Unità",["YETI"],["Freljord"],"COMUNE"],"01FR049":["Lupo Cacciatore","Quando vengo evocato, il tuo avversario evoca 1 Lepre delle Nevi.","","\"Non si fa un lupo con una lepre.\"\n- Proverbio dell'Artiglio d'Inverno","Unità",["CANIDE"],["Freljord"],"COMUNE"],"01FR037":["Pionieri Avarosani","Fedeltà: Conferisci +3|+3 e Sopraffare al primo alleato del tuo mazzo.","","Mentre i rinforzi si affacciavano sul crinale, i Pionieri chinarono il capo davanti alla madre guerriera. Perché lei, la loro Avarosa incarnata, la loro regina Ashe, era una promessa di pace.","Unità",[],["Freljord"],"RARA"],"01FR026":["Artiglio selvaggio Alfa","","","La potenza di un cavallo da guerra, l'istinto ferino di un gatto.","Unità",["FELINO"],["Freljord"],"COMUNE"],"01FR030":["Acciaio in frantumi","Congela un nemico con 3 o meno Salute.","","\"Freddo? Ah! Speriamo che il vostro spirito sia più forte del vostro acciaio!\" - Braum","Incantesimo",["ELEMENTALE"],["Freljord"],"COMUNE"],"01FR013":["Vrynna, Madre delle cicatrici","Quando sopravvivo ai danni, conferiscimi +3|+0.","","\"Preferisco morire congelata che sedermi davanti al fuoco con i deboli al seguito di Ashe. Ma se è calore che cercano, glielo darò.\"","Unità",[],["Freljord"],"EPICO"],"01FR019":["Soffio dell'Inverno","Uccidi tutti i nemici con 0 Potere, poi congela tutte le unità nemiche.","","La madre guerriera Inverno è il primo e ultimo nemico che affronta chi osa invadere il Freljord. I suoi spietati compagni di sangue sono il vento e il gelo.","Incantesimo",["ELEMENTALE"],["Freljord"],"EPICO"],"01FR041":["Guardia Interna Avarosana ","Quando vengo evocato, conferisci agli alleati nel tuo mazzo +1|+1.","","\"Tante tribù sotto un unico stendardo! Forse un giorno il Freljord combatterà come una cosa sola.\"","Unità",[],["Freljord"],"EPICO"],"01FR025":["Allevatore di Poro","Quando vengo evocato, pesca 1 Poro se hai un Poro Visibile.","","Un branco ha bisogno di due cose: amore e compagnia. Tutto il resto sono palle... di pelo.\n","Unità",[],["Freljord"],"RARA"],"01FR054":["Predatrice Vergine delle cicatrici","","","\"I deboli raccolgono, i forti prendono. I piccoli avarosani scopriranno presto chi sono!\"","Unità",[],["Freljord"],"RARA"],"01FR021":["Tarkaz il Senzatribù","Attacca: Infliggi 1 a TUTTE le unità in battaglia.","","\"Tarkaz combatteva con più forza e convinzione degli altri. Ha accettato la sconfitta con eleganza, ho pensato. Beh, in un certo senso...\" - Tryndamere","Unità",[],["Freljord"],"EPICO"],"01FR043":["Cuore di Poro","Gioca: Combina i tuoi seguaci Poro in Batuffolo di Poro, che ottiene le statistiche e le parole chiave positive dei Poro combinati.","","\"Ancora una storia, ma in silenzio o arriva la mamma!\nTanto tempo fa, i predoni attaccarono il villaggio di Avarosa. Le sue forze erano poche e tutto sembrava perduto. Ma apparve un Poro che offrì il suo aiuto...\"","Unità",["PORO"],["Freljord"],"RARA"],"01FR033":["Pietre del Fato","Inizio del turno: Ottieni una gemma di mana extra per questo turno.","","\"Questi antichi cerchi di pietra ci ricordano che siamo solo l'ultima di tante tribù ad aver affrontato queste terre selvagge.\" - Ashe","Unità",[],["Freljord"],"COMUNE"],"01FR011":["Arciere di Valgelata","Gioca: Congela un nemico.","","Gli avarosani sono fieri dei loro rigidi inverni e delle loro terre ghiacciate. I loro difensori dall'occhio di falco ne sono la dimostrazione. ","Unità",[],["Freljord"],"COMUNE"],"01FR050":["Locandiere cortese","Gioca: Cura un alleato o il tuo Nexus di 3.","","\"Questo bellissimo localino è il Gufo Brillo! Abbiamo birre e stufati da far paura al freddo. Entrate, forza!\"","Unità",[],["Freljord"],"COMUNE"],"01FR052":["Bestia errante","Gioca: Annienta TUTTE le unità con 4 o meno Potere, in gioco e in mano.","","\"Sono emerso dalle macerie e ho visto una cicatrice bruciata nella terra intorno a me. Ceneri fumanti dove prima c'erano i miei compagni, e nella distanza una figura incombente...\"\n- Bjerg il Vagabondo","Unità",[],["Freljord"],"EPICO"],"01FR016":["Poro-Snax","Conferisci +1|+1 ai Poro alleati ovunque.","","\"Li mangiano in un sol boccone e poi ti guardano con gli occhioni e la lingua fuori, più felici di un elnuk appena tosato. Provaci tu, a dirgli di no.\" - Pasticcere avarosano","Incantesimo",[],["Freljord"],"COMUNE"],"01FR005":["Furia guerriera","Conferisci +8|+4 a un alleato.","","\"Mi dicono che ho... un brutto carattere.\" - Tryndamere","Incantesimo",[],["Freljord"],"RARA"],"01FR023":["Chiamata della Madre Guerriera","Evoca il primo alleato dal tuo mazzo, ora e a OGNI inizio del turno.","","Verrà un giorno in cui una chiamata inconfondibile risuonerà nel Freljord. Tutti risponderanno, perché annuncerà il ritorno dei nostri antichi nemici.","Incantesimo",[],["Freljord"],"EPICO"],"01FR047":["Mistico selvaggio","Illuminato: Ho +4|+4.","","\"Chi impara a ruggire come le bestie presto dimentica la sua lingua.\" - Anivia","Unità",[],["Freljord"],"COMUNE"],"01FR056":["Yeti dei ghiacci","Quando vengo evocato,congela i nemici con 3 o meno Salute.","","\"AaaaaaaAAaaaAaaaaah!\" - Bjerg il Vagabondo","Unità",["YETI"],["Freljord"],"RARA"],"01FR027":["Elnuk Taurino","","","I racconti avarosani parlano dello \"zio Elnuk\", un vecchio testardo che non desiderava altro che un po' d'erba su cui sdraiarsi e un'occasione per bisticciare. ","Unità",["ELNUK"],["Freljord"],"COMUNE"],"01FR057":["Istinto del branco","Fornisci +2|+2 e Sopraffare agli alleati per questo turno.","","Un ululato solitario riecheggiò per la notte, seguito da un altro, e da un altro ancora. In pochi secondi il branco ululò come un solo lupo... un furioso coro di voci in cerca di sangue.","Incantesimo",[],["Freljord"],"RARA"],"01FR004":["Elisir del ferro","Fornisci +0|+2 a un alleato per questo turno.","","\"È dura là fuori, eh? Nessun problema: il Gufo serve un intruglio speciale talmente forte da far crescere la barba persino a un neonato!\" - Locandiere cortese","Incantesimo",[],["Freljord"],"COMUNE"],"01FR048":["Cacciatore avarosano","Quando vengo evocato, crea 1 Yeti furioso tra le prime 3 carte del tuo mazzo.","","\"È una settimana che non prendo niente! O quelle bestie sanno dove sono, o qualcosa le sta spaventando...\"","Unità",[],["Freljord"],"COMUNE"],"01FR017":["Branco di Elnuk","Gioca: Evoca tutti gli Elnuk presenti nelle prime 6 carte del tuo mazzo. Rimetti il resto delle carte nel tuo mazzo.","","\"Gli avarosani sono come gli elnuk. Degli erbivori dagli occhi spenti, facile preda persino per chi non ha cicatrici. Sopravvivono solo perché sono tanti.\" - Vrynna, Madre delle cicatrici","Unità",["ELNUK"],["Freljord"],"COMUNE"],"01FR046":["Coraggio","Conferisci +3|+3 a un alleato ferito.","","\"...Grandi erano le sue ferite, ma Braum alzò la testa e rise. Poiché sapeva che è nei tempi duri che si forgiano gli eroi!\"\n- La saga di Braum","Incantesimo",[],["Freljord"],"RARA"],"01FR012":["Ametista degli eoni","Ottieni una gemma di mana vuota e cura di 3 il tuo Nexus.","","Né il rubino né lo zaffiro superano in lucentezza la pietra secolare, una gemma luminosa dotata di irreali proprietà curative.","Incantesimo",[],["Freljord"],"COMUNE"],"01FR040":["Sciamana Zannagelata","Inizio del turno: Congela il nemico più forte.","","\"Per diventare una cosa sola con la natura non dobbiamo nasconderci dal freddo, ma crogiolarci nella sua furia.\"","Unità",[],["Freljord"],"RARA"],"01FR031":["Yeti antico","Fine del turno: Riduci il mio costo di 1.","","\"Che cos'era? Mi è sembrato uno starnuto. I ghiacciai starnutiscono?\" - Bjerg il Vagabondo\n","Unità",["YETI"],["Freljord"],"RARA"],"01FR053":["Poro possente","","","\"Il vecchio Lungocorno qui ha perso un occhio, difendendo il Re dei Poro da uno scontroso artiglio selvaggio! Del resto non sono le dimensioni del martello che contano, ma quelle del cuore.\" - Allevatore di Poro\n","Unità",["PORO"],["Freljord"],"COMUNE"],"01FR010":["Giuramento dei Compagni di Sangue","Conferisci +0|+3 a due alleati.","","\"Sarò la torcia nel tuo cuore e lo scudo al tuo fianco. Dammi la forza di proteggere noi e la nostra stirpe, e che le nostre vite possano fluire insieme come il sangue che sigilla questo patto.\" - Tryndamere","Incantesimo",[],["Freljord"],"RARA"],"01FR001":["Colpo raggelante","Congela un nemico.","","Il gelo colpisce all'improvviso. Al suo cospetto anche i più forti guerrieri sono inermi.","Incantesimo",["ELEMENTALE"],["Freljord"],"RARA"],"01FR032":["Veggente Stellato","Quando giochi un incantesimo, conferisci +1|+1 al primo alleato nel tuo mazzo.","","\"Fai che abbia orecchie fini per udire l'arrivo del vento, piedi leggeri per attraversare le nevi e occhi acuti che vedano oltre il velo dell'inverno.\"","Unità",[],["Freljord"],"RARA"],"01FR051":["Fanfaronate","Se hai uno Yeti, evoca 1 Yeti furioso. Altrimenti, crea l'unità in cima al tuo mazzo.","","\"...e ha la bocca piena di denti seghettati giganti e pugni che picchiano occhi arrabbiatissimi a un RUGGITO DA FAR TREMARE LA FORESTA! Me l'ha raccontato lo zio Bjerg!\" - La piccola Ingvar","Incantesimo",[],["Freljord"],"COMUNE"],"01FR034":["Gli Eterni","Quando vengo evocato, conferiscimi +1|+1 per ogni alleato morto.","","\"Ah, il vecchio Bjerg ne ha passate di tutti i colori. Ha perso i suoi uomini a nord ed è tornato mesi dopo, pallido e farneticante. Ora parla solo di \"bestie enormi\" e \"artigli giganti\". Pover'uomo.\" - Locandiere cortese","Unità",[],["Freljord"],"RARA"],"01FR007":["Bjerg farneticante","Quando vengo evocato, pesca un'unità con 5+ Potere.","","\"Mi-mi-mi dovete credere! Era enorme, vi dico, ENORME!\"","Unità",[],["Freljord"],"COMUNE"],"01FR003":["Sentinella avarosana","Ultimo respiro: Pesca 1 carta.","","\"Un tempo credevo che il mio posto fosse nei lontani campi di battaglia. Ora l'ho trovato vicino alla tribù, alle mie terre. I miei occhi sono i suoi occhi, la sua sicurezza è nelle mie mani.\"","Unità",[],["Freljord"],"COMUNE"],"01SI038":["Burlona fantasma","Quando un altro alleato muore, infliggi 1 al Nexus nemico.","","Il suo scherzo più crudele non fu massacrare i soldati che avevano creduto alle urla di una bambina, ma seminare il dubbio tra i sopravvissuti tornati a casa, che ignorarono le urla delle loro figlie.","Unità",[],["Isole Ombra"],"RARA"],"01SI049":["Oltre il velo","Uccidi un alleato per pescare 2 carte.","","\"Ho peccato. Non dovevamo scrutare oltre il pallido velo. Ciò che nasconde ha un prezzo troppo grande.\" - Arie Wrence, Indomita vendicatrice","Incantesimo",[],["Isole Ombra"],"COMUNE"],"01SI053":["Elise","Attacca: Evoca 1 Ragnetto attaccante.","Inizio del turno: Hai 3+ altri Ragni.","Un tempo a capo di una potente casata di Noxus, Elise ha dei legami con le Isole Ombra che le hanno donato una bellezza e una giovinezza sovrannaturali in cambio di qualche anima in sacrificio. Una scelta facile.","Unità",["RAGNO"],["Isole Ombra"],"Campione"],"01SI057":["Crocolite antico","Per giocarmi, uccidi 2 alleati.","","\"Sbattili nella gabbia, pum, pata pum...\nPrenditi tutte le anime, una dopo l'altra...\nNon farla andare lontano!\nAltrimenti sai che baccano...\"","Unità",["RETTILE"],["Isole Ombra"],"RARA"],"01SI023":["Guida delle Anime","Quando evochi un alleato Effimero, conferiscigli +1|+1.","","Solo i caduti sanno che non era sola. Solo loro hanno visto gli infiniti compagni che ha condotto verso le terre dell'aldilà.","Unità",[],["Isole Ombra"],"COMUNE"],"01SI010":["Massacro di ombre","Evoca 2 Cavalieri Spettrali.","","Vivono come sono morti: leali fino alla fine.","Incantesimo",[],["Isole Ombra"],"COMUNE"],"01SI042":["Hecarim","Attacca: Evoca 2 Cavalieri Spettrali attaccanti.","Hai attaccato con 7+ alleati Effimeri.","Non è un tuono. L'Ombra della Guerra è all'orizzonte.","Unità",[],["Isole Ombra"],"Campione"],"01SI027":["Vittima sacrificale","Se 3+ alleati sono morti in questo turno, evoca Vilemaw.","","\"Inginocchiati davanti alle fauci della tua dea. Anzi, lascia che ti uccidano.\" - Elise","Incantesimo",[],["Isole Ombra"],"RARA"],"01SI048":["Guardiano maledetto","Ultimo respiro: Evoca 1 Abominio evaso.","","Tempo e follia. Mai ci fu una combinazione più letale.","Unità",[],["Isole Ombra"],"COMUNE"],"01SI018":["Scriba del compianto","Quando vengo evocato, crea una copia di un alleato morto in questa partita nella tua mano.","","\"L'autore ignorava che presto la Rovi... no, no, no, non ci siamo, mi si è rovesciato l'inchiostro! L'autore ignorava che... no, no, no!\"","Unità",[],["Isole Ombra"],"COMUNE"],"01SI030":["Kalista","","Ho visto 3+ alleati morire.","Nella vita fu un generale, una protettrice, un'eroina. Ma quando la sua carne cedette non le rimase altro che il fuoco ardente del castigo, uno spirito immortale di vendetta.","Unità",[],["Isole Ombra"],"Campione"],"01SI035":["Rhasa il Separatore","Gioca: Uccidi i 2 nemici più deboli se un alleato è morto durante questo turno.","","\"Ci dissero... che era il viaggio di una leggenda. Che lo facevamo... per il futuro di Demacia. Salpammo pieni di speranza. Ma tutte quelle vite... per cosa?\" - Arie Wrence, soldatessa demaciana","Unità",[],["Isole Ombra"],"EPICO"],"01SI005":["Argospettro","Costo 1 in meno per ogni alleato morto in questa partita.","","Un tempo un animale da soma per un regno a lungo dimenticato, questo mostro vaga per gli antichi campi di battaglia, aggiungendo rottami al suo guscio e anime dei morti al suo nucleo.","Unità",[],["Isole Ombra"],"RARA"],"01SI037":["Poro sinistro","","","Dai, ci sono modi peggiori per morire.","Unità",["PORO"],["Isole Ombra"],"COMUNE"],"01SI052":["Thresh","","Ho visto 6+ unità morire.","\"Cling clang, fan le catene, qualcuno ti dà la caccia...\nCling clang, oh le catene, dal carceriere non si scappa...\"","Unità",[],["Isole Ombra"],"Campione"],"01SI033":["Comandante Ledros","Gioca: Infliggi danni al Nexus nemico pari alla metà della sua Salute (arrotondando per eccesso).\nUltimo respiro: Riprendimi in mano.","","Gli spiriti tendono a dimenticarsi, man mano che gli anni erodono il ricordo. Ma il dolore ha legato Ledros al suo passato. Certe cose non vengono perdonate neanche dal tempo.","Unità",[],["Isole Ombra"],"EPICO"],"01SI003":["La Mietitura","Rianima i 6 alleati più forti che sono morti in questa partita e conferisci loro Effimero.","","In alcune notti, una marea di spiriti affamati espande la Nebbia Oscura, che li traghetta oltre i mari a rapire i vivi, alimentando il buio con nuove non vite.","Incantesimo",[],["Isole Ombra"],"EPICO"],"01SI041":["L'Imperituro","Ultimo respiro: Resuscitami al prossimo Inizio del turno e conferiscimi +1|+1 per ogni volta in cui sono morto.","","Il vecchio martire ricordava di aver condotto i compagni verso la loro fine. Ma erano anni che non ricordava il perché...","Unità",[],["Isole Ombra"],"EPICO"],"01SI045":["Assorbianima","Assorbi 4 Salute da un alleato.","","\"Ciò che ti uccide mi rende più forte.\" - Thresh","Incantesimo",[],["Isole Ombra"],"COMUNE"],"01SI036":["Formicolio","Evoca 2 Ragnetti se un alleato è morto durante questo turno.","","Quella sensazione sulla pelle non è inquietante come la consapevolezza di ciò che c'è sotto.","Incantesimo",[],["Isole Ombra"],"COMUNE"],"01SI051":["Prodigio tormentato","Quando muore un altro alleato, o Ultimo respiro: Ripristina il tuo mana incantesimo.","","Lavorava giorno e notte per perfezionare la sua composizione. Poi, in un batter d'occhio, un oscuro silenzio lo invase. Tutti iniziarono a urlare e a scappare. Lui non si accorse di niente.","Unità",[],["Isole Ombra"],"RARA"],"01SI012":["Ignaro isolano","Gioca: Conferisci lo stato Effimero a un alleato nella tua mano e riduci di 1 il suo costo.","","Oh, povero ragazzo...","Unità",[],["Isole Ombra"],"COMUNE"],"01SI031":["Messaggero di ferro","Attacca: Conferiscimi +1|+0 per ogni alleato Effimero che hai.","","Nella morte, come nella vita, urla l'ordine nero e perverso. Nella morte, come nella vita, i leali cavalieri di Hecarim rispondono, caricando con la furia del massacro.","Unità",[],["Isole Ombra"],"RARA"],"01SI034":["Lancia oscura","Infliggi 4 a un'unità se un alleato è morto durante questo turno.","","\"La nostra lancia canta per i caduti.\" - Kalista","Incantesimo",[],["Isole Ombra"],"COMUNE"],"01SI043":["Nobile sventurato","Ultimo respiro: Evoca 1 Ragnetto.","","\"Lady Elise? Dove... dov'è finita?\"","Unità",[],["Isole Ombra"],"COMUNE"],"01SI009":["Spiriti inquieti","Supporto: Conferisci +2|+0 ed Effimero al mio alleato supportato.","","C'è chi guarda la Rovina e vede solo distruzione e miseria. Altri vedono il bicchiere mezzo pieno.","Unità",[],["Isole Ombra"],"COMUNE"],"01SI007":["Reliquia infestata","Evoca 3 Spiriti scatenati.","","Questi antichi artefatti sono un tesoro tanto per i vivi che li bramano, quanto per i morti che non vogliono separarsene.","Incantesimo",[],["Isole Ombra"],"COMUNE"],"01SI056":["Insetto frenetico","Quando vengo evocato, fornisci +1|+0 agli altri Ragni alleati e -1|-0 ai nemici per questo turno.","","\"Possono tessere una tela grande quanto un uomo in meno di un minuto... vuoi una dimostrazione?\" - Elise","Unità",["RAGNO"],["Isole Ombra"],"RARA"],"01SI001":["Vendetta","Uccidi un'unità.","","Chi viene tradito invoca Kalista con il suo ultimo respiro, nella speranza che la sua lancia sia foriera di vendetta.","Incantesimo",[],["Isole Ombra"],"COMUNE"],"01SI019":["La scatola","Infliggi 3 a ogni nemico evocato in questo turno.","","\"Nessuno può scappare.\" - Thresh","Incantesimo",[],["Isole Ombra"],"RARA"],"01SI011":["Macellaio famelico","Per giocarmi, uccidi un alleato.","","Sei quel che mangi.","Unità",[],["Isole Ombra"],"COMUNE"],"01SI014":["Spettro della Nebbia","Quando vengo evocato, conferisci +1|+0 agli altri Spettri della Nebbia alleati ovunque.","","Gli spettri delle Isole hanno perso la loro identità molto tempo fa, divenendo un ammasso di pura fame insaziabile.","Unità",[],["Isole Ombra"],"COMUNE"],"01SI022":["Marchio delle Isole","Conferisci +2|+2 ed Effimero a un alleato.","","Potenza, ma a che prezzo?","Incantesimo",[],["Isole Ombra"],"COMUNE"],"01SI006":["Possessione","Ruba un seguace nemico per questo turno (non può essere giocato se possiedi già 6 alleati o monumenti.)","","Si svegliò con un bagliore rosso intorno alle mani, in un campo stranamente silenzioso. ","Incantesimo",[],["Isole Ombra"],"RARA"],"01SI028":["Anima riflessa","Evoca una copia esatta di un alleato. È Effimera e 1|1.","","\"Alzai il corpo dall'acqua, per identificare quella povera anima. Non appena gli misi la mano sulla spalla, si girò e mi mostrò il suo volto. Ed ero... io?\" - Arie Wrence, soldatessa demaciana","Incantesimo",[],["Isole Ombra"],"RARA"],"01SI025":["Atrocità","Uccidi un alleato per infliggere a un bersaglio danni pari al suo Potere.","","Uccidere non ha significato per chi non conosce la morte.","Incantesimo",[],["Isole Ombra"],"RARA"],"01SI046":["Richiamo della Nebbia","Rianima un alleato casuale morto in questo turno.","","\"La Nebbia separa la carne dallo spirito, lasciandosi dietro un'orrenda parodia della vita. Ha corrotto le mie terre, quindi ora vado in quelle isole dannate a porre fine a questa storia.\" - Arie Wrence, Indomita vendicatrice","Incantesimo",[],["Isole Ombra"],"COMUNE"],"01SI050":["Risveglio della nidiata","Evoca 3 Ragnetti, poi conferisci +1|+0 alle unità Ragno alleate.","","Quando si schiudono hanno più fame.","Incantesimo",[],["Isole Ombra"],"RARA"],"01SI016":["Invocatrice degli Spettri","Fedeltà: Evoca 1 Spettro della Nebbia.","","Appare silente, senza far rumore. Gli spettri che la seguono sono molto meno discreti.","Unità",[],["Isole Ombra"],"RARA"],"01SI021":["Biga degli squali","Ultimo respiro: La prossima volta che un alleato Effimero attacca, rianimami come attaccante.","","\"Ha visto cosa? Capisco. La follia è una severa padrona, farmacista. Almeno gli altri hanno un barlume di senno.\"\n- Chirurgo demaciano","Unità",[],["Isole Ombra"],"RARA"],"01SI032":["Storica della Rovina","Gioca: Uccidi un alleato e rianimalo.","","Un tempo sedeva accanto al padre, un lord curatore, mentre studiava i tomi polverosi. Sperava che un giorno avrebbe seguito le sue orme, ma non così.","Unità",[],["Isole Ombra"],"COMUNE"],"01SI058":["Assolutore etereo","Gioca: Uccidi un alleato per evocare un seguace casuale che costa 2 in più.","","Spiriti, prestatemi la vostra voce! Insieme evocheremo l'oscurità sempiterna!","Unità",[],["Isole Ombra"],"RARA"],"01SI054":["Presa dell'immortale","Assorbi 3 da un'unità.","","I morti non desiderano altro che placare l'instancabile battito dei vivi.","Incantesimo",[],["Isole Ombra"],"COMUNE"],"01SI044":["Matrona Spettrale","Gioca: Scegli un alleato nella tua mano. Evocane una copia esatta. È Effimera.","","La Rovina corruppe tutti quelli che la incontrarono. I gentili divennero crudeli. I coraggiosi divennero brutali. La ragione divenne rabbia.","Unità",[],["Isole Ombra"],"EPICO"],"01SI039":["Orrore aracnide","","","Alcuni spiriti malevoli si ispirano alla fauna locale, trasformando la normalità in incubo.","Unità",["RAGNO"],["Isole Ombra"],"COMUNE"],"01SI020":["Il Ravvivatore","Quando vengo evocato, rianima il campione alleato morto più forte.","","A cosa serve una candela morente, se non ad accendere quella successiva?","Unità",[],["Isole Ombra"],"RARA"],"01SI029":["Lamento vanescente","Infliggi 1 a tutti i nemici. Cura di 3 il tuo Nexus.","","Quello che ci uccide ci rende più forti.","Incantesimo",[],["Isole Ombra"],"COMUNE"],"01SI004":["Flagello di Onda atra","","","Alcuni, nel tentativo di fuggire dalla Rovina, provarono a tuffarsi tra le onde, credendo che la corruzione non sarebbe arrivata nelle profondità. Si sbagliavano.","Unità",[],["Isole Ombra"],"COMUNE"],"01SI026":["Preda del Carceriere","Ultimo respiro: Crea nella mano un altro seguace casuale con Ultimo respiro che costa 3 o meno.","","Trattenne l'ultimo respiro il più a lungo possibile, pregando che il carceriere passasse oltre. Non sapeva che la caccia sarebbe stato solo il primo dei tormenti di Thresh.","Unità",[],["Isole Ombra"],"COMUNE"],"01SI040":["Banchetto insidioso","Assorbi 1 salute da un'unità per evocare 1 Ragnetto.","","\"Mia signora! Non sapevo fosse una tale... aracnofila! Forse potrebbe richiamarli? Lady Elise? Per favore?\" - Lord Sassen, Nobile sventurato","Incantesimo",[],["Isole Ombra"],"COMUNE"],"01SI015":["La Rovina","Uccidi TUTTE le unità.","","Incredibile come qualcosa di così puro come l'amore possa provocare una fine tanto crudele e ineluttabile. ","Incantesimo",[],["Isole Ombra"],"EPICO"],"01SI055":["Divoratore d'Anime","","","\"Mentre le nostre navi si avvicinano a quelle coste maledette, mi chiedo: quegli incubi sono nati su queste terre perverse? Hanno mai realmente vissuto?\" - Arie Wrence, soldatessa demaciana","Unità",[],["Isole Ombra"],"RARA"],"01SI047":["Ricordi frammentari","Scegli un seguace. Creane una copia Effimera nella tua mano.","","Per un istante, ricordò. Le chiazze di sole che danzavano sulla sua pelle, le more mature e succose, la dolce melodia della radura cullata dalla brezza. Poi... il nulla.","Incantesimo",[],["Isole Ombra"],"RARA"],"02PZ001":["Sottomiaorino","Quando vengo evocato, pesca 1 carta.\nPoi, se hai giocato almeno 10 altre carte con nomi diversi, conferiscimi +4|+0.","","Nulla poté fermare la sua fuga da quegli smorfiosi umani. Nemmeno un po' d'acqua...","Unità",["FELINO"],["Piltover e Zaun"],"EPICO"],"02PZ010":["Investigatore veterano","Quando vengo evocato, TUTTI i giocatori pescano 1 carta.","","Alcuni agenti si affidano all'istinto per risolvere i casi, altri ai propri agganci. L'agente J.S. Harknor invece si affida solo alla sua scrupolosità e ai documenti. Montagne di documenti.","Unità",["YORDLE"],["Piltover e Zaun"],"COMUNE"],"02PZ006":["Preso!","Quando mi peschi, costo 2 in meno per questo turno.\nInfliggi 3 danni a un'unità.","","\"Ti spiace provare queste manette, Berz?\"\n\"E io cosa ci guadagno?\"\n\"Le puoi tenere.\"\n\"D'accordo.\"\n\"Sei in arresto. Portatelo via!\"","Incantesimo",[],["Piltover e Zaun"],"COMUNE"],"02PZ004":["Spaccaferro","Fornisci +2|+0 a un alleato per questo turno.\nCrea 1 Spaccaferro Fugace nella tua mano.","","\"Lascio la parola alle mie mani.\" - Vi","Incantesimo",[],["Piltover e Zaun"],"RARA"],"02PZ007":["Investigatrice provetta","Quando giochi una carta di costo 2, pesca 1 carta e conferiscile Fugace.","","\"Tutti i detective intervengono, ma i più bravi anticipano. I migliori prevengono.\"\n- Il manuale del Guardiano","Unità",[],["Piltover e Zaun"],"RARA"],"02PZ002":["Zevi, capo meccanicista","Quando peschi una carta, conferiscile Fugace e creane 1 copia esatta nella tua mano.","","A cinque anni, creò il primo pugnale sonico multifrequenza del mondo. Non era molto pratico (lo usava per tagliare i panini), ma la mise sulla strada che l'avrebbe portata al dipartimento delle armi d'élite dei Guardiani.","Unità",[],["Piltover e Zaun"],"EPICO"],"02PZ008":["Vi","Conferiscimi +1|+0 quando giochi un'altra carta mentre sono in gioco o nella mano (massimo +8|+0).","Ho colpito infliggendo 10+ danni in un solo colpo.","\"Agente Vi, per favore! Pensa alla gente! Ai danni collaterali! ALLE SCARTOFFIE PER OGNI FERITO!\"\n- Investigatrice provetta","Unità",[],["Piltover e Zaun"],"Campione"],"02PZ009":["Pista di prove","Crea nella mano una carta casuale di costo 2 delle tue regioni. Costa 2 in meno per questo turno.","","\"E quindi\", annunciò l'agente Harknor, \"gli indizi portano a...\"","Incantesimo",[],["Piltover e Zaun"],"COMUNE"],"02PZ003":["Vestito a festa!","Quando mi peschi, costo 2 in meno per questo turno.\nPorta un alleato a 4|4.","","\"Problemi al porto! Prendi questo, e porgi i miei saluti.\" - Zevi, capo meccanicista","Incantesimo",[],["Piltover e Zaun"],"RARA"],"02PZ005":["Guardiani di pattuglia","Quando veniamo pescati, costiamo 1 in meno per questo turno.","","Lo sprint del guardiano Mir era un tormentone tra gli altri agenti. Il guardiano Kepple non lo capiva.","Unità",[],["Piltover e Zaun"],"COMUNE"],"02BW040":["Anguscio ","","","\"LA MIA PIÙ GRANDE FORSA È FORSE IL MIO COMMANDO DELLA GENTE COMMUNE E FORZE ANCHE L'ORTOGRAFFIA\" - Nota scritta nella sabbia","Unità",[],["Bilgewater"],"COMUNE"],"02BW057":["Cavalcaonde sfuggente","","","\"Giurerei di aver visto delle cose assurde su quegli scogli, capitano. Cos'ha messo quello schifoso nelle arance? Vorrei proprio saperlo...\" - Sottufficiale","Unità",[],["Bilgewater"],"COMUNE"],"02BW041":["Mostro degli Abissi","","","\"Non temere la bestia dannata,\nPerché c'è chi sopravvive ai suoi assalti,\nMa pensa a chi ha spezzato lo scafo\nE quelle povere anime ha affogato?\n- Incisione su una trave in una taverna di Bilgewater","Unità",["MOSTRO MARINO"],["Bilgewater"],"COMUNE"],"02BW013":["Tagliagole insidiosa","","","\"...e l'idiota ha detto che i miei fianchi erano più sinuosi delle onde. Gli ho detto di darci un taglio, o gli avrei tagliato la lingua.\"","Unità",[],["Bilgewater"],"COMUNE"],"02BW034":["Idolo scimmia","Inizio del turno: Infliggimi 2 ed evoca 1 Scimmia da sparo.","","\"Ecco un... souvenir. L'equipaggio l'ha recuperato da un mio vecchio rivale, un folle. A quanto pare, i suoi deliri su poteri antichi e misteriosi avevano un fondo di verità...\"\n- Miss Fortune","Unità",[],["Bilgewater"],"RARA"],"02BW056":["Divoratore abissale","Gioca: Annienta un nemico con meno Salute di me.","","\"L'altro dì, mentre andavo per mare,\ntutt'a un tratto l'ho vista spuntare.\nFuori dalla Baia di Bilgewater ella m'assale,\nl'incredibile Dama del Fondale...\"\n- La Ballata della Dama del Fondale","Unità",["MOSTRO MARINO"],["Bilgewater"],"EPICO"],"02BW060":["Piratessa Occhio di falco","Quando gli alleati attaccano, infliggi 1 al Nexus nemico.","","\"Essere minuti è un gran vantaggio in combattimento. Nessuno si ricorda mai di guardare in basso.\"","Unità",["YORDLE"],["Bilgewater"],"COMUNE"],"02BW011":["Yordle Truffatore","Fedeltà: Sottrai 1 e crea 1 Colpo d'avvertimento nella tua mano.","","\"Sai, gli amici aiutano gli amici. E tu? Mi piace la luce nei tuoi occhi e il luccichio della tua sciabola! Una bellissima sciabola, sì.\"","Unità",["YORDLE"],["Bilgewater"],"RARA"],"02BW030":["Sciacallo dei naufragi","Quando vengo evocato, getta 2 carte e crea 2 Tesori nel tuo mazzo.","","\"Di questi tempi, c'è più tesoro sotto che sopra le onde. Sarebbe roba facile da recuperare, se non fosse per lei.\"\n- Macellaio impietoso","Unità",["MOSTRO MARINO"],["Bilgewater"],"EPICO"],"02BW019":["Axoblob","","","Vivide correnti magiche si agitano nelle coste delle Isole Serpente, nutrendo gli straordinari abitanti del mare.","Unità",[],["Bilgewater"],"COMUNE"],"02BW007":["Giocatrice d'azzardo","Per giocarmi, scarta 2 carte.\nAttacca: Pesca 2 carte e conferisci Fugace a entrambe.","","\"Di solito è un gioco da ragazzi. I tavoli sono pieni di sciocchi che si stonano troppo per concentrarsi sul gioco. Non che mi dispiaccia. I soldi sono soldi e nelle mie tasche stanno meglio.\"","Unità",[],["Bilgewater"],"RARA"],"02BW014":["Creature coralline","Quando vengo evocata, crea nella mano un incantesimo casuale di costo 1 delle tue regioni.","","Le acque basse brulicano di vita marina, ma nulla regge il confronto con l'Azzurra Via. La Via è un luogo magico, ultraterreno, ricco di meraviglie.","Unità",[],["Bilgewater"],"RARA"],"02BW055":["Capomastro impietoso","Saccheggio: Conferisci +1|+0 agli alleati di costo 1 ovunque.","","Quando spara, gli uncini devono muoversi in velocità. Il sangue in acqua attira ospiti di tutti i tipi... e nessuno di loro è gradito.","Unità",[],["Bilgewater"],"EPICO"],"02BW017":["Corriere di agrumi","Saccheggio: Cura di 3 i tuoi alleati e il tuo Nexus, poi prepara l'assalto.","","\"Tutti i marinai si credono dei duri! Grrr di qui, yarrr di là. Sì, sì. Tutto molto bello. Ma ci vogliono le arance! Fanno venire la pelle bella, non fanno cadere i denti e mi rendono felice. Quindi mangia, o finisci in pasto ai pesci. Facile.\"","Unità",[],["Bilgewater"],"RARA"],"02BW038":["Zap Pinnaspruzzo","Quando vengo evocato, pesca dal tuo mazzo un incantesimo che costa 3 o meno.","","Zap riuscì a completare il circuito dell'Azzurra Via in meno di tre minuti. Alla fine ha persino dovuto schivare lo scavo spezzato della Jilldaw! Quel giorno le correnti erano FANTASTICHE.","Unità",[],["Bilgewater"],"EPICO"],"02BW021":["Cacciatore Squamarasoio","Gioca: Conferisci Vulnerabile a un nemico.","","\"Ho sentito che nuota per miglia prima di trovare la sua preda, e quando la trova non manca un colpo. Non so se sia un uomo o un pesce, ma è chiaro che conosce queste acque molto meglio di noi.\" - Macellaio impietoso","Unità",[],["Bilgewater"],"RARA"],"02BW035":["Sceriffo Lariette Rose","Quando vengo evocata, conferisci Vulnerabile a tutti i nemici.","","A Bilgewater non ci sono leggi, ma alcune anime coraggiose non hanno paura di far rispettare la loro idea di giustizia.","Unità",[],["Bilgewater"],"EPICO"],"02BW058":["Macellaio impietoso","Saccheggio: Conferiscimi +1|+1.","","Imbarcarsi sull'Uncino Scheggiato non è roba da poco. I marinai devono dimostrare di sapersi destreggiare sul ponte, in battaglia, e anche in cucina. A volte ci sono stati alcuni che disgustosamente sono riusciti a superare tutte e tre le prove in un colpo solo.","Unità",[],["Bilgewater"],"COMUNE"],"02BW028":["Rex Frantumante","Saccheggio: Gioca Sbarramento d'artiglieria 7 volte su bersagli nemici casuali.","","\"Naviga oltre il marinaio, oltre il relitto,\nLa battaglia è già finita.\nIl fumo ha ripulito l'acqua, il loro capitano ha incontrato Rex,\nE la loro nave è spezzata come un ramoscello.\" \n- \"Torna a casa, Sally\"","Unità",[],["Bilgewater"],"EPICO"],"02BW037":["Occhio degli abissi","Colpisci il Nexus: Pesca 1 carta.","","\"Comandi, urlarono, e ripartirono,\nPer vedere i guai della bella Nashramae,\nMa la natura disse giammai, e in molti morirono,\nIl resto invece incontrerà l'occhio che tutto vede!\"\n- \"L'occhio che tutto vede\"","Unità",["MOSTRO MARINO"],["Bilgewater"],"RARA"],"02BW008":["Sottufficiale","Gioca: Evoca 1 Barile di polvere da sparo o 1 seguace casuale di costo 1.","","Poche cose, scoprì, potevano motivare un marinaio pigro come una miccia accesa.","Unità",["YORDLE"],["Bilgewater"],"RARA"],"02BW047":["Dragafondali","Quando vengo evocato, getta 3.","","Ci vuole un talento speciale per trasformare la spazzatura in attrezzatura da mare. Ma se c'è qualcosa che sanno fare, è quello. Solo quello.","Unità",[],["Bilgewater"],"COMUNE"],"02BW004":["Mozzo della Via del dolore","Quando vengo evocata, evoca 1 Barile di polvere da sparo.","","\"Possiamo affrontarli all'alba, quando l'equipaggio è sveglio e i loro cannoni sono pronti. Oppure gli lasciamo un regalino questa notte, silenziosamente...\"","Unità",[],["Bilgewater"],"COMUNE"],"02BW002":["Via del dolore","Quando vengo evocato, pesca Gangplank.\nRaddoppia tutti i danni inflitti dai tuoi incantesimi, dalle tue abilità e dai tuoi alleati.","","\"Ohhh, ammaina le vele e di' addio al sole,\nPerché arriva la Via del dolore.\nNoi si va nel profondo, dove sazie son le tombe,\nPerché arriva la Via del dolore!\" - \"Arriva la Via del dolore\"","Unità",[],["Bilgewater"],"EPICO"],"02BW016":["Jackbot","Quando vengo evocato o all'Inizio del turno: Conferiscimi +0|+1 per ogni carta che hai pescato lo scorso turno, poi mescola le mie statistiche.","","Un prototipo ha estratto tre bombe e poi è esploso. Ai modelli successivi è stata rimossa quella \"funzionalità\".","Unità",[],["Bilgewater"],"RARA"],"02BW027":["Flotta da caccia","Quando vengo evocato, il tuo avversario evoca 1 Narvalo d'oro.","","L'oro che brilla sotto le onde non è di moneta o di lingotti. È il prezioso corno dell'astuto avversario del capitano della flotta del massacro.","Unità",[],["Bilgewater"],"COMUNE"],"02BW050":["Solista ingannevole","Saccheggio: Riduci di 2 il costo degli alleati nella tua mano e nel mazzo.","","\"Partite per un viaggio musicale! Scoprite canzoni da tutta Runeterra! E ricordate: l'ingresso è a pagamento e le mance sono molto gradite...\" - Promotore dello spettacolo","Unità",[],["Bilgewater"],"RARA"],"02BW015":["La Sirena","Quando vengo evocato, pesca Miss Fortune.\nMentre attacco, tutti i tuoi incantesimi e le tue abilità infliggono 1 danno in più.","","La Sirena è inconfondibile. Le sue candide vele e il legno lucido la rendono elegante come il capitano al timone.","Unità",[],["Bilgewater"],"EPICO"],"02BW010":["Poro saccheggiatore","Saccheggio: Conferiscimi 2 parole chiave casuali.","","\"Il suo ritratto è sulla bacheca delle taglie da una vita, perché è un diavolo avido e spietato che non si fa mettere i piedi in testa da nessuno. La cosa peggiore? È... carino, accidenti a lui.\" - Gangplank","Unità",["PORO"],["Bilgewater"],"COMUNE"],"02BW009":["Asso del biliardo","Quando vengo evocato, pesca 1 carta al prossimo Inizio del turno e conferiscile Fugace.","","\"Per me non ha senso. Stavo andando alla grande, ma l'ultimo non voleva proprio mollare. Non è la mia giornata, suppongo...\" - Giocatrice d'azzardo","Unità",[],["Bilgewater"],"COMUNE"],"02BW005":["Sicario","Quando vengo evocata, conferisci Vulnerabile al nemico più forte.","","\"Saresti tu? Accidenti, una bruttezza oltre ogni aspettativa. Speriamo che la tua testa valga il mio tempo.\"","Unità",[],["Bilgewater"],"COMUNE"],"02BW039":["Cacciatori di jaull","Quando vengo evocato, crea 1 Mostro marino casuale nella tua mano.","","Il richiamo della fortuna attira molti equipaggi lontano dalle acque basse. Quelle povere anime scoprono che il mare può essere terrificante, e in pochi fanno ritorno.","Unità",[],["Bilgewater"],"RARA"],"02BW006":["Mago ingannevole","Gioca: Trasforma un alleato in un seguace casuale di costo 5.","","\"Marvolio? Dove... sono le mie mani?\"\n\"Ora le farò riapparire! Tadà! Ehm. Ta... dà!\"\n\"DOVE SONO LE MIE MANI?!?\"\n\"OK, DEVO ANDARE! GRAZIE INFINITE A TUTTI!\"","Unità",[],["Bilgewater"],"RARA"],"02BW036":["Narvalo d'oro","","","Le leggende narrano di una balena con le corna che provò a derubare la Donna Barbuta. Per punizione la Donna coprì l'avida creatura di oro scintillante, in modo che per sempre avrebbe attratto la cupidigia altrui.","Unità",[],["Bilgewater"],"COMUNE"],"02BW033":["Mercante del mercato nero","Quando peschi una carta nemica, riduci di 1 il suo costo.\nSaccheggio: Sottrai 1.","","\"Se vuoi, ho tutto! Anche della... merce speciale. Ma ricorda, io non ti ho dato niente!\"","Unità",[],["Bilgewater"],"RARA"],"02BW032":["Gangplank","Quando vengo evocato, evoca 1 Barile di polvere da sparo.","Hai danneggiato il Nexus nemico in 5+ turni diversi di questa partita.","\"Non fissarlo troppo a lungo, o se ne accorgerà. E non parlare male di lui, perché sente tutte le voci di Bilgewater. Arriva. Abbassa lo sguardo.\" - Mozzo della Via del dolore","Unità",[],["Bilgewater"],"Campione"],"02BW022":["Miss Fortune","Quando gli alleati attaccano, infliggi 1 a tutti i nemici in battaglia e al Nexus nemico.","Ti ho visto attaccare 4 volte.","\"Miss Fortune? Qui il mio nome è capitana.\"","Unità",[],["Bilgewater"],"Campione"],"02BW046":["Fizz","Quando giochi un incantesimo, ferma tutti gli incantesimi e le abilità del nemico che hanno me come bersaglio e forniscimi Elusione per questo turno.","Hai giocato 6+ incantesimi.","Di tutte le figure leggendarie di Bilgewater, Fizz è la più mutevole. Alcuni marinai danno a lui la colpa per i tanti relitti che si trovano lungo la costa...","Unità",["YORDLE"],["Bandle City","Bilgewater"],"Campione"],"02BW026":["Twisted Fate","Gioca: Gioca una carta Destino.","Ti ho visto pescare 9 carte.","\"Ora guarda le mani, conta le carte e prova a starmi dietro. E ricorda...\"","Unità",[],["Bilgewater"],"Campione"],"02BW053":["Nautilus","","Quando sei in Profondità. Quando aumento di livello, copia gli alleati gettati di costo 4+ nel tuo mazzo.","\"È stata un'ancora ad affondare la Rancour. Ha portato giù Finn e tutto il resto. Siamo rimasti in pochi, ma la notte si avvicina... e anche il freddo. Scusa, mamma. Avevi ragione tu. Il Titano è ancora vivo.\" - Appunto ritrovato","Unità",[],["Bilgewater"],"Campione"],"02BW061":["Assi nella manica","Quando mi peschi, costo 1 in meno per questo turno.\nConferisci +2|+1 a un alleato.","","\"Il segreto per accumulare un bel gruzzolo è avere sempre una buona mano.\" - Twisted Fate","Incantesimo",[],["Bilgewater"],"COMUNE"],"02BW024":["Guai doppi","Evoca 2 seguaci casuali di costo 1.","","\"Ehi Gav, non è quello il tizio che stiamo cercando? Sembra che abbia trovato un amico.\"\n\"Ma quello... è un uomo squalo, Baz?\"\n\"È anche un sacco di oro in più, socio. Forza...\" - Baz e Gav, aspiranti cacciatori di taglie","Incantesimo",[],["Bilgewater"],"RARA"],"02BW003":["Maniere forti","Saccheggio: Richiama QUALSIASI seguace nella tua mano.","","\"Ora lavori per noi!\" - Sottufficiale","Incantesimo",[],["Bilgewater"],"RARA"],"02BW025":["Evocazione acquatica","Conferisci Vulnerabile a un nemico ed evoca Zannalunga.","","\"Squalo!\" - Fizz","Incantesimo",[],["Bilgewater"],"COMUNE"],"02BW012":["Più polvere!","Evoca 2 Barili di polvere da sparo.","","\"Barile!\" - Gangplank","Incantesimo",[],["Bilgewater"],"COMUNE"],"02BW018":["Parrrlé","Infliggi 1 a un bersaglio.\nSe muore, infliggi 1 al Nexus nemico.","","L'idea di mediazione di Gangplank è solitamente breve e sanguinosa.","Incantesimo",[],["Bilgewater"],"COMUNE"],"02BW048":["Evasione","Evoca un seguace casuale di costo 1.","","\"Che ne dici, Baz? Non mi sembra tanto forte.\"\n\"Dici, Gav? È scappato dalla prigione...\"\n\"Vuol dire che è astuto, non forte. Andiamo!\" - Baz e Gav, aspiranti cacciatori di taglie","Incantesimo",[],["Bilgewater"],"COMUNE"],"02BW043":["Scegli una carta","Per giocarmi, metti nel tuo mazzo una carta dalla tua mano.\nPesca 2 carte al prossimo Inizio del turno e conferisci loro Fugace.","","\"La mia non è solo fortuna.\" - Twisted Fate","Incantesimo",[],["Bilgewater"],"RARA"],"02BW051":["Giocoso/Ingannatore","Rimuovi dal combattimento un alleato attaccante per preparare l'assalto.","","\"Sono un guizzo avanti a tutti.\" - Fizz","Incantesimo",[],["Bilgewater"],"RARA"],"02BW054":["Frantumazione terrena","Stordisci un nemico.\nMescola quell'unità nel mazzo avversario se hai 1 Nautilus.","","\"Trasciniamoli a fondo...\" - Nautilus","Incantesimo",[],["Bilgewater"],"RARA"],"02BW042":["Fusione mentale","Per questo turno, porta Potere e Salute degli alleati al numero di altri incantesimi che hai giocato in questa partita.","","Le correnti e le maree intorno a Bilgewater sono temute per la loro forza e la loro imprevedibilità. Nessun marinaio, però, ne conosce il vero potere.","Incantesimo",[],["Bilgewater"],"EPICO"],"02BW059":["Salva esplosiva","Getta 3.\nInfliggi 7 a un'unità.","","\"Se vanno a fondo, ne è valsa la pena.\" - Detto di Bilgewater","Incantesimo",[],["Bilgewater"],"RARA"],"02BW023":["Fascino delle profondità","Riduce di 1 il costo dei Mostri marini alleati ovunque.\nPesca un Mostro marino.","","I marinai mormorano dei giorni bui che ci attendono, quando il mare ribollirà e orrori inenarrabili emergeranno dai flutti.","Incantesimo",[],["Bilgewater"],"RARA"],"02BW031":["Doppio colpo","Infliggi 2 a un nemico.\nSe muore, infliggi 4 al Nexus nemico.","","\"Sparo sempre per prima.\" - Miss Fortune","Incantesimo",[],["Bilgewater"],"RARA"],"02BW029":["Recupero","Getta 2.\nPesca 2 carte.","","I detriti non galleggiano a lungo. I marinai esperti sanno distinguere i carichi di valore dalla robaccia...","Incantesimo",[],["Bilgewater"],"COMUNE"],"02BW049":["Merce rubata","Sottrai 1.\nSaccheggio: Sottrai 1.","","Quel che è mio è mio, quel che è tuo... è mio.","Incantesimo",[],["Bilgewater"],"COMUNE"],"02BW001":["Ti ho avvisato","Fornisci Vulnerabile a un nemico per questo turno. Se muore in questo turno, pesca 1 carta.","","\"Su la testa e su il morale, giovane! Se ti vede così il capitano, ti issa, ti apre come una sardina e ti dà in pasto ai gabbiani. E ora muovi le chiappe!\" - Mozzo della Via del dolore","Incantesimo",[],["Bilgewater"],"COMUNE"],"02BW063":["Mano svelta","Saccheggio: Pesca una carta non-campione casuale dalla mano del nemico.","","\"Nelle carte non conta la fortuna, contano le persone. Se riesci a far dubitare l'avversario di se stesso, praticamente l'hai già lasciato in mutande.\" - Twisted Fate","Incantesimo",[],["Bilgewater"],"RARA"],"02BW045":["Pioggia di piombo","Infliggi 1 a tre nemici casuali diversi o al Nexus nemico.","","\"Fuoco a volontà.\" - Miss Fortune","Incantesimo",[],["Bilgewater"],"COMUNE"],"02BW020":["Colpo d'avvertimento","Infliggi 1 al Nexus nemico.","","\"Dovevi sparare con noi! Lo sai cos'è una salva?\" - Sottufficiale","Incantesimo",[],["Bilgewater"],"COMUNE"],"02BW044":["Buttare a mare","Getta 4.","","\"Se non vale il suo peso, lo buttiamo in mare. Lo stesso vale per voi. E ora, al lavoro!\" - Sottufficiale","Incantesimo",[],["Bilgewater"],"RARA"],"02BW062":["Navigatrice delle isole","Quando vengo evocata, evoca un seguace casuale di costo 1 da qualunque regione e conferiscigli Esploratore.","","\"Innalza la luce della Madre Serpente\nfino alle nuvole, sopra le onde.\nIl cielo con occhi grigi ci osserva\nriflettendo placidamente il suo sguardo.\nElla sorride, è in pace...\"\n- Preghiera a Nagakabouros","Unità",[],["Bilgewater"],"RARA"],"02FR009":["Cavalcalupi","Saccheggio: Ottieni una gemma di mana vuota.","","I giovani cavalieri dell'Artiglio d'Inverno ricevono un cucciolo di lupo sin dal momento in cui riescono a tenere un'arma in mano. La loro formazione orbita interamente intorno alla battaglia. Il lupo viene addestrato a divorare e mutilare, il cavaliere a saccheggiare e rubare.","Unità",[],["Freljord"],"COMUNE"],"02FR004":["Morsa del gelo","Infliggi Congelamento e fornisci Vulnerabile a un nemico per questo turno.","","\"Questi sangue caldo non durerebbero un giorno nel Freljord!\" - Sejuani","Incantesimo",["ELEMENTALE"],["Freljord"],"RARA"],"02FR002":["Sejuani","Gioca: Congela e fornisci Vulnerabile a un nemico per questo turno.","Hai danneggiato il Nexus nemico in 5+ turni diversi di questa partita.","Anche se il suo flagello di Vero Ghiaccio è formidabile, è Sejuani stessa a essere un'arma: forgiata nel freddo del Freljord, messa alla prova dal clima glaciale.","Unità",[],["Freljord"],"Campione"],"02FR001":["Vergine ardente","Inizio del turno: Infliggi 1 a TUTTO.","","\"Areranno i loro fertili campi,\nDebolmente pianteranno i loro semi.\nNoi tutto daremo alle fiamme,\nL'Artiglio d'Inverno prende ciò che vuole!\"\n- Filastrocca per bambini sull'Artiglio d'Inverno","Unità",[],["Freljord"],"RARA"],"02FR005":["Urside sciamano","Saccheggio: Mi trasformo in Urside artiglio del tuono.","","Gli Ursidi nacquero come umani, ma abbandonarono la loro vita mortale per quella ferale, con il potere selvaggio donato dal grande spirito del Volibear.","Unità",[],["Freljord"],"COMUNE"],"02FR010":["Bottino condiviso","Conferisci +1|+1 alle prime 3 unità nel tuo mazzo.\nSaccheggio: Pescane 1.","","\"Bisogna condividere.\" - Cavaliere spietato","Incantesimo",[],["Freljord"],"RARA"],"02FR008":["Zanna predatrice","Quando vengo evocato, pesca Sejuani.\nSaccheggio: Raddoppia Potere e Salute degli alleati nel tuo mazzo.","","\"Quando la primavera ci porta un tempo abbastanza mite da piantare qualcosa, arrivano anche le barcacce... e il grano, da abbondante, si fa scarso.\" - Guardia Interna Avarosana","Unità",[],["Freljord"],"EPICO"],"02FR007":["Furia del nord","Fornisci +3|+4 a un alleato per questo turno.","","\"Accogli la tua bestia interiore!\" - Sejuani","Incantesimo",[],["Freljord"],"COMUNE"],"02FR006":["Predone spietato","","","L'Artiglio d'Inverno non conosce eguali nel Freljord, e tutti conoscono la ferocia dei suoi razziatori. Quando la sete di sangue prende il sopravvento, il meglio in cui si può sperare è una morte rapida.","Unità",[],["Freljord"],"COMUNE"],"02FR003":["Aurora Porealis","Crea nella mano 2 Poro casuali e 2 Poro-Snax.","","\"Quando esprimi un poro desiderio,\nE guardi il firmamento,\nVedrai gli snax tra le stelle,\nCome stelle nei tuoi occhi\" - La piccola Ingvar","Incantesimo",[],["Freljord"],"EPICO"],"02NX001":["Leviatano","Quando vengo evocato, pesca Swain.\nInizio del turno: Infliggi due volte 1 al Nexus nemico.","","Quando gli ioniani la videro all'orizzonte, pensarono a un mostro. Non si sbagliavano poi di tanto... La nave d'acciaio era terrificante. Era l'apice dell'ingegneria navale noxiana.","Unità",[],["Noxus"],"EPICO"],"02NX007":["Swain","Colpisci il Nexus: Infliggi 3 al Nexus nemico.","Hai inflitto 14+ danni fuori dal combattimento.","\"Un potere che va oltre la comprensione mortale mi ha donato la visione su ciò che i più non vedono. Scruto nell'oscurità che gli altri temono.\"","Unità",[],["Noxus"],"Campione"],"02NX006":["Spaccamura","Inizio del turno: Infliggi 1 al Nexus nemico.","","La voce dell'anziano era stranamente calma. \"Che senso ha, di grazia, accumulare pietre per costruire muri più alti, quando i noxiani riescono sempre ad abbatterli?\"","Unità",[],["Noxus"],"RARA"],"02NX002":["Aurok Splendicorno ","Attacca: Stordisci tutti i nemici danneggiati.","","\"Per generazioni siamo stati sottomessi. Solo ora che Noxus ha preso le nostre terre abbiamo capito il senso della libertà. Per questo lotterò per l'impero.\"","Unità",[],["Noxus"],"EPICO"],"02NX009":["Stormo famelico","Infliggi 4 a un'unità se è danneggiata o Stordita.","","Ascolta. Riesci a sentirlo? Il rombo di migliaia di ali che battono.","Incantesimo",[],["Noxus"],"RARA"],"02NX004":["Demolitrice imperiale","Gioca: Infliggi 1 a un alleato per infliggere 2 al Nexus nemico.","","\"Rapido e silenzioso, fino al botto.\"","Unità",[],["Noxus"],"COMUNE"],"02NX003":["Fervore di Noxus","Infliggi 3 a un alleato per infliggere 3 a un qualsiasi bersaglio.","","\"Sono necessari dei sacrifici.\" - Jericho Swain","Incantesimo",[],["Noxus"],"COMUNE"],"02NX010":["Cavalcazanne corazzato","I nemici con 4 o meno Potere non possono infliggermi danni.","","\"Non c'è modo di fermare una bestia da guerra quando parte. Meglio farsi da parte.\" - Cavaliere del Basilisco","Unità",[],["Noxus"],"RARA"],"02NX008":["Mano della morte","Infliggi 2 a un nemico e 1 al Nexus nemico.","","\"Cerca di morire con dignità.\" - Swain","Incantesimo",[],["Noxus"],"COMUNE"],"02NX005":["Balista di ferro","","","\"Un assedio è facile con gli strumenti giusti. I carri per attirarli allo scoperto, le baliste per devastarli.\" - Ingegnere d'assedio","Unità",[],["Noxus"],"COMUNE"],"02DE003":["Tassorso fedele","","","È vero quello che dicono: l'animale somiglia al padrone.","Unità",[],["Demacia"],"COMUNE"],"02DE008":["Compagno Grancorno","","","Una recluta dei ranger trascorre mesi nella foresta con i suoi compagni, imparando a prevedere ogni mossa del suo cervo. Deve essere paziente ma, una volta formato il legame, nulla li può separare.","Unità",[],["Demacia"],"COMUNE"],"02DE004":["Guardiano di Zannaverde","","","\"Giuro solennemente di proteggere questa foresta e tutti coloro che vi si rifugiano.\"","Unità",["ÉLITE"],["Demacia"],"COMUNE"],"02DE006":["Quinn","Quando vengo evocata, evoca Valor.","Ti ho visto attaccare 4 volte.","\"La nostra Quinn è sempre stata un'impavida cavalier-ranger, e con Valor al suo fianco nei cieli formano una coppia inarrestabile.\" - Genevieve Cuordolmo, cavalier-ranger","Unità",[],["Demacia"],"Campione"],"02DE009":["Ranger brizzolato","Ultimo respiro: Evoca 1 Tassorso fedele.","","Betrand ha cominciato negli scout di Bandle. Ha tutti i distintivi, tranne quello per \"Carattere allegro\".","Unità",["YORDLE"],["Demacia"],"RARA"],"02DE005":["Spirito incrollabile","Conferisci a un alleato ''Non posso subire danni o morire''.","","Ignorando il dolore alla gamba ferita, la ranger si mise di nuovo in piedi, impugnando saldamente la spada. Non era solo la sua determinazione a sostenerla, ma quella di tutta Demacia.","Incantesimo",[],["Demacia"],"EPICO"],"02DE002":["Assalto accecante","Evoca Valor.","","\"Ce l'ho nei capelli! CE L'HO NEI CAPELLI!\"\n- Predone della Legione","Incantesimo",[],["Demacia"],"RARA"],"02DE010":["Genevieve Cuordolmo","Quando vengo evocata, fornisci +1|+1 agli altri alleati per questo turno.","","Vedere i ranger di Demacia in battaglia è straordinario. Combattono come una cosa sola, uomo e animale, fianco a fianco, determinati e inseparabili.","Unità",[],["Demacia"],"EPICO"],"02DE007":["Determinazione del ranger","Fornisci Tenacia agli alleati per questo turno.","","\"Quando il nemico si avvicina, non lasciate che la paura entri nel vostro cuore, perché saranno gli alberi a proteggerci.\" - Guardiano di Zannaverde","Incantesimo",[],["Demacia"],"RARA"],"02DE001":["Colpo coordinato","Scegli un nemico. 2 alleati lo colpiscono, uno dopo l'altro.","","\"Con me, come un sol uomo!\" - Guardiano di Zannaverde","Incantesimo",[],["Demacia"],"COMUNE"],"02SI005":["Assorbi magia","Getta 3.\nCura di 3 gli alleati.","","\"Queste isole verranno purificate.\" - Maokai","Incantesimo",[],["Isole Ombra"],"RARA"],"02SI010":["Fiormorto vagabondo","Quando vengo evocato, getta 3.","","\"Il grande treant continua a mostrare... creature. Questa... diffondere vita mentre vaga... in modo rimarchevole... qui. Sono davvero Isole Benedette!\" - Diario ritrovato","Unità",[],["Isole Ombra"],"COMUNE"],"02SI008":["Maokai","Ogni turno, la prima volta che evochi un altro alleato, Getta 2 ed evoca 1 Germoglio.","Le tue unità sono morte o le tue carte sono state gettate 25+ volte.","Maokai non si sarebbe fatto piegare da quelle terre maledette. La sua determinazione era troppo radicata, la sua furia troppo bruciante. Nulla gli avrebbe sbarrato la strada.","Unità",[],["Isole Ombra"],"Campione"],"02SI007":["Rospo spinoso","Ultimo respiro: Getta 2 e cura di 2 il tuo Nexus.","","\"...specie notevole... stessa creatura che ho visto da piccolo... non sembra passato un giorno! Chissà... prossima città. Magari questi splendidi esseri possono vivere per sempre!\" - Diario ritrovato","Unità",[],["Isole Ombra"],"COMUNE"],"02SI003":["Terrore delle maree","Gli alleati Mostro marino hanno Temibile.\nAttacca: Fornisci -2|-0 ai nemici per questo turno.","","Si resero conto del pericolo troppo tardi. L'enorme bestia spalancò le fauci e si lanciò verso di loro. I cacciatori non poterono far altro che attendere la fine mentre un'infinita distesa di denti sgranocchiava lentamente l'imbarcazione.","Unità",["MOSTRO MARINO"],["Isole Ombra"],"EPICO"],"02SI001":["Collezionista di Mairadura","Quando un altro alleato muore, assorbi 1 dal Nexus nemico.","","\"Ho incontrato Niven questo... il nuovo traghettatore! Ci ha portati... in... Ha una voce niente male! Prima... dovrei invitarlo a cena, uno di questi giorni.\" - Diario ritrovato","Unità",[],["Isole Ombra"],"RARA"],"02SI002":["Strampicante ipertrofica","Quando giochi un seguace, uccidilo per evocare 1 Strampicante ipertrofica.","","\"Oggi... un'altra interessante... è venuta a galla... bambini si sono spaventati. Però... nessuna minaccia. Si è strofinata... creatura fiduciosa. Devo dargli altre bacche!\"\n- Diario ritrovato","Unità",[],["Isole Ombra"],"EPICO"],"02SI004":["Custode sventurato","Gioca: Uccidi un alleato per evocare 2 Germogli.","","\"Ogni cuore è un giardino in cui si possono mettere radici!\"","Unità",[],["Isole Ombra"],"RARA"],"02SI006":["Atrocorteccia","La prima volta che un alleato muore, conferiscimi +2|+2.","","La fame ha costretto le creature delle Isole Ombra a sbarazzarsi dei sentimentalismi molto tempo fa.","Unità",[],["Isole Ombra"],"COMUNE"],"02SI009":["Lancio verde","Evoca 1 Germoglio al prossimo Inizio del turno.","","\"Wiiiii!\" - Germoglio","Incantesimo",[],["Isole Ombra"],"COMUNE"],"02IO008":["Onda sonica","Fornisci Sfidante a un alleato per questo turno.\nCrea 1 Colpo risonante Fugace nella tua mano.","","\"Impara a dominare te stesso...\" - Lee Sin","Incantesimo",[],["Ionia"],"COMUNE"],"02IO002":["Squame di drago","Quando vengo evocato, crea 1 Protezione del drago nella tua mano.","","\"Uno studente deve agire con compassione, poiché il Drago nutrì le Terre Antiche, donando loro il tepore e la vita.\" - Insegnamenti del Drago","Unità",[],["Ionia"],"COMUNE"],"02IO006":["Lee Sin","Quando giochi un incantesimo, forniscimi Sfidante per questo turno.\nSe ne giochi un altro, forniscimi Barriera per questo turno.","Hai giocato 8+ incantesimi.","\"Il Drago aiuta i degni. Dona vigore agli esausti, conforto ai malati, luce agli smarriti. A chi è scosso, equilibrio...\"","Unità",[],["Ionia"],"Campione"],"02IO004":["Corna del drago","","","\"Uno studente deve impegnarsi con tutta la sua forza, poiché il Drago tirò fuori la terra da sotto le onde, dandoci un suolo da chiamare casa.\" - Insegnamenti del Drago","Unità",[],["Ionia"],"COMUNE"],"02IO003":["Occhio del drago","Inizio del turno: Flusso: Evoca 1 Cucciolo di drago.","","\"Uno studente deve pensare in modo lucido, poiché il Drago trascina il sole nei nostri cieli, rivelando il mondo intorno a noi.\"\n- Insegnamenti del Drago","Unità",[],["Ionia"],"EPICO"],"02IO001":["Artigli del drago","Quando sono nella mano, evocami se giochi 2 incantesimi in un turno.","","\"Uno studente deve ascoltare concentrato, poiché fu il Drago a emettere i primi suoni, benedicendo i nostri giovani spiriti con il dono della magia.\" - Insegnamenti del Drago","Unità",[],["Ionia"],"COMUNE"],"02IO005":["Palmo stordente","Stordisci un nemico per evocare 1 Coda del drago.","","\"Non mi avete visto partire, né mi vedrete tornare.\"\n- Coda del drago","Incantesimo",[],["Ionia"],"RARA"],"02IO010":["Ritirata","Richiama un alleato per creare 1 Ritorno Fugace nella tua mano.","","I noxiani che misero piede sulle spiagge di Ionia trovarono un nemico debole e impreparato. In tanti furono massacrati, ma alcuni riuscirono a mettersi in salvo...","Incantesimo",[],["Ionia"],"RARA"],"02IO007":["Furia del dragone","Un alleato scaglia un nemico contro il suo Nexus, colpendo prima il nemico e poi il Nexus.\nSe il nemico sopravvive, richiamalo.","","\"Il Drago deve essere scatenato, o mi consumerà dall'interno.\" - Lee Sin","Incantesimo",[],["Ionia"],"EPICO"],"02IO009":["Meditazione profonda","Flusso: Costo 2 in meno.\nPesca altri 2 incantesimi.","","La meditazione è un lungo viaggio senza destinazione, che si può seguire solamente perdendosi lungo la via.","Incantesimo",[],["Ionia"],"RARA"],"03NX019":["Caccia al debole","Il tuo nemico scarta il seguace più debole dalla mano.","","\"Il mondo non è un posto per fragili. Ogni giorno porta un nuovo tormento, un altro giro della morsa. Io non dispenso morte, ma pietà.\" - Arrel la Braccatrice","Incantesimo",[],["Noxus"],"RARA"],"03NX022":["Artigli selvaggi","Un alleato colpisce un nemico. Se possiede Sopraffare, i danni in eccesso vengono inflitti al Nexus nemico.","","\"Oooh! Il selvaggio oggi sembra particolarmente feroce! State alla larga da quelle unghiette!\" - Annunciatore dell'Arena","Incantesimo",[],["Noxus"],"EPICO"],"03NX007":["Riven","Quando vengo evocata, se hai il gettone d'attacco, o quando ottieni il gettone d'attacco, Riforgia.","Hai creato Lama dell'esiliato.","\"Non scapperò da ciò che ero. Ho promesso di riparare ciò che ho infranto...\"","Unità",[],["Noxus"],"Campione"],"03NX006":["Elsa dell'arma","Fornisci +2|+0 a un alleato per questo turno. Riforgia.","","\"Per conoscere il tuo nemico, prima devi conoscere la sua arma. Ti dirà come si muove, cosa pensa e quando attaccherà. È la più pura espressione del suo portatore.\" - Arrel la Braccatrice","Incantesimo",[],["Noxus"],"COMUNE"],"03NX002":["Arrel la Braccatrice","Fine del turno: Se hai giocato un incantesimo su di me in questo turno, colpisco il nemico più debole.","","\"Nasconditi e ti troveremo.\nRespira e ti sentiremo.\nScappa e ti uccideremo.\"","Unità",[],["Noxus"],"EPICO"],"03NX018":["Arresto","Stordisci un nemico.\nSe hai Darius, prepara l'assalto.","","\"Me ne occupo io.\" - Darius","Incantesimo",[],["Noxus"],"RARA"],"03NX009":["Cavalcatrice furiosa","","","\"Non c'è niente come dare la caccia a un altro soldato. Per seguirne le tracce, devi pensare come lui. Per prenderlo, non devi avere paura di essere preso. Devi temerlo come lui teme te. È un legame che pochi possono conoscere, ma che assaporo più di qualsiasi altra cosa.\"","Unità",[],["Noxus"],"COMUNE"],"03NX017":["Fiutasangue del Basilisco","Gioca: Infliggi 1 a un alleato e a un nemico 4 volte.","","Gli addestratori di basilischi non danno cibo vivo alle loro belve nei giorni prima di una battaglia. Quando vengono scatenate non fanno distinzione fra amici e nemici, e diventano inarrestabili.","Unità",["RETTILE"],["Noxus"],"EPICO"],"03NX015":["Abilità di sopravvivenza","Gli alleati non possono scendere sotto 1 di Salute in questo turno.\nQuando vengo scartata, il tuo alleato più forte non può scendere sotto 1 di Salute per questo turno.","","\"I mastini draconici hanno fiutato il suo odore. La troveremo e metteremo fine a questa storia. Non c'è altro modo.\" - Arrel la Braccatrice","Incantesimo",[],["Noxus"],"RARA"],"03NX014":["Determinazione affilata","Fornisci +3|+2 a un alleato per questo turno.","","\"Sì, riparerò le tue armi, mi occuperò dei cavalli e cucinerò il tuo dannato cibo. Cos'altro saprò fare, d'altro canto?\" - Erath, scudiero della lama","Incantesimo",[],["Noxus"],"COMUNE"],"03NX003":["Scudiero della lama","Ultimo respiro: Riforgia.","","\"Come ha detto la cacciatrice, cento giorni e cento notti. Cento vesciche sotto i piedi, cento insetti nella mia colazione, cento lame di qui e cento vendette di lì. E ben più di cento angherie da quei tre, te lo dico io...\" ","Unità",[],["Noxus"],"COMUNE"],"03NX001":["Tessitrice di rune","Quando vengo evocata, Riforgia.","","\"Molte armi sono strumenti rozzi che non valgono più delle mani che le brandiscono. Ma un'arma intrisa di magia runica è molto più che semplice acciaio.\"","Unità",[],["Noxus"],"COMUNE"],"03NX005":["Cacciatrice brutale","Quando vengo evocata, forniscimi Attacco rapido per questo turno.","","\"Eccoti. SAPEVAMO che non saresti venuto senza combattere. O almeno, lo speravamo.\"","Unità",[],["Noxus"],"RARA"],"03BW006":["Jack il Vincitore","Inizio del turno: Crea 1 Dormi coi pesci nella tua mano.","","Gli anni trascorsi sul ring hanno insegnato a Jack molte lezioni preziose. Ha imparato che se il suo avversario sanguina allora può anche tremare. Ha imparato la forza di uno sguardo silenzioso e quello della violenza incontrollata.","Unità",[],["Bilgewater"],"EPICO"],"03BW010":["Brunch nel bayou","Un alleato cattura un altro alleato e ottiene le statistiche dell'alleato catturato.","","\"Entra, amico, e tutto ciò che desideri sarà per sempre tuo.\" - Tahm Kench","Incantesimo",[],["Bilgewater"],"COMUNE"],"03BW005":["Costo nascosto","Mescola un'unità o un monumento nel suo mazzo.","","\"Ora, ti ho dato esattamente ciò che volevi, amico. Non ho mai detto che sarebbe durato per sempre.\" - Tahm Kench","Incantesimo",[],["Bilgewater"],"RARA"],"03BW004":["Tahm Kench","Quando vengo evocato o all'Inizio del turno: Crea 1 Gusto acquisito nella tua mano.","Ho catturato 3+ unità. Quando aumento di livello, annienta i miei nemici catturati e libera i miei alleati.","\"Amico mio, conosco quell'espressione. Senti che le carte che hai in mano non sono quelle che meriti. Desideri cose migliori, vero? Forse sarai disposto a consentirmi di saziare la tua fame, facendoti assaggiare tutto ciò che hai mai desiderato. Mi serve solo il tuo nome, scritto su questo foglio... e tu, amico mio, sarai soddisfatto a vita.\"","Unità",[],["Bilgewater"],"Campione"],"03BW002":["Tipo viscido","Inizio del turno: Infliggimi 2.","","\"Ah, la gente è stupida! Basta darle una bevanda fresca e una sedia al caldo, e racconta tutti i suoi segreti ai volti amichevoli. E chi ha un volto più amichevole del giovane Leonard, eh?\" - Scienide veggente","Unità",[],["Bilgewater"],"COMUNE"],"03BW014":["Scimmiottando","Evoca 1 Scimmia da sparo.\nSaccheggio: Evoca ancora 1 all'inizio del prossimo turno.","","\"Oh, le trovi carine? BEH, NON LO SONO. Si infilano dappertutto, sporcano come gabbiani col mal di mare e NON CHIUDONO MAI IL BECCO. NIENTE SCIMMIE A BORDO. FINE DELLA STORIA.\" - Sottufficiale","Incantesimo",[],["Bilgewater"],"COMUNE"],"03BW007":["Polpugile","Gioca: Infliggimi 3.","","\"Certo, Pablo sarà anche un po' a secco in questo periodo, e sì, ha preso la sua buona dose di pugni... ma sai cosa? Non c'è nessun altro qui, che fa delle uccisioni ottuple.\" - Tipetto saggio","Unità",[],["Bilgewater"],"COMUNE"],"03BW016":["L'Esplosiva","Infliggi 1 a un'unità.\nEvoca un numero di Barili di polvere da sparo pari ai danni inflitti.","","\"Il giovane Gerent fece suonare l'allarme appena prima dell'esplosione. Lo scafo oscillò pericolosamente e il fiocco prese fuoco, ma la Jilldaw non affondò. Pensavo che fosse finita lì, ma seguendo lo sguardo di Gerent vidi quattro barche a remi dirette verso di noi, tutte cariche di polvere da sparo.\" - Sopravvissuto della Jilldaw","Incantesimo",[],["Bilgewater"],"RARA"],"03BW001":["Moli del sangue","Inizio del turno: Getta 1. Se sei in Profondità, distruggimi per evocare un Mostro marino casuale.","","Ogni giorno, la gente del luogo vaga per i Moli del sangue per vedere gli orrori pescati dalle profondità dai cacciatori di Bilgewater. I mostri sono solitamente morti. Solitamente.","Monumento",[],["Bilgewater"],"EPICO"],"03BW015":["Vecchio crostoso","Gioca: Infliggimi 2.","","\"TI MUOVI A SUONARE IL GONG? SPIEGHERÒ A QUEL FETIDO IRSUTO COME HO GUADAGNATO I MIEI SOPRANNOMI. PABLO OTTO PUGNI, IL KRAKEN CHE SCROCCHIA, IL TERRORE TENTACOLARE! I TUOI PICCOLI PUNGIGLIONI CHIAMERANNO LA MAMMA, QUANDO AVRÒ FINITO CON TE.\" - POLPUGILE","Unità",[],["Bilgewater"],"COMUNE"],"03BW003":["Tipetto saggio","Gioca: Infliggi 1 a tutti gli altri alleati e conferiscimi +1|+0 per ognuno di loro.","","L'ascesa al potere è spesso una questione violenta... ma di solito non è così sguaiata.","Unità",[],["Bilgewater"],"RARA"],"03BW017":["Gorgopesce serpeggiante","Costo 1 in meno per ogni incantesimo che hai giocato in questa partita.\nQuando vengo evocato, crea nella mano un incantesimo casuale di costo 1 delle tue regioni.","","\"Sull'attenti, nouellino! La tua mishone è infiltuarti dietuo le linee nemiche, piazzaue più bolle che puoi e dirci tutto quello che vedi! TUTTO. HAI CAPITO?\" - Ammiwaglio Shelly, Anguscio","Unità",[],["Bilgewater"],"EPICO"],"03BW008":["Scienide veggente","Gioca: Infliggi 1 a me e a un alleato per pescare 1 carta.","","\"La vecchia Babs ha fatto qualche errore. Ha ucciso un po' di gente del posto ai suoi tempi, ma questo le dà un'aura di autenticità.\" - Tipo viscido","Unità",[],["Bilgewater"],"COMUNE"],"03BW020":["Delirio scimmiesco","Evoca 1 Scimmia da sparo tante volte quante hai attivato Saccheggio in questa partita.","","\"Oh, quelle palle di pelo non sono così male. Ti svelo un segreto: adorano i fuochi d'artificio. Una volta colpita la santabarbara del nemico, le scimmie penseranno al resto.\" - Miss Fortune","Incantesimo",[],["Bilgewater"],"EPICO"],"03BW009":["Estorsione","Infliggi 2 a un alleato per conferire Vulnerabile a 2 nemici.","","\"Hai intenzione di dirmi dove hai preso quei due barili in più, Slim? Eh? Altrimenti, possiamo giocare al tiro alla fune con la tua lingua e il braccio di Jimbo. E fidati... non scommetterei su di te.\" - Tipetto saggio","Incantesimo",[],["Bilgewater"],"RARA"],"03DE010":["La Grande piazza","Quando viene evocato un alleato, forniscigli +1|+1 e Sfidante per questo turno.","","Tianna guardò il raduno di soldati, scrutandone le file. L'unico rumore nella piazza era il garrire dello stendardo nella brezza. Fece un cenno di approvazione, poi sollevò lo stendardo con un urlo: \"Chi, di voi, è pronto a combattere per Demacia?\" L'urlo che ricevette in risposta sembrò quasi far tremare le montagne.","Monumento",[],["Demacia"],"EPICO"],"03FR009":["Abisso ululante","Inizio del turno: Crea nella tua mano un campione casuale di livello 2 che non sia nella tua mano, nel mazzo o in gioco.","","Gli eroi giungono al ponte, chiamati da qualcosa di ignoto. Affrontano il suo freddo spietato e il suo passaggio in rovina per vedere cosa li attende oltre. Vittoria o morte.","Monumento",[],["Freljord"],"EPICO"],"03MT005":["Vie divergenti","Pesca un Monumento o distruggi un Monumento.","","Targon è un luogo bizzarro, dove l'infrangibile può essere rotto e il rotto può essere ricomposto.","Incantesimo",[],["Targon"],"COMUNE"],"03SI009":["Cripte di Helia","Inizio del turno: Se puoi, uccidi il tuo alleato più costoso per evocare un alleato che costa 1 in più dal tuo mazzo.","","Cosa potrebbe attirare un'anima in questo luogo maledetto, più della promessa di una vita eterna e di ricchezze infinite?","Monumento",[],["Isole Ombra"],"EPICO"],"03IO006":["Monastero di Hirana","Inizio del turno: Crea 1 Santuario nella tua mano.","","Le montagne di Ionia nascondono molti santuari per chi desidera ritrovare se stesso e sollevare il suo spirito.","Monumento",[],["Ionia"],"EPICO"],"03NX013":["Terra bruciata","Uccidi un'unità danneggiata o distruggi un Monumento.","","\"I mastini draconici hanno fiutato il suo odore. La troveremo e metteremo fine a questa storia. Non c'è altro modo.\" - Arrel la Braccatrice","Incantesimo",[],["Noxus"],"COMUNE"],"03NX004":["Arena Noxkraya","Fine del turno: Il tuo alleato più forte e il tuo nemico più debole si colpiscono a vicenda.","","\"Ehi, voi, fan dell'arena, siete pronti a una notte di BRIVIDI bollenti nel CERCHIO DI FUOCO? Whu-oh, a quanto pare il Piccolo Trik ha pescato il bastoncino più CORTO, oggi. Deve affrontare il possente e bellicoso GRANAAAAK il Grande! Preparate i medici accanto al ring, sarà uno scontro rapido!\" - Annunciatore dell'Arena","Monumento",[],["Noxus"],"EPICO"],"03DE004":["Capitana Arrika","Gioca: Cattura un'unità o un monumento.","","Da bambina, Arrika vide con i suoi occhi la devastazione che Noxus aveva inflitto alle sue terre. Quando si arruolò nell'esercito, giurò che non avrebbe mai permesso alla bandiera noxiana di sventolare in terra demaciana, né che altri bambini rimanessero orfani.","Unità",["ÉLITE"],["Demacia"],"RARA"],"03IO005":["Il ritorno a casa","Richiama un'unità o un Monumento alleati per Richiamare un'unità o un Monumento nemici.","","\"Trevvvvorrrrrr, torna indietro...\" - Casa di Trevor","Incantesimo",[],["Ionia"],"COMUNE"],"03MT052":["Sorgente stellare","Fine del turno: Cura di 1 gli alleati danneggiati. Poi, se ti ho visto curare 22+ danni agli alleati, vinci la partita.","","\"Dall’alto, dalla cascata sacra,\nFino ai più profondi pozzi, le sorgenti guaritrici\nRisplendono di luce, d’acqua brillante,\nAscolta il canto del fiume,\nIn alto sul monte di cristallo.\"\n- Poesia Ottrani","Monumento",[],["Targon"],"EPICO"],"03MT064":["Vetta del Targon","Inizio del turno: Riduci a 0 il costo di una carta casuale nella mano di TUTTI i giocatori per questo turno.","","Il guardiano cristallino di Targon protegge il cancello verso il reame celestiale. In sua presenza, spariscono la speranza, il dubbio, la paura. Le sue prove tolgono le preoccupazioni della vita mortale e mettono a nudo l'essenza dell'anima di chi tenta la scalata. E su questa che si basa il giudizio, poiché il guardiano è il grande arbitro. ","Monumento",[],["Targon"],"EPICO"],"03SI008":["Crolla","Uccidi un alleato per uccidere un'unità o distruggere un Monumento.","","Nulla dura, su queste isole maledette. Tutto ha una fine.","Incantesimo",[],["Isole Ombra"],"RARA"],"03PZ001":["Università di Piltover","Inizio del turno: Scarta la tua mano. Crea 3 carte casuali nella tua mano e rendile Fugaci.","","Le invenzioni del Professor Cecil B. Heimerdinger l'hanno reso famoso, ma furono le sue vivaci lezioni e le sue imprevedibili dimostrazioni in classe a rimanere impresse nelle menti più brillanti di Piltover.","Monumento",[],["Piltover e Zaun"],"EPICO"],"03FR003":["Colui che osserva","Gioca: Annienta TUTTI i monumenti o infliggi 3 a TUTTE le altre unità.","","\"Non c'era tempo per prendere le nostre cose e avvisare gli altri. Potemmo solo correre verso la foresta e guardare come distruggeva le nostre case.\" - Guardia avarosana del focolare","Unità",[],["Freljord"],"RARA"],"03MT026":["Rahvun, Lancia dell'alba","Alba: Crea una carta Alba casuale nella tua mano.\nPer noi è sempre giorno.","","\"Tieni salda la tua fede, Ra-Horak, e la nostra luce non si spegnerà mai!\"","Unità",[],["Targon"],"RARA"],"03MT067":["Ibice cristallino","Gioca: Conferisci Sopraffare a un alleato.","","Chi vuole scalare il Targon dovrebbe farsi amica la fauna locale. Nessuna creatura conosce meglio le pericolose prove del Targon, e nessuna sa attraversare più rapidamente i suoi terreni ghiacciati.","Unità",[],["Targon"],"COMUNE"],"03MT084":["Astroformazione","Invoca una carta Celestiale dal costo di 7 o più, poi cura un alleato o il tuo Nexus di 5.","","\"Guarda le stelle. Se hai fortuna, io ricambierò lo sguardo.\" - Aurelion Sol","Incantesimo",[],["Targon"],"COMUNE"],"03MT221":["Le zanne","Gioca: Invoca una carta Celestiale dal costo di 3 o meno.","","\"Madre Luna, mostrami la via,\nApri il cielo,\nPortami oltre.\"\n- Preghiera Lunari","Unità",[],["Targon"],"EPICO"],"03MT093":["Stella vagante","Infliggi 5 a un nemico che ha attaccato in questo turno o che è stordito.","","\"KaBOOMey!\" - Zoe","Incantesimo",[],["Targon"],"COMUNE"],"03MT073":["Portatrice del crepuscolo Lunari","Quando vengo evocata, crea 1 Polvere di petalo crepuscolare nella tua mano.","","\"I petali crepuscolari si schiudono la notte e solo con la luna piena. È un simbolo dei Lunari, usiamo la loro polvere da secoli, perché solo noi sappiamo raccoglierli senza pericolo.\"","Unità",[],["Targon"],"COMUNE"],"03MT002":["I cieli discendono","Costo 2 in meno per ogni alleato Drago o Celestiale che possiedi. Infliggi 15 a tutti i nemici.","","\"Quando verrà il momento, punirò Runeterra in modo esemplare. Forse trascinerò il suo guscio fumante con me per tutta l'eternità. Come un giocattolo. Un giocattolo livido e morto. Non so. Non ci ho ancora pensato.\" - Aurelion Sol","Incantesimo",[],["Targon"],"EPICO"],"03MT217":["Aphelios","Crepuscolo: scegli un'Arma lunare da creare nella tua mano.\nOgni turno, la prima volta che giochi altre 2 carte, crea l'Arma lunare Mutata nella tua mano se non ne hai già una.","Hai giocato 4 o più Armi lunari.","\"A ogni conflitto mostriamo ai Solari che siamo degni di rispetto. Abbiamo insegnato loro che la luce della Luna è pari a quella del loro Sole, e che non devono disprezzare ciò che non conoscono. E ciò che ancora devono imparare...\" - Affatturatore Lunari","Unità",[],["Targon"],"Campione"],"03MT044":["Guardiano del Sole","Alba o quando attivi un'altra Alba: Conferiscimi +1|+1.","","\"Guardiano lucente, la tua furia arde come il cielo di mezzogiorno. Vieni e punisci chi osa calcare questo suolo sacro.\" - Iscrizione del Guardiano del Sole","Unità",[],["Targon"],"EPICO"],"03MT056":["Diana","Crepuscolo o quando attivi un altro Crepuscolo: Forniscimi Sfidante per questo turno.","Hai attivato Crepuscolo 4+ volte.","Era tra loro, pronta a combattere. Radiosa, adornata d'argento e blu, con gli occhi come stelle. La luna sorse per illuminarla, e i Lunari lì riuniti chiusero gli occhi, pregando silenziosamente per la sua sicurezza, colmi di gratitudine.","Unità",[],["Targon"],"Campione"],"03MT020":["Stellacorno risplendente","Gioca: Cura un alleato e il tuo Nexus di 3.","","\"Vedi quella stella che attraversa la notte? È uno stellacorno adulto. I piccoli ci donano la loro magia curativa finché non crescono e tornano nel cielo, finalmente in grado di controllare quel potere. È una grande fortuna vederne uno e riconoscerlo, e lo è ancora di più poterlo accudire.\" - Lidari, custode delle stelle","Unità",[],["Targon"],"COMUNE"],"03MT091":["Mappa stellare fichissima","Invoca una carta Celestiale dal costo di 3 o meno.","","\"E queste stelle SUPER brillanti le chiamo... 'La Corda Celestiale per Saltare'! O forse è più una faccia felice al contrario?\" - Zoe","Incantesimo",[],["Targon"],"RARA"],"03MT047":["Cygnus l'Osservatore Lunari","Crepuscolo: Fornisci Elusione a un alleato per questo turno.","","Il Lunari attese la notte e la sicurezza che recava. Il sentiero sembrava deserto, ma Cygnus sapeva che poco più avanti erano accampati i Solari. Fece un gesto e gli altri si misero silenziosamente in fila dietro di lui.","Unità",[],["Targon"],"EPICO"],"03MT094":["Predatrice dell'ombra Lunari","Crepuscolo: Conferiscimi Elusione.","","\"Rivolgiamo gli occhi al cielo, verso il sole, verso la luce della nostr... Ma... cosa... Cos'è quello...?\" - Sacerdotessa Solari","Unità",[],["Targon"],"COMUNE"],"03MT036":["Benedizione di Targon","Conferisci +3|+3 a un alleato.","","\"Un regalino dal Targon.\" - Taric","Incantesimo",[],["Targon"],"RARA"],"03MT092":["Capra di montagna","Colpisci: Crea 1 Gemma nella tua mano.","","Le capre del Monte Targon sono ancora più pericolose di quelle normali, perché le gemme sulle loro corna rilasciano dolorose schegge all'impatto. ","Unità",[],["Targon"],"RARA"],"03MT060":["Protettore spallelarghe","Inizio del turno: Cura di 3 il tuo Nexus. Infliggimi danni pari alla quantità curata.","","\"Nessuno conosce i sentieri di Targon come me, quindi mi toccano sempre gli stellacorni più... ostinati. Meno male che ci sono io a sorvegliarli!\" ","Unità",[],["Targon"],"EPICO"],"03MT001":["Ziblì subdoli","Gioca: Stordisci i nemici con 2 o meno Potere.","","Nel silenzio cristallino dei monti, giunse il tintinnio del ghiaccio che cade e, molto più in alto, ciò che ai viaggiatori sembravano... delle risate.","Unità",[],["Targon"],"COMUNE"],"03MT055":["Soraka","Supporto: Cura me e il mio alleato supportato di 4.","Hai curato danni agli alleati 4+ volte.","\"La cura, nella sua vera natura, è un atto generoso. Non devi assorbire il loro potere, te lo donano di loro volontà. Mostra loro compassione e vedrai come brillano.\"","Unità",[],["Targon"],"Campione"],"03MT048":["Donatrice generosa","Quando vengo evocata, crea 1 Gemma nella tua mano.","","\"Dicono che il Protettore abbia benedetto queste gemme. Indossale e il suo spirito sarà con te.\"","Unità",[],["Targon"],"COMUNE"],"03MT082":["Luce del mattino","Fornisci +1|+1 agli alleati per questo turno.\nAttiva Alba di un alleato.","","\"Sorgeremo assieme all'alba! Marciate nella luce!\" - Leona","Incantesimo",[],["Targon"],"RARA"],"03MT058":["Taric","Supporto: Fornisci Tenacia a me e al mio alleato supportato per questo turno. Copia sull'alleato l'ultimo incantesimo che hai giocato solo su di me in questo turno (non può essere copiato di nuovo).","Ti ho visto bersagliare o supportare alleati 7+ volte.","\"Chiunque incontri Taric è ispirato dalla sua gentilezza e spinto a trovare in sé un calore capace di riscaldare anche nelle notti più gelide.\" - Divinatore della montagna","Unità",[],["Targon"],"Campione"],"03MT062":["Brilleologa frivola","Gioca: Se una carta Celestiale è visibile, conferisci a un alleato +1|+1 e Scudo magico.","","\"...e poi una farfallucciola è come polvere di stelle che cade per terra e si rialza in volo, è fantastica, ne ho vista una l'altra sera, era così bella e ho fame ed è volata su fino alle STELLE e poi...\"","Unità",[],["Targon"],"RARA"],"03MT040":["Farfallucciola","","","\"La speranza è una cosa delicata che vola sempre più in alto e non dovrebbe mai farsi catturare.\" - Sacerdotessa Lunari","Unità",[],["Targon"],"COMUNE"],"03MT086":["Artista stralunata","Gioca: Scarta 1 carta per Invocare una carta Celestiale dal costo di 3 o meno.","","\"Questo è il mio preferito! Lo chiamo 'Identità metafisica della psiche cosciente'. Se però pieghi la testa così... sembrano due cucchiai.\"","Unità",[],["Targon"],"RARA"],"03MT016":["Pestatore sorpreso","","","\"Oh, il piccolo Pestatore non vuole passare per il portale? Non ti preoccupare vorrà dire che... AHAHAH! Scherzavo. PARTENZA!\" - Zoe","Unità",[],["Targon"],"COMUNE"],"03MT054":["Leona","Alba: Stordisci il nemico più forte.","Hai attivato Alba 5+ volte.","Era tra loro, pronta a combattere. Radiosa, adornata d'oro e cremisi, con il fuoco negli occhi. Il sole sorse incoronandola come un'aureola e i Solari abbassarono lo sguardo. Non per vergogna, ma per rispetto verso la loro splendente condottiera.","Unità",[],["Targon"],"Campione"],"03MT220":["La via divisa","Crepuscolo: Stordisci un nemico. Se è un seguace, stordiscilo di nuovo al prossimo Inizio del turno.","","\"Madre Luna, la nostra notte fa il suo corso,\nAiutaci a fermare chi ci minaccia\nE insegna loro il rimorso.\"\n- Preghiera Lunari","Unità",[],["Targon"],"RARA"],"03MT021":["Spaccamente infinito","Gioca: Scegli 2 nemici.\nInizio del turno: Stordiscili.","","Si dice che i viaggiatori che incrociano lo sguardo della creatura ricevano una conoscenza e una consapevolezza tanto profonda da far crollare le loro menti.","Unità",["DRAGO"],["Targon"],"EPICO"],"03MT006":["Inviolus Vox","In ogni turno, quando un alleato con Furia uccide un nemico per la prima volta, crea un seguace Drago casuale nella tua mano.","","\"Guarda ai cieli e vedi ciò che vedo io! Prima i segnali, poiché di notte brillano. Poi la furia, perché di giorno tutto brucia. Vedrai! Tutti vedranno!\" - Messaggero dei draghi","Unità",["DRAGO"],["Targon"],"EPICO"],"03MT015":["Ammirate l'infinito","Invoca.","","Il cielo si apre sopra di te, come un arazzo nero illuminato da stelle lucenti. Sei minuscolo e fioco di fronte alla sua vastità. Dove volgerai il tuo primo sguardo?","Incantesimo",[],["Targon"],"COMUNE"],"03MT013":["Afflizione della luce lunare","Silenzia 2 unità nemiche per questo turno.\nCrepuscolo: Non possono bloccare per questo turno.","","\"Chi non è abituato alla luce lunare deve imparare a usarla per vedere, altrimenti non vedrà nulla.\" - Diana","Incantesimo",[],["Targon"],"COMUNE"],"03MT009":["Zoe","Colpisci il Nexus: Crea 1 Mappa stellare fichissima nella mano o, se ne hai una, riduci il suo costo di 1.","Ti ho visto giocare 10 carte con nomi diversi.","\"Ehi, ciaooo! Cosa stai facendo? È un GIOCO DI CARTE? Posso giocare anch'io? Cosa? SONO nel TUO gioco? Ah! Che dimensione sciocchina...\"","Unità",[],["Targon"],"Campione"],"03MT087":["Aurelion Sol","Gioca: Invoca una carta Celestiale dal costo di 7 o più.\nInizio del turno: Crea una carta Celestiale casuale nella tua mano.","Fine del turno: I tuoi alleati hanno 20+ Potere totale.","\"Non mi interessa ciò che scrivi di me, misera creatura! Vedi solo che sia descritto come bello. E magnifico. E anche molto, molto intelligente. Sai come si scrive?\"","Unità",["DRAGO"],["Targon"],"Campione"],"03MT019":["Bastione","Conferisci +1|+1 e Scudo magico a un alleato.","","\"Onora la montagna.\" - Taric","Incantesimo",[],["Targon"],"COMUNE"],"03MT214":["Il Volo","Colpisci il Nexus: Pesca 1 carta e piazzami nelle prime 3 carte del tuo mazzo.","","\"Madre Luna, dammi sicurezza,\nRiempimi della fede del Volo,\nConducimi sul mio cammino.\"\n- Preghiera Lunari","Unità",["VOLATILE"],["Targon"],"RARA"],"03MT071":["Tyari il Viandante","Supporto: Conferisci +0|+2 al mio alleato.","","Quando viaggi, devi accettare l'idea che il tuo cammino ti cambierà inevitabilmente. Quando viaggi, prendi qualcosa di nuovo con te... e abbandoni qualcosa del tuo passato. ","Unità",[],["Targon"],"COMUNE"],"03MT008":["Desiderio","Cura completamente gli alleati danneggiati.","","\"Per la vita!\" - Soraka","Incantesimo",[],["Targon"],"RARA"],"03MT023":["Esplosione solare","Infliggi 6 a un'unità.\nAlba: Invece, silenziala per questo turno e infliggile 6.","","Poche creature sopravvivono a uno sguardo eterno come il sole.","Incantesimo",[],["Targon"],"RARA"],"03MT045":["Protezione astrale","Cura un alleato di 4 e conferiscigli +0|+4.","","\"Pensavi di poterci battere? Ah! Abbiamo appena cominciato.\" - Protettore spallelarghe","Incantesimo",[],["Targon"],"COMUNE"],"03MT080":["Guardiano della Sorgente","Quando vengo evocato, crea 1 Doni della Sorgente nella tua mano.","","\"Mi occupo principalmente delle sorgenti, ma la prima responsabilità di un pastore è il suo gregge. Le priorità a volte collidono.\"","Unità",[],["Targon"],"COMUNE"],"03MT042":["Furto magico","Manifesta un incantesimo nemico giocato in questa partita.","","\"Oh, è stato FANTASTICO! Ma quanto sarebbe meglio se lo facessi io? Ciaociaograzievado!\" - Zoe","Incantesimo",[],["Targon"],"RARA"],"03MT057":["Forgiasole Solari","Alba: Forniscimi Rubavita per questo turno.","","Il Forgiasole restava tutto concentrato, mentre la luce inondava la stanza. L'artefatto dei Solari trasformava i brillanti raggi del sole in un potente incanto per la sua arma.","Unità",[],["Targon"],"COMUNE"],"03MT041":["Mentore delle pietre","Supporto: Conferisci +2|+2 al mio alleato supportato.\nUltimo respiro: Crea 3 Gemme nella tua mano.","","\"Hai capito qualcosa di quel che ha detto?\"\n\"Niente di niente. Però sembrava gentile.\"\n - Emir e Haley, visitatori della montagna","Unità",["YORDLE"],["Targon"],"EPICO"],"03MT027":["Lama dello zenith","Conferisci +1|+2 a un alleato. Forniscigli Sopraffare per questo turno.\nAlba: Pesca 1 Lama dello zenith.","","\"Lascia che il sole ti doni la sua forza!\" - Sacerdotessa Solari","Incantesimo",[],["Targon"],"COMUNE"],"03MT096":["Sacerdotessa Solari","Alba: Invoca una carta Celestiale dal costo di 4, 5 o 6.","","I Solari cercano la guida delle stelle come ogni altro targoniano, poiché a una stella è dedicata tutta la loro fede.","Unità",[],["Targon"],"RARA"],"03MT028":["Scudiera dei Solari","Alba: Forniscimi +0|+4 per questo turno.","","\"È sciocco non presentarsi col favore delle tenebre.\" La Scudiera si rizzò. \"Posa le armi e avvicinati lentamente.\"\nLa Lunari si inchinò in silenzio, preparando di nuovo le sue lame curve.\nE sia.\nLa Solari si preparò a sua volta, sollevando lo scudo per riflettere i raggi dell'alba. ","Unità",[],["Targon"],"COMUNE"],"03MT089":["Guardiano della mezzaluna","Crepuscolo: Conferiscimi +2|+0.","","\"Stoico guardiano, il tocco gentile del plenilunio ti restituisca forza. Risvegliati e proteggici da coloro che calpestano questo sacro luogo.\" - Iscrizione del Guardiano della mezzaluna","Unità",[],["Targon"],"RARA"],"03MT051":["Tocco guida","Cura un alleato o il tuo Nexus di 2. Pesca 1 carta.","","Gli stellacorni felici brillano più intensamente.","Incantesimo",[],["Targon"],"COMUNE"],"03MT003":["Covata del drago","Pesca 2 Draghi diversi o conferisci +1|+1 e Sopraffare ai Draghi alleati.","","\"Il loro verso è simile a quello di un gatto rauco. Se lo senti, gira i tacchi e cerca la guardia più vicina. Hai capito? Perché dove ci sono uova di drago, ci sono anche i draghi.\" - Contandina targoniana","Incantesimo",[],["Targon"],"RARA"],"03MT098":["Vigore benedetto dal sole","Conferisci +0|+2 a un alleato.","","\"Il nostro scudo è la nostra convinzione, il nostro credo, la nostra fede nella luce!\" - Scudiero dei Solari","Incantesimo",[],["Targon"],"COMUNE"],"03MT215":["Doni dall'aldilà","Scegli un'Arma lunare da creare nella tua mano.","","\"Protenditi, Aphelios...\" - Alune","Incantesimo",[],["Targon"],"COMUNE"],"03MT063":["Sognaluna","Gioca: Invoca.\nCrepuscolo: Riduci il costo di quella carta di 1.","","\"Guarda quanti amici nel cielo stanotte! Vedi quella stella luminosissima? È l'occhio del Messaggero che ci osserva! E quell'ammasso fioco laggiù? È l'Ingannatore nascosto dietro alle nubi! Quello invece... KULUN, BUONO! Non puoi tirarli giù con le zampe...!\"","Unità",[],["Targon"],"COMUNE"],"03MT100":["Drago dell'eclissi","Alba: Il prossimo Drago o unità Celestiale che giochi costa 2 in meno.\nCrepuscolo: Crea un seguace Drago e Celestiale casuale nella tua mano.","","Squama di drago (Drago dell'eclissi, Draco Obscuratus)\nNote: la squama ha incredibili proprietà ottiche. Sotto la luce diretta del sole, è altamente riflettente.\nAnnotato: BRILLA ANCHE DI NOTTE!\n- Note di Anden Mayne, Ricercatore cervellone","Unità",["DRAGO"],["Targon"],"RARA"],"03MT076":["Divinatore della montagna","Le tue carte Celestiali costano 1 in meno.\nFedeltà: Invoca.","","\"C'è molto da imparare dalle stelle, dalla loro guida. Per noi sono una costante, una luce che ci indica il cammino.\"","Unità",[],["Targon"],"RARA"],"03MT029":["Pastorella delle Stelle","Quando curi un alleato danneggiato, conferiscimi +2|+0.","","\"La prima volta che ho visto uno stellacorno solcare il cielo me ne sono innamorata. Ancora non sapevo che ne avrei incontrati così tanti!\"","Unità",[],["Targon"],"RARA"],"03MT219":["Il tempio velato","Ogni turno, la prima volta che giochi altre 2 carte, ripristina 2 mana e conferisci +1|+0 al tuo alleato più forte.","","È da qui, dal reame degli spiriti, che Alune comunica con suo fratello Aphelios. È lei che sussurra parole di conforto al taciturno assassino, e che attraversa il velo per consegnargli i suoi strumenti di castigo.","Monumento",[],["Targon"],"RARA"],"03MT079":["Monello delle stelle","Se una carta Celestiale è Visibile, costo 2 in meno.","","\"Gli adulti sono un PACCO. Gli unici tipi forti, da queste parti, sono Zoe e i suoi amici. Ho imparato molto da loro, sai? Non sono come quella stupida sacerdotessa radiosa. Cioè... UGHHHH!\"","Unità",[],["Targon"],"COMUNE"],"03MT007":["Stellacorno cucciolo","","","\"Prima o poi ogni piccolo di stellacorno deve tentare il suo primo, incerto volo. Quando lo fa è come le altre stelle della notte e cade altrettanto in fretta. Per fortuna noi siamo lì ad afferrarlo e, quando è pronto, a restituirlo al cielo.\" - Lidari, custode delle stelle","Unità",[],["Targon"],"COMUNE"],"03MT038":["Protettore Fiammabianca","","","Furono i piccoli di Targon a stringere per primi amicizia con i draghi più giovani e pacifici. Forse quelle creature percepirono la curiosità innocente dei bambini e, invece di attaccarli, decisero di proteggerli. ","Unità",["DRAGO"],["Targon"],"COMUNE"],"03MT014":["Messaggero dei draghi","Gli alleati Drago costano 1 in meno.","","Le nuvole si avvolsero intorno alla loro forma colossale, mentre il cielo sembrava tremare a ogni loro lugubre lamento. Lei sapeva cosa stava per succedere, ma non provava paura. Sentiva solo il tiepido abbraccio del destino.","Unità",[],["Targon"],"RARA"],"03MT110":["Fuori dai piedi","Per il resto della partita, i buff degli alleati \"di questo turno\" (tranne Barriera) sono permanenti. Pesca 1 carta.","","\"You know I mean everything that I say\nWhen you see me coming get out of the way\nI came to slay I came to slay\nBack and I’m better and ready to stay.\"\n- Kai'Sa, \"THE BADDEST\"","Incantesimo",[],["Targon"],"EPICO"],"03MT017":["Sigillo del Messaggero","Crea 5 I Messaggeri nel tuo mazzo.","","\"Il tempo passa, i cieli ruotano, il Serpente si fa da parte e il Messaggero prende il suo posto. Ci attende una stagione di abbondanza...\" - Sacerdotessa Lunari","Incantesimo",[],["Targon"],"RARA"],"03MT025":["Frammenti della Montagna","Riempi la tua mano di Gemme.","","\"Gira una gemma in questo modo e brilla sotto la luce. Come le vite mortali, ogni cosa ha un suo fuoco interiore.\" - Taric","Incantesimo",[],["Targon"],"EPICO"],"03MT216":["Ombre celesti","Quando vengo evocato, ripristina 2 mana incantesimo se è Visibile una carta Crepuscolo.","","\"Madre Luna, concedimi di ricordare\nChe anche se vago in solitudine\nI tuoi figli danzano nel cielo\nE sempre mi accompagnano.\"\n- Preghiera Lunari","Unità",[],["Targon"],"COMUNE"],"03MT012":["Arbitro del Picco","Costo 1 in meno per ogni volta che hai bersagliato o supportato alleati durante questa partita.","","L'Arbitro è la prova finale della montagna, poiché solo il guardiano vede oltre le imprese di colui che sale, scrutandone lo spirito.","Unità",[],["Targon"],"EPICO"],"03MT085":["Shhh","Silenzia un'unità per questo turno.","","\"Scopriranno la serenità.\" - Soraka","Incantesimo",[],["Targon"],"RARA"],"03MT081":["Visitatori della montagna","Supporto: Conferisci +2|+2 al mio alleato supportato. Se ha Supporto, conferisce +2|+2 al suo alleato supportato e prosegue per ogni alleato supportato in successione.","","Chiunque affronti il Monte Targon ha una ragione per scalarlo. Alcuni lo fanno per dimostrare il proprio valore ai loro pari, altri a se stessi.","Unità",[],["Targon"],"EPICO"],"03MT030":["Osservatrice delle stelle","Quando curi un alleato danneggiato, forniscigli Elusione per questo turno.","","\"Le stelle non rimangono sempre con noi. Una volta sistemate, le restituisco al cielo, in un'improvvisa esplosione di luce stellare... e zoccoli impetuosi.\"","Unità",[],["Targon"],"RARA"],"03MT088":["Soldato Solari","Alba: Forniscimi +1|+1 per questo turno.","","Mentre il sole lo scaldava, sorvegliava la prigione dell'eretica, ignorando le suppliche che presto diventarono amaro silenzio.","Unità",[],["Targon"],"COMUNE"],"03MT033":["Nonno Rumul","Gioca: Conferisci +0|+4 a due alleati.","","\"Ascolta, Osu! Le senti? Campanelle! Il nonno è tornato!\" - Illi, pastorella delle stelle","Unità",[],["Targon"],"RARA"],"03MT035":["Cascata cerulea","Fornisci +1|+1 a un alleato per questo turno.\nCrepuscolo: Pesca 1 carta.","","\"Nell'ombra della notte, vegliata dalla pallida luna.\" - Diana","Incantesimo",[],["Targon"],"COMUNE"],"03MT075":["Sacerdotessa Lunari","Crepuscolo: Invoca.","","\"Oh stelle, pellegrine in viaggio nell'immensità della notte. State con noi un momento, raccontateci cos'avete visto.\" - Inno alla Sera","Unità",[],["Targon"],"RARA"],"03MT218":["Osso siderale","Se una carta Celestiale è Visibile, crea Il Messaggero nel tuo mazzo e conferisci +1|+1 agli alleati Celestiali ovunque.","","\"Che il Messaggero giochi,\nE con la sua gioia\nAccenda le stelle.\"\n- Preghiera Lunari","Incantesimo",[],["Targon"],"EPICO"],"03MT074":["Bolla della nanna","Stordisci un nemico. Crea 1 Stella vagante Fugace nella mano.","","\"Pisolino per te! Una farfallucciola, dueee farfallucciole, tre... ehi, checos'èquello?\" - Zoe","Incantesimo",[],["Targon"],"RARA"],"03MT072":["Tizzone fuso","","","Infinite avversità attendono chi sfida il Monte Targon. Alcune, come l'interminabile scalata, erodono lentamente le forze. Altre sono molto più immediate.","Unità",["DRAGO"],["Targon"],"COMUNE"],"03MT039":["Porovolo","","","Nello spazio, nessuno può sentirti squittire.","Unità",["PORO"],["Targon"],"COMUNE"],"03PZ019":["Porobot rattoppato","Quando sono nella tua mano, ho una parola chiave casuale che cambia ogni turno. Quando vengo evocato, conferiscimi quella parola chiave.","","Non è così coccoloso come quello reale, ma è altrettanto carino.","Unità",["PORO"],["Piltover e Zaun"],"RARA"],"03PZ005":["Bot balistico","Inizio del turno: Crea 1 Accensione nella tua mano.","","Il soggetto ha chiesto di tenere intatta solo la sua mente, dicendo che \"è qui dove tengo tutto il mio rancore.\"\n- Diario del potenziatore, voce 1011","Unità",[],["Piltover e Zaun"],"COMUNE"],"03PZ004":["Raggio della morte - Mk1","Infliggi 1 a un'unità. Crea 1 Raggio della morte - Mk2 nelle prime 3 carte del tuo mazzo.","","\"Oggi ho dimostrato con successo che l'energia splendente può essere concentrata in un raggio potentissimo! Con le dovute migliorie, il raggio potrebbe diventare estremamente preciso, ma c'è ancora molto lavoro da fare.\"\n- Appunti di Viktor","Incantesimo",[],["Piltover e Zaun"],"RARA"],"03PZ003":["Viktor","Quando vengo evocato o all'Inizio del turno: Crea 1 Potenziamento del nucleo hex nella tua mano.","Hai giocato 7+ carte create.","\"Zaun, hai visto la tua dose di tragedie ed è giunto il momento di cambiare. Come con tutti i grandi passi avanti, bisogna cominciare da te.\"","Unità",[],["Piltover e Zaun"],"Campione"],"03PZ010":["Imitatrice meccanizzata","Attacca: Conferiscimi tutte le parole chiave degli alleati.","","\"Sono come te, ma meglio.\"","Unità",[],["Piltover e Zaun"],"EPICO"],"03PZ022":["Metticela tutta","Aumenta Potere e Salute di tutti gli alleati allo stesso livello dell'alleato con più Potere o Salute.\nConferisci agli alleati tutte le parole chiave alleate.","","\"I know I know\nYou want some more\nIf you ready let’s go\nGiving it all\"\n- Seraphine, \"MORE\"","Incantesimo",[],["Piltover e Zaun"],"EPICO"],"03PZ014":["Creazioni calcolate","Crea 1 Fanatico armato, Bot balistico o Miaodroide nella mano e conferiscigli +1|+1.","","\"La razionalità e l'arbitrio separano gli umani dagli istinti animali.\" - Viktor","Incantesimo",[],["Piltover e Zaun"],"COMUNE"],"03PZ013":["Miglioramento iterativo","Scegli un seguace. Creane una copia con +1|+1 nella tua mano.","","\"Il miglioramento personale è un gioco nel quale sei contemporaneamente il buono e il cattivo. Farai fatica. Penserai persino di aver vinto. Ma alla fine, sarai sempre tu l'ostacolo da superare.\" - Imitatrice meccanizzata","Incantesimo",[],["Piltover e Zaun"],"COMUNE"],"03PZ025":["Stress test","Rimuovi Fugace da tutte le carte nella tua mano. Quando mi scarti, pesca 1 carta Fugace.","","\"È molto semplice. Ho sostituito l'acciaio del telaio con una lega più robusta di mia invenzione, e ho deviato i circuiti dalle cerniere per evitare che i sistemi vadano in corto. Una passeggiata.\" - Zevi, capo meccanicista","Incantesimo",[],["Piltover e Zaun"],"RARA"],"03PZ012":["Fanatico armato","","","\"OK! Nuovo braccio! Ne ho sempre voluto uno. E ora cos'abbiamo? Ruote gravitazionali al posto delle gambe? Elettrocinture? DENTI DI METALLO? Anzi, la faccia lasciamela. Mi piace.\"","Unità",[],["Piltover e Zaun"],"COMUNE"],"03PZ020":["Fonderia di nuclei hex","Inizio del turno: TUTTI i giocatori pescano 1 carta.","","\"Dicano pure quel che vogliono dei miei metodi. Non possono negare il progresso. La luce del mio sapere è come un faro nell'oscurità dell'ignoranza!\" - Viktor","Monumento",[],["Piltover e Zaun"],"RARA"],"03PZ002":["Miaodroide","","","\"Con grande fatica ho superato anni di accademia piltoveriana, solo per sentirmi dire che le mie tecnologie sono troppo pericolose e che la mia presenza è troppo carina! Miao a Zaun, dove almeno una grande mente condivide le mie ambizioni...\"","Unità",["FELINO"],["Piltover e Zaun"],"RARA"],"03PZ011":["Scossa di assestamento","Infliggi 3 a un'unità o distruggi un Monumento.","","\"Questo raggio di luce guiderà la nostra marcia verso Piltover. Niente si può frapporre tra noi e la nostra Gloriosa evoluzione!\" - Viktor","Incantesimo",[],["Piltover e Zaun"],"COMUNE"],"03PZ017":["Improbabilatore Tri-Raggio","Infliggi 1 a un'unità. Evoca un seguace casuale di costo 1. Quando sono in mano e giochi una carta di costo 3, aumenta danni e costo di 1.","","\"...e uno, e due, e TRE!!! Oh. Oh, cielo... Un altro risultato imprevisto?!?\" - Heimerdinger","Incantesimo",[],["Piltover e Zaun"],"EPICO"],"03PZ018":["Cannone Poro","Per giocare, scarta 1 carta.\nCrea 2 Poro audaci nella tua mano.","","Due archi vellutati scesero elegantemente sulla folla adorante, lasciando dietro di loro una nuvola soffice e un tenue odore di torta.","Incantesimo",[],["Piltover e Zaun"],"COMUNE"],"03SI004":["Ombre cacciatrici","Scegli un seguace dalle prime 4 carte del tuo mazzo.\nPescalo, mescola le altre nel mazzo e creane una copia esatta Effimera nella tua mano.","","\"Andate... circondateli...\" - Nocturne","Incantesimo",[],["Isole Ombra"],"RARA"],"03SI001":["Cacciatore di Ombreterna","Crepuscolo: Crea una mia copia nella tua mano.","","\"All'inizio era solo un paio d'occhi, poi una voce solitaria nell'ombra. Ogni volta che mi voltavo era più forte. Più arrabbiata. Quando ho visto il dente, sono scappato.\" - Ladro del dente di balena","Unità",[],["Isole Ombra"],"EPICO"],"03SI018":["Gola","Uccidi un alleato con Ultimo respiro per evocare dal mazzo un seguace che costa 1 in più.","","\"ORA DI CEEEEENA!\" - Macellaio famelico","Incantesimo",[],["Isole Ombra"],"RARA"],"03SI012":["Passaggio immeritato","Annienta tutte le unità che sono state evocate, ma non giocate, in questo turno.","","\"Certo, la morte esiste anche a Demacia. La vediamo portar via i nostri cari e sappiamo che un giorno verrà per noi. Ma in quelle isole puoi quasi toccarla. Mi entra nei polmoni quando respiro, mi sussurra all'orecchio. Non è un concetto astratto. È seduta accanto a me. Ora. E ci prenderà tutti.\"\n- Appunti di Jens Tommen, storico","Incantesimo",[],["Isole Ombra"],"RARA"],"03SI014":["Ombre invadenti","Conferisci a TUTTI gli alleati nel tuo mazzo e nella tua mano +2|+2 ed Effimero.","","\"Temo che prima o poi gli incubi delle Isole Ombra ci piegheranno tutti nel corpo e nella mente, e la follia regnerà per sempre.\"\n- Appunti di Jens Tommen, storico","Incantesimo",[],["Isole Ombra"],"EPICO"],"03SI016":["Dacci dentro","Assorbi 1 da un'unità.\nCrea 2 copie di Dacci dentro nel mazzo. Dopo tre volte, trasforma tutte le mie copie ovunque in Fai le valigie.","","\"We go hard, 'til we get it, get it\nWe go hard, we so in it, in it\nWe Pop Stars (Pop Stars), only winning, winning now\nAin't nobody bringing us down, down, down, down\"\n- Evelynn, \"POP/STARS\"","Incantesimo",[],["Isole Ombra"],"EPICO"],"03SI007":["Veste delle tenebre","La prossima volta che evochi un alleato in questo turno, forniscigli +1|+0 e Scudo magico per questo turno.","","\"Appena esci dal Dente, li percepisci, come dita sulla tua nuca, leggere come la pioggia. Non si muovono nemmeno se le attacchi. Non temono né la spada né la torcia. Nessuna reazione. Esseri orribili.\" - Razziatore del Dente di Balena","Incantesimo",[],["Isole Ombra"],"COMUNE"],"03SI005":["Nocturne","Crepuscolo: Conferisci a un nemico Vulnerabile e fornisci -1|-0 ai nemici per questo turno.","Hai attaccato con 5+ alleati con Crepuscolo o Temibile.","\"Sembra che, dopo aver scosso anime a sufficienza, possa entrare nel nostro mondo. Solo la speranza può rimandarlo da dove è venuto... ma qui la speranza è morta da tempo, con l'ultimo respiro di una regina e l'urlo eterno di un re.\"\n- Appunti di Jens Tommen, storico","Unità",[],["Isole Ombra"],"Campione"],"03SI006":["Bestia della rovina","Crepuscolo: Assorbi 2 dal Nexus nemico.","","I viaggiatori erano notte dopo notte sempre più stanchi. Il loro sonno era agitato, i loro sogni intensi. Dormire non era più un sollievo, ma anzi strappava lentamente la vita dalle loro ossa.","Unità",[],["Isole Ombra"],"COMUNE"],"03SI015":["Spettro molesto","Ultimo respiro: Crea 2 mie copie nel mazzo del nemico.","","Molti degli spiriti delle Isole Ombra sono creature terrificanti e macabre. Alcune sono... beh... diciamo, molto fastidiose.","Unità",[],["Isole Ombra"],"COMUNE"],"03SI003":["Astante Stigio","Crepuscolo: Forniscimi +2|+0 e Temibile per questo turno.","","Appena il sole affonda, gli orrori di questo luogo si svegliano, osservano e attendono.","Unità",["VOLATILE"],["Isole Ombra"],"COMUNE"],"03SI002":["Orrore inenarrabile","Assorbi 1 da qualsiasi cosa.\nCrepuscolo: Crea una carta Crepuscolo casuale nella tua mano.","","\"Ogni giorno che passa fiacca il mio spirito e mi toglie il vigore che mi ha spinto a trovare questo luogo. Il Dente di Balena è pieno di gusci vuoti, svuotati di ogni volontà e temo che più resterò qui più diventerò come loro.\"\n- Appunti di Jens Tommen, storico","Incantesimo",[],["Isole Ombra"],"COMUNE"],"03SI010":["Cavalcatramonto","Crepuscolo: Conferiscimi +1|+0 per ogni volta che hai attivato Crepuscolo in questa partita.","","Ad ogni tramonto, la notte spiega le sue ali nere e copre le ultime scintille di speranza del giorno.","Unità",[],["Isole Ombra"],"RARA"],"03SI013":["Nebbie ascese","Evoca 1 Spettro della Nebbia.","","Gli Spettri della Nebbia si muovono tra i piani, invisibili ai mortali, appaiono all'improvviso e recano sventura a chiunque incontrano.","Incantesimo",[],["Isole Ombra"],"COMUNE"],"03IO025":["Raffica di pugni","Conferisci a un alleato +1|+0 e Attacco rapido. Se lo possiede già, conferiscigli invece Attacco doppio.","","\"Colpisci tanto. Colpisci veloce. Colpisci forte.\" - Corna del drago","Incantesimo",[],["Ionia"],"RARA"],"03IO017":["Pix!","Supporto: Fornisci +2|+1 al mio alleato supportato per questo turno.","","\"Pix è FORMIDABILE, piccola, tosta e amabile,\nAdora un sacco gli opossum e... ehm... il colore rossum!\" - Lulu","Unità",["FATATO"],["Ionia"],"COMUNE"],"03IO008":["Metamorfosi","Trasforma un seguace in 1 Scoiattolo 1|1 e silenzialo per questo turno.","","\"Adoribus!\" - Lulu","Incantesimo",[],["Ionia"],"COMUNE"],"03IO001":["Bimba dei fiori","Quando ricevo supporto, conferiscimi +2|+0.","","Tutti vorrebbero un famiglio, ma nessuno è preparato a ciò che comporta. Bisogna farlo passeggiare, assicurarsi che segua una dieta bilanciata, insegnargli a non sporcare... Non è tutto rose e fiori.","Unità",["FATATO"],["Ionia"],"COMUNE"],"03IO019":["Volontà singolare","Scegli un alleato. Richiama TUTTE le altre unità e i Monumenti.","","\"Il mio è un cammino solitario.\" - Asceta Solitaria","Incantesimo",[],["Ionia"],"EPICO"],"03IO002":["Lulu","Supporto: Il mio alleato supportato aumenta fino a 4|4 per questo turno.","I nostri alleati sono stati supportati 3+ volte.","\"Non preoccuparti, Pix! Usciremo dalla Radura e allora... Adoribus per TUTTI! Ci siamo?!?\"","Unità",["YORDLE"],["Bandle City","Ionia"],"Campione"],"03IO011":["Scoiattolo Palestrato","Colpisci: Raddoppia il mio Potere.","","Il suo segreto? Dei beveroni alla polvere di ghianda, quattro volte al giorno.","Unità",["FATATO"],["Ionia"],"RARA"],"03IO009":["Gigante buono","","","Energia: 104 kJ (25 kcal), Carboidrati: 5,88 g, Zuccheri: 3,53 g, Fibre: 3 g, Grassi: 0,18g, Proteine: 0,98g, Acqua: 92 g...","Unità",["FATATO"],["Ionia"],"COMUNE"],"03IO003":["Guida fatata","Gioca: Conferisci Elusione a un alleato.","","\"Shhh! Di qua! Dobbiamo girare a sinistra dopo la casa sull'albero vagante, poi andare dritti oltre i fiori parlanti. Lu, mi ascolti? Lu? Lu! LULU! NON dargli da mangiare. Non farlo.\"","Unità",["YORDLE"],["Ionia"],"RARA"],"03IO007":["Trevor Dormiglione","Supporto: Crea 1 Brontolina attaccante con le statistiche del mio alleato supportato.","","Devi seguire i tuoi sogni, non manifestarli con invocazioni involontarie sussurrate mentre fluttui, nottambulo, in un'antica e magica foresta. SILENZIO, suvvia.","Unità",["YORDLE"],["Ionia"],"EPICO"],"03IO010":["Streghetta","Supporto: Fornisci Attacco rapido e +1|+0 al mio alleato supportato per questo turno.","","Sir Ribery Montague partì con l'intento di compiere una grande impresa o di ottenere il favore di una potente casata. Il fato lo condusse invece a una foresta di Bandle, dove la giovane Bri lo trasformò in una rana e lo trascinò nelle SUE peripezie. Povero Rib!","Unità",[],["Ionia"],"COMUNE"],"03IO020":["Nonnullare!","Ferma un incantesimo Veloce o Lento che costa 3 o meno.","","\"Non farlo, sciocco di un pelociuffo! Potresti fare del male alle antilopi!\" - Lulu","Incantesimo",[],["Ionia"],"RARA"],"03IO022":["Va' e spacca","Richiama un alleato per evocare 1 sua copia esatta Effimera al suo posto. Riduci il suo costo a 0 per questo turno.","","\"More\nKnow I got it,\nSo here you go,\nYou look like you could use some more.\"\n- Akali, \"MORE\"","Incantesimo",[],["Ionia"],"EPICO"],"03IO018":["Custode peloso","Quando ricevo supporto, forniscimi +0|+3 per questo turno.\nSupporto: Fornisci +3|+0 al mio alleato supportato per questo turno.","","Le fatate creature viola sono dolci esserini amati e aiutati da tutti quelli che incontrano. Quasi tutti, almeno.","Unità",["YORDLE"],["Ionia"],"RARA"],"03DE008":["Tenente della Guardia del Drago","Quando vengo evocato, se un Drago è visibile, conferiscimi Sfidante.","","\"Quando ho perso i miei compagni a Wrenwall, pensavo che avrei perso anche la determinazione... invece non c'è nulla che una battaglia non possa risvegliare in un vecchio soldato.\"","Unità",[],["Demacia"],"COMUNE"],"03DE001":["Confronto","Conferisci Sfidante a un alleato.\nSe è un Drago, pesca 1 carta.","","\"Nessuno ci sfuggirà!\" - Shyvana","Incantesimo",[],["Demacia"],"COMUNE"],"03DE015":["Soppressore roccioso","TUTTI gli incantesimi costano 1 in più.","","Un grossolano blocco di petricite, nelle abili mani del suo scultore, diventa qualcosa di più. È allora che un pezzo inizia realmente a prendere vita.","Unità",[],["Demacia"],"RARA"],"03DE006":["Drago stridente","","","Ogni creatura difende fino alla morte i propri cuccioli, ma poche di loro sanno farlo con l'efficacia di un drago.","Unità",["DRAGO"],["Demacia"],"COMUNE"],"03DE025":["Respiro incandescente","Un alleato con Furia colpisce i 2 nemici più deboli uno dopo l'altro.","","Per secoli i demaciani hanno conosciuto la furia dei draghi solo attraverso le leggende. Dopo Wrenwall, è cambiato tutto.","Incantesimo",["ELEMENTALE"],["Demacia"],"RARA"],"03DE002":["Attacco aereo","Un alleato e un nemico si colpiscono a vicenda. Poi, se l'alleato è un Drago, curalo di 5.","","Quando cavaliere e drago si separarono, feriti e ansimanti, il drago sembrava rinvigorito. Aveva fiutato il sangue e ne voleva ancora.","Incantesimo",[],["Demacia"],"RARA"],"03DE011":["Shyvana","Attacca: Forniscimi +1|+1 per questo turno.","I Draghi alleati hanno inflitto 16+ danni.","\"Da un lato, per la sua stessa natura, è il nostro nemico più odiato, visto che la sua stirpe ha storicamente portato solo dolore a Demacia. Dall'altro, ha la fiducia del Principe e sembra possedere tutte le caratteristiche di una soldata determinata e di un'alleata preziosa. Spero solo che non tradisca la nostra fiducia.\"\n- Pagina del racconto del Tenente Jerik su Wrenwall","Unità",["DRAGO"],["Demacia"],"Campione"],"03DE003":["Vedetta della Guardia del Drago","Quando vengo evocata, se un Drago è visibile, prepara l'assalto.","","\"Lì, in lontananza! Ma è...?\"\n\"Sembrerebbe.\"\n\"Come fai ad averne la certezza?\"\n\"Oh, impossibile confondersi. Copriti le orecchie. Sarà rumoroso.\" - Anden e Yessenia","Unità",[],["Demacia"],"RARA"],"03DE013":["Madre della nidiata","","","\"Attenti, soldati! Se ci muoviamo con cautela e non disturbiamo il nido, possiamo tenere la madre drago sulla difensiva. Se la agitiamo ulteriormente... Beh, vi conviene essere pronti a scappare.\" - Anden Mayne, Ricercatore cervellone","Unità",["DRAGO"],["Demacia"],"COMUNE"],"03DE005":["Ricercatore cervellone","Quando vengo evocato, crea un Drago casuale nella tua mano.","","Uovo di drago (Drago stridente, Draco Murmurationis)\nLuogo: scoperto dal ricercatore Anden Mayne durante la spedizione.\nNote: periodo di gestazione ignoto. Incubazione continuata. Recentemente sono stati osservati dei movimenti nel guscio. L'uovo risponde al calore, alla luce e al martello. Studi inconclusivi.\n- Note di Anden Mayne, Ricercatore cervellone","Unità",[],["Demacia"],"COMUNE"],"03DE007":["Kadregrin l'Infernale","Quando vengo evocato, conferisci +4|+4 agli altri alleati Draghi ovunque.","","Quando Demacia vide un'impennata di attacchi di draghi, Shyvana capì che la colpa era di Kadregrin l'Infernale. Gli altri draghi, ispirati dalla sua audacia e dalla sua fiamma possente, fecero precipitare nel terrore i demaciani. ","Unità",["DRAGO"],["Demacia"],"EPICO"],"03DE012":["Per i caduti!","Quando evochi un'unità Élite, riduci il mio costo di 1.\nPer ogni alleato morto durante questo turno, evoca 1 Indomita Avanguardia.","","\"Se un soldato cade, un altro prende il suo posto. Il nostro stendardo non deve mai cadere.\" - Garen","Incantesimo",[],["Demacia"],"EPICO"],"03DE014":["Vista acuta","Fornisci a un alleato +1|+2 e Vista acuta per questo turno.","","Chiunque osi fare breccia nelle mura di Demacia troverà una compagnia di soldati, pronti e armati fino ai denti.","Incantesimo",[],["Demacia"],"COMUNE"],"03FR020":["Campi delle Cicatrici","Quando un alleato sopravvive ai danni, conferiscigli +1|+0 e Tenacia.","","Ci sono molti luoghi d'onore nell'Artiglio d'Inverno, ma il più importante sono i Campi delle Cicatrici, dove le barche danneggiate di ritorno dalle razzie vengono trasformate in ritrovi per i guerrieri e le loro famiglie. Quelle navi incarnano lo spirito della tribù che le ha costruite: sono resistenti e adattabili.","Monumento",[],["Freljord"],"EPICO"],"03FR007":["Troll spazzino","Quando vengo evocato, se una carta di costo 8+ è visibile, conferiscimi +3|+0.","","L'esploratore si chinò su un brandello di tessuto nascosto nella neve, dove l'odore di sudore umano e fumo riempiva l'aria gelida.\nQuando lo estrasse e lo sollevò, un talismano sbiadito penzolò davanti al cielo grigio. Un talismano avarosano. ","Unità",[],["Freljord"],"COMUNE"],"03FR004":["Ruggito rivitalizzante","Scegli un'unità dalla tua mano e rivelala. Cura il Nexus per il suo Potere.\nIlluminato: Riduci il suo costo a 0.","","\"I troll adulti hanno pelle spessa, ossa robuste e si rigenerano in fretta, quindi sono avversari tenaci e terribili. Abbatteteli subito o ve li ritroverete di nuovo davanti il giorno dopo.\" - Tiratore Avarosano","Incantesimo",[],["Freljord"],"RARA"],"03FR017":["Presagio degli Antichi","Gioca: Se una carta di costo 8+ è visibile, conferisci a un alleato Sopraffare e Rigenerazione.","","Si dice siano pochi i troll a cui vengono trasmessi gli inni degli Antichi, e che quelli che li conoscono possono invocare i loro antenati per dare ai loro fratelli una forza eccezionale.","Unità",[],["Freljord"],"RARA"],"03FR006":["Trundle","Quando vengo evocato, crea 1 Pilastro glaciale nella tua mano.","Ti ho visto giocare Pilastro glaciale.","Le torce del passaggio si accesero a una a una, portando alla luce la scena. C'erano dozzine, forse centinaia di troll, tutti enormi, orribili e letali.\n\"Ve lo chiedo per l'ultima volta,\" ringhiò Trundle con Brividosso appoggiata sulla spalla. \"Vi arrendete, o preferite che spacchi il cranio a ognuno di voi?\"","Unità",[],["Freljord"],"Campione"],"03FR008":["Criosisma ","Fornisci -3|-0 a TUTTE le unità per questo turno. Infliggi 3 a TUTTE le unità.","","\"Seppelliteli vivi!\" - Trundle","Incantesimo",["ELEMENTALE"],["Freljord"],"EPICO"],"03FR002":["Canto dei Troll","Fornisci +0|+2 a un alleato per fornire -2|-0 a un nemico per questo turno.","","Gli inni dei troll sono molto variegati. Cambiano a seconda del gruppo e spesso sono incomprensibili, ma ciò non li rende meno terrificanti da udire. ","Incantesimo",[],["Freljord"],"COMUNE"],"03FR011":["Uzgar l'Antico","","","Lo percepirono prima ancora di sentirlo, il terreno che tremava sotto i loro piedi. Poi arrivò il rumore, come un tuono distante che si avvicinava.\nMeyrick alzò la testa e sgranò gli occhi, ascoltando.\n\"Cos'è?\" sussurrò ansiosamente Anya estraendo l'arco, ma Meyrick stava già correndo via.\n\"SCAPPA!\"","Unità",[],["Freljord"],"RARA"],"03FR005":["Troll razziatore","Quando vengo evocato, se una carta di costo 8+ è visibile, conferiscimi Rigenerazione.","","Una volta giunti tra le capanne avarosane, fecero avanzare Hgar. Lei, ridendo, sollevò Rompineve e si preparò ad abbatterla sulle case di legno fino a ridurle in trucioli.","Unità",[],["Freljord"],"COMUNE"],"03FR018":["Richiamo della natura","Pesca le prime 4 carte del tuo mazzo e tieni tutti gli Yeti, Poro ed Elnuk. Mescola il resto delle carte nel tuo mazzo.","","\"...Poi un elnuk ENOOOOORME è VOLATO fuori dal bosco con un poro piccolo piccolo sulla schiena e c'era anche uno YETI GENTILE che voleva giocare col suo amico e sono rotolati giù dalla montagna tipo RAAAAAWRRRRR e poi...\" - La piccola Ingvar","Incantesimo",[],["Freljord"],"COMUNE"],"03FR010":["Volti degli Antichi","Inizio del turno: Se una carta di costo 8+ è visibile, ottieni una gemma di mana extra per questo turno.","","\"Sorgete, o Antichi, sorgete,\nPadroni del ghiaccio, il cielo infrangete.\nSorgete, o Antichi, sorgete,\nDateci forza, i nemici abbattete.\"\n- Canto dei Troll","Unità",[],["Freljord"],"COMUNE"],"03FR019":["Voci degli Antichi","Ottieni 2 gemme di mana vuote. Pesca tutte le carte che costano 8+ fra le prime 5 carte del tuo mazzo. Rimescola il resto delle carte nel tuo mazzo.","","Per intere generazioni, i coloni avarosani hanno sentito strani e inspiegabili suoni nel tumulto delle tempeste invernali. Un giorno, quando si avventurarono molto più a nord, scoprirono finalmente la fonte. Gli antichi monoliti dei troll parlavano in lingue dimenticate quando il vento soffiava tra le loro fauci sbadiglianti.","Incantesimo",[],["Freljord"],"COMUNE"],"03FR025":["Doni dei troll","Conferisci Rigenerazione a un alleato. Se la possiede già, conferiscigli invece +2|+2.","","Mi fa pena chi crede di vedere la vittoria nel sangue di un troll.","Incantesimo",[],["Freljord"],"RARA"],"03FR022":["Senti il fervore","Evoca 2 campioni casuali diversi, dalla tua mano e dal mazzo. Aumenta le loro statistiche fino a 10|10.","","\"We got it all in our hands now\nSo can you handle what we're all about?\"\n- Ahri, \"POP/STARS\"","Incantesimo",[],["Freljord"],"EPICO"],"04PZ001":["Ekko","Colpisci: Crea 1 Trucco temporale Fugace nella tua mano.","Hai fatto una Previsione 4+ volte. Quando salgo di livello, crea 3 Fratture temporali nel tuo mazzo.","Non conta quanto tempo hai, ma come lo usi.","Unità",[],["Piltover e Zaun"],"Campione"],"04PZ005":["Chirean del Sump","Quando evochi un altro Chirean del Sump, annientami e trasforma le carte Chirean del Sump alleate ovunque in Posse del Sump.","","Il primo zaunita a scoprire i chirean li credeva creature semplici e timide. Col passare degli anni, si abituarono agli umani e mostrarono i loro veri legami sociali, oltre alla loro innata comprensione della tecnologia.","Unità",[],["Piltover e Zaun"],"COMUNE"],"04PZ014":["Aumento di produzione","Per giocare, spendi tutto il tuo mana. Evoca Torrette casuali con costo totale pari al mana speso.","","\"Ti mancano le risorse? Ho costruito il mio primo marchingegno meccanizzato con pezzi di ricambio da orologi e un condensatore termico arrugginito. Bisogna sapersi arrangiare!\" - Heimerdinger","Incantesimo",[],["Piltover e Zaun"],"RARA"],"04PZ003":["Cronodisco","Per giocare, scarta 1 carta.\nInfliggi 1 a un nemico o al Nexus nemico e 1 a un altro.","","\"Occhi aperti!\" - Ekko","Incantesimo",[],["Piltover e Zaun"],"COMUNE"],"04PZ011":["Colpo annunciato","Pesca 1 carta.\nCrea 1 Convergenza parallela nel tuo mazzo.","","\"Divido le linee temporali...\" - Ekko","Incantesimo",[],["Piltover e Zaun"],"EPICO"],"04PZ002":["Felino caduto","Quando vengo evocato, crea 1 Cristallo di hexite tra le ultime 10 carte del tuo mazzo.","","\"NOOO! IL MIAO PIANO È ROVINATOOOOO!\"","Unità",["FELINO"],["Piltover e Zaun"],"RARA"],"04PZ020":["Scambiobot difettoso","Gioca: Scambia le mie statistiche con quelle di un'altra unità.","","\"Un altro jackbot? La fabbrica non aveva chiuso anni fa?\"\n\"Lo credevo anch'io. Si era parlato di 'situazione esplosiva' e 'conflagrazioni inaspettate'.\"\n\"Ah.\"\n\"...Volete giocare?\"\n\"Diamine, sì.\"\n- Avventori di Zaun","Unità",[],["Piltover e Zaun"],"RARA"],"04PZ013":["Elnuk volontario","Quando vengo evocato, crea 1 Elnuk casuale tra le prime 6 carte del tuo mazzo.","","\"OK, PICCOLETTO. TU STAI FERMO QUI MENTRE IO ABBASSO QUESTA LEVA E... BAM! HAH! ELNUK A NON FINIRE! Ci servirà più erba. E molto più spazio.\" - Perfezionista pratica","Unità",["ELNUK"],["Piltover e Zaun"],"RARA"],"04PZ010":["Linee temporali contemporanee","Conferisce a un seguace nella tua mano \"Quando mi giochi, scegli 1 su 3 seguaci con il mio costo e trasformami in quel seguace.\"","","\"Giochiamo con le MIE regole.\" - Ekko","Incantesimo",[],["Piltover e Zaun"],"EPICO"],"04PZ016":["Bombabbuino","Quando vengo evocato, crea 1 Fuochino fuochino! nella tua mano.","","Una volta Jinx aveva un fornitore più convenzionale, ma le cose tra di loro sono precipitate. Il che vuol dire che il fornitore è precipitato da una finestra. Il che vuol dire che il fornitore è stato catapultato fuori da una finestra. Da Jinx.","Unità",[],["Piltover e Zaun"],"COMUNE"],"04PZ007":["Trucco temporale","Prevedi, poi pesca 1 carta.","","\"Il futuro è come lo voglio io...\" - Ekko","Incantesimo",[],["Piltover e Zaun"],"COMUNE"],"04PZ012":["Perfezionista pratica","Gioca: Prevedi. Crea nel tuo mazzo 3 copie della carta scelta.","","\"Kay è eccezionale. È davvero convinta che sbagliando si impara e non ha nessuna paura di sbagliare.\" - Shomi","Unità",[],["Piltover e Zaun"],"RARA"],"04PZ017":["Gloriosa evoluzione","Le tue carte hanno costo -1, Potenziamento, sono create da Gloriosa evoluzione e ora sono Tecnologia.","","\"Il progresso è tutto. Porterò questa città nel futuro, che sia pronta oppure no.\" - Viktor","Incantesimo",[],["Piltover e Zaun"],"EPICO"],"04PZ015":["Adattatron 3000","Quando evochi una Tecnologia, condividiamo le parole chiave.","","\"Ah, sì! L'Adattatron 3000! Adattabile, innovativo e di gran classe! Se potesse parlare, avremmo un sacco da raccontarci.\" - Heimerdinger","Unità",["TECNOLOGIA"],["Piltover e Zaun"],"EPICO"],"04PZ004":["Dropboarder","Se mi vedi in una Previsione, evocami.","","\"Ahhh, Shomi è GENIALE con il hoverboard. Una volta ha fatto un sumpgrinder per poi passare a un boardslide inverso e spiccare il volo con un flip a 360! O almeno credo che si dica così. Il punto è che è eccezionale!\" - Perfezionista pratica","Unità",[],["Piltover e Zaun"],"COMUNE"],"04BW002":["Arpionaggio","Un alleato colpisce un nemico, poi si sposta in cima al tuo mazzo.","","\"Un piccolo regalo d'addio...\" - Pyke","Incantesimo",[],["Bilgewater"],"EPICO"],"04BW007":["Pesce-jaull","Gioca: Ogni alleato in Agguato colpisce un nemico casuale.","","\"Niente di meglio di un pesce-jaull per capire di chi ti puoi fidare e chi puoi far fuori.\" - Pyke","Unità",["LURKER"],["Bilgewater"],"EPICO"],"04BW001":["Testadimaglio pinnarossa","Gioca: Conferisci Vulnerabile a un nemico.","","Sembra che i Testadimaglio spacchino le chiglie delle navi per puro divertimento. Raramente divorano i naufraghi, che diventano invece un banchetto per le altre creature nei paraggi.","Unità",["LURKER"],["Bilgewater"],"COMUNE"],"04BW005":["Pyke","Quando sono in Agguato, trasformami in Morte dagli abissi.","I Pyke alleati hanno inflitto 15+ danni.","\"... Le visioni sono tornate. Vedo i suoi occhi disperati fissarmi mentre il pesce-jaull serra le sue fauci attorno a lui. Abbiamo provato a tirare, ma la barca era troppo piccola e quel mostro troppo grande. Non avevo scelta. Ho dovuto tagliare la cima. Ho dovuto.\"\n- Lettera insanguinata","Unità",["LURKER"],["Bilgewater"],"Campione"],"04BW010":["Arpione da mostri","Saccheggio: Costo 2 in meno.\nInfliggi 5 a un'unità.","","\"La bestia è già stata colpita, ragazzi! Ora infilzatela di nuovo finché non smetterà di dimenarsi e le acque non saranno più blu!\" - Capomastro impietoso","Incantesimo",[],["Bilgewater"],"COMUNE"],"04BW014":["Filotto","Evoca 1 Barile di polvere da sparo.\nCrea 1 Fuori gioco nella tua mano.","","\"Ho fatto come ha chiesto, capitano. È bastata una scintilla e ha fatto il botto.\" - Mozzo della Via del dolore","Incantesimo",[],["Bilgewater"],"COMUNE"],"04BW011":["Dado truccato","Nel prossimo turno, quando danneggi il Nexus nemico, Sottrai 1.","","\"Quindi, cosa sei disposto a scommettere, amico?\" - Tahm Kench","Incantesimo",[],["Bilgewater"],"EPICO"],"04BW015":["Squaletto","","","\"Sembrano innocui, ma adorano il sangue. E se glielo fai assaggiare, quando cresceranno ti verranno a cercare. È meglio se usi i guanti.\" - Cacciatori di jaull","Unità",["LURKER"],["Bilgewater"],"COMUNE"],"04BW003":["Branco di Scannacuda","Gioca: Avvio un attacco gratuito.","","\"Plink, plink, il sangue inizia a zampillare,\nSplash, splash, arriva il branco, meglio annegare,\nZac, zac, i denti squarciano tra gli strilli,\nSul fondale ora dormiamo sonni tranquilli!\"\n- Filastrocca di Bilgewater","Unità",["LURKER"],["Bilgewater"],"COMUNE"],"04BW009":["Baia dello squartatore","Quando gli alleati attaccano, prima di attivare Agguato, conferisci Agguato al primo alleato nel tuo mazzo.","","Le baie più insidiose di Bilgewater divennero presto la tana di svariate bestie marine. Lì si nascondono in attesa di nuove ciurme troppo arroganti per seguire i consigli della capitaneria di porto.","Monumento",[],["Bilgewater"],"RARA"],"04BW008":["Ricchezze perdute","Pesca un Tesoro. Se non ce ne sono da pescare, creane 2 nel tuo mazzo.","","\"Siamo ricchi!\" - Macellaio impietoso","Incantesimo",[],["Bilgewater"],"RARA"],"04BW013":["Vicolo dei predatori","Quando eseguo un conto alla rovescia, evoca 1 seguace casuale di costo 1.\nConto alla rovescia 2: Conferisci +2|+1 e Temibile agli alleati di costo 1.","","\"Pensi di avere la stoffa per essere un Uncino, eh? Lo vedremo, pulce. Dopo il nostro trattamento diventerai un rude lupo di mare... o cibo per pesci.\" - Sottufficiale","Monumento",[],["Bilgewater"],"RARA"],"04BW004":["Esca di sangue","Crea 1 Branco di Scannacuda in cima al tuo mazzo.","","\"Se fosse per me, preferirei farmi ammazzare da un pesce-jaull. Meglio andarsene in fretta che pregare i miei compagni di finirmi mentre vengo mangiato vivo.\" - Macellaio impietoso","Incantesimo",[],["Bilgewater"],"COMUNE"],"04BW016":["Rex in Rovina","Gioca: Gioca Sbarramento d'artiglieria su bersagli nemici casuali per ogni carta che hai pescato in questo turno, fino a 6 volte.","","\"...Rex?\" - Sottufficiale","Unità",[],["Bilgewater"],"RARA"],"04BW006":["La lista","Conferisci Vulnerabile a un nemico. Se è già Vulnerabile, l'alleato più forte inizia un attacco gratuito sfidandolo.","","\"Tu hai un nome e io ho una lista.\" - Pyke","Incantesimo",[],["Bilgewater"],"RARA"],"04IO008":["Danza sprezzante","Richiama 1 unità.\nDanza delle lame 1.","","\"Ritirata! Lasciamo il palcoscenico a qualcun altro!\" - Zinneia, il crescendo d'acciaio","Incantesimo",[],["Ionia"],"COMUNE"],"04IO005":["Irelia","Quando vengo evocata o inizia il turno: Se hai il gettone d'attacco, crea 1 Duetto impeccabile nella tua mano.","Hai attaccato con 14+ alleati.","\"Un tempo studiavamo l'arte e la bellezza e i nostri cuori volavano. Quando hanno fatto irruzione nelle nostre mura, versando il nostro sangue, siamo tornati coi piedi per terra...\"","Unità",[],["Ionia"],"Campione"],"04IO020":["Gruppo disperso","Gioca: Pesca un incantesimo Lento, Veloce o con Raffica.\nIlluminato: Ho Elusione.","","Gli strani e tristemente dolci canti celesti dei Bevitori delle nuvole tennero a bada la Nebbia Oscura... ma solo per poco.","Unità",[],["Ionia"],"RARA"],"04IO004":["Lama fiorente","Gioca: Danza delle lame 2.","","\"C'è chi pensa che i fiori siano fragili e delicati, ma dimentica quanto sia difficile rimanere attaccati all'umile terra, ispirando speranza con ogni petalo.\"\n- Zinneia, il crescendo d'acciaio","Unità",[],["Ionia"],"COMUNE"],"04IO003":["Lama dell'avanguardia","Scegli un alleato che attaccherà con le Lame, poi Danza delle lame 3.","","\"Non lasciateli scappare! I noxiani hanno scatenato questa guerra, ma saremo noi a finirla.\" - Irelia","Incantesimo",[],["Ionia"],"RARA"],"04IO015":["Goccia danzante","Quando vengo richiamata, pesca 1 carta.","","\"L'acqua è flessibile e capace di adattarsi. Assume la forma necessaria al momento e sa fluire e ritirarsi dalla costa.\" - Monaco di Ionia","Unità",[],["Ionia"],"COMUNE"],"04IO014":["Apprendista dell'ombra","Quando evochi un alleato Effimero, forniscimi +1|+0 per questo turno.","","\"Sei come fumo, come un soffio nel vento. I tuoi pugni devono unirsi al buio, come l'ombra. Ora... di nuovo!\" - Maestra Shi","Unità",[],["Ionia"],"COMUNE"],"04IO002":["Zinneia, il crescendo d'acciaio","Quando esegui la Danza delle lame, attacco con le Lame.\nGioca: Danza delle lame 1.","","\"Venite, miei cari. Oggi i nostri piedi scivoleranno sulla terra che ci ha dato nutrimento, con i movimenti che le nostre famiglie ci hanno insegnato. Noi siamo i figli di Ionia e oggi danzeremo per l'arte, la libertà e per il prossimo!\"","Unità",[],["Ionia"],"EPICO"],"04IO007":["Sincope","Scambia 2 alleati.","","\"La danza è il moto in armonia con ogni cosa.\" - Zinneia, il crescendo d'acciaio","Incantesimo",[],["Ionia"],"RARA"],"04IO011":["Direzione ed esecuzione","Richiama un alleato per creare 1 Duetto impeccabile nella tua mano.","","\"Sarà uno spettacolo... indimenticabile.\" - Zinneia, il crescendo d'acciaio","Incantesimo",[],["Ionia"],"COMUNE"],"04IO013":["Protettore sacro","Gioca: Fornisci Barriera a un alleato per questo turno e pesca 1 Shen.\nGli alleati con Barriera hanno Attacco doppio.","","\"Come noi lottiamo per proteggere questa terra, così essa si erge a nostra difesa. Dalla sua furia traiamo la forza per sgominare i nostri nemici. Così, l'equilibrio è salvo.\" - Sacerdote ioniano","Unità",[],["Ionia"],"EPICO"],"04IO012":["Ombre del passato","Richiama tutti gli alleati ed evoca 1 Ombra vivente al loro posto.","","\"Che colpiscano le ombre, dove le loro armi non potranno fare presa.\" - Zed","Incantesimo",[],["Ionia"],"RARA"],"04IO009":["Danzatrice dei nastri","Gioca: Danza delle lame 1.","","\"Che vergogna, ragazzi! Tutta quella forza e poi non avete ritmo? Non tutti nascono per diventare delle stelle, del resto...\"","Unità",[],["Ionia"],"RARA"],"04IO001":["Musicisti battaglieri","Ogni turno, dopo che hai evocato altri 3 alleati, ripristina il mana incantesimo e pesca 1 carta.","","Per alcuni, la musica è una via di fuga dalla violenza e dalla fatica. Per altri, la musica è resistenza.","Unità",[],["Ionia"],"EPICO"],"04IO006":["Difensore della costa","Quando evochi un altro alleato, forniscimi +2|+0 per questo turno.","","Mia cara Kay,\nsono arrivati questa mattina con una flotta che ha oscurato l'alba all'orizzonte. Le loro macchine hanno dato fuoco alle Pianure d'Argento e ora non resta altro che un fitto fumo che infesta l'aria dell'estate. Non possiamo più stare a guardare. Dobbiamo impugnare le vanghe, i rastrelli, le falci e le spade per affrontare il nostro destino.\nSappi che amo te e la nostra casa più di quanto le parole possano esprimere.\n- Lettera bruciata\n","Unità",[],["Ionia"],"COMUNE"],"04SH100":["Attenta preparazione","Per giocarmi, metti nel tuo mazzo una carta dalla tua mano.\nPrevedi, poi crea una copia della carta scelta nella tua mano.","","\"Le azioni di oggi sono i semi per gli alberi del futuro.\" - Tai, aspirante cronomante","Incantesimo",[],["Shurima"],"COMUNE"],"04SH070":["Indegno","Fornisci a un seguace nemico -4|-0 per questo turno.\nSe hai meno gemme di mana del tuo avversario, uccidi il seguace.","","\"Il sole tornerà a splendere sulle terre di Shurima.\" - Voce dell'Ascesa","Incantesimo",[],["Shurima"],"EPICO"],"04SH081":["Tessitrice delle sabbie baccai","Gioca: Conferisci -1|-0 e Vulnerabile a un nemico.","","Ogni grano che versa ruba un secondo delle loro vite, logorandoli come il vento.","Unità",[],["Shurima"],"RARA"],"04SH077":["Voce dell'Ascesa","Se hai fatto salire di livello un campione, gli alleati hanno +2|+0.","","\"L'ho vista parlare, molto tempo fa.\" Il vecchio soldato sorrise e, per un istante, la sua nipotina riuscì a immaginarla: Shurima, dorata e scintillante, con il fiero Azir a guardia della città scelta dalla voce dell'Ascesa. \"Ha risvegliato in noi una passione che credevamo perduta.\"","Unità",[],["Shurima"],"EPICO"],"04SH019":["Rek'Sai","Quando sono in Agguato o Attacco: Conferisci +1|+0 agli alleati con Agguato ovunque.\nFine del turno: Mettimi nel tuo mazzo.","Ho attaccato con 10+ Potere.","\"Il giovane Jhuraa stava esplorando come sempre, quando in una piccola caverna nascosta ha trovato degli antichi testi! Li abbiamo portati a uno studioso a Marrowmark e... parlano di un antico terrore che minacciava i nostri antenati. Una regina. Una regina xer'sai!\" - Fezhaur, anziano di Vekaura","Unità",["LURKER"],["Shurima"],"Campione"],"04SH138":["L'assolutore","Fornisci +2|+1 a un alleato per questo turno. Se hai fatto salire di livello un campione in questa partita, crea 1 Il ritorno dell'assolutore nella tua mano.","","\"Mi hanno detto tutti di non usarla. Secondo loro 'Nessuno dovrebbe impugnare un'arma tanto potente'.\" - Akshan","Incantesimo",[],["Shurima"],"COMUNE"],"04SH089":["Naturalista del deserto","Gioca: Distruggi un Monumento. Se è alleato, evoca 1 Rocciorso burbero.","","\"Kadira oggi ha rotto qualcosa! Di nuovo! Era solo un muro di pietra, ma sembrava vecchio e probabilmente importante per qualche avo. La sua scusa è stata che le mura sono più resistenti a Tereshni, ma insomma... sono molto irritata.\"\n- Diario di Zaifa","Unità",[],["Shurima"],"RARA"],"04SH015":["Raz il Rosso","Attacca: Fornisci -2|-0 ai nemici per questo turno.","","\"Quando nacque questo coccodrillo, gli altri si misero a scommettere su quanto sarebbe vissuto, essendo il più debole della nidiata, nonché un mostro. Nessuno pensava che avrebbe divorato tutti i suoi fratelli. Eh.\"","Unità",[],["Shurima"],"EPICO"],"04SH058":["Artigiana della sabbia","Attacca: Evoca 1 Soldato della sabbia attaccante.","","A pochi vengono insegnate le vie del deserto e quasi a nessuno viene data l'abilità di Azir, quella di dare ordini alle sabbie. Brandire questo potere e conoscere i segreti delle sabbie è un dono conferito solo ai più fedeli e capaci seguaci di Azir.","Unità",[],["Shurima"],"COMUNE"],"04SH080":["Richiamo del branco","Per giocare, piazza in cima al tuo mazzo una carta dalla tua mano.\nCrea 2 unità casuali con Agguato nella tua mano.","","\"Che il sole splenda e la xer'sai dorma.\"\n- Preghiera dei mercanti","Incantesimo",[],["Shurima"],"COMUNE"],"04SH035":["Giorno di paga","Crea 1 Ritrovamento fortunato nella tua mano.","","\"Certo, ho avuto giornate buone e giornate cattive, come tutti. In questo lavoro, le giornate cattive possono essere molto cattive e quelle buone possono essere molto redditizie.\" - Sivir","Incantesimo",[],["Shurima"],"COMUNE"],"04SH028":["Preparativi antichi","Gioca: Prevedi.\nConto alla rovescia 2: Evoca 1 Orolotto.","","Anche se si credevano persi nel tempo, seppelliti sotto anni di sabbia, gli automi erano piazzati con precisione e aspettavano solo di essere risvegliati.","Monumento",[],["Shurima"],"COMUNE"],"04SH054":["Cacciatrice di tesori","Quando vengo evocata, crea 1 Sabbie senzienti nella tua mano.","","\"OK, Davu. Ora entri, prendi quel... qualunque cosa sia e ci rendi... MI rendi ricca. Tutto chiaro? Ah, e se dovesse esserci qualche trappola, ti chiedo scusa in anticipo.\"","Unità",[],["Shurima"],"COMUNE"],"04SH002":["Mietitore baccai","Quando abbatti un'unità, conferiscimi +1|+0.","","\"I baccai scapparono o vennero risparmiati dopo l'Ascensione fallita e nessuno di loro si è più visto. Chi sa per quanto sono rimasti nelle loro tombe oscure, con il marchio della loro vergogna?\" - Scriba Kah'nir, Storie dell'Ascensione","Unità",[],["Shurima"],"RARA"],"04SH042":["Rocciorso ibernato","Conto alla rovescia 3: Evoca 1 Rocciorso burbero.","","\"MI CHIAMO ZAIFA E MI PIACE SCRIVERE COSE STUPIDE SUL MIO STUPIDO DIARIO QUANDO PENSO CHE TUTTI GLI ALTRI STIANO DORMENDO. PERSINO SAMI.\"\n- Diario di Zaifa","Monumento",[],["Shurima"],"COMUNE"],"04SH032":["Spaccaossa spietata","Reputazione: Costo 1 in meno e quando vengo evocata, conferiscimi Sopraffare.","","Il soldato cercò faticosamente di raggiungere la sua lancia, ma lei premette con più forza sul suo torace, fino a farlo desistere. \"No, no,\" lo ammonì, mostrando i suoi denti affilati in un sorriso malvagio. \"Adesso è mia.\"","Unità",[],["Shurima"],"COMUNE"],"04SH055":["Cavalcarovine","","","Prima di arrivare alle cripte, i mercenari e i tombaroli di Shurima devono imparare a sopravvivere agli altri pericoli del deserto, quelli più evidenti. Il caldo intollerabile e i predoni assetati di sangue.","Unità",[],["Shurima"],"COMUNE"],"04SH039":["Zilean","Gioca: Crea 4 Bombe temporali nel tuo mazzo, poi Prevedi.","Ti ho visto distruggere 2+ Bombe temporali alleate.","Nel corso degli anni, Zilean formò una rete di giovani e promettenti maghi da ere diverse, tutti in grado di completare la sua opera, in caso si verificasse l'impensabile. Pur essendo un mentore gentile e incoraggiante, la tristezza corrucciava la sua fronte quando si ritirava nella solitudine. I suoi occhi tradivano una stanchezza che solo chi ha vissuto più vite può sperare di comprendere.","Unità",[],["Shurima"],"Campione"],"04SH073":["Taliyah","Gioca: Evoca una copia esatta di un Monumento alleato.","Hai evocato 5+ Monumenti.","\"Il passo del nomade è sempre leggero, perché non ha il peso delle radici e la sua casa è sempre oltre l'orizzonte.\"\n- Le società di Shurima","Unità",[],["Shurima"],"Campione"],"04SH091":["Khahiri lo Studente","Quando vengo evocato, conferiscimi +1|+1 se hai fatto una Previsione durante questa partita.","","\"Ricorda cos'abbiamo imparato,\" disse Zilean, con un'inusuale dolcezza nella voce. \"Sei sicuro di essere pronto?\"\nKhahiri rassicurò il suo mentore con un sorriso. \"Tornerò presto. E poi ho passato gli ultimi quattro anni a prepararmi per questo momento. Se non ora, quando?\"","Unità",[],["Shurima"],"COMUNE"],"04SH024":["Guglia di sale","Conto alla rovescia 2: Evoca 1 Rocciorso burbero. Poi, se hai evocato 4+ Monumenti in questa partita, conferisci +2|+2 all'alleato più forte.","","Un lavoratore del sale di Shurima apprende rapidamente quali depositi vanno raccolti e quali vanno lasciati in pace.","Monumento",[],["Shurima"],"COMUNE"],"04SH003":["Azir","Quando gli alleati attaccano, evoca 1 Soldato della sabbia in attacco.","Hai evocato 12+ alleati o Monumenti.","\"Quando Azir indossò il mantello dell'imperatore di Shurima, era arrogante. Cieco. Accumulò potere e pianificò l'Ascensione per dominare non solo Shurima, ma tutto il mondo.\" - Scriba Kah'nir, Storie dell'Ascensione","Unità",["ASCESO","VOLATILE"],["Shurima"],"Campione"],"04SH011":["Ricercatori dello Xenotipo","Quando vengo evocata, conferisci +3|+3 a 3 alleati casuali nel tuo mazzo.","","Il Vuoto è pieno di sorprese, che crescono ogni giorno e trovano nuovi modi di infiltrarsi nella torre, invadenti come un ciecospino ma molto più letali. Per questo studiarle è difficile, perché ci vogliono ricercatori astuti, capaci di anticipare e comprenderne i pericoli.","Unità",[],["Shurima"],"RARA"],"04SH130":["Akshan","Quando vengo evocato o colpisco: Evoca 1 Palazzo del condottiero o fai avanzare la carta di 1 turno.","Palazzo del condottiero ha completato il Conto alla rovescia. Quando aumento di livello, evoca 1 Scorta del condottiero.","\"Il codice delle Sentinelle è pieno di limitazioni. 'Non togliere la vita per vendetta', 'Lotta per il mondo, non per te stesso'... Per quanto mi riguarda...\"","Unità",[],["Shurima"],"Campione"],"04SH114":["Furia del deserto","Conferisci +1|+0 agli alleati Soldati della sabbia ovunque.\nEvoca 2 Soldati della sabbia.","","Non dormono. Non esitano. Non conoscono il compromesso, l'emozione, la paura.","Incantesimo",[],["Shurima"],"RARA"],"04SH067":["Renekton","Quando sfido un nemico, forniscimi +2|+1 per questo turno.","Ho inflitto 10+ danni.","\"È facile dimenticare che un tempo era umano, perché l'aspetto da coccodrillo si sposa bene con il suo amore per le battaglie sanguinose...\" - Scriba Kah'nir, Storie dell'Ascensione","Unità",["ASCESO","RETTILE"],["Shurima"],"Campione"],"04SH120":["Possibilità immaginarie","Crea un Monumento casuale con Conto alla rovescia nella tua mano o fai avanzare i tuoi Monumenti di 1 turno.","","\"Il tempo è evanescente.\" - Zilean","Incantesimo",[],["Shurima"],"RARA"],"04SH119":["Colpo di rimbalzo","Reputazione: Costo 3 in meno.\nInfliggi 1 a un nemico casuale o al Nexus nemico per 5 volte.","","\"Non sarà un bello spettacolo.\" - Sivir","Incantesimo",[],["Shurima"],"COMUNE"],"04SH068":["Xer'sai richiamante","Gioca: Prevedi.","","Non tutti gli xer'sai sono nati solo per uccidere. Alcuni riescono a richiamare i loro simili con urla che fanno tremare le sabbie e i sensi.","Unità",["LURKER"],["Shurima"],"COMUNE"],"04SH093":["Pietra plasmata","Fornisci +1|+1 a un alleato per questo turno. Se hai evocato un Monumento in questa partita, forniscigli invece +2|+1.","","\"Con l'aiuto della terra, ci difenderemo da soli!\" - Taliyah","Incantesimo",[],["Shurima"],"COMUNE"],"04SH079":["Sabbie divinatorie","Prevedi.\nFornisci -2|-0 a un nemico per questo turno.","","\"Ho visto il mio destino e questa volta non mi lascerò fermare.\" - Azir","Incantesimo",[],["Shurima"],"RARA"],"04SH038":["Saltarocce","Quando vengo evocata, evoca 1 Sabbie travolgenti.","","\"Oggi comincia il nostro viaggio per Nashramae! Samir vuole attraversare il Grande Sai prima della prossima luna piena e sta facendo un sacco di pasticci! Non sapevo che una singola tavola da sabbia potesse far collassare un'intera duna. E nemmeno Sami. Lui sta bene.\"\n- Diario di Zaifa","Unità",[],["Shurima"],"COMUNE"],"04SH104":["Costrutto della preservazione","Gioca: Fai avanzare un Monumento alleato di 3 turni.","","Quando vuole un momento di pace, Zilean torna nell'ultimo giardino di Icathia, trovandolo esattamente come lo ricordava.","Unità",[],["Shurima"],"RARA"],"04SH128":["Nomade di Vekaura","Quando vengo evocata, evoca 1 Palazzo del condottiero o fai avanzare la carta di 2 turni.","","Vedendo Akshan penzolare sotto la finestra del quarto piano, Najah imprecò sottovoce. Quel ragazzino l'aveva preceduta. Di nuovo. Giocherellando con il pugnale, si chiese cosa avrebbe potuto dirgli. Magari stavolta avrebbe riconosciuto il suo valore.","Unità",[],["Shurima"],"COMUNE"],"04SH109":["Sabbie fatali","Fornisci -4|-0 a un nemico o -1|-0 a 2 nemici e disabilita le loro parole chiave positive per questo turno.","","In alcune parti del deserto le vecchie rovine sono sprofondate nella sabbia, dove creano buche in cui gli incauti viaggiatori rischiano di cadere. ","Incantesimo",["ELEMENTALE"],["Shurima"],"COMUNE"],"04SH043":["Sabbie mobili","Infliggi 4 a un'unità.\nEvoca 2 Soldati della sabbia.","","\"Andate e circondateli. Non possono nulla contro la terra stessa.\" - Azir","Incantesimo",[],["Shurima"],"RARA"],"04SH099":["Sorgi!","Evoca 1 Soldato della sabbia.\nCrea 1 Sorgi! Fugace nella tua mano.","","\"L'ordine è stato dato.\" - Azir","Incantesimo",[],["Shurima"],"RARA"],"04SH048":["Santuario segreto","Reputazione: Costo 3 in meno.\nConto alla rovescia 1: Crea 2 Ritrovamenti fortunati nella tua mano.","","\"Alcune mappe richiedono anni per essere decifrate, così come certe trappole richiedono mesi per essere disinnescate e alcune cripte richiedono settimane per essere esplorate. Ma le volte che ce la fai? Quelle valgono tutto, fino all'ultimo secondo.\" - Sivir","Monumento",[],["Shurima"],"COMUNE"],"04SH056":["Speculatrice","Quando vengo evocata, crea 1 Ritrovamento fortunato nella tua mano.","","\"Amico mio, ti ho recuperato questa meraviglia dalla bellezza senza pari direttamente dalla leggendaria Tomba degli Imperatori, strappandola alle mani di Renekton in persona, per poi fuggire, circondata da dieci... venti cavalca-sauren assetati di sangue! È un miracolo che un simile tesoro possa arrivare nelle tue mani.\"","Unità",[],["Shurima"],"COMUNE"],"04SH020":["Sivir","","Hai inflitto 30+ danni.","Sivir ha vissuto una vita da mercenaria, accollandosi i rischi e le ricompense della sua scelta. Una fatidica spedizione le costò quasi la pelle, ma il suo sangue filtrò nelle sabbie di Shurima e svegliò un antico potere, che avrebbe riportato lei e la sua patria alla grandezza.","Unità",[],["Shurima"],"Campione"],"04SH057":["Maresciallo motivante","Quando evochi un altro alleato, forniscigli +2|+0 per questo turno.","","Ricevere la benedizione di Azir è un grande onore. Benedire in suo nome è un onore ancor più grande.","Unità",[],["Shurima"],"RARA"],"04SH103":["Cacciatrice spietata","Gioca: Conferisci Vulnerabile a un nemico.","","\"Ecco fatto. Legato come un salame. Renekton preferisce che i suoi pasti siano ancora vivi e tremanti.\"","Unità",[],["Shurima"],"COMUNE"],"04SH065":["Xerxa'reth, Titano del Sottosuolo","Attacca: Se ho 8+ Potere, forniscimi Temibile, Sopraffare e Scudo magico per questo turno.","","\"Si dice che secoli fa sulle sponde del fiume Khaleek sorgesse un grande avamposto commerciale detto Taraleek, ma un brutto giorno una belva spaventosa emerse dal terreno e fece sparire nel nulla sia l'avamposto sia tutti quelli che ci vivevano. Ma che razza di mostro può fare una cosa simile?\" - Storico shurimano","Unità",["LURKER"],["Shurima"],"EPICO"],"04SH034":["Lancetta","Quando vengo evocata, crea 2 Secoli istantanei nella tua mano.","","Il costante rumore nei piani bassi della torre è dovuto a Lancetta, il guardiano della torre che mantiene gli ingranaggi in movimento.","Unità",[],["Shurima"],"EPICO"],"04SH082":["Via della rovina","Pesca 1 carta.\nSe hai abbattuto un'unità in questo turno, assorbi 2 dal Nexus nemico.","","Le Furie della sabbia reclutano tra le fila nemiche. Chiunque sopravviva all'assalto iniziale viene invitato a unirsi... o a morire.","Incantesimo",[],["Shurima"],"RARA"],"04SH075":["Scorta imperiale","Fornisci Vulnerabile ai nemici per questo turno ed evoca 6 Soldati della sabbia.","","\"Soldati, marciate.\" - Azir","Incantesimo",[],["Shurima"],"EPICO"],"04SH018":["Rito del dominio","Uccidi un alleato o distruggi una tua gemma di mana per fornire -2|-0 a tutti i nemici per questo turno.","","\"Noi combattiamo, loro sanguinano!\" - Renekton","Incantesimo",[],["Shurima"],"RARA"],"04SH009":["Baccai furioso","Gioca: Se hai ucciso 4+ unità in questa partita, io e un nemico ci colpiamo a vicenda.","","Il risentimento di chi porta rancore non può fare altro che crescere, anche se l'oggetto del suo rancore è morto da secoli.","Unità",[],["Shurima"],"RARA"],"04SH049":["Poro del destino","Inizio del turno: Se hai fatto aumentare di livello un campione, trasformami in Poro gloriosa.","","Non sapeva cosa aveva trovato, di preciso... ma luccicava e sembrava un bello spuntino.","Unità",["PORO"],["Shurima"],"COMUNE"],"04SH045":["Sfinimento","Fornisci -2|-0 e Vulnerabile a un nemico per questo turno.","","Chi vive nel deserto sa come evitare il calore bruciante del sole, ma chi è impreparato scopre che consuma forze ed energie con una velocità allarmante.","Incantesimo",[],["Shurima"],"COMUNE"],"04SH037":["Disfare il terreno","Evoca 2 Sabbie travolgenti.\nPesca 1 carta.","","Il Grande Sai è splendido, ma non è un posto per i deboli. Molte vite sono andate perdute tra le sue dune e mentre gli xer'sai hanno fatto le loro vittime, la terra si prende la sua parte.","Incantesimo",["ELEMENTALE"],["Shurima"],"RARA"],"04SH107":["Salita dell'Asceso","Fai salire di livello tutti gli alleati Ascesi di livello 1.","","\"Il futuro verrà scritto dagli Ascesi!\" - Azir","Incantesimo",[],["Shurima"],"EPICO"],"04SH047":["Nasus","Ho +1|+1 per ogni unità che hai ucciso in questa partita.","Ho colpito infliggendo 10+ danni in un solo colpo.","\"La nuova benedizione di Nasus gli diede innumerevoli vite da dedicare allo studio e alla natura della vita e della morte. Questa vita estesa, dopo la caduta di Shurima, si sarebbe rivelata la sua maledizione.\" - Scriba Kah'nir, Storie dell'Ascensione","Unità",["ASCESO","CANIDE"],["Shurima"],"Campione"],"04SH097":["Custode del santuario","Gioca: Uccidi un seguace nemico. Se hai abbattuto 13+ unità in questa partita, uccidi invece tutti i seguaci del nemico e poi evoca una mia copia.","","I baccai hanno il compito di difendere il santuario e proteggere i suoi antichi tesori. Sono lì anche per il bene dei mortali che si credono abbastanza intelligenti o forti da sostenere il peso del giudizio del Curatore.","Unità",[],["Shurima"],"EPICO"],"04SH026":["Custode delle dune","Quando vengo evocato, evoca 1 Soldato della sabbia.","","\"Quando l'imperatore comanda, io e la sabbia obbediamo.\"","Unità",[],["Shurima"],"COMUNE"],"04SH102":["Ambasciatrice d'oro","Fedeltà: Pesca un campione e conferiscigli +2|+2.","","\"Il nostro futuro luminoso è sotto le sabbie. Sta a noi spianare la via ad Azir. L'impero dorato del deserto sorgerà nuovamente!\"","Unità",[],["Shurima"],"COMUNE"],"04SH001":["Aspirante cronomante","Gioca: Prevedi.","","Nei suoi studi di cronomanzia, Tai ha dovuto fare i conti con l'incertezza della sua decisione. Era meglio sperare in una possibile vittoria che fissarsi sui possibili intoppi.","Unità",[],["Shurima"],"COMUNE"],"04SH022":["Xer'sai spaccasabbia","","","Tutti gli xer'sai sono abili scavatori, ma solo gli spaccasabbia sono abbastanza grandi e potenti da sbriciolare il sostrato roccioso che serpeggia lungo il Grande Sai e aprire la terra per continuare a cacciare.","Unità",["LURKER"],["Shurima"],"RARA"],"04SH030":["Spostamento temporale","Fornisci a un campione alleato \"La prossima volta, se dovessi morire in questo turno, curami completamente e conferiscimi +3|+3\".","","\"Non possiamo fermare l'inevitabile... ma possiamo posticiparlo.\" - Zilean","Incantesimo",[],["Shurima"],"RARA"],"04SH013":["Preservarium","Quando vengo evocato, pesca 1 carta.\nConto alla rovescia 2: Pesca 1 carta.","","Zilean mostra alle persone che porta alla torre ciò che vogliono ripristinare. Il preservatore è in grado di mostrarglielo, anche se solo per un istante.","Monumento",[],["Shurima"],"RARA"],"04SH062":["Disco solare sepolto","Inizio della partita: Evoca 1 mia copia dal tuo mazzo se è solo di Shurima.\nConto alla rovescia 25: Restaura il Disco solare.\nAvanzo di 9 turni per ogni volta che un Asceso alleato è salito di livello in questa partita.","","Quando Azir vide il Disco solare della capitale di Shurima, non lo vide per ciò che era, ma per ciò che poteva diventare: la chiave per riportare Shurima alla gloria di un tempo.","Monumento",[],["Shurima"],"EPICO"],"04SH016":["Attacco incrementale","Un alleato colpisce un'unità.\nSe muore, conferisci +2|+2 ai campioni alleati ovunque.","","\"La tua anima verrà misurata.\" - Nasus","Incantesimo",[],["Shurima"],"RARA"],"04SH125":["Scassinatrice di Vekaura","Gioca: Fornisci +2|+0 a un alleato per fornire -2|-0 a un nemico per questo turno.","","Tena attese pazientemente che la saliva caustica del suo animaletto sciogliesse le barre dorate del cancello posteriore del palazzo. Dietro l'angolo l'aspettava una montagna di tesori inestimabili... Più che sufficienti a ridare a Vekaura la sua gloria perduta.","Unità",[],["Shurima"],"RARA"],"04SH108":["Lama boomerang","Un alleato colpisce il nemico più forte e quello più debole uno dopo l'altro.","","\"Meglio abbassarsi.\" - Sivir","Incantesimo",[],["Shurima"],"RARA"],"04SH066":["Tempo in bottiglia","Prevedi e fai avanzare un Monumento alleato di 2 turni.","","\"Se vedessi il tempo come lo vedo io, sapresti che non è immutabile.\" - Zilean","Incantesimo",[],["Shurima"],"COMUNE"],"04SH021":["Khahiri il Rinnovato","Quando vengo evocato, crea una mia copia nel tuo mazzo. Quando mi vedi in una Previsione, conferisci +2|+2 a tutte le mie copie alleate ovunque.","","Khahiri sparì solo per un istante per poi riapparire. Più vecchio di dieci anni e con una strana arma dall'aspetto letale, fu accolto da sussulti di stupore e preoccupazione.","Unità",[],["Shurima"],"RARA"],"04SH101":["Consiglio devoto","Inizio del turno: Se hai fatto salire di livello un campione, cura di 2 i tuoi campioni e il tuo Nexus.","","\"Ho giurato fedeltà ad Azir e a Shurima, la mia patria! Farai lo stesso?\"","Unità",[],["Shurima"],"RARA"],"04SH012":["Stimato ierofante","Quando vengo evocato, fai avanzare il tuo Disco solare sepolto di 3 turni.","","\"Oh! È Padjuman, uno degli anziani di Nashramae! Oggi sono proprio venuti tutti nella nostra città, papà!\" - Spettatore emozionato","Unità",[],["Shurima"],"COMUNE"],"04SH031":["Futuro promettente","Conferisci a un Monumento alleato \"Il completamento del mio Conto alla rovescia attiva due volte i suoi effetti\".","","\"I mortali passano così tanto tempo nell'attesa. La mia più grande speranza è che tutti vengano ricompensati per la loro pazienza.\" - Zilean","Incantesimo",[],["Shurima"],"EPICO"],"04SH004":["Peso del giudizio","Infliggi 2 a un campione o 4 a un seguace.","","\"Una vita in cambio di tante. Una vita per far prosperare gli altri.\" - Nasus","Incantesimo",[],["Shurima"],"COMUNE"],"04SH059":["Rito della negazione","Uccidi un alleato o distruggi una tua gemma di mana per fermare tutti gli incantesimi veloci, gli incantesimi lenti e le abilità del nemico.","","L'analisi è uno dei fondamenti della cronomanzia, perché molte azioni vanno fermate in vista delle soluzioni del futuro.","Incantesimo",[],["Shurima"],"EPICO"],"04SH044":["Curatore meccanico","Gioca: Fai avanzare un Monumento alleato di 2 turni.","","I costrutti che proteggono la torre di Zilean sono in grado di resistere ai rigori del deserto per migliaia di anni, e non solo perché sono ben progettati.","Unità",[],["Shurima"],"COMUNE"],"04SH076":["Clessidra antica","Annienta un alleato per evocare al suo posto 1 Statua in stasi con quell'alleato conservato all'interno.","","\"Oh, Tai! Vieni! Ci serve il tuo aiuto con una cosa.\"\n- Xetsa, ricercatrice del Vuoto","Incantesimo",[],["Shurima"],"RARA"],"04SH118":["Sabbie senzienti","Evoca 1 Destriero di arenaria.","","\"La scatola potrebbe valere qualcosa, ma quello che contiene no di sicuro. Quindi non vale la pena aprirla. Parlo per esperienza.\" - Sivir","Incantesimo",[],["Shurima"],"COMUNE"],"04SH072":["Idromante","Quando vengo evocata, conferisci ai campioni e ai Monumenti alleati Scudo magico.","","\"Ah, non ti aspettavi di vedere dell'acqua nel bel mezzo del deserto. Non temere. Vieni, bevi un po', lavati i piedi. Riposati un po' all'ombra. Questa è la nuova Shurima di Azir ed è un'oasi.\"","Unità",[],["Shurima"],"COMUNE"],"04SH041":["Esploratrice Sai","Gioca: Prevedi. Se scegli un Monumento, conferiscimi Elusione.","","\"Abbiamo avuto problemi, poco fa! Si prospettava una grande tempesta da ovest e Taliyah ha superato le gallerie degli xer'sai a sud. Ho visto il tempio a nord e ora siamo al sicuro tra le sue mura di terracotta. Gli altri stanno dormendo e la mia fiamma, come me, vacilla. Spero di fare dei bei sogni.\"\n- Diario di Zaifa","Unità",[],["Shurima"],"COMUNE"],"04SH005":["Predone assetato di sangue","","","Le Furie della sabbia fanno ogni cosa con i loro compagni. Lottano, cacciano, uccidono... e mangiano.","Unità",[],["Shurima"],"COMUNE"],"04SH083":["Preveggenza crudele","Prevedi.","","\"La pinna porta paura, ma i denti portano la morte.\" - Detto shurimano","Incantesimo",[],["Shurima"],"RARA"],"04SH092":["L'ora è giunta","Evoca 1 Orolotto.\nSe hai fatto una Previsione durante questa partita, evocane invece 2.","","\"Smettila di lamentarti e vieni qui! Hai della sabbia negli ingranaggi.\" - Tai, aspirante cronomante","Incantesimo",[],["Shurima"],"COMUNE"],"04SH046":["Chimera di arenaria","Costo 1 in meno per ogni volta che un alleato ha attaccato durante questa partita.","","Al ritorno di Azir, gli shurimani videro le antiche bestie della leggenda, fatte di sabbia, ma comunque impressionanti.","Unità",[],["Shurima"],"RARA"],"04SH105":["Sepolcro insabbiato","Quando gli alleati attaccano, evoca 1 Destriero di arenaria in attacco.","","Quando passarono nella gola, l'artigiana della sabbia pronunciò le parole magiche. Una raffica di vento risuonò nel canyon, per poi lasciare spazio al fragore degli zoccoli in lontananza.","Monumento",[],["Shurima"],"RARA"],"04SH131":["Rampino","Un alleato che hai bersagliato in questo turno colpisce un nemico.","","\"Nessuno si aspetta mai il rampino!\" - Akshan","Incantesimo",[],["Shurima"],"RARA"],"04SH074":["Cucciolo di xer'sai","","","A volte, dopo aver bloccato una carovana, i cacciatori si ritirano e lasciano ai neonati il compito di foraggiare. È così che i giovani xer'sai affinano il loro istinto, distinguendo i suoni del deserto e quelli delle loro prede.","Unità",["LURKER"],["Shurima"],"COMUNE"],"04SH137":["Sciame ronzante","Quando vengo evocato, crea una mia copia nella tua mano se hai fatto salire di livello un campione durante questa partita.","","Gli scarabei giganti furono ritenuti estinti dopo la caduta dell'impero di Shurima, ma i tentacoli striscianti della nebbia scavarono a fondo nella sabbia e riportarono alla luce quelle antiche creature, asservendole a Viego.\n","Unità",[],["Shurima"],"EPICO"],"04SH069":["Predatore spietato","Fornisci +2|+0 a un alleato per rendere Vulnerabile un nemico per questo turno.","","\"Fateli a brandelli!\" - Renekton","Incantesimo",[],["Shurima"],"COMUNE"],"04SH121":["Rito della chiamata","Uccidi un alleato o distruggi una tua gemma di mana per pescare un campione.","","\"È necessario un sacrificio.\" - Nasus","Incantesimo",[],["Shurima"],"COMUNE"],"04SH110":["Tessitura di pietra","Manifesta un Monumento che ti puoi permettere.","","\"Vieni, c'è così tanto da vedere!\" - Taliyah","Incantesimo",["ELEMENTALE"],["Shurima"],"EPICO"],"04SH051":["Altare dell'imperatore","Quando gli alleati attaccano, evoca 1 Soldato della sabbia in attacco.","","Gli artigiani della sabbia alzarono le mani, dando alla sabbia la familiare forma di soldati corazzati e senza nome: un esercito instancabile, pronto a lottare per il suo dio-imperatore. ","Monumento",[],["Shurima"],"RARA"],"04SH106":["Fuoco dello spirito","Fornisci ai nemici -2|-0 e \"Fine del turno: Infliggimi 2\" per questo turno.","","\"Il loro spirito brucerà.\" - Nasus","Incantesimo",[],["Shurima"],"RARA"],"04SH129":["Picchiatore di Vekaura","Colpisci: Crea 1 Ritrovamento fortunato nella tua mano.","","\"OK, Barb. Abbiamo sistemato le guardie su questo piano, ma dobbiamo comunque essere silenziosi.\n\"BLARGH-BLAAA!\"\n\"Voce bassa, Barbara.\"\n\"Blarb.\"\n\"Brava ragazza.\"","Unità",[],["Shurima"],"RARA"],"04FR006":["Inquisitore Draklorn","Quando vengo evocato, evoca 1 Schiavo ghiacciato.\nFine del turno: Se il Conto alla rovescia di una delle tue carte Schiavi ghiacciati è di 4 o meno, fallo avanzare fino a 0.","","\"La mia signora mi appare nei sogni e mi sussurra di seguirla. Non oso disobbedire al suo ordine.\"","Unità",[],["Freljord"],"EPICO"],"04FR012":["Sepolto nel ghiaccio","Annienta ogni nemico per evocare al suo posto 1 Tomba di ghiaccio con quel nemico conservato all'interno.","","\"Il freddo travolge tutto, prima o poi.\" - Lissandra","Incantesimo",["ELEMENTALE"],["Freljord"],"EPICO"],"04FR016":["Bottino di guerra","Conferisci +1|+2 a un alleato.\nSaccheggio: Conferisci +2|+4.","","\"Voi avarosani vi rammollite nei vostri campi fertili. Riposate questa notte, miseri smidollati. Mentre sognerete il raccolto di domani, noi ce lo prenderemo.\" - Vrynna, Madre delle cicatrici","Incantesimo",[],["Freljord"],"COMUNE"],"04FR013":["Resistenza al gelo","Ottieni una gemma di mana vuota e conferisci +0|+2 a un alleato.","","\"Attenzione al ghiaccio, ma soprattutto... a ciò che nasconde!\" - Scritta sul muro di una locanda del Freljord","Incantesimo",["ELEMENTALE"],["Freljord"],"COMUNE"],"04FR005":["Lissandra","Quando vengo evocata, evoca 1 Schiavo ghiacciato e fai avanzare la carta di 2 turni.","Hai evocato 2+ alleati di costo 8+. Quando aumento di livello, crea 1 Osservatore nella tua mano.","\"Le Sentinelle del Gelo attendono dietro queste mura, sospese nel ghiaccio, congelate nel tempo... e mentre aspettano, io ho dei piani da realizzare...\"","Unità",[],["Freljord"],"Campione"],"04FR011":["Soccombi al freddo","Congela un nemico.\nEvoca 1 Schiavo ghiacciato.","","\"Il freddo provoca molte reazioni. Vediamo quale sarà la tua.\" - Lissandra","Incantesimo",["ELEMENTALE"],["Freljord"],"COMUNE"],"04FR001":["Schiavo ghiacciato","Conto alla rovescia 9: Evoca 1 Servo della Guardia del Gelo.","","C'erano senza dubbio molti guerrieri senza sale in zucca nelle prime linee del caotico esercito di Trundle, ma Lissandra voleva qualcosa di più fedele, che servisse solo lei...","Monumento",[],["Freljord"],"COMUNE"],"04FR007":["Sepoltura","Annienta un'unità per evocare al suo posto 1 Tomba di ghiaccio con quell'unità conservata all'interno.","","\"Inginocchiati o congela.\" - Lissandra","Incantesimo",["ELEMENTALE"],["Freljord"],"RARA"],"04FR017":["Dono ancestrale","Conferisci +2|+2 al primo alleato nel tuo mazzo.\nIlluminato: Conferisci +2|+2 a tutti gli alleati nel tuo mazzo.","","Il freddo impietoso del Freljord, con le sue brutali tempeste, uccide quasi tutti quelli che si addentrano nelle sue lande desolate. Chi sopravvive, però, trova dentro di sé una forza che lo alimenta per il resto della vita.","Incantesimo",[],["Freljord"],"COMUNE"],"04FR014":["Gola della sventura","Quando vengo evocato, cura di 2 il tuo Nexus.\nConto alla rovescia 1: Infliggi 2 a TUTTE le unità.","","Bizzarre forme di ghiaccio oscuro crescono sulle superfici della gola, con spine rivolte verso l'esterno che dissuadono i potenziali intrusi.","Monumento",[],["Freljord"],"RARA"],"04FR009":["Frammento di ghiaccio","Infliggi 1 a TUTTO.","","\"Ricoprirò il mondo di ghiaccio.\" - Lissandra","Incantesimo",["ELEMENTALE"],["Freljord"],"COMUNE"],"04FR015":["Poro mitico","Quando vengo evocato, conferisci una parola chiave casuale ai Poro alleati.","","Si dice che tra i poro esista un essere leggendario, una creatura mitica che viaggia per il mondo elargendo ogni sorta di dono magico ai suoi amici pelosi.","Unità",["PORO"],["Freljord"],"RARA"],"04FR019":["Madre Zannabrina","Quando vengo evocato, evoca 1 Branco Zannabrina.","","Restando accucciati e circospetti, i lupi zannabrina giravano attorno al drüvask. Era pervaso da un pungente e soverchiante odore di morte.","Unità",["CANIDE"],["Freljord"],"RARA"],"04FR018":["Guardiano abominevole","Quando sono nella mano, all'Inizio del turno: Se hai 2+ Yeti, evocami e crea una mia copia nel tuo mazzo.\nGioca: Pesca 1 Yeti.","","\"...e sono anche silenziosi! L'ultima volta che ero là avevo trovato rifugio in una caverna e ci ho trovato dei cuccioli addormentati. Ho provato ad allontanarmi, ma uno degli adulti è tornato, grosso come una montagna e coperto di ghiaccio! E ora apri bene le orecchie...\" - Bjerg farneticante","Unità",["YETI"],["Freljord"],"EPICO"],"04FR010":["Tre sorelle","Crea 1 Colpo raggelante, Furia del nord o Sepoltura Fugaci nella mano.","","Le sorelle freljordiane Avarosa, Serylda e Lissandra avevano un grande potere, che decisero di brandire ognuna in modo diverso - con pietà, rigore o malizia.","Incantesimo",[],["Freljord"],"RARA"],"04NX002":["Parole sussurrate","Reputazione: Costo 2 in meno.\nPesca 2 carte.","","Prima delle notizie, le voci. Prima delle voci, l'atto. Prima dell'atto, il piano.","Incantesimo",[],["Noxus"],"RARA"],"04NX010":["Spina della rosa","Quando vengo evocata, crea 1 Astuzia nella tua mano.","","\"Aelana, mia cara amica e collega! Hai visto Lord Duin? Ah, che peccato. Volevo proprio fare due chiacchiere. Spero che abbia fatto con calma stasera. Non vorrei che succedesse qualcosa di brutto al caro vecchio...\" - Lady Auvray, spia della Rosa Nera","Unità",[],["Noxus"],"COMUNE"],"04NX021":["Gladiatore a riposo","Quando mi scegli come bersaglio, conferiscimi +1|+0.","","Dopo innumerevoli battaglie, Beryn giurò di non impugnare più una spada, neppure per difendere la sua stessa vita. Ma quando le strane nebbie invasero Noxus e si impadronirono di Thea, capì che la sua promessa andava infranta: l'avrebbe liberata a qualsiasi costo.","Unità",[],["Noxus"],"RARA"],"04NX022":["Gladiatrice in Rovina","Quando vengo evocata, crea 1 Raid di mezzanotte nella tua mano.","","Una volta scontata la sua pena, Thea capì che non avrebbe mai potuto riunirsi alla sua gente. La guerra e Noxus l'avevano cambiata, rendendola un'assassina. Non avrebbe mai più trovato pace. Per questo decise di usare le sue abilità per fare soldi nell'arena.","Unità",[],["Noxus"],"RARA"],"04NX015":["Affari insanguinati","Reputazione: Costo 2 in meno.\nUn alleato con 5+ Potere colpisce un nemico.","","\"I più grandi pericoli sono quelli che passano inosservati.\" - LeBlanc","Incantesimo",[],["Noxus"],"COMUNE"],"04NX019":["Squamasauro furioso","Quando un nemico mi blocca, forniscimi +3|+0 per questo turno.","","Sorpreso dalla resilienza della creatura trovata sulle rive di Ionia, il giovane generale decise di portarla a casa, desideroso di scoprire la sua vera forza.","Unità",["RETTILE"],["Noxus"],"EPICO"],"04NX008":["Stratega incisivo","Reputazione: Costo 2 in meno.\nQuando vengo evocato, prepara l'assalto.","","Nelle stanze segrete della Rosa Nera, i nobili noxiani muovono i loro pedoni, assassinando vittime lontane.","Unità",[],["Noxus"],"RARA"],"04NX006":["Spia della Rosa Nera","Reputazione: Quando vengo evocata, trasformami in una copia esatta dell'alleato più forte che ha colpito in questo turno.","","\"Un segreto vale solo il costo di mantenerlo.\"","Unità",[],["Noxus"],"EPICO"],"04NX001":["Simulacro","Reputazione: Costo 3 in meno.\nQuando giochi il tuo prossimo incantesimo in questo turno, giocalo di nuovo sugli stessi bersagli.","","L'imitazione è una lusinga e le lusinghe possono essere letali.","Incantesimo",[],["Noxus"],"RARA"],"04NX004":["LeBlanc","","Ti ho visto infliggere 15+ danni. Quando aumento di livello, crea 1 Immagine riflessa nella tua mano.","\"Non c'è bisogno di litigare. Per il momento, evitiamo di agire d'impulso. Riparliamone dopo aver ricevuto notizie dal nostro emissario. In fondo...\"","Unità",[],["Noxus"],"Campione"],"04NX016":["Tessitore urlante","Attacca: Fornisci +2|+0 agli alleati Ragno in questo turno.","","\"Vai, dolcezza. Che gli altri sentano la tua chiamata. Sai come si agitano. Sai quanto mi dà piacere.\" - Elise","Unità",["RAGNO"],["Noxus"],"RARA"],"04NX007":["Athakan, Latore di Rovina","Gioca: Rianima l'alleato morto più forte.\nAttacca: Conferiscimi Potere pari alla somma del Potere di tutti gli alleati.","","Un'aberrazione senza nome svettava sopra di loro nella sala piena di fumo. I maghi intonavano cori disarmonici con voci stridule rotte dal terrore. Il mostro respirava a pieni polmoni la loro paura e ogni afflato lo riempiva di un terribile potere.","Unità",[],["Noxus"],"EPICO"],"04NX018":["Belva Cremisi ","La prossima volta che evochi un altro alleato, infliggigli 1 e conferiscimi +1|+1.","","\"Vengono raramente tenuti come animali domestici. Basta un piccolo graffietto per aprire una vena... ma a me non dispiace.\" - Clara, Adepta Cremisi","Unità",["FELINO"],["Noxus"],"COMUNE"],"04NX003":["Sigillo della malvagità","Reputazione: Costo 2 in meno.\nInfliggi 2 a un bersaglio.","","Quando la battaglia è vinta, non bisogna esitare: avanzare, inseguire e annientare il nemico.","Incantesimo",[],["Noxus"],"COMUNE"],"04NX017":["Superiorità numerica","Evoca 2 Predoni della Legione.","","I soldati di Noxus non lasciano quasi mai sopravvissuti, ma i predoni ancora di meno.","Incantesimo",[],["Noxus"],"COMUNE"],"04NX009":["Lama spinata","Fornisci +5|+0 a un alleato per questo turno.","","\"Agirai con grazia ed eleganza. Blandirai e disarmerai. Ascolterai e imparerai. E quando sarà il momento, colpirai... e ucciderai.\" - LeBlanc","Incantesimo",[],["Noxus"],"COMUNE"],"04SI005":["Kindred","In ogni turno, la prima volta che abbatti un'unità, marchio il nemico più debole.\nFine del turno: Uccidi le unità con il mio marchio.","Ti ho visto abbattere 2+ unità con il mio marchio.","Un uomo afflitto da una grande mancanza\nIn due entità improvvisamente si divise\nDa uno nacque una nuova speranza\nDa quel momento la nuova vita gli sorrise.","Unità",[],["Isole Ombra"],"Campione"],"04SI055":["Viego","La prima volta che un altro alleato muore in un turno, evoca 1 Nebbia invadente.","Ho visto morire alleati con un totale di 20+ Potere.","\"C'è qualcosa nel giovane re che mi turba enormemente. È il suo cuore... Soffre per una fame che non può essere saziata, per un desiderio inesaudibile.\" - Dalle cronache di Nunyo Necrit di Camavor","Unità",[],["Isole Ombra"],"Campione"],"04SI016":["Sanguisuga spirituale ","Gioca: Uccidi un alleato per pescare 2 carte.","","Si nascondono nell'ombra, in attesa di un cenno di stanchezza o di una mente distratta. Poi artigli, fauci e, finalmente, il buio.","Unità",[],["Isole Ombra"],"COMUNE"],"04SI007":["Demone dell'etere","Gioca: Uccidi un alleato per uccidere un nemico.","","\"Il mio tempo in questo luogo volge al termine e mi ritrovo a pensare non alla mia prima morte, ma alla seconda. Chi sarà l'ultimo a ricordare il mio nome? E quando lascerà questa terra... cosa sarà di me?\" - Illustre benefattore","Unità",["VOLATILE"],["Isole Ombra"],"RARA"],"04SI011":["Volontà crepuscolare","Pesca 1 carta.\nCrepuscolo: Attiva l'effetto Crepuscolo di un alleato, ignorando le parti che richiedono un bersaglio.","","\"Vieni, piccolo. Non c'è bisogno di avere paura.\" - Madre della maschera","Incantesimo",[],["Isole Ombra"],"RARA"],"04SI018":["Selva demoniaca","Dopo che ho visto 3+ alleati Temibili o con Crepuscolo attaccare, distruggimi per evocare Vilemaw.","","I suoi altari son silenti, i suoi sentieri sepolti,\nma nel buio ancor serpeggia la belva scordata dagli stolti.","Monumento",[],["Isole Ombra"],"EPICO"],"04SI015":["Scarabeo di mare","Quando muore un altro alleato, o Ultimo respiro: Getta 1.","","\"Bene, gente, tirate su le trappole! E ricordate, se vedete uno scarabeo di mare, tagliate la fune e su un'altra. Inutile rischiare la chiglia per qualcosa che hanno mezzo mangiato, capito?\" - Capitano di Bilgewater","Unità",["MOSTRO MARINO"],["Isole Ombra"],"RARA"],"04SI004":["Le ali e l'onda","Gioca: Giocami come Prima ondata o Ultimo soffio.","","I Kinkou parlano solo di due divinità: la prima ondata, che culla la vita nelle sue tiepide acque, e l'ultimo soffio, che la porta via con i suoi ultimi e freddi sospiri.","Unità",[],["Isole Ombra"],"EPICO"],"04SI017":["Canto delle Isole","Conferisci Rubavita, Temibile ed Effimero a un alleato.","","\"Vieni, piccolo. Vedi ciò che io vedo, senti ciò che io sento. Non temere l'oscurità.\" - Il Ravvivatore","Incantesimo",[],["Isole Ombra"],"COMUNE"],"04SI054":["Soldato di Camavor","Quando vengo evocato, evoca 1 Nebbia invadente.","","I soldati del Camavor marciarono per Viego in vita, e poi di nuovo dopo la morte. La loro lealtà è assoluta.","Unità",[],["Isole Ombra"],"COMUNE"],"04SI001":["Riposo dell'Agnella","Fornisci ''Non posso subire danni o morire'' all'alleato più debole per questo turno.","","\"Brilla un'ultima volta, prima della fine.\" - Agnella","Incantesimo",[],["Isole Ombra"],"EPICO"],"04SI056":["Nebbia vanescente","Assorbi 2 da 2 nemici.","","\"Prenderò ciò che voglio e mi sbarazzerò del resto.\" - Viego","Incantesimo",[],["Isole Ombra"],"RARA"],"04SI012":["Volpe astrale","Gioca: Uccidi un alleato per infliggere 3 al Nexus nemico.","","Solo poche tribù del Targon parlano della Volpe, un dio della morte visto come una stella solitaria nel cielo notturno. Secondo la leggenda, la Volpe scende sulla montagna a ogni morte per portare in cielo le anime dei defunti, con cui crea la sua costellazione oscura.","Unità",[],["Isole Ombra"],"COMUNE"],"04SI029":["Disperazione","Scegli un'unità con cui colpire il tuo Nexus, poi uccidila.","","\"Ho dato tutto per trovarla... e ancora non è abbastanza.\"\n- Viego","Incantesimo",[],["Isole Ombra"],"COMUNE"],"04SI009":["Tessitore delle anime","Quando vengo evocato, conferiscimi +1|+1 e Temibile se è morto un alleato durante questo turno.","","\"C'era una volta un giovane inerme convinto di poter corteggiare un ragno, senza sapere che sarebbe finito nella sua tela...\"","Unità",["RAGNO"],["Isole Ombra"],"COMUNE"],"04SI013":["Madre della maschera","Gioca: Uccidi un alleato per conferirmi le sue statistiche e le sue parole chiave.","","Dicono che la madre della maschera abbia creato Kindred, così come ha creato tutte le incarnazioni della morte. Ma da chi ha ricevuto la maschera, se non l'ha creata lei stessa?","Unità",[],["Isole Ombra"],"COMUNE"],"04SI021":["Vermevipera strisciante","Per giocarmi, colpisco un alleato o infliggo 3 al tuo Nexus.","","All'inizio, i soldati demaciani pensavano di aver sentito gli artigli di decine di creature attraversare la piazza. Solo quando la torre di guardia venne sfondata si accorsero che si trattava di un solo mostro.","Unità",["DRAGO"],["Isole Ombra"],"COMUNE"],"04SI002":["Viaggio spirituale","Uccidi un'unità, poi rianimala.","","\"Questo è solo un interludio.\" - Agnella","Incantesimo",[],["Isole Ombra"],"RARA"],"04SI053":["Idracante infestante","Quando vengo evocata o all'Inizio del turno: Evoca 1 Nebbia invadente.","","Maokai lavorò senza sosta per far germogliare la vita nelle Isole Ombra. L'ambivalenza della Nebbia rende l'ironia ancora più crudele.","Unità",[],["Isole Ombra"],"EPICO"],"04SI003":["Icona evanescente","Quando vengo evocata, evoca 1 Preda.","","Chi può dimenticare il suo dio della morte, se non chi ha la maledizione dell'immortalità? E quale paura più grande può avere un dio della morte, se non quella di venire dimenticato? ","Unità",[],["Isole Ombra"],"COMUNE"],"04SI028":["Drago camavorano","Per giocarmi, colpisco un alleato o infliggo 3 al tuo Nexus.\nQuando uccido un'altra unità, assorbi 1 dal Nexus nemico.","","Per secoli, la Nebbia Oscura ha posseduto creature in tutto il mondo, corrompendole e trasformandole in spaventose ombre di se stesse.","Unità",["DRAGO"],["Isole Ombra"],"RARA"],"04MT014":["Occhio di Ra-Horak","Conto alla rovescia 1: Stordisci i 2 nemici più deboli.\nAlba: Evoca una mia copia con Conto alla rovescia 2.","","\"Che il sole splenda su di noi. I deboli e gli indegni si nasconderanno al suo sguardo!\" - Sacerdotessa Solari","Monumento",[],["Targon"],"RARA"],"04MT008":["Malphite","Gioca: Stordisci un nemico.","Hai evocato Monumenti per 10+ mana. Quando salgo di livello, se hai il gettone d'attacco, crea 1 Forza inarrestabile nella tua mano.","\"Ed ecco l'ultima fermata del tour del Targon di Chip! È PAPÀ! È il più GROSSO gigante del Targon e ha anche una voce da far paura. Non provate a scalarlo, però! I chiodi gli fanno solletico e se fa ecciù sono guai!\"\n- Avventure con Chip, parte 6","Unità",[],["Targon"],"Campione"],"04MT010":["Picco stellato","Conto alla rovescia 2: Crea nella tua mano 2 carte Celestiali casuali che costano 3 o meno.","","Chi parte per scalare il monte Targon viene ricompensato con i panorami più belli di Runeterra. Quando la scalata si fa più difficile, le ricompense si fanno più sostanziose.","Monumento",[],["Targon"],"RARA"],"04MT005":["Chip","Dopo aver evocato un Monumento in questa partita, conferiscimi +2|+2.","","\"Ciao, sono Chip e oggi vi faccio vedere il Targon! È super grande e altissimo quindi spero che avete delle scarpe comode per camminare! Si parte!\"\n- Avventure con Chip, parte 1\n","Unità",[],["Targon"],"COMUNE"],"04MT009":["Spirale di scale","Conto alla rovescia 3: Crea 1 Seme della forza nella tua mano.","","\"Ecco la prima fermata del tour! Questo lo chiamo il GAMBE DI BURRO perché accidenti quanti scalini ci sono! E la vista non è male, è una delle cose più belle del Targon. OK, andiamo!\"\n- Avventure con Chip, parte 2","Monumento",[],["Targon"],"RARA"],"04MT001":["Sentiero delle rocce","Conto alla rovescia 2: Annienta il nemico più debole.","","\"OK, gente, attenti perché questo è UN GROOOSSO SALTO e lo so perché ci sono già caduto io e fidatevi che è UN SIGNOR VOLO! E io rimbalzo perché sono di roccia, ma voi no, fate attenzio... oh, ecco Roccia! Andiamolo a salutare!\"\n- Avventure con Chip, parte 3","Monumento",[],["Targon"],"COMUNE"],"04MT018":["Ibice spaventato","Quando ricevo supporto, fornisci +1|+1 a me e all'alleato di supporto per questo turno.","","\"Non temer l'ululato del vento\nChe tra monti e valli porta il suo lamento\nNon aver paura, non aver timore\nLa mamma è qui, dormi, amore.\" - Ninnananna targoniana","Unità",[],["Targon"],"COMUNE"],"04MT004":["Guardiano di quarzo","Ultimo respiro: Evoca 1 Stemma dell'intelletto.","","\"OK, gente, salutate BLU! CIAO BLU! OK, un tempo rispondeva CIAO BLU pure lui, o forse era solo l'eco della mia voce. FA NIENTE, è magico e cose del genere, ed è così blu che non deve neanche parlare! OK CIAO BLU NOI ANDIAMO!\"\n- Avventure con Chip, parte 5","Unità",[],["Targon"],"COMUNE"],"04MT013":["Falcolucente Solari","Alba: Stordisci il nemico più forte.","","I Solari pensano che siano stati i falchilucenti del Targon, con la loro luce, ad attirare l'attenzione della Fiamma Immortale, ispirando il suo ciclo di morte e rinascita.","Unità",["VOLATILE"],["Targon"],"COMUNE"],"04MT003":["Elementale della terra","Dopo aver evocato 4+ Monumenti in questa partita, conferiscimi +3|+0.","","\"OK, ecco ROCCIA! È un tipo grossissimo che è in giro da UN SACCO di tempo. E sembra un tipo tranquillo, ma ha parecchia roba in spalla che ogni tanto cade sulla gente, quindi FATE ATTENZIONE, capito? Grazie andiamo avanti!\"\n- Avventure con Chip, parte 4","Unità",[],["Targon"],"COMUNE"],"04MT002":["Spaccaroccia","Gioca: Se hai evocato 4+ Monumenti in questa partita, infliggi 4 a un nemico e 2 al Nexus nemico.","","Di tanto in tanto, i grandi colossi del Targon si svegliano dal loro sonno e si spostano in luoghi diversi della grande montagna. Questi eventi tendono a essere tanto rumorosi quanto pericolosi.","Unità",[],["Targon"],"EPICO"],"04MT006":["Rivelazione stellata","Invoca.\nSe hai un alleato Celestiale, sostituisci il tuo mazzo con 20 copie di Ammirate l'infinito.","","\"Vedi, Kulun? Le stelle hanno così tante storie da raccontarci! Quale vogliamo ascoltare stasera?\" - Sognaluna","Incantesimo",[],["Targon"],"EPICO"],"04MT012":["Chiamata del destino","Conferisci +8|+8 a un alleato nella tua mano.","","\"Abbraccia il tuo destino e brilla più di quanto sia immaginabile.\" - Taric","Incantesimo",[],["Targon"],"EPICO"],"04MT007":["Onda d'urto ","Stordisci un nemico. Infliggi 3 al nemico se hai evocato un Monumento durante questa partita.","","\"Oops, sì, questa è la terra che trema, non il papà che muove le sue mani... NO, OK, andiamo avanti eeee sempre più in alto!\" - Chip","Incantesimo",["ELEMENTALE"],["Targon"],"RARA"],"04MT015":["Allineamento celeste","Alba: Crea 1 carta Crepuscolo casuale nella tua mano.\nCrepuscolo: Crea 1 carta Alba casuale nella tua mano.","","Così procede il ciclo di notte e giorno, che si susseguono in eterno.","Incantesimo",[],["Targon"],"COMUNE"],"04DE004":["Scout inarrestabile","Quando evochi un'unità Élite, riduci il mio costo di 1.","","Anche se i noxiani avevano teso con sapienza la loro trappola, nessuno conosceva i boschi meglio degli scout di Demacia. Ogni ramo spezzato e ogni impronta erano un indizio che li portava verso il loro principe.","Unità",["ÉLITE"],["Demacia"],"RARA"],"04DE014":["Cibo per draghi","Quando giochi un drago, mi colpisce e tu peschi 1 carta.","","\"Quello stridio che hai sentito in cielo? Non è un uccello, ragazzo. È il verso di un drago a caccia.\" - Contadino demaciano","Unità",[],["Demacia"],"COMUNE"],"04DE001":["Lord onorato","La prima volta che sfido un nemico, forniscimi Barriera per questo turno.","","Dopo aver saputo della scomparsa del figlio, re Jarvan III incaricò l'amico fidato, lord Barrett Buvelle, di organizzare le ricerche. Il principe tornò sano e salvo. Lord Buvelle, con eterno dispiacere del re, non tornò.","Unità",["ÉLITE"],["Demacia"],"COMUNE"],"04DE012":["Promozione sul campo","La prossima volta che giochi un'unità in questo turno, conferiscile Esploratore. Ora diventa Élite.","","Quando i demaciani vengono messi alla prova, sono sempre all'altezza.","Incantesimo",[],["Demacia"],"COMUNE"],"04DE003":["Cataclisma","Un alleato avvia un attacco gratuito sfidando un nemico.","","\"Per il re!\" - Jarvan IV","Incantesimo",[],["Demacia"],"RARA"],"04DE002":["Egida dorata","Fornisci Barriera a un alleato per questo turno.\nPrepara l'assalto.","","\"Ancora una volta, soldato di Demacia!\" - Jarvan IV","Incantesimo",[],["Demacia"],"RARA"],"04DE006":["Bravura in battaglia","Conferisci +1|+1 a un alleato.","","\"Posso insegnarti un paio di cosette.\" - Lord Buvelle","Incantesimo",[],["Demacia"],"COMUNE"],"04DE008":["Jarvan IV","Quando attacchi, paga il mio costo per evocarmi in sfida al nemico più forte.","Gli alleati sono sopravvissuti a 3+ colpi dei bloccanti nemici.","I noxiani sapevano dove li avrebbe portati la caccia al principe Jarvan. Sapevano quanti demaciani aveva al suo fianco e che l'onore non gli avrebbe consentito di fuggire. La trappola era pronta.","Unità",["ÉLITE"],["Demacia"],"Campione"],"04DE005":["Cithria, Signora delle nuvole","Quando vengo evocata, raddoppia il Potere e la Salute degli altri alleati e conferisci loro Sfidante.","","\"Chi di meglio poteva mandare Demacia a salvare il suo principe, se non la Signora delle nuvole?\" - Re Jarvan III","Unità",["ÉLITE"],["Demacia"],"EPICO"],"04DE020":["Guardia del Drago in Rovina","Quando un alleato con Furia uccide un'unità, conferiscigli un ulteriore +1|+1.","","La Nebbia ha corrotto la mente di Gregem, costringendolo a rivivere all'infinito la tragedia di Wrenwall. Alimentato da rabbia e rancore a lungo sopiti, si è rivoltato contro quelli che un tempo chiamava compagni.","Unità",[],["Demacia"],"COMUNE"],"04DE010":["Re Jarvan III","Quando vengo evocato, pesca Jarvan IV.\nSe è già in gioco, fornisci Sfidante ed Esploratore agli alleati per questo turno.","","\"Cosa potrebbe sacrificare un padre per salvare suo figlio? E un re, invece?\" - LeBlanc","Unità",["ÉLITE"],["Demacia"],"EPICO"],"04DE016":["Kadregrin in Rovina","Gioca: Conferisci Sfidante e +1|+1 a un alleato.","","Kadregrin seminava caos e terrore molto prima che la Nebbia Oscura raggiungesse Demacia. Al servizio di Viego, le sue capacità renderebbero inarrestabili le forze del Re in Rovina.","Unità",["DRAGO"],["Demacia"],"RARA"],"04DE013":["Litocorno imponente","Non subisco danni dagli incantesimi e dalle abilità dei nemici.","","Si dice che i grandi litocorni siano nati nell'era in cui la foresta di petricite era giovane, e che i loro ampi corni siano fatti di un materiale simile a quello degli antichi alberi.","Unità",[],["Demacia"],"COMUNE"],"04DE015":["Volo degli Ala lesta","Gioca: Crea 1 Avanguardia Ala d'argento, Assalto accecante o Segugio Piumalesta nella tua mano.\nAttacca: Fornisci +1|+1 agli altri alleati in sfida in questo turno.","","La sola vista degli Ala lesta è di grande ispirazione per i fanti demaciani. Quando li scorgono discendere tra le nuvole, le truppe a terra si sentono rinvigorite e pronte a continuare la lotta.","Unità",["ÉLITE","VOLATILE"],["Demacia"],"EPICO"],"04DE007":["Scudiera penitente","Quando vengo evocata, se un'unità Élite è visibile, crea 1 Stendardo lacero nella tua mano.","","Le gambe le cedettero solo dopo aver raggiunto le mura della città. L'Indomita Avanguardia avrebbe portato il suo messaggio al re, che avrebbe salvato il principe. Il suo torto sarebbe stato raddrizzato e il suo onore sarebbe stato preservato.","Unità",[],["Demacia"],"COMUNE"],"04DE009":["Cavaliere coraggioso","La prima volta che sfido un nemico, trasformami in Cavalleria dell'Avanguardia.","","Dopo la chiamata, tutti i soldati demaciani furono convocati per la ricerca del principe. Era fondamentale cogliere il momento.","Unità",["ÉLITE"],["Demacia"],"RARA"],"05BC058":["Kennen","Quando vengo evocato, crea 1 Marchio della tempesta nella tua mano.","Hai evocato lo stesso alleato 5+ volte.","Anche Kennen l'aveva udito. Era il ruggito di... qualcosa. Uomo o mostro, non aveva importanza. I Kinkou avrebbero protetto la loro terra a ogni costo.","Unità",["YORDLE"],["Bandle City","Ionia"],"Campione"],"05BC010":["Addestratore di squali","Quando gli alleati attaccano, evoca 1 Dentecorto in attacco.","","Ogni notte, l'addestratore ripete sempre gli stessi gesti. Cena a base di pesce e birra, una breve tirata di pipa a bolle, poi una favola della buonanotte e un bacino sul muso dei suoi squali.","Unità",["YORDLE"],["Bandle City","Bilgewater"],"RARA"],"05BC102":["Stregone appuntito","Inizio del turno: Ripristina 1 mana incantesimo.","","Se i tagli da carta sono i più dolorosi, allora le persone che meglio comprendono il dolore sono i bibliotecari.","Unità",["YORDLE"],["Bandle City"],"COMUNE"],"05BC230":["Portale spirituale","Per giocare, scarta una carta. Conferisci +1|+1 agli alleati.","","\"Non ricordo mai come funzionano questi cosi.\" - Poppy","Incantesimo",[],["Bandle City"],"COMUNE"],"05BC099":["Esploratore pompato","Quando vengo evocato, conferiscimi +1|+1 per ogni altro alleato Yordle che possiedi.","","\"Il mio segreto? Chiedilo ai miei muscoli. Loro adorano parlare.\"","Unità",["YORDLE"],["Bandle City"],"RARA"],"05BC133":["Tristana","Ho +1|+0 per ogni alleato multi-regione che hai evocato in questa partita.\nQuando evochi un alleato multi-regione, conferiscigli +1|+0.","Hai evocato 5+ alleati multi-regione.","\"OK, piano A: entriamo con la forza e iniziamo a sparare. Se non funziona, tocca al piano B: usciamo con la forza e continuiamo a sparare. Poi ci riuniamo e passiamo al piano C, ovvero riprovare col piano A...\"","Unità",["YORDLE"],["Bandle City"],"Campione"],"05BC023":["Minitino","Fine del turno: Se hai danneggiato il Nexus nemico in questo turno, trasformami in Megatino.","","Cose che piacciono ai minitini: sonnecchiare sulle caldepietre vicino alle terre tribali dei Nakotak. Cose che non piacciono ai minitini: venire scacciati da quelle caldepietre da yordle fastidiosi...","Unità",[],["Bandle City"],"EPICO"],"05BC029":["Yuumi","Inizio del turno: Conferisci +1|+1 all'unità alla quale sono Collegata. Altrimenti, conferisci +1|+1 a me.","Io o l'unità alla quale sono Collegata abbiamo attaccato 3 volte.","Yuumi dovette ammettere che, nonostante le sue lamentele, Libro le piaceva un bel po'. Le piaceva il suo profumo. Le piacevano le illustrazioni. Le piaceva anche saltare dentro i suoi portali... ma nulla sarebbe stato come riportare Norra a casa sana e salva.","Unità",["FATATO","FELINO"],["Bandle City","Targon"],"Campione"],"05BC078":["Arpione elettrico","Per giocare, scarta 1 carta. Infliggi 2 a un'unità e 2 al Nexus nemico.","","\"Diamo spettacolo!\" - Rumble","Incantesimo",[],["Bandle City"],"RARA"],"05BC106":["Brontolumaca","","","\"Seppur minuta, la Brontolumaca ha un appetito vorace e possiede ciò che definirei un 'grave problema comportamentale'.\" \n- Appunti di concologia applicata, giorno 17","Unità",[],["Bandle City","Bilgewater"],"COMUNE"],"05BC161":["Gnar","Colpisci: Crea 1 Bastone da pungolatura nella tua mano o, se ne hai già uno, riduci il suo costo di 2.","Fine del turno: Hai danneggiato il Nexus nemico in questo turno.","Molto tempo fa, Gnar e la sua gente vivevano tranquilli nella Valle Nakotak. Era un luogo innocente, dove non erano ancora arrivati i problemi dell'epoca moderna. Un vero peccato che il passaggio del tempo abbia sottratto quel luogo a Gnar. Ma che fortuna che il tempo non funzioni esattamente come ci si aspetti a Bandle City.","Unità",["YORDLE"],["Bandle City","Freljord"],"Campione"],"05BC073":["Chimica creativa","Quando vengo evocata, evoca 1 Bomba rimediata.","","Giselle era una delle migliori allieve del professor Heimerdinger, prima di sapere degli strani esperimenti condotti da Ziggs a Zaun: da allora pensa solo agli hexplosivi e a come farsi raccomandare per un tirocinio. ","Unità",["YORDLE"],["Bandle City"],"COMUNE"],"05BC039":["Granatiere burbero","Fedeltà: Evoca un seguace Yordle casuale che costa 3 o meno.","","\"Alice ha due colpi: il primo è un ciao, il secondo un addio. Vuoi che te la presenti?\"","Unità",["YORDLE"],["Bandle City"],"RARA"],"05BC148":["Spiritello furioso","Quando vengo evocato, se hai inflitto danni al Nexus nemico 4+ volte in questa partita, conferiscimi 4 Impatto.","","Tenero fuori, duro e grintoso dentro.","Unità",["FATATO"],["Bandle City","Piltover e Zaun"],"COMUNE"],"05BC119":["Minion","Ultimo respiro: Crea una mia copia nella tua mano al prossimo Inizio del turno.","","\"Un vero supercattivo non ha mai abbastanza minion! Quei piccoletti sanno stare al loro posto, obbediscono a qualsiasi ordine e poi tornano per riceverne altri.\"\n- Estratto dal cap. 2 di \"Come diventare un supercattivo\" di Lord Veigar","Unità",[],["Bandle City","Isole Ombra"],"COMUNE"],"05BC019":["Pesce arcobaleno","","","Il Pesce arcobaleno era contento di fare un po' di ricognizione aerea, anche se questo significava osare più di quanto avesse mai fatto prima d'ora. Ma questo e altro per allontanarsi, anche solo per un attimo, dallo sguardo affamato di Yuumi.","Unità",["FATATO"],["Bandle City"],"COMUNE"],"05BC093":["Veigar","Quando vengo evocato, crea 1 Oscurità nella tua mano, se non è già presente. Inizio del turno: Conferisci alla tua Oscurità ovunque 1 danno in più.","Hai inflitto 12+ danni con Oscurità.","\"Il mondo imparerà a temermi. Porterà le cicatrici della mia furia per l'eternità. Soffrirà sotto il peso del mio potere. Tremerà nell'ombra della mia grandezza!\"\n- Estratto dal cap. 1 di \"Come diventare un supercattivo\" di Lord Veigar","Unità",["YORDLE"],["Bandle City","Isole Ombra"],"Campione"],"05BC007":["Impilatori di pietre","","","Gli yordle non capiscono ancora del tutto come funziona la gravità, ma in fondo nemmeno la gravità sa bene come funzionare a Bandle City.","Unità",["YORDLE"],["Bandle City"],"COMUNE"],"05BC174":["Amicizia!","Fornisci Barriera o Scudo magico a un alleato per questo turno.","","\"Ti proteggerò con il mio selvaggio e furioso... miao!\" - Yuumi","Incantesimo",[],["Bandle City"],"RARA"],"05BC185":["Gioco delle tre conchiglie","Ripristina il tuo mana incantesimo. Fornisci Elusione e +1|+1 a un alleato per questo turno.","","\"Lo VEDO entrare nella conchiglia sinistra, ma quando la SCELGO è vuota. Inizio a sospettare che questo gioco sia truccato...\"\n- Appunti di concologia applicata, giorno 14","Incantesimo",[],["Bandle City"],"RARA"],"05BC096":["Tenore del Terrore","Quando vengo evocato, se hai giocato una carta creata o ucciso un'unità con un incantesimo in questa partita, evoca 1 Basso drammatico.","","Veigar voleva dar voce alla sua malvagità e con loro ne ha trovate ben due. Sono i sultani del solfeggio, i visconti del vibrato, i crociati della cacofonia.","Unità",["YORDLE"],["Bandle City","Isole Ombra"],"RARA"],"05BC088":["Rumble","Gioca: Scarta fino a 3 carte per conferire ai Rumble alleati ovunque Impatto per la prima, Attacco rapido per la seconda e Scudo magico per la terza scartata.","Ho visto alleati Mecha yordle infliggere 12+ danni.","\"Cooosì dovrebbe andare.\"\n\"ERRORE.\"\n\"CHE?!? Ma ho appena sistemato tutto!\"\n\"AVARIA DEL SISTEMA IMMINENTE.\"\n\"Spegniti. SPEGNITI!\"\n- Rumble e Tristy","Unità",["MECHA","YORDLE"],["Bandle City","Noxus"],"Campione"],"05BC056":["Monaco del vento","Quando vengo evocato, crea 1 Posizione della nuvola nella tua mano.","","\"La tecnica della nostra scuola si basa sul controllo del respiro, proprio come una tempesta che nasce dalla brezza.\"","Unità",["YORDLE"],["Bandle City"],"RARA"],"05BC190":["Mechannunciatore dell'Arena","Attacca: Fornisci +2|+0 agli altri alleati attaccanti per questo turno.","","\"Il mio segreto per riuscire a urlare così ogni sera? Gargarismi con olio per motori. Cinque minuti quando mi alzo e cinque minuti prima di andare a letto.\"","Unità",["YORDLE"],["Bandle City","Noxus"],"EPICO"],"05BC042":["Frullì di baccaviola","Porta un alleato a 3|3 per questo turno.","","\"Una volta ero come te: non sollevavo nemmeno uno scoppiettino. Poi ho scoperto Frullì alla baccaviola. Ha tutti i nutrienti necessari per trasformare uno yordle in un titano. Quindi, al prossimo allenamento, fai il pieno di Frullì e diventerai una montagna di muscoli come me!\" \n- Annuncio pubblicitario","Incantesimo",[],["Bandle City"],"COMUNE"],"05BC205":["Punto di non ritorno","Stordisci un nemico e stordisci tutti i nemici con 2 o meno Potere.","","\"Non... ti... muovere...\" - Veigar","Incantesimo",[],["Bandle City"],"COMUNE"],"05BC223":["Intrappolamento","Scegli 1 fra 3 unità o incantesimi dal mazzo nemico e piazza 3 Scoppiettini velenosi su tutte le copie della carta scelta.","","\"Regola 986: le trappole NON sono giocattoli... anche se sono divertenti!\"","Incantesimo",[],["Bandle City"],"RARA"],"05BC091":["Buttadentro dell'Arena","Gioca: Scarta 1 carta per manifestare un Mecha yordle e ridurre il suo costo di 1.","","\"BIGLIETTI! COMPRATE QUI I VOSTRI BIGLIETTI! ORA A METÀ PREZZO! Accidenti, se non vendo questi biglietti il capo mi ammazza... letteralmente.\"","Unità",["YORDLE"],["Bandle City"],"COMUNE"],"05BC163":["Ziggs","Attacco: Infliggo 1 all'unità che mi sta bloccando e al Nexus nemico.","Hai distrutto 4+ Monumenti alleati.","\"È FONDAMENTALE fare una buona impressione. Il nuovo ispettore di sicurezza sta arrivando e questo vuol dire...\"\n\"Niente esplosioni?\"\n\"Cosa?!? NO! Vuol dire che dovremo far esplodere le cose dove non può vederle! Tsk. 'Niente esplosioni'... Sei scemo?!\" - Ziggs e Otto","Unità",["YORDLE"],["Bandle City","Shurima"],"Campione"],"05BC151":["Maga degli specchi","Quando giochi un seguace creato, evoca una copia esatta. Quando giochi un incantesimo creato, giocalo di nuovo sugli stessi bersagli.","","\"Oh sì, è una vera maestra degli specchi. Fa apparire i miei modelli ancora più sublimi e, con un abile gioco di luci, riesce persino a far sembrare più alto chi ha un disperato bisogno di sentirsi più imponente...\" - Sarto arrogante","Unità",["YORDLE"],["Bandle City"],"EPICO"],"05BC027":["Campo minato hexplosivo","Quando vengo evocato o mi distruggi, stordisci il nemico più forte.","","\"Come sarebbe a dire che non sembra molto sicuro?\" - Ziggs","Monumento",[],["Bandle City"],"COMUNE"],"05BC200":["Portale yordle","Per giocare, scarta 1 carta. Manifesta 1 Yordle dal costo di 3 o meno ed evocalo.","","\"Mai abbandonare un artigliere!\" - Tristana","Incantesimo",[],["Bandle City"],"COMUNE"],"05BC021":["Ordigno rotolante","Infliggi 2 a un'unità o infliggi 1 a due nemici.","","\"Bomba in buca!\" - Ziggs","Incantesimo",[],["Bandle City"],"COMUNE"],"05BC167":["Commando di Bandle","Colpisci il Nexus: Crea 1 Gattufo famelico nella tua mano.","","\"Siamo il terrore di queste strade e dei bambini che non vanno a letto presto!\"","Unità",["YORDLE"],["Bandle City"],"COMUNE"],"05BC179":["Esploratrice yordle","Attacca: Conferisci +0|+1 agli alleati con Potere pari o inferiore al mio.","","\"Poppy! Ottimo lavoro con l'ultima tattica. Che ne dici di chiamarla 'Tempesta di noccioline'?\"\n\"Ma... io ho solo colpito il cattivo col mio martello. Non possiamo chiamarla semplicemente 'Martello'?\"\n\"È lo stesso nome che hai dato alle ultime tre!\" - Kip e Poppy","Unità",["YORDLE"],["Bandle City","Demacia"],"EPICO"],"05BC214":["Mega bomba infernale","Infliggi 1 a tutti i nemici, poi fallo di nuovo.","","\"Tirate fuori... quella grossa!\" - Ziggs","Incantesimo",[],["Bandle City"],"RARA"],"05BC221":["Cerchio di funghi","Quando vengo evocato o all'Inizio del turno: Forniscimi Potere pari al numero degli altri alleati Fatati in gioco o Collegati per questo turno.","","Le loro teste a punta sono davvero carine e poi possono fungere da piccole sentinelle.","Unità",["FATATO"],["Bandle City","Ionia"],"RARA"],"05BC041":["Poppy","Attacca: Conferisci +1|+1 agli alleati con Potere pari o inferiore al mio.","Ho attaccato con degli alleati 3 volte.","L'umiltà è simbolo di eroismo, ma molti storici sarebbero d'accordo nel dire che Poppy esagera.","Unità",["YORDLE"],["Bandle City","Demacia"],"Campione"],"05BC176":["Proiettile Stregatto","Conferisci +1|+0 a un alleato. Infliggi 1 a un nemico.","","\"Zoooooom!\" - Yuumi","Incantesimo",[],["Bandle City"],"RARA"],"05BC105":["Artiglieri di Bandle","Costo 1 in meno per ogni alleato multi-regione che hai evocato in questa partita.\nQuando vengo evocato, conferiscimi 3 Impatto.","","Un punto per la squadra.","Unità",["YORDLE"],["Bandle City"],"RARA"],"05BC066":["Pennalesta","","","\"D... o... v... e... è... N... o... r... r... a...? Oh cielo, cosa dovrei dirgli?\" - Assistente topo","Unità",["FATATO"],["Bandle City"],"COMUNE"],"05BC177":["Drago di carta","","","\"Un'altra piega qui e, vedi? Questa è una giraffa! Si chiama Calzino.\" \n\"Perché 'Calzino'?\" \n\"A Norra piacciono i calzini, quindi le piacerà anche questo!\" - Assistenti topi","Unità",["FATATO"],["Bandle City"],"EPICO"],"05BC136":["Pila di scarti","Per giocare, scarta 1 carta.\nManifesta un Mecha yordle.","","\"Rottami. Spazzatura. Cianfrusaglie... BINGO! Adesso sì che si ragiona!\" - Rumble","Incantesimo",[],["Bandle City"],"COMUNE"],"05BC164":["Dardo velenoso","Infliggi 1 a un bersaglio e piazza 3 Scoppiettini velenosi nel mazzo nemico.","","\"Ahah! Centro perfetto!\" - Teemo","Incantesimo",[],["Bandle City"],"COMUNE"],"05BC194":["L'Albero di Bandle","Inizio del turno: Crea un seguace di una nuova regione nella tua mano. Se ho visto alleati da 10 regioni, vinci la partita.","","L'Albero di Bandle, con i suoi rami che si estendono all'infinito verso il cielo, è un simbolo irreale della città. Alcuni yordle considerano il suo possente tronco nodoso un faro di speranza e amicizia, mentre per altri è un colosso infausto e misterioso. Tutti però sono d'accordo nel dire che guardare l'Albero di Bandle è come scrutare nell'anima di un essere molto antico e molto potente.","Monumento",[],["Bandle City"],"EPICO"],"05BC127":["Rissu, Tempesta silente","Quando vengo evocata, evoca 1 Nembo.","","Tessere un Nembo richiede tempo, e Rissu non ne aveva. Le sue mani si muovevano freneticamente mentre l'Aberrazione si avvicinava. Un po' di nube qui, qualche fulmine là e... CRACK! BOOM! Ce l'aveva fatta, ma sarebbe bastato?","Unità",["YORDLE"],["Bandle City"],"EPICO"],"05BC216":["Marchingegno yordle","Distruggi un Monumento o crea 2 seguaci multi-regione casuali nella tua mano.","","\"Resisti, arriviamo!\" - Bombardieri gemelli","Incantesimo",[],["Bandle City"],"COMUNE"],"05BC212":["Ispettore di sicurezza","Inizio del turno: Crea 1 Ispezione superata! nella tua mano.","","All'inizio Wilfred era scettico. E ha continuato ad esserlo. Anzi, è rimasto scettico fino alla fine. Però Ziggs e gli altri esperti di hexplosivi gli hanno dimostrato che erano in grado di mettere su uno spettacolo pirotecnico coi fiocchi. ","Unità",["YORDLE"],["Bandle City"],"RARA"],"05BC141":["Melodia eroica","Fornisci +2|+1 a due alleati per questo turno.","","\"Gli eroi erano lì, spalla a spalla...\"\n\"...Chiappe contro chiappe! Eheheheh!\"\n\"N-no! Peppy, se devi interrompere, almeno cerca di farlo in momenti meno drammatici!\"\n- Storie raccontate al falò degli yordle","Incantesimo",[],["Bandle City"],"COMUNE"],"05BC209":["Difesa impanicata","Imposta le statistiche di un'unità su 1|6 per questo turno.","","In circostanze normali, la Chiocciatrice è una cavalcatura leale e tenace. Tuttavia, quando accumula troppo stress tende a reagire in modi... inconsueti.","Incantesimo",[],["Bandle City"],"COMUNE"],"05BC210":["Sputafuoco","Conferisci +2|+0 e Impatto a un alleato.","","\"Se non urlano, non scotta abbastanza! Eh eh.\" - Rumble","Incantesimo",[],["Bandle City"],"COMUNE"],"05BC013":["Tentacoli malandrini","Il tuo avversario scarta la sua carta con il minor costo.","","\"Promemoria: alla prossima spedizione, tenere le cose di valore nelle tasche ANTERIORI.\" \n- Appunti di concologia applicata, giorno 19","Incantesimo",[],["Bandle City"],"COMUNE"],"05BC100":["Cucciolo Scoppiettino","Colpisci: Piazza 3 Scoppiettini velenosi nel mazzo nemico.","","\"Che c'è, bello? Mi stai dicendo che due reclute erano in ricognizione nel bosco, hanno incontrato un orribile mostro vegetale e ora rischiano una morte lenta e dolorosa? Portami da loro!\" - Teemo","Unità",["CANIDE"],["Bandle City"],"COMUNE"],"05BC098":["Catalizzatore contorto","Colpisci: Conferisci alla tua Oscurità ovunque 1 danno in più.","","L'oscurità può avere molte forme, alcune delle quali SORPRENDENTEMENTE adorabili.","Unità",["YORDLE"],["Bandle City"],"COMUNE"],"05BC122":["Yordle principiante","Quando evochi un altro Yordle, forniscimi +2|+0 per questo turno.","","\"Erbaceus enormis. Queste terrificanti creature si sdraiano mimetizzandosi nell'erba e attaccano chiunque abbia la sfortuna di calpestarle. Se ne incontrate uno, scappate a gambe levate!\" - Ava l'Ambiziosa","Unità",["YORDLE"],["Bandle City"],"COMUNE"],"05BC120":["Capitano yordle","Quando evochi un altro alleato con Potere pari o inferiore al mio, conferiscigli +1|+1.","","\"Il senso delle avventure è incontrare nemici e trasformarli in amici!\"","Unità",["YORDLE"],["Bandle City"],"COMUNE"],"05BC046":["Pugno di tuono","Quando vengo evocato, se hai evocato 1 Pugno di tuono in questa partita, trasformami in Masa, tuono devastante.","","Appena Masa colpì il fantoccio, dal pugno si sprigionò un fulmine che spezzò in due il legno e incenerì i peli sulle sue mani. Tirò a se la corda per recuperare la mano di bronzo, e rifletté sul suo addestramento: finalmente era pronto. Improvvisamente, un ruggito mostruoso riecheggiò in lontananza.","Unità",["YORDLE"],["Bandle City"],"COMUNE"],"05BC018":["Cavaliere borioso","","","\"Novecentonovantotto... Novecentonovantanove... Mille! Ecco fatto, Bawky. Impeccabile come sempre. Ora tocca a te!\"","Unità",["YORDLE"],["Bandle City","Demacia"],"RARA"],"05BC132":["Palla di cannone","Costo 2 in meno se hai 1 Tristana o se hai giocato carte di 4 o più regioni in questa partita.\nInfliggi 3 a un'unità.","","In ogni botto c'è uno scoppio che scalpita per uscire.","Incantesimo",[],["Bandle City"],"COMUNE"],"05BC168":["Rospo maculato","Fine del turno: Se hai danneggiato il Nexus nemico in questo turno, trasformami in Giga Gromp.","","Gli yordle della Valle Nakotak hanno provato a capire i loro vicini gromp per diverse generazioni. Prima, il Capo Hegabo provò a pungolarli con un bastone. Poi, il Capo Babobu provò a pungolarli con un bastone. Il Capo Nakotak aveva un nuovissimo piano: li avrebbe pungolati con un bastone.","Unità",[],["Bandle City"],"RARA"],"05BC014":["Microdattilo","Fine del turno: Se hai danneggiato il Nexus nemico in questo turno, trasformami in Terrordattilo.","","Le creature della Valle Nakotak sono varie e piene di vita come la loro dimora... e hanno la stessa possibilità di esplodere.","Unità",["VOLATILE"],["Bandle City"],"COMUNE"],"05BC138":["Ricondizionatori","La prima volta che scarti una carta o danneggi il Nexus nemico, conferiscimi +2|+1.","","\"OK, bell'incontro. Ottimo spettacolo, gente. Ora pulite tutto e ricordate la regola: tutto ciò che è salvabile va sistemato, messo in negozio e rivenduto! AH AH AH!\" - Karl, Boss dell'Arena","Unità",[],["Bandle City"],"COMUNE"],"05BC198":["Foto di gruppo","Infliggi 1 a un'unità. Se hai 4+ alleati, infliggi invece 2.","","\"OK, questa è per il bollettino. E stavolta sorridete! Uno... Due... Tre!\" - Tristana\n","Incantesimo",[],["Bandle City"],"COMUNE"],"05BC181":["Posizione della nuvola","Fornisci +2|+0 e \"Fine del turno: Richiamami\" a un alleato per questo turno.","","\"Torna a respirare e trova la tua forza!\" - Monaco del vento","Incantesimo",[],["Bandle City"],"COMUNE"],"05BC160":["Poro primitivo","","","I poro dell'antichità avevano crani molto più spessi dei loro attuali discendenti, cosa che riduceva la loro intelligenza ma aumentava la pericolosità delle loro testate.","Unità",["PORO"],["Bandle City","Freljord"],"COMUNE"],"05BC005":["Vergini delle alghe","Colpisci il Nexus: Crea 1 Scherzo nella tua mano.","","\"Perbacco, che sogno assurdo. Frugavo tra le alghe in cerca del mio cappello a conchiglia, quando all'improvviso ho sentito una melodia paradisiaca... E subito dopo mi ritrovo qui, seduto con la penna in mano a scrivere queste parole. Non ricordo nemmeno di essermi addormentato...\"\n- Appunti di concologia applicata, giorno 22","Unità",[],["Bandle City"],"RARA"],"05BC020":["Assistente bibliotecaria","Colpisci il Nexus: Pesca un incantesimo di costo 3 o inferiore.","","\"Gelli è la mia MIGLIORE AMICA! Voglio dire, dopo di te, Libro. E Norra. OK, Gelli è la mia TERZA MIGLIORE AMICA. È comunque una buona cosa, no?!?\" - Yuumi","Unità",["FATATO"],["Bandle City"],"COMUNE"],"05BC049":["Concologo","Gioca: Manifesta un incantesimo delle tue regioni che costa 3 o meno.","","\"Oggi sarà un giorno memorabile. Mi aspetta un viaggio negli abissi! Non vedo l'ora di... tuffarmi in quest'avventura! Oh oh oh!\" \n- Appunti di concologia applicata, giorno 1","Unità",["YORDLE"],["Bandle City"],"RARA"],"05BC001":["Minimizzazione","Trasforma un'unità in 1 Mini-minitino 3|3 e silenziala.","","\"Oh! Quant'è carino! Quant'è adorabile! Quant'è MINUSCOLO!\" - Veigar","Incantesimo",[],["Bandle City"],"RARA"],"05BC026":["Passaggi nascosti","Costo 2 in meno se hai creato 2+ carte in questa partita. Pesca 2 carte.","","Pochissimi stranieri sanno come raggiungere Bandle City, ma i più attenti possono trovare indizi negli strani segni su pietre e alberi di Runeterra.","Incantesimo",[],["Bandle City"],"COMUNE"],"05BC152":["Viaggiatori infreddoliti","Quando veniamo evocati, TUTTI i giocatori pescano 1 carta, poi il tuo avversario scarta la sua carta col costo più alto.","","\"Il peggior viaggio di sempre.\" - Elle","Unità",["YORDLE"],["Bandle City","Piltover e Zaun"],"COMUNE"],"05BC070":["Ava l'Ambiziosa","Quando vengo evocata o alla Fine del turno: Piazza 3 Scoppiettini velenosi nel mazzo nemico.\nLe trappole sulle carte nemiche raddoppiano quando vengono attivate.","","\"Regola 378: un bravo esploratore è sempre coraggioso, preparato e ardito!\"","Unità",["YORDLE"],["Bandle City"],"EPICO"],"05BC015":["Lucertolina","Fine del turno: Se hai danneggiato il Nexus nemico in questo turno, trasformami in Lucertola di lava.","","\"Mangia il peperoncino!\" urlò Nakotak, forse. \"No, TU mangia il peperoncino!\" rispose Jojo, forse. Mentre litigavano, si avvicinò una piccola lucertola che inseguiva una mosca. I due yordle guardarono la lucertola, poi il peperoncino e poi l'un l'altro. Se fossero esistite le lampadine, se ne sarebbe appena accesa una.","Unità",["RETTILE"],["Bandle City"],"COMUNE"],"05BC145":["Scudiera yordle","Gioca: Crea 1 Mini lancia o 1 Mini scudo nella tua mano.","","\"Anche la mia lancia è stata brandita da una leggenda... Poppy l'ha impugnata per un minuto intero!\"","Unità",["YORDLE"],["Bandle City"],"COMUNE"],"05BC140":["Poroslitta","Attacca: Evoca un Poro casuale di costo 1 in attacco.","","\"Poi a un certo punto quel cavolo di Poro ha fatto un gesto tipo 'DA QUELLA PARTE!', poi è sfrecciato verso l'orizzonte e tutti gli altri poro gli sono andati dietro cercando di raggiungerlo!\" - La piccola Ingvar","Unità",["PORO"],["Bandle City","Freljord"],"EPICO"],"05BC129":["Boss dell'Arena","","","\"La madre dei polli è sempre incinta e io sono sempre pronto a spennarli... Quest'arena meccanica diventerà una MINIERA D'ORO.\"","Unità",["YORDLE"],["Bandle City","Noxus"],"COMUNE"],"05BC004":["Polpontra","Quando vengo evocata, crea 1 Scherzo nella tua mano.","","\"Curiose e giocherellone, le polpontre spesso si riuniscono in... branchi? Mandrie? Stormi? ...Ehi, non avevo portato tre panini?\" \n- Appunti di concologia applicata, giorno 7","Unità",[],["Bandle City"],"COMUNE"],"05BC155":["Monaco della fiamma","Quando evochi un altro alleato, conferiscimi +1|+0.","","\"Una piccola scintilla può diventare un incendio devastante. Noi siamo le fiamme che vi distruggeranno!\"","Unità",["YORDLE"],["Bandle City"],"RARA"],"05BC104":["Forza primordiale","Conferisci +2|+2 e Impatto a un alleato.","","Sì, è molto carino. Sì, ha un caratteraccio. No, è meglio se non lo vedi.","Incantesimo",[],["Bandle City"],"COMUNE"],"05BC218":["Aiuto fatato","Crea 1 Gattufo famelico nella tua mano, poi conferisci +1|+1 alle unità Fatate nella tua mano.","","\"Chi è che continua a nutrire questi cosi?\" - Poppy","Incantesimo",[],["Bandle City"],"RARA"],"05BC192":["Bombardieri gemelli","Quando veniamo evocati, crea un Monumento casuale di costo 2 o inferiore nella tua mano.","","Il Bombastatore X faceva esattamente ciò per cui era stato progettato: seminare caos. Inoltre, era facilissimo da parcheggiare. ","Unità",["YORDLE"],["Bandle City","Shurima"],"COMUNE"],"05BC162":["Capo Nakotak","Quando un alleato si trasforma, guariscilo completamente e conferiscigli +1|+1 e Impatto.","","Il Capo Nakotak si dichiarò leader della tribù dopo aver trovato un grosso osso di dinosauro tra le nevi intorno alla loro terra. Nessuno degli altri sapeva che trovare ossa di dinosauro significasse diventare capotribù, ma a nessuno importava più di tanto. E quindi fu Nakotak.","Unità",["YORDLE"],["Bandle City"],"RARA"],"05BC032":["Lanterna splendente","Ogni turno, la prima unità Fatata che giochi costa 2 in meno.","","\"Lanterna segue Norra, falene di luna seguono Lanterna, topi seguono falene di luna! Seguite, seguite!\"","Unità",["FATATO"],["Bandle City"],"RARA"],"05BC166":["Bastone da pungolatura","Infliggi 1 a un bersaglio. Pesca 1 carta.","","Prima regola della sperimentazione: pungolare e vedere che succede.","Incantesimo",[],["Bandle City"],"COMUNE"],"05BC006":["L'Arsenale","Quando vengo evocato, conferiscimi una parola chiave casuale per ciascun Monumento alleato che hai distrutto in questa partita.\nQuando distruggi un Monumento alleato, conferiscimi una parola chiave casuale.","","Ovunque Ziggs andasse, Arnie lo seguiva. La sua indole tranquilla era il complemento naturale del caotico fervore di Ziggs. I suoi compiti andavano dal controllare le riserve di munizioni allo spegnere gli incendi, oltre a coprire le orecchie di Ziggs quando si scordava le cuffie insonorizzanti (cioè sempre). ","Unità",["YORDLE"],["Bandle City"],"EPICO"],"05BC110":["Scalatore istruito","","","\"Sì, sì, mi hai già detto tutto su come le piacciano il tè, i calzini, come le piaccia tu, i bottoni e collezionare cianfrusaglie, ma non mi hai ancora detto niente sul SUO ASPETTO!\" ","Unità",["YORDLE"],["Bandle City","Targon"],"COMUNE"],"05BC063":["Guerriera Tornado","Quando vengo evocata, conferiscimi +1|+0 e una parola chiave casuale.\nQuando vengo richiamata, conservo i buff alle statistiche e le parole chiave.","","Il Tornado mantiene la calma attraverso gli esercizi di respirazione... e incanalando il suo tumulto interiore in un terribile ciclone di lame mortali. ","Unità",["YORDLE"],["Bandle City"],"COMUNE"],"05BC217":["Bocciolo fatato","Manifesta un'unità Fatata e conferiscile +1|+1.","","Ogni essere vivente ha bisogno di sostentamento. Le Fate non fanno la differenza, anche se può essere difficile capire come ne facciano uso esattamente.","Incantesimo",[],["Bandle City"],"RARA"],"05BC180":["Velocizzare","Richiama un'unità con 3 o meno Potere","","\"Noi siamo veloci! Noi siamo il vento!\" - Kennen","Incantesimo",[],["Bandle City"],"COMUNE"],"05BC040":["Scambio alla pari","Manifesta 1 Polpontra o uno fra 2 incantesimi delle tue regioni che costa 3 o meno.","","\"Ridammi subito il mio panino!\" - Concologo","Incantesimo",[],["Bandle City"],"RARA"],"05BC213":["Bam!","Infliggi 1 a un nemico e stordiscilo.","","\"Ahanga!\" - Gnar","Incantesimo",[],["Bandle City"],"COMUNE"],"05BC208":["Carica eroica","Un alleato colpisce un nemico. Se sopravvive, stordiscilo.","","\"Pista!\" - Poppy","Incantesimo",[],["Bandle City"],"RARA"],"05BC085":["Topo da stiva monello","Gioca: Scarta 1 carta per manifestare un Mecha yordle e conferirgli Scudo magico.","","\"Abbassa il volume! Continuo a perdere il conto di tutti questi soldi!\" - Karl, Boss dell'Arena","Unità",["YORDLE"],["Bandle City"],"RARA"],"05BC112":["Germoglio di Bulbo esplosivo","Gioca: Forniscimi Barriera per questo turno o conferiscimi Impatto.","","I Germogli di Bulbo Esplosivo sono creature timide e anche se all'inizio scelgono sempre la ritirata, se vengono minacciati...","Unità",["FATATO"],["Bandle City","Ionia"],"COMUNE"],"05BC135":["A colpo sicuro","Un alleato colpisce un nemico. Se l'alleato è multi-regione, colpisce il nemico di nuovo.","","\"Il Ghianda M1-85: un fucile automatico in quercia con mirino di puro legno di Bandle e finiture color baccaviola. Stasera vedremo i fuochi d'artificio!\" - Commando di Bandle","Incantesimo",[],["Bandle City"],"COMUNE"],"05BC084":["Squittino","Gioca: Scarta 1 carta per manifestare un Mecha yordle.","","Piccola statura, GRANDE personalità.","Unità",[],["Bandle City"],"COMUNE"],"05BC184":["Cantastorie chiacchieroni","Quando veniamo evocati, crea 1 Gattufo famelico nella tua mano.","","\"Questa canzone parla\ndi Poppy l'invincibile!\nPoppy è più grande, forte e... ibile?\" \n- Testo cancellato del \"Canzoniere di Reginaldattilo e Faltimischio, bardi sopraffini\"","Unità",["YORDLE"],["Bandle City"],"COMUNE"],"05BC116":["Sindaco di Bandle City","Ogni turno, la prima unità Multi-regione che giochi costa 1 in meno.\nGioca: Manifesta un seguace Multi-regione.","","Nessuno sa se a Bandle City ci siano elezioni per il sindaco, ma se così fosse è probabile che i candidati debbano avere per legge un enorme paio di baffi.","Unità",["YORDLE"],["Bandle City"],"EPICO"],"05BC111":["Yordle armati ","Fornisci agli alleati +2|+2 per questo turno. Se hai giocato carte di 4+ regioni, fornisci invece +3|+3.","","\"Siamo... assolutamente fantastici.\" - Tristana","Incantesimo",[],["Bandle City"],"RARA"],"05BC224":["Trasposizione","Richiama un alleato. Il prossimo alleato che giochi in questo turno con un costo uguale o inferiore, costa 0.","","\"Velocità del corpo, velocità della mente!\" - Kennen","Incantesimo",[],["Bandle City"],"RARA"],"05BC130":["Testacalda","Attacco: Conferisci +1|+1 e una parola chiave casuale al primo campione del tuo mazzo.","","I barbecue estivi di Otto avevano una certa fama. Anche se era un grande appassionato di grigliate, le uniche due scelte che dava ai suoi ospiti per quanto riguardava la cottura della carne erano \"ben cotta\" o \"estremamente ben cotta\".","Unità",["YORDLE"],["Bandle City","Shurima"],"COMUNE"],"05BC191":["Verdetto del custode","Piazza un'unità nemica in cima al mazzo nemico.","","\"E non farti rivedere!\" - Poppy","Incantesimo",[],["Bandle City"],"RARA"],"05BC052":["Rifiuti preziosi","Riempi la tua mano di carte casuali. Costano 0 e sono Fugaci. Puoi giocare solo altre 3 carte in questo turno.","","Ciò che per i mortali è spazzatura, per uno yordle è una montagna di opportunità.\n","Incantesimo",[],["Bandle City"],"RARA"],"05BC050":["Stranemone","Quando vengo evocato, crea 2 Scherzi nella tua mano.","","\"Se avete la nausea facile, avvicinatevi a questo gigante gentile con ESTREMA cautela. Il vostro stomaco vi ringrazierà... A questo proposito, non avrei dovuto mangiare quel secondo panino ai funghi...\" \n- Appunti di concologia applicata, giorno 3","Unità",[],["Bandle City"],"COMUNE"],"05BC094":["Accolito bulboscuro","Quando vengo evocato, crea 1 Oscurità nella tua mano, se non è già presente.","","\"Sì, il tipo sul tetto ha sicuramente molte storie da raccontare. Lo sappiamo tutti. Il problema è che non abbiamo idea di cosa stesse dicendo!\" - Sarto arrogante","Unità",["YORDLE"],["Bandle City"],"COMUNE"],"05BC146":["Pittrice di Bandle","Gioca: Scarta 1 carta per creare un seguace multi-regione nella tua mano e riducine il costo di 1.","","\"Dipingere non vuol dire copiare ciò che si vede, ma esprimere come TU vedi le cose. E io ora sto vedendo che ti sei mosso di nuovo. Immobile, per favore!\"","Unità",["YORDLE"],["Bandle City","Piltover e Zaun"],"COMUNE"],"05BC235":["Fabbro yordle","Attacca: Fornisci Attacco rapido agli alleati con Potere pari o inferiore al mio per questo turno.","","\"Poppy non mi dà mai retta, quindi fallo almeno tu: il segreto non sta nel martello, ma nello yordle che lo usa.\"\n","Unità",["YORDLE"],["Bandle City"],"COMUNE"],"05BC175":["Telescopio dinoccolato","Gioca: Manifesta 1 carta Celestiale che costa 3 o meno, una epica o un seguace multi-regione.","","La cosa più strana non era che il telescopio si fosse alzato, stiracchiato e messo a camminare, ma il fatto che pretendesse di vestirsi di tutto punto e insistesse per trovare una sciarpa adeguata.","Unità",["FATATO"],["Bandle City","Targon"],"RARA"],"05BC182":["Furia elettrica","Richiama un alleato per infliggere 2 a un qualsiasi bersaglio.","","\"Prima lo schiocco, poi lo schianto!\" - Kennen","Incantesimo",["ELEMENTALE"],["Bandle City"],"RARA"],"05BC069":["Yordle ammonitore","Attacca: Crea 1 Dardo velenoso Fugace nella tua mano.","","Non fatelo iniziare a parlare.","Unità",["YORDLE"],["Bandle City"],"RARA"],"05BC057":["Sarto arrogante","Quando vengo evocato, riduci di 1 il costo della tua Oscurità ovunque.","","\"Quando si crea un gruppo di supercattivi, è importante che ognuno dei suoi folli membri aggiunga qualcosa di unico all'insieme di malvagità. Uno dei miei soci, per esempio, ha un senso dello stile letale...\"\n- Estratto dal cap. 4 di \"Come diventare un supercattivo\" di Lord Veigar","Unità",["YORDLE"],["Bandle City"],"RARA"],"05BC108":["Esploratore yordle","Quando evochi un altro yordle, conferiscigli +1|+0.","","\"La gloria dell'esplorazione non ha prezzo, ma le grandi scoperte che ne derivano sono sempre... ehm, redditizie.\"","Unità",["YORDLE"],["Bandle City"],"COMUNE"],"05BC183":["Nonno Fatato","Quando vengo evocato, crea 1 Gattufo famelico nella tua mano.\nQuando evochi un'altra unità Fatata, conferiscile +1|+0.","","\"Venite qui e sedetevi sul prato,\nascoltate la triste storia del Nonno Fatato.\nOgni giorno nutriva gli uccellini,\ncon dei semi davvero carini...\"\n- Storiella di Bandle City","Unità",["FATATO"],["Bandle City","Ionia"],"RARA"],"05BC188":["Conchelide curiosa","Quando scegli una carta non campione fra più opzioni casuali, creane una copia in mano e riduci il suo costo di 1.","","Notoriamente timidi, gli schivi conchelidi si nascondono nei loro gusci finché la loro curiosità non li spinge a uscire. Una volta emersi, la loro indole giocosa viene alla luce e si divertono a fare scherzi usando la loro grande capacità di imitare i versi degli animali marini.","Unità",[],["Bandle City"],"EPICO"],"05FR001":["Sciamano Luposcuro","Fine del turno: Se hai danneggiato il Nexus nemico in questo turno, trasformami in Furiante Luposcuro.","","\"Non moriremo come codardi! Piuttosto, cadremo con denti e artigli bene in vista. È così che rendiamo onore al Grande Lupo.\" - Hyara la veggente","Unità",[],["Freljord"],"COMUNE"],"05FR002":["Sciamano Mammut","Fine del turno: Se hai danneggiato il Nexus nemico in questo turno, trasformami in Furiante Mammut.","","Quando affrontano dei predatori, i branchi di mammut circondano i loro piccoli e gli esemplari gravidi. E quindi gli sciamani del grande spirito mammut non invocano solo la forza fisica del loro spirito, ma anche la forza dell'unità che protegge la famiglia.","Unità",[],["Freljord"],"RARA"],"05FR013":["Udyr","Quando vengo evocato o colpisco: Crea 1 Cambio di Posizione nella tua mano o, se ne hai già uno, riduci il suo costo a 0.","Hai giocato Cambio di Posizione 3+ volte.","\"Gli Spiriti modellano il nostro mondo proprio come noi e il nostro mondo modelliamo gli Spiriti. Attingendo al loro potere, è come attingere al potere dentro di noi.\"","Unità",[],["Freljord"],"Campione"],"05FR016":["Chiamata dello sciamano","Crea 2 Cambi di Posizione Fugaci e a costo 0 nella tua mano.","","\"Potrai vederli... grandi Spiriti di denti e artigli, scaglie e piume. E in quel momento, tremerai dalla paura e dalla meraviglia, e capirai che gli Antichi Dei non ci hanno dimenticati.\" - Hyara la veggente","Incantesimo",[],["Freljord"],"COMUNE"],"05FR012":["Hyara la Veggente","Quando vengo evocata, crea 1 Cambio di Posizione nella tua mano.\nIl primo Cambio di Posizione che giochi ogni turno costa 0.","","Riverita da tutti, la grande sciamana Hyara la veggente ha perso la vista molto tempo fa, e ora vede attraverso gli occhi dei falchi e delle aquile che nidificano nella sua casa in cima alla montagna. Ora, degli eventi preoccupanti l'hanno fatta scendere dalla sua montagna... anche se spera che quelle minacce restino soltanto delle visioni.","Unità",[],["Freljord"],"RARA"],"05FR014":["Furia del Freljord","Gioca: Congela un nemico.\nI nemici con 3 o meno Potere non possono bloccare.","","\"Io c'ero, anni fa... prima arrivò il freddo, pungente e inarrestabile. Poi una tempesta, furiosa e spietata. Per ultimo arrivò un ruggito, così tagliente da ferirmi nelle ossa. Caddi in ginocchio e pregai di non aver fatto un grave errore. Chiamare un grande spirito significa invocare la sua vendetta... e chiedere la sua pietà.\" - Hyara la veggente ","Unità",[],["Freljord"],"EPICO"],"05FR017":["Belva interiore","Fornisci +1|+1 a un alleato per questo turno. Crea 1 Cambio di Posizione nella tua mano.","","\"Accorrete, spiriti. Accorrete...\" - Udyr","Incantesimo",[],["Freljord"],"COMUNE"],"05FR006":["Oratore delle Zanne","Gioca: Infliggi 1 a ENTRAMBI i Nexus.","","Poche famiglie di sciamani hanno servito la tribù dell'Artiglio d'Inverno a lungo come quella di Chuluun. Come sciamano del grande tricheco, lui prevede e preannuncia le ricchezze del mare... e i suoi pericoli. ","Unità",[],["Freljord"],"COMUNE"],"05FR015":["Spiriti scatenati","Conferisci +1|+1 agli alleati ovunque. Poi infliggi 1 a TUTTO.","","\"Antichi, rendeteci forti contro il freddo sconfinato e respingete i nostri nemici con tempeste di vento e ghiaccio. Perché noi non abbiamo dimenticato voi e gli onori che vi dobbiamo.\"\n- Benedizione dello Sciamano Luposcuro","Incantesimo",[],["Freljord"],"RARA"],"05FR005":["Veggente delle ossa","Quando sopravvivo ai danni, infliggi 1 al Nexus nemico.","","Pochi hanno una visione chiara del futuro come gli sciamani che servono l'Alce delle Ossa. Ancora meno riescono a sopportare la visione della morte di coloro che vengono a chiedere consiglio.","Unità",[],["Freljord"],"COMUNE"],"05FR004":["Viaggiatrice Volpina","Quando vengo evocata, crea 1 Cambio di Posizione nella tua mano.","","\"Curiosa e cauta. Rapida e silenziosa. La gioia della volpe è di vedere senza essere vista. In viaggio e in guerra, un capo saggio rende onore a coloro che seguono lo spirito della volpe, poiché nessuna battaglia può essere vinta senza ricognitori ed esploratori.\" - Vrynna, Madre delle cicatrici","Unità",[],["Freljord"],"COMUNE"],"05IO003":["Antico Senzavia","Costo 2 in meno per ogni unità che hai richiamato in questo turno.","","\"Himon'she, è un onore viaggiare con te. Gli altri dicono che la tua saggezza è smisurata. Dove stiamo andando?\"\n\"Oh, cielo. Io seguivo te!\" - Ahri e l'Antico Senzavia","Unità",[],["Ionia"],"COMUNE"],"05IO004":["Ahri","Attacca: La prima volta che metto un attacco a segno, scambiami con l'alleato alla mia destra, poi richiamalo.","Hai richiamato 5+ unità.","Aveva cercato se stessa nei segreti altrui. Si era vista con gli occhi di tanti altri. Mentre si avvicinava alla foresta, si chiese se quella non sarebbe stata solo un'altra lente... o se per una volta avrebbe trovato uno specchio.","Unità",[],["Ionia"],"Campione"],"05IO023":["Malìa amorosa","Richiama un alleato per fornire Vulnerabile a un nemico per questo turno.","","\"Dimmi un segreto.\" - Ahri","Incantesimo",[],["Ionia"],"COMUNE"],"05IO020":["Cantavento","Gioca: Richiama un'unità.","","Il caos dona artigli ai deboli. Un lupo bracca la sua preda, e viene bloccato da un ramo caduto. Un falco va in picchiata, e viene sbalzato via da un vento improvviso. Noi siamo il ramo. Noi siamo il vento.","Unità",[],["Ionia"],"COMUNE"],"05IO007":["Sai'nen Millecode","Quando vengo evocato, pesca 2 carte e fornisci +1|+1 agli alleati per questo turno.","","La foresta offre a tutti i suoi segreti... ma in pochi hanno il coraggio di domandarglieli.","Unità",[],["Ionia"],"EPICO"],"05IO021":["Germoglio di Salice divino","Gioca: Richiama un alleato per evocare una sua copia Effimera.\nConto alla rovescia 3: Evoca un'altra sua copia Effimera.","","Un tempo il Salice divino crebbe a Omikayalan. Ciò che ora si erge in quel luogo può essere più forte o più debole, ma l'importante è che sia nuovo.","Monumento",[],["Ionia"],"RARA"],"05IO024":["Figli della foresta","Richiama un alleato, oppure spendi 8 mana per evocare copie Effimere dei tre seguaci più forti che hai richiamato in questa partita.","","I ricordi hanno le zanne.","Incantesimo",[],["Ionia"],"EPICO"],"05IO001":["Custode della foresta","Quando vengo evocata, forniscimi +1|+0 ed Elusione per questo turno.","","\"Si dice che tu non parli per non affossare gli altri col peso della tua conoscenza. Mmm... Secondo me ti sei solo stufata di rispondere.\" - Ahri","Unità",[],["Ionia"],"COMUNE"],"05IO025":["Matriarca dei Codamanto","Ogni turno, la prima volta che richiami un seguace, evoca una sua copia esatta Effimera.","","Un mistero è sempre più grande della sua soluzione.","Unità",[],["Ionia"],"RARA"],"05IO026":["La compianta","Colpisci il Nexus: Richiamami.","","Chi realmente venera la caccia, si ferma a piangere la sua preda.","Unità",[],["Ionia"],"RARA"],"05IO006":["Nove vite","Evoca 1 Guardiano liminale.","","Alla foresta serviva un guardiano, qualcuno che ne sorvegliasse i confini per anni, magari secoli, senza muoversi. Gai'sh si offrì volontario e dimostrò subito la sua dedizione facendosi un sonnellino di dieci anni.","Incantesimo",[],["Ionia"],"EPICO"],"05IO002":["Cappa della memoria","Seleziona un alleato bersagliato da incantesimi lenti, incantesimi veloci o abilità del nemico che hanno come bersaglio un singolo alleato, e fermali tutti.","","Una freccia non conosce l'intenzione del cacciatore né il valore della sua preda.","Incantesimo",[],["Ionia"],"COMUNE"],"05SH014":["Xerath","Quando distruggi un Monumento alleato, infliggi 1 al nemico più debole.","Hai distrutto 4+ Monumenti alleati.","\"Una volta i due erano amici, ma il tempo e la vicinanza li avevano resi fratelli. Di certo Azir non avrebbe mai potuto compiere tante meraviglie senza Xerath al suo fianco.\" \n- Scriba Kah'nir, Storie dell'Ascensione","Unità",["ASCESO"],["Shurima"],"Campione"],"05SH017":["Messaggera del Magus","Quando vengo evocata, se hai distrutto 4+ Monumenti alleati in questa partita, conferisci +2|+2 e Sopraffare ai tuoi campioni ovunque.","","La Messaggera allargò le braccia sollevando il volto verso il sole, che incombeva rosso sopra Shurima. \"Gloria al Magus Ascendente,\" disse con espressione beata mentre la sua voce riecheggiava tra le colonne distrutte. \"Gloria a Xerath!\"","Unità",[],["Shurima"],"RARA"],"05SH011":["Devozione eterna","Ultimo respiro: Evoca 1 Sarcofago.","","Le ricche decorazioni della tomba non erano di alcun aiuto per defunti ed esiliati.","Unità",[],["Shurima"],"RARA"],"05SH022":["Duello nel deserto","Fornisci -2|-0 a un nemico per questo turno. Un alleato e quel nemico si colpiscono a vicenda.","","\"Un viaggiatore che non teme il deserto è un viaggiatore che non conosce il deserto.\" - Proverbio shurimano","Incantesimo",[],["Shurima"],"COMUNE"],"05SH003":["Obelisco del Potere","Conto alla rovescia 3, quando vengo evocato o mi distruggi: Conferisci +2|+0 all'alleato più forte.","","Colonne scintillanti e crepitanti emersero dalle sabbie, simboli di potere sovversivi che avrebbero rinforzato il già potente esercito di Xerath.","Monumento",[],["Shurima"],"COMUNE"],"05SH016":["Accolito funesto","Gioca: Distruggi un Monumento alleato per conferire +1|+1 agli Accoliti funesti alleati ovunque.","","Tutti gli accoliti di Xerath sacrificavano una parte di sé stessi in cambio del potere, ma i suoi più devoti sostenitori avevano perso ogni traccia della propria identità, servendo sia da condotti, che da fonti di energia per il loro nuovo imperatore.","Unità",[],["Shurima"],"COMUNE"],"05SH018":["Schiavitù della desolazione","Evoca 1 Statua in stasi per contenere al suo interno tutte le unità alleate morte e i Monumenti alleati distrutti in questo turno.","","L'energia magica non scompare. Cambia semplicemente scopo.","Incantesimo",[],["Shurima"],"EPICO"],"05SH012":["Altare emerso","Conto alla rovescia 3 o quando mi distruggi: Evoca 1 Dami'yin lo Sfrenato.","","\"In ogni luogo di potere erigeremo un obelisco, tramite il quale il Magus Ascendente potrà assorbire energia dal cuore delle sabbie.\" - Messaggera del Magus","Monumento",[],["Shurima"],"EPICO"],"05SH020":["Costrutto della desolazione","Crea 1 Accolito funesto o 1 Obelisco del Potere nella tua mano.","","\"Plasmerò Shurima a MIA immagine!\" - Xerath","Incantesimo",[],["Shurima"],"COMUNE"],"05SH015":["Veggente delle Sabbie","Quando vengo evocata, pesca 1 carta. Se peschi un Monumento, ripeti questo effetto.","","L'orizzonte davanti a lei vibrava d'energia. Laddove altri vedevano solo sabbia e limo, lei vedeva linee temporanee, accecanti reticoli di pura energia che aspettavano solo di essere sfruttati.","Unità",[],["Shurima"],"EPICO"],"05SH004":["Energia scatenata","Fornisci +2|+1 a un alleato per questo turno, oppure distruggi un Monumento alleato per fornire +4|+2 a un alleato per questo turno.","","\"Strapperò il potere al deserto e distruggerò chiunque osi opporsi a me!\" - Xerath","Incantesimo",[],["Shurima"],"COMUNE"],"05SH002":["Errante della Desolazione","Quando distruggi un Monumento alleato, conferiscimi +1|+1.","","Gli accoliti erano già altamente istruiti prima di trovare Xerath. Ora che avevano finito di studiare ciò che lui stesso aveva studiato in passato, erano inarrestabili.","Unità",[],["Shurima"],"COMUNE"],"05SH007":["Rito arcano","Distruggi un Monumento alleato o una tua gemma di mana per infliggere 4 a un'unità.","","\"Un piccolo sacrificio in cambio di un grande potere.\" - Xerath","Incantesimo",[],["Shurima"],"RARA"],"05NX009":["Anima perduta","Quando vengo evocato o mi scarti: Crea 1 Redivivo doppialama nella tua mano.","","I demaciani hanno strisciato fino ai loro forti solo per vedere la morte calare fra le loro stesse mura. Hanno abbattuto una piccola parte della Legione Grigia, ma l'onda nera della guerra li ha travolti.","Unità",[],["Noxus"],"EPICO"],"05NX006":["Granatiere risorto","Per giocare, scarta 1 carta.\nQuando mi scarti, evoca una mia copia esatta.","","\"Siamo incappati in un'anomalia. Molti di coloro che rianimiamo disprezzano il ritorno alla vita, ma questo sembra aver compreso la sua situazione ed è esaltato dalle possibilità che ne conseguono. Bizzarro.\"\n- Appunti del dott. Esslanger","Unità",[],["Noxus"],"COMUNE"],"05NX005":["Antico guerrafondaio","Quando mi scarti, conferisci +2|+0 al tuo alleato più forte.","","Mentre i poteri di Noradi crescevano, si chiese se avrebbero avuto effetto sui cadaveri ammassati nelle fosse più vecchie di Noxus. La luce della vita non era che una scintilla nel buio, ma tra quelle fiamme morenti danzavano ancora le ombre della guerra.","Unità",[],["Noxus"],"RARA"],"05NX001":["Sion","Quando mi scarti, conferisci Sopraffare al tuo alleato più forte e mettimi nel tuo mazzo.\nHo +1|+0 per ogni carta che hai scartato in questa partita (massimo +7|+0).","Hai scartato o evocato unità per un totale di 35+ Potere.","Sion vide fugaci lampi di ricordi sbiaditi. Legioni schierate di fronte a lui. Encomi. Corone. Guerre. L'ultimo rantolo di un re. Il Grande Nulla. Sangue. E come erano arrivate quelle visioni, così se ne andarono, simili a folate di vento.","Unità",[],["Noxus"],"Campione"],"05NX003":["Sale e suture","Per giocare, scarta 1 carta.\nEvoca 1 Granatiere risorto e forniscigli +2|+0 per questo turno.","","\"Risorgi, figlio mio...\" - Dott. Esslanger, medico riflessivo","Incantesimo",[],["Noxus"],"RARA"],"05NX015":["Gladiatore caduto","Quando vengo evocato, conferisci Non può bloccare al nemico più debole.\nUltimo respiro: Crea 1 Gladiatore risorto nella tua mano.","","\"I primi minotauri che ho rianimato erano bestie docili e inutili. I loro sensi non reagivano né al richiamo della guerra né alla minaccia della morte.\"\n- Appunti del dott. Esslanger","Unità",[],["Noxus"],"RARA"],"05NX019":["Per la gloria!","Reputazione: Costo 3 in meno. Evoca 2 Trifariani Assetati di Gloria.","","Nulla potrà fermare chi cerca la gloria.","Incantesimo",[],["Noxus"],"RARA"],"05NX013":["Cavaliere caduto","Quando mi scarti, crea 1 Cavaliere risorto nella tua mano.","","\"Strofinare foglie di Ombranera sull'armatura del cavaliere era l'unico modo per difenderlo dalla furia del basilisco. È una pianta che cresce nello stesso habitat di quelle belve ed è tanto acre quanto velenosa.\"\n- Appunti del dott. Esslanger","Unità",[],["Noxus"],"COMUNE"],"05NX012":["Urlo del massacratore","Per giocare, scarta 1 carta. Uccidi il nemico più debole.","","\"Alleati, nemici, non mi importa.\" - Sion","Incantesimo",[],["Noxus"],"COMUNE"],"05NX014":["Armi dei perduti","Infliggi 3 a un'unità ed evoca 1 Spaccascudo Trifariano.","","\"Spaccascudo!\" - Sion","Incantesimo",[],["Noxus"],"COMUNE"],"05NX004":["Medico funereo","Gioca: Scarta 1 carta per pescare 1 unità.","","Un tempo il dott. Esslanger era un medico rispettato e riservato che si era guadagnato una buona reputazione con anni di duro lavoro. Tuttavia, quando una giovane nobildonna posseduta dal demone del tradimento si avvicinò ai suoi studi, iniziò a servire Noxus con tutte le sue forze.","Unità",[],["Noxus"],"COMUNE"],"05NX016":["La Signora del Sangue","Quando un'unità non Fugace alleata in mano viene scartata, crea una sua copia Fugace nella tua mano.","","Col favore delle tenebre, madama Faris Noradi condusse la sua Legione Grigia fuori da Noxus. Ci vollero tre infernali settimane, ma alla fine raggiunsero il piccolo avamposto demaciano individuato dalle sue vedette. Era il momento di una dimostrazione pratica.","Unità",[],["Noxus"],"EPICO"],"05NX002":["Nobile ribelle","Quando hai scartato 3+ carte in questa partita, conferiscimi +2|+1.","","\"Niente instilla lealtà nel cuore di un potenziale traditore più della vista del cadavere di un cospiratore riportato in vita per combattere sotto la bandiera di Noxus. In un modo o nell'altro, tutti ci serviranno.\" - La Signora del Sangue","Unità",[],["Noxus"],"COMUNE"],"05BW005":["Nami","Quando giochi un incantesimo, conferisci +1|+0 a un altro alleato più debole non Immobile.","Hai giocato 5+ incantesimi con una Nami alleata in gioco.","\"Hai salutato chi dovevi, giovane spirito delle maree?\"\n\"Sì, nonna.\"\n\"Hai paura?\"\n\"...Sì, nonna.\"\n\"Bene. La paura è la madre della cautela. Però devi credere in te, come facciamo tutti noi. Ora va' e che le correnti ti proteggano.\"","Unità",[],["Bilgewater"],"Campione"],"05BW006":["Riflusso","Infliggi 2 casualmente a un nemico o al Nexus nemico e crea 1 Flusso nella tua mano.","","\"Percepisci l'umore delle onde...\" - Nami","Incantesimo",["ELEMENTALE"],["Bilgewater"],"COMUNE"],"05BW002":["Saltasabbie girovago","","","\"Certo alcuni ci danno la caccia, come fanno con tutti. Però molti dei terricoli che incontro vogliono solo godersi il mare come noi. In fondo, non siamo poi tanto diversi.\"","Unità",[],["Bilgewater"],"COMUNE"],"05BW008":["Guardia degli abissi","Quando giochi un incantesimo, forniscimi +2|+0 per questo turno.","","\"Molti nella nostra tribù trovano Loto inquietante. In lui vedono solo un guerriero instancabile dallo sguardo turbato e distante. Io però so cosa nasconde il suo cuore... La paura di non essere abbastanza forte per proteggerci... e un amore straordinario.\" - Tama, cantrice Marai","Unità",[],["Bilgewater"],"COMUNE"],"05BW011":["Ammiraglio Shelly","Quando giochi 2 incantesimi in un turno, conferisci +1|+1 agli altri alleati.","","\"SENTIMI BENE, SHOLDATO. DEVI SHAPERE CHE HO PIÙ DI SHEICENTO UCCISHIONI CONFEWMATE E SONO UN GRANDE AMMIWAGLIO DELLA MAWINA, QUINDI SHE TI DICO DI NUOTARE TU NUOTI, CHIAWO? GWAZIE!\"","Unità",[],["Bilgewater"],"EPICO"],"05BW003":["Mareggiata","Infliggi 1 a due nemici casuali diversi e crea 1 Onda fragorosa nel tuo mazzo.","","\"Onde dell'oceano!\" - Nami","Incantesimo",["ELEMENTALE"],["Bilgewater"],"RARA"],"05BW004":["Avatar delle maree","Se ottieni una gemma di mana, ripristina invece il tuo mana incantesimo.\nQuando giochi un incantesimo, crea nella tua mano un incantesimo casuale di costo 3 o inferiore e conferiscigli Fugace.","","Per i Marai, il Leo'lei è foriero di grandi cambiamenti. Si dice che ogni battito delle sue eleganti ali influenzi il flusso delle maree.","Unità",[],["Bilgewater"],"EPICO"],"05BW001":["Guardiana Marai","Quando vengo evocata, evoca un seguace casuale di costo 1.","","È raro che i Marai si allontanino dalla loro patria, ma Ai'la era nata con un animo curioso. Seppur legata alla sua tribù dal senso del dovere, passa ogni secondo sognando il giorno in cui potrà essere finalmente libera.","Unità",[],["Bilgewater"],"RARA"],"05BW010":["Nonna Marai","Quando vengo evocata, crea 5 incantesimi casuali di costo 6+ nel tuo mazzo e riduci il loro costo a 3.","","La dimora ancestrale dei Marai è protetta dalla luce celestiale di una pietra di luna. Ogni cento anni, la sua luce inizia a spegnersi e un nuovo spirito delle maree riceve il compito di trovarne un'altra, perché senza di essa i Marai verrebbero inghiottiti dall'oscurità e invasi dagli orrori nascosti negli abissi.","Unità",[],["Bilgewater"],"COMUNE"],"05BW013":["Cantante Marai","Quando vengo evocata, conferiscimi Elusione se hai giocato un incantesimo in questo turno.","","\"L'oceano sa che l'onda tornerà,\ndopo la marea che viene e se ne va.\nCosì quando un'onda sulla costa si schianta,\nl'oceano si rallegra e del suo ruggito si vanta.\"\n- Strofa della \"Serenata per lo spirito delle maree\"","Unità",[],["Bilgewater"],"RARA"],"05PZ015":["Giustizia su ruote","Ogni volta che l'avversario pesca una carta, piazza 1 Trappola Bombalampo tra le prime 8 carte del mazzo nemico.","","\"L'agente è stata vista inseguire il sospetto ad alta velocità, spingendolo in una trappola di sua creazione. Dopo l'arresto, l'agente si è multata per il suo stesso eccesso di velocità, affermando (in modo solenne) che 'La giustizia è una strada a doppio senso'.\"\n- Estratto dal rapporto di un guardiano","Unità",[],["Piltover e Zaun"],"EPICO"],"05PZ012":["Archivista della stazione","Gioca: Scegli un incantesimo tra le prime 5 carte del tuo mazzo e creane una copia esatta Fugace nella tua mano, poi piazza quelle 5 carte nel tuo mazzo.","","Agli investigatori servono piste da seguire: è compito di un archivista raccogliere ogni brandello d'informazione per creare nuove possibilità dal nulla.","Unità",[],["Piltover e Zaun"],"RARA"],"05PZ026":["Catena di montaggio","Evoca 2 Lavoratori della fucina.","","\"Cambio di turno!\" - Capo della forgia","Incantesimo",[],["Piltover e Zaun"],"COMUNE"],"05PZ019":["Ricercato numero uno","Scegli un giocatore a cui far scartare la carta di costo più basso per pescare 3 carte.","","\"Tutto ha un prezzo.\" - Corina Veraza","Incantesimo",[],["Piltover e Zaun"],"EPICO"],"05PZ031":["Albus Ferros","Quando vengo evocato, pesca Jayce. Attacca: Infliggi 3 al Nexus nemico. Per ogni incantesimo di costo 6+ che hai giocato in questa partita, aumenta la quantità di 1.","","\"Il magnanimo Albus Ferros si è ancora una volta IMPOSTO sotto i riflettori, battendo i Clan Cadwalder e Giopara nell'asta per i diritti sulla ricerca dei portali hextech di Jayce. \"Un gran giorno per i Ferros è un gran giorno per Piltover\", dice il proverbio, e ieri è stato veramente un giorno incredibile, per i Ferros.\"\n- Da una doppia pagina pubblicitaria sul giornale di Piltover","Unità",[],["Piltover e Zaun"],"EPICO"],"05PZ027":["Esplosione shock","Infliggi 3 a un nemico o al Nexus nemico, e 3 a un altro.","","\"Fuoco!\" - Jayce","Incantesimo",[],["Piltover e Zaun"],"RARA"],"05PZ022":["Jayce","Gioca: Conferiscimi Attacco rapido o Sfidante.","Hai giocato due incantesimi che costano 6 o più. Quando aumento di livello, crea 1 Portale acceleratore nella tua mano.","\"Come sai, Rosa, questa tecnologia enerformativa promette di cambiare il mondo.\"\n\"Una vera rivoluzione, Jayce. Mi toglie il fiato vedere come hai abbinato quei percussori.\"\n\"Puoi dirlo forte. Tutta un'idea di Axel, tra l'altro! Vero, vecchio mio?\"\n\"Beh, mi conosci. Non sono un tipo che si vanta...\"","Unità",[],["Piltover e Zaun"],"Campione"],"05PZ017":["Vapori del Sump","Infliggi 2 a un'unità. Se hai aggiunto 2+ carte alla tua mano in questo turno, infliggi invece 3.","","\"Meglio che prendano un po' d'aria. All'inizio l'odore è nauseante, ma quando ti abitui... non c'è niente di meglio!\" - Venditore di Scoppiettini","Incantesimo",[],["Piltover e Zaun"],"COMUNE"],"05PZ013":["Pacificatore di Piltover","Infliggi 2 a un'unità e piazza 2 Trappole Bombalampo tra le prime 8 carte del mazzo nemico.","","\"Ecco il MIO biglietto da visita.\" - Caitlyn","Incantesimo",[],["Piltover e Zaun"],"COMUNE"],"05PZ020":["Imboscata","Fornisci +2|+0 a un alleato per questo turno. Se hai aggiunto 2 o più carte alla tua mano in questo turno, forniscigli anche Elusione per questo turno.","","\"Circonderemo la zona usando i fumogeni per coprire i nostri movimenti...\" - Caitlyn","Incantesimo",[],["Piltover e Zaun"],"COMUNE"],"05PZ024":["Finanziere dei Ferros","Gioca: Manifesta un incantesimo di costo 6+ delle tue regioni.","","\"L'unico lato positivo di ricevere finanziamenti dai Ferros era poter lavorare con Reggie. Non è solo uno dei più competenti che abbia mai conosciuto, ma è anche una gran bella persona.\"\n- Dal diario di Jayce","Unità",[],["Piltover e Zaun"],"COMUNE"],"05PZ010":["Intelligence avanzata","Piazza 2 Trappole Bombalampo tra le prime 8 carte del mazzo nemico.\nPesca 1 carta.","","\"Al mio segnale.\" - Caitlyn","Incantesimo",[],["Piltover e Zaun"],"COMUNE"],"05PZ014":["Corina, Genio criminale","Gioca: Piazza 5 Trappole Bombalampo tra le prime 5 carte del mazzo nemico o attiva gli effetti di tutte le trappole tra le prime 5 carte del mazzo nemico.","","Corina sorrise mentre i guardiani di Piltover sfondavano la sua porta, calpestavano i suoi amati fiori e venivano avvolti da una nube di polline tossico. Tutto secondo i piani.","Unità",[],["Piltover e Zaun"],"EPICO"],"05PZ002":["Informazioni riservate","TUTTI i giocatori pescano 2 carte.","","\"È un caso celebre, eh? C'era un altro tizio a consultarlo fino a poco fa. Beh, divertiti!\" - Archivista della stazione","Incantesimo",[],["Piltover e Zaun"],"COMUNE"],"05PZ021":["La fucina del domani","Quando vengo evocata, evoca 1 Lavoratore della fucina. Quando giochi un incantesimo che costa 6 o più, distruggimi e ripristina il tuo mana incantesimo.","","Se Piltover è una città guidata dalle invenzioni, le fucine sono i suoi motori.","Monumento",[],["Piltover e Zaun"],"RARA"],"05PZ025":["Capo della forgia","Colpisci: Ripristina 1 mana incantesimo.","","\"Ci vogliono due cose per concretizzare un'idea. Da una parte i fondi, dall'altra una buona fucina. E non bastano dei buoni strumenti, ci vuole anche un capo che sappia come gestire il tutto, altrimenti le idee rimangono schizzi su un foglio di carta.\" - Jayce","Unità",[],["Piltover e Zaun"],"COMUNE"],"05PZ006":["Caitlyn","Colpisci: Piazza 2 Trappole Bombalampo tra le prime 8 carte del mazzo nemico.","5+ delle tue trappole sono state attivate.","Caitlyn era sempre stata un'investigatrice caparbia e meticolosa, qualità che le avevano permesso di scalare in fretta i ranghi della polizia di Piltover. Tuttavia, quando si imbatté nel caso di un certo \"C\" che innumerevoli altri agenti avevano abbandonato, in molti pensarono che forse Caitlyn avesse trovato pane per i suoi denti. Forse.","Unità",[],["Piltover e Zaun"],"Campione"],"05PZ004":["Squadra di agenti","Quando vengo evocata, crea 1 Ricercato numero uno nella tua mano.","","Disporsi silenziosamente nella strada e preparare l'ariete non richiese molto tempo. Non restava che aspettare il segnale di Caitlyn.","Unità",[],["Piltover e Zaun"],"RARA"],"05PZ009":["Agente sotto copertura","Colpisci il Nexus: Piazza 2 Trappole Bombalampo tra le prime 8 carte del mazzo nemico.","","Come tutti i bambini di Zaun, anche Zayne Asako era dovuto crescere in fretta tra i vicoli oscuri e pericolosi della città. Dopo aver perso suo fratello nell'ennesimo insensato crimine legato alle gang, si è unito alla polizia di Piltover sperando di poter rendere sicura la sua casa grazie alla legge e alla ragione.","Unità",[],["Piltover e Zaun"],"COMUNE"],"05PZ016":["Colpo di grazia","Piazza un seguace nemico nel mazzo nemico. Dopodiché, l'avversario pesca 1 carta.","","La grande città di Piltover ospita alcune delle menti più brillanti di Runeterra. Lo stesso vale per la sua prigione.","Incantesimo",[],["Piltover e Zaun"],"RARA"],"05PZ030":["Anomalia hextech","Quando mi peschi o mi crei nella mano o a ogni Inizio del turno: Quando sono nella tua mano, trasformami in un incantesimo casuale da 6+.","","\"La più grande sfida è stata stabilizzare la struttura hextech. Per lunghe notti mi è sembrato che i cristalli e la hexite tramassero contro di me, ed è solo dopo innumerevoli tentativi che sono riuscito ad armonizzare i componenti...\"\n- Dal diario di Jayce","Incantesimo",[],["Piltover e Zaun"],"RARA"],"05PZ028":["Aeronave dei Ferros","Conferiscimi +2|+0 dopo aver giocato un incantesimo di costo 6+ in questa partita.","","\"Il popolo di questa città si prostra ai piedi dell'intelligenza. Ma a cosa serve una mente brillante, se non ha modo di esprimersi? A niente. Io mostrerò la vera grandezza a Piltover. Svetterà sopra di loro. Oscurerà il sole. Porterà il mio nome.\" - Albus Ferros","Unità",[],["Piltover e Zaun"],"COMUNE"],"05PZ038":["Sbarramento missilistico","Infliggi 4 a un nemico e 1 a tutti gli altri nemici.","","\"Dovrebbero andare su, non DAPPERTUTTO! Cielo!\" - Heimerdinger","Incantesimo",[],["Piltover e Zaun"],"COMUNE"],"05PZ035":["Rodicchietto puzzolente","Ultimo respiro: Crea 1 mia copia nel mazzo nemico con 2 Scoppiettini velenosi attaccati.","","Il fetore dei rodicchietti nel pieno della stagione degli Scoppiettini è indescrivibile. Riuscite a immaginare una fogna piena di pesce stantio e uova marce? Bene. Ora raddoppiatela.","Unità",[],["Piltover e Zaun"],"RARA"],"05PZ029":["Manipolatore hextech","Conferisci +1|+0 agli alleati con Tecnologia ovunque dopo aver giocato un incantesimo che costa 6 o più in questa partita.","","Il manipolatore hextech è stato costruito per trasportare materiali grezzi a Piltover, ma col passare del tempo gli abitanti si sono affezionati. La squadra di Jayce della fucina l'ha soprannominato Polpetta, un signore di Piltover gli ha donato un cappello, e i bambini di passaggio lo decorano con tutto ciò che capita.","Unità",["TECNOLOGIA"],["Piltover e Zaun"],"RARA"],"05SI014":["Registro dei rimpianti","Inizio del turno: Crea nella tua mano una copia Fugace di un incantesimo non Fugace che hai giocato nel turno precedente.","","Quando le Isole Benedette dimenticano, le Isole Ombra ricordano. Quando le Isole Ombra dimenticano, le Isole Benedette ricordano.","Monumento",[],["Isole Ombra"],"EPICO"],"05SI013":["Custodi della Nebbia","Ogni turno, la prima volta che uccidi un'unità con un incantesimo, evoca 1 Spettro della Nebbia Effimero.","","La Nebbia Oscura intrappola le sue vittime in cicli infiniti di tormenti autoindotti. Usando i Caccianebbia, Tek e Kana danno a quelle anime la possibilità di spezzare il ciclo con le loro forze.\n","Unità",[],["Isole Ombra"],"RARA"],"05SI009":["Senna","Quando vengo evocata o attacco: Crea 1 Oscurità nella tua mano, se non è già presente. I tuoi incantesimi con danni e uccisioni diventano Veloci.","Ti ho visto uccidere 3+ unità con incantesimi o ho visto un Lucian alleato morire.","\"Essere una Sentinella significa combattere. Significa perdersi o perdere quelli che amiamo. Ma soprattutto significa vivere. Per se stessi... e per quelli che amiamo.\"","Unità",[],["Isole Ombra"],"Campione"],"05SI016":["Tenebre dell'alba","Uccidi un'unità e fornisci ai nemici -2|-0 per questo turno.","","\"Non esiste ombra senza luce. Non esiste morte senza vita.\" - Senna","Incantesimo",[],["Isole Ombra"],"COMUNE"],"05SI004":["Osservatore delle Isole","Ogni turno, la prima volta che uccidi un'unità con un incantesimo, infliggi 2 al Nexus nemico.","","\"Un cucciolo è sempre un cucciolo.\" - Parole scarabocchiate sull'anima","Unità",[],["Isole Ombra"],"RARA"],"05SI012":["Sentinella dei Solari","Quando vengo evocata, crea 1 Oscurità nella tua mano, se non è già presente.","","\"Non riesco più a sentire il sole. Però conservo il suo ricordo e questo mi basta.\"","Unità",[],["Isole Ombra"],"COMUNE"],"05SI008":["Sentinella di Ixtal","Quando vengo evocata, crea 1 Oscurità nella tua mano, se non è già presente. Quando giochi la prossima Oscurità in questo turno, copiala prendendo come bersaglio il Nexus nemico.","","\"Senna, mi hai chiesto cosa mi spinge a combattere. La Nebbia non mi ha tolto nulla e non minaccia la mia casa. Eppure esiste e non dovrebbe. Io sono qui per scoprire il perché. Mi servono altri motivi per unirmi alla tua causa?\"","Unità",[],["Isole Ombra"],"RARA"],"05SI003":["Oscurità perforante","Assorbi 5 da un'unità.","","\"La morte è attratta dalla vita.\" - Senna","Incantesimo",[],["Isole Ombra"],"COMUNE"],"05SI010":["Dess e Ada","Quando vengo evocato, crea 1 Oscurità nella tua mano, se non è già presente. La tua prossima Oscurità in questo turno costa 0 e ottiene \"Infliggo danni a tutti i bersagli nemici\".","","\"Un altro incubo?\"\n\"Beh, la cosa positiva era che tu non c'eri.\"\n\"Idiota. E la cosa negativa?\"\n\"Tu non c'eri.\"","Unità",[],["Isole Ombra"],"EPICO"],"05SI011":["Sentinella promettente","La prima volta che uccidi un'unità con un incantesimo, conferiscimi +2|+1.","","Cosa vedrà la Nebbia guardando Maeve? Esuberanza, sicurezza, incrollabile ottimismo. Deve avere una voglia matta di spegnere la sua fiamma... Perché in fondo per la morte non c'è cosa più spaventosa della vita.","Unità",[],["Isole Ombra"],"COMUNE"],"05SI015":["Sentinella Buhru","La prima volta che uccidi un'unità con un incantesimo, conferiscimi +2|+1.","","La filosofia dei Buhru e quella delle Sentinelle convergono in un solo punto: tutte le cose devono finire e alcune vanno fatte finire.","Unità",[],["Isole Ombra"],"COMUNE"],"05MT004":["Camphor, l'Incertezza","Quando vengo evocata, se hai bersagliato alleati in 4 turni diversi, conferiscimi Scudo magico, Sopraffare e Sfidante.","","Per secoli la demone Camphor imperversò nelle terre di Targon, strappando alle sue vittime ciò che più li definiva: ai potenti toglieva la forza, ai saggi la conoscenza. Tuttavia, non aveva interesse per quei doni. Lei si nutriva della sofferenza, del dubbio e della tristezza che infliggeva. Era un mostro in ogni senso.","Unità",[],["Targon"],"EPICO"],"05MT006":["Fiammabianca ferito","","","\"Ai targoniani non servono altre prove della crudeltà degli dei. Basta guardare ciò che hanno fatto a noi e ai nostri amati compagni.\" - Pantheon","Unità",["DRAGO"],["Targon"],"RARA"],"05MT008":["Slancio dello scudo","Conferisci +1|+1 a un alleato e stordisci un nemico.","","Pantheon era un esperto nell'arte della guerra. Innumerevoli scontri gli avevano insegnato che i nemici si guardavano sempre dalla sua lancia, ma quasi mai dal suo scudo.","Incantesimo",[],["Targon"],"RARA"],"05MT014":["Meraviglia celestiale","Stordisci due nemici.","","\"Il cielo notturno del Targon è uno spettacolo dalla bellezza inimmaginabile. È facile perdersi con lo sguardo nell'immensità, senza sapere fin dove si spingono le stelle e quali esseri potrebbero osservarci a loro volta...\" - Scalatore targoniano","Incantesimo",[],["Targon"],"COMUNE"],"05MT003":["Pantheon","","Hai bersagliato alleati in 5+ turni diversi.","Ammirate Atreus, colui la cui libertà venne strappata dalle Incarnazioni che tanto venerava. Ammirate il fuoco della Guerra, che lasciò ad Atreus doni che pochi umani possono comprendere. Ammirate l'uomo pronto a lottare e morire per coloro che ama.","Unità",[],["Targon"],"Campione"],"05MT013":["Iula","Gioca: Conferisci Scudo magico o Sopraffare a un alleato. Se non lo fai, conferiscilo a me.","","Iula ricorda ancora il cocente dolore che la attraversò dopo aver saputo della morte di suo marito. Quando Pantheon andò da lei, chiedendo il suo aiuto per distruggere la creatura che si cibava di quello stesso dolore, rispose senza pensarci un attimo.","Unità",[],["Targon"],"COMUNE"],"05MT009":["Legami marziali","Conferisci +2|+2 a due alleati.","","Muovere guerra agli dèi può sembrare un'impresa folle, ma superando dolore e paura i pochi che hanno avuto questo ardire hanno riconosciuto le loro debolezze. Gli esseri divini pensano ciascuno per sé, sono egoisti, hanno perso il dono della comunione: questi difetti sarebbero diventati le loro armi e i loro scudi.","Incantesimo",[],["Targon"],"COMUNE"],"05MT010":["Mistica cieca","Gioca: Conferisci +1|+1 a un alleato e silenzia un seguace nemico.","","Un tempo Eshiyme era un riverito oracolo, che usava le sue visioni per guidare i bisognosi. Purtroppo quel dono le fu sottratto da Camphor, bramosa di banchettare con la sua angoscia. Tuttavia, la demone aveva sottovalutato la resilienza di Eshiyme.","Unità",[],["Targon"],"COMUNE"],"05MT002":["Resistere insieme","Fornisci +1|+2 a due alleati per questo turno.","","\"È nel legame di fratellanza che dobbiamo cercare la nostra forza.\" - Pantheon","Incantesimo",[],["Targon"],"RARA"],"05MT012":["Colosso liberato","Quando vengo evocato o attacco: Crea 1 Gemma nella tua mano.","","I colossi sono antichi e riveriti protettori dei luoghi più sacri del Targon. Ferirli significa insultare la montagna stessa, e torturarli è un crimine che nessun targoniano può perdonare.","Unità",[],["Targon"],"COMUNE"],"05MT011":["Contro ogni probabilità","Se il tuo avversario ha più unità di te, conferisci a un alleato +1|+1 per ogni unità in più rispetto alle tue.","","Quel manipolo di coraggiosi sapeva di stare per affrontare esseri dal potere inimmaginabile. Sapevano che la morte era a un passo da loro. Eppure li affrontarono.","Incantesimo",[],["Targon"],"EPICO"],"05MT005":["Cercatore di saga","","","Tor sentiva la vita scivolare via a ogni battito, ma in quella tetra e lugubre oscurità, dove doveva accogliere il terrore, trovò invece un senso. Non solo sarebbe andato incontro alla morte, di sua spontanea volontà, ma avrebbe portato con sé il demone che aveva osato condannarlo. È così che sarebbe stato ricordato. Quella sarebbe stata la saga di Tor.","Unità",[],["Targon"],"COMUNE"],"05DE003":["Gorlith l'Immenso","Gioca: Scambia la mia salute con quella del tuo Nexus.\nNon posso essere bloccato da nemici con meno salute di me.","","\"Un tributo onorevole a coloro che abbiamo perduto, ma mai dimenticato: quando la gente di Demacia vedrà i raggi del sole spuntare da dietro le sue forme, ricorderà la speranza e lo spirito indomito che hanno ispirato la sua costruzione.\" \n- Targa nel laboratorio Durand","Unità",[],["Demacia"],"EPICO"],"05DE009":["Galio","Quando vengo evocato, conferisci +0|+3 agli altri alleati.","Fine del turno: I tuoi alleati hanno 25+ salute totale.","Per molti anni dopo la sua creazione, Galio è rimasto dormiente, senza percezione né emozione. Dopo essere stato portato in vita con la magia e aver provato il brivido della battaglia, scoprì la gioia dell'essere vivi. Ora, ogni volta che è di nuovo dormiente, gli mancano quelle sensazioni!","Unità",[],["Demacia"],"Campione"],"05DE020":["Scudo di Durand","Conferisci +0|+3 a un alleato. Al prossimo Inizio del turno, conferiscigli +0|+2.","","Basta la vista di Galio per ispirare i nobili cuori dei demaciani.","Incantesimo",[],["Demacia"],"RARA"],"05DE021":["Forza dell'Avanguardia","Per giocarmi, spendi tutto il tuo mana. Evoca 1 Indomita Avanguardia e aumentane le statistiche fino alla quantità di mana speso. Se hai speso 9+ mana, conferisci +2|+2 alle altre unità Élite alleate.","","Quando ogni speranza sembra essere perduta, i soldati di Demacia invocano l'Avanguardia.","Incantesimo",[],["Demacia"],"EPICO"],"05DE017":["Venti di guerra","Cura completamente un alleato. Poi, quell'alleato e un nemico si colpiscono a vicenda.","","\"Diamoci da fare, allora!\" - Galio","Incantesimo",[],["Demacia"],"RARA"],"05DE010":["Scultore di Durand","Quando evochi un altro alleato, conferiscigli +0|+1.","","\"Potrebbe non essere ovvio per i non esperti, ma il lavoro di un grande artista è un piccolo colpo di scalpello dopo l'altro.\"","Unità",[],["Demacia"],"COMUNE"],"05DE013":["Cervo di petricite","Supporto: Subisco tutti i danni al posto del mio alleato supportato in questo turno.","","Al seguito dell'esploratore a cavallo di un cervo, il guardiano di petricite si ergeva imponente accanto alla stessa creatura che ne aveva ispirato le forme eleganti.","Unità",[],["Demacia"],"EPICO"],"05DE015":["Drago della montagna","Furia mi conferisce +0|+2 invece di +1|+1.","","I placidi draghi della montagna non sono propensi alla rabbia, nonostante il loro aspetto. Il loro stoicismo, rispetto ad altre bestie della montagna, li rende i protettori naturali delle, altrimenti, vulnerabili creature.","Unità",["DRAGO"],["Demacia"],"EPICO"],"05DE019":["Architetto di Durand","Supporto: Fornisci +0|+2 e Formidabile al mio alleato supportato per questo turno.","","\"Il Ranger Cuordolmo ci porta brutte notizie\", disse l'architetto, concentrandosi nel ripiegare il rotolo di pergamena per nascondere il tremolio nelle sue mani. Si voltò verso gli scultori e fece loro un severo gesto con la testa. \"Sembra sia ora che i protettori invisibili di Demacia debbano uscire allo scoperto.\"","Unità",[],["Demacia"],"RARA"],"05DE014":["Protetta di Durand","Gioca: Conferisci +0|+1 e Tenacia a un alleato.","","Shireen distolse lo sguardo dal suo lavoro dopo aver sentito il rumore di zoccoli pesanti. Era preoccupata per la fretta del ranger, ma anche curiosa. Ordinò al suo uccello di petricite di alzarsi in volo per seguire il ranger.","Unità",[],["Demacia"],"COMUNE"],"05DE012":["Grandala di petricite","Quando evochi un altro alleato, conferiscimi Sfidante.","","Ogni volta che il Grandala passava sulle loro teste, gli stanchi soldati demaciani esultavano, ispirati dalla sua resistente forma.","Unità",[],["Demacia"],"RARA"],"05DE018":["Segugio di petricite","","","\"È sempre una gioia vederli prendere vita. Ogni tanto si tende a dimenticare quanto siano diversi l'uno dall'altro: la loro personalità è un riflesso dell'artista che li ha creati.\" - Scultore di Durand","Unità",[],["Demacia"],"COMUNE"],"06NX024":["Lord Broadmane","Gioca: Infliggi 2 a un nemico.\nI tuoi incantesimi Veloci, Lenti e le Abilità hanno \"Quando danneggio un nemico danneggiato o stordito, uccidilo.\"","","\"Secondo atto: un subdolo lord in rovina e con un guanto Kashuri rubato incanta una folla ioniana. Peccato che la sua maschera sia rozza e che non celi la sua identità. Lui implora pietà, dicendosi ignaro di tutto. Il pugno di ferro col quale voleva governare ora è vuoto.\"","Unità",[],["Noxus"],"RARA"],"06NX033":["Esecuzione strategica","Stordisci 2 nemici oppure spendi 6 mana per evocare 1 Generale della Legione.","","Prima di ogni battaglia, l'assegnazione degli incarichi è fondamentale. Un buon comandante sa che è il segreto per la vittoria...","Incantesimo",[],["Noxus"],"RARA"],"06NX012":["Annie","Attacca: Infliggo 2 all'unità che mi sta bloccando. Se non c'è più o è morta, infliggo invece 2 al Nexus nemico.","Ti ho visto giocare 6 incantesimi Veloci, Lenti o Abilità. Quando aumento di livello, crea Tibbers nella tua mano.","Più di dieci anni fa, Amoline Kiosar fuggì dal Conservatorio Ravenbloom con una risorsa preziosa e scottante tra le mani. Gli scout di Ravenbloom l'hanno cercata in ogni angolo dell'impero, ma tutte le piste si sono rivelate inutili. Così, anni dopo, quando è giunta notizia di una ragazzina sperduta e ardente di rabbia nel nord dei Picchi di ferro, Fynn Retrick ha accettato con riluttanza di partire e indagare sul caso. Non si aspettava di trovare niente. Si sbagliava e di grosso.","Unità",[],["Noxus"],"Campione"],"06NX029":["La grigia farmacia","Quando un alleato con 5+ Potere muore, crea un seguace casuale con 5+ Potere nella tua mano.","","\"Oggi mi sono trovato a ripensare alla piccola infermeria che avevo a Colle Penrose e agli anni trascorsi in cerca dei segreti della fisiologia. Anni! Sono al servizio della Signora Noradi da pochi mesi, ma ho realizzato che non avevo capito niente. Com'ero semplice. E fortunato.\"\n- Note del dottor Esslanger","Monumento",[],["Noxus"],"EPICO"],"06NX032":["Mastino draconico obbediente","Quando un alleato attacca, io attacco con lui.","","\"Che meraviglia i mastini draconici, vero? Sempre pronti a obbedire e così malleabili. Se solo i miei nemici gli assomigliassero un po'.\" - Spina della rosa","Unità",["CANIDE"],["Noxus"],"COMUNE"],"06NX030":["Disertore della Legione","Ottengo tutti i buff alleati ovunque.","","\"Primo atto: un ex soldato, dopo aver disertato in seguito al furto di un antico manufatto Kashuri, si nasconde alla locanda Qayanvi, ubriaco e arrogante. Non lo sa ancora, ma il suo tesoro rubato sussurra tutto ciò che vede al legittimo proprietario! La sua vita si consuma come il vino, con un cremisi noxiano sopra l'oro ioniano.\"","Unità",[],["Noxus"],"RARA"],"06NX013":["Tiratore di incantesimi","Gioca: Stordisci un nemico o, se è già stordito, infliggigli 2 danni.","","\"Studente: Sydell Kythera\nInsegnante: J. Willough\nRapporto: ho un morso di ragno sull'avambraccio sinistro. Sydell sostiene che sia un malinteso, ma il suo sorrisino tradisce la mala fede. Dovrà prestare due settimane di servizio nel refettorio.\"\n- Richiamo disciplinare di Ravenbloom","Unità",["RAGNO"],["Noxus"],"COMUNE"],"06NX040":["Arene di addestramento trifariane","In ogni turno, la prima volta che un alleato con 5+ Potere attacca, prepara l'assalto.","","\"Al mio comando, combattete! Se uccidete il vostro compagno, trovatene un altro! Se cadete, sappiate che la vostra morte ha reso Noxus più forte! Soldati trifariani... cominciate!\" - Esperta Trifariana","Monumento",[],["Noxus"],"EPICO"],"06NX028":["Conservatorio Ravenbloom","Conto alla rovescia 11: Crea 1 Tybaulk nella tua mano.\nAvanzo di 1 turno per ogni incantesimo Veloce, Lento o Abilità che hai giocato in questa partita.","","\"... ormai ti sarà giunta voce del disastroso fallimento dell'Accademia Roseguard. Mi aspetto che impariate dagli errori della vostra scuola gemella. Mi aspetto che gestiate la struttura in modo che sia utile all'impero.\"\n- Lettera bruciata nelle macerie del conservatorio","Monumento",[],["Noxus"],"RARA"],"06NX014":["Disintegrazione","Scegli un'unità. La prossima volta che subisce 1 o più danni in questo turno, uccidila.","","La direttrice Telsi ha parlato a lungo dei principi noxiani, annoiando e rendendo inquieti oltremodo i bambini. Mentre gli altri studenti si sono contenuti, Annie ha invece agito. Prima con il fumo, poi con il fuoco.","Incantesimo",["ELEMENTALE"],["Noxus"],"COMUNE"],"06NX031":["Yeti prigioniero","Reputazione: Costo 4 in meno.","","Il pubblico sussultò vedendo l'arrivo di due yeti in catene nella leggendaria arena dei Bordent. Nessuno pensava che le bestie fossero abbastanza forti da spezzare le catene, perché nessuno aveva mai affrontato uno yeti.","Unità",["YETI"],["Noxus"],"COMUNE"],"06NX009":["Dorsogrigio catturato","Attacco: Infliggo 3 all'unità che mi sta bloccando. Se non c'è più o è morta, infliggo invece 3 danni al Nexus nemico.","","\"Terzo atto: una crudele custode e il suo animale. Il dorsogrigio è innocente, anche nel suo orribile scopo. L'artefatto obbliga all'obbedienza. La custode si rifiuta di urlare, mentre viene data in pasto al suo animale. Se solo tutti i noxiani fossero così nobili nella morte.\"","Unità",[],["Noxus"],"COMUNE"],"06NX015":["Studioso della mananima","Ogni turno, la prima volta che giochi un incantesimo Veloce, Lento o un'Abilità, io gioco Lapilli magici.","","\"La prima volta che ho incontrato Daani è stata un paio d'anni fa. Che bravo padre. E che bella famiglia! Poi, nel mio ultimo viaggio, sono passato dal suo villaggio e ho trovato il povero Daani nella piazza, tutto solo. Ha detto che stava aspettando il ritorno della sua famiglia. Il poveretto sarà stato lì per mesi. Non ho avuto cuore di dirgli cos'avevo visto...\" - Fynn Retrick","Unità",[],["Noxus"],"COMUNE"],"06NX037":["Tellstones - Noxus","Crea 1 Determinazione affilata, Morte turbinante o Armi dei perduti Fugace nella tua mano.","","\"Clara, tesoro, devi pulire le pietre dal sangue.\" - Ophelia Noradi, Nobile Cremisi","Incantesimo",[],["Noxus"],"RARA"],"06NX008":["Capoclasse","Quando giochi un incantesimo Veloce, Lento o un'Abilità, conferiscimi +1|+0.","","\"Molti dei bambini hanno un'età in cui le inclinazioni naturali li portano a ribellarsi contro ogni indicazione formale. Per fortuna, la più grande è stimata dagli altri ed è propensa a perorare la nostra causa. Se gli studenti ignoreranno le nostre lezioni, insegneremo attraverso di lei.\" - Direttrice Telsi","Unità",[],["Noxus"],"EPICO"],"06MT044":["Stellacorno Solari","Alba: Fornisci +0|+2 agli altri alleati per questo turno.","","Gli stellacorni sono figli delle stelle. Alcuni ardono con più intensità degli altri.","Unità",[],["Targon"],"COMUNE"],"06MT036":["Consulto celeste","Cura completamente tutti gli alleati, poi rendi il loro Potere pari alla loro Salute.","","\"Bisogna innanzitutto avere compassione per noi stessi. Il resto vien da sé.\" - Soraka","Incantesimo",[],["Targon"],"EPICO"],"06MT039":["Trespolo del drago","Conto alla rovescia 3: Evoca Inviolus Vox.","","\"Dicono che i draghi celestiali nascano direttamente dalle nebulose, formandosi dalle polveri cosmiche. Ma come facciamo a saperlo, noi mortali? Da lontano, non vediamo altro che la loro luce.\" - Messaggero dei draghi","Monumento",[],["Targon"],"EPICO"],"06MT045":["Trittico celestiale","Invoca una carta Celestiale di costo basso, medio e alto.","","\"Le stelle predicono un grande potenziale. Qualcosa sta arrivando. Che forma prenderanno? Non sta a me saperlo! Cosa ne dici, Kulun?\" - Sognaluna","Incantesimo",[],["Targon"],"RARA"],"06MT043":["Tellstones - Targon","Crea 1 Ammirate l'infinito, Shhh o Benedizione di Targon Fugace nella tua mano.","","\"Che strana cosa, Shorin... Anche senza girare la pietra, so per certo quale costellazione ritrae.\" - Tyari il Viandante","Incantesimo",[],["Targon"],"RARA"],"06MT029":["Esmus, Anelito del mondo","Quando vengo evocata, piazza una Campanella sulla carta in cima al tuo mazzo.\nSupporto: Conferisci +1|+1 al mio alleato supportato.","","\"... ma ho sentito che Esmus è stata creata dal custode in persona e che con la sua nascita il mondo ha scoperto il suono!\"\n\"Frottole, dico io! Si sa che Esmus aveva il viso di una vecchia cantante dal cuore angelico e dalla voce mortifera... finché Bard in persona non le ha donato una voce di pura bellezza!\"\n\"Sciocchezze! Esmus è...\"\n- Esempio della Nascita di Esmus, un noto gioco da bardi","Unità",[],["Targon"],"COMUNE"],"06MT038":["Luce avvolgente","Crepuscolo: Fornisci +2|+1 e Sopraffare agli altri alleati per questo turno.","","\"Madre luna, donaci la tua forza.\nNonostante il buio che ci circonda,\ncon la tua luce trionferemo.\"\n- Preghiera Lunari","Unità",[],["Targon"],"COMUNE"],"06MT047":["Vortice mistico","Quando vengo evocato o finisco il conto alla rovescia, piazza 3 Campanelle nel tuo mazzo. Conto alla rovescia 2: Pesca 1 carta.","","\"E poi li ho visti. Migliaia, tutti che cantavano e ballavano. Poco dopo, ho visto un lampo di luce e non c'erano più, così come il tempio. E nelle mie mani? Beh, il vecchio Gaff si è trovato a stringere una campanella.\" - Storia del vecchio Gaff, terza parte","Monumento",[],["Targon"],"RARA"],"06MT041":["Branco di segugi delle stelle","I miei buff del Destino vengono conferiti alle unità Branchi di segugi delle stelle alleate ovunque.","","I segugi delle stelle non possono essere attirati o persuasi da chi affronta la scalata. Sono distanti e apparentemente incuranti della magia della montagna.","Unità",["CANIDE"],["Targon"],"COMUNE"],"06MT049":["Benedizione di Mikhael","Conferisci +1|+2 a un alleato e rimuovi tutte le sue parole chiave negative.","","Chi sente il suono della campana rimane colpito dalla purezza del suo rintocco.","Incantesimo",[],["Targon"],"RARA"],"06RU025":["Evelynn","Origine: Abbraccio agonizzante.\nQuando vengo evocata, evoca un Succubo casuale.","Quando vedo che tu o un alleato uccidete un Succubo alleato, forniscimi le sue parole chiave per questo turno e io salgo di livello.","Le pupille della sacerdotessa erano dilatate e la sua mano tremava per l'emozione. Era pronta. Era il momento che Evelynn desiderava più di ogni altra cosa. Sorrise e cambiò lentamente le sue sembianze. Poi, come sempre, cominciarono le urla.","Unità",[],["Runeterra"],"Campione"],"06RU001":["Bard","Origine: Il custode errante.\nAttacca: Piazza 3 Campanelle nel tuo mazzo.","Hai aumentato le statistiche totali degli alleati in mano o in gioco di 20+.","\"Sì, il vecchio Gaff ne ha viste di stranezze! La prima volta fu il custode in persona, penso. Come una stella che sfrecciava nel cielo, sì. Mi è sembrato come se il mondo si fosse fermato per un minuto e che fossimo solo io e lui...\" - Storia del vecchio Gaff, prima parte","Unità",[],["Runeterra"],"Campione"],"06RU002":["Jhin","Origine: Il virtuoso.\nAttacca: Infliggi 2 a tutti i nemici storditi.","Hai giocato 12+ incantesimi Veloci, Lenti o Abilità.","\"Preludio: apriamo sulla città di Qayanvi, dove un vecchio maestro convoca un giovane discepolo. Gli viene chiesto di eliminare un gruppo di feroci nemici e di recuperare alcuni manufatti sacri rubati. L'attore è entusiasta, ma non prende ancora posto. Per ora si limita a prepararsi, restando in attesa fuori scena.\"","Unità",[],["Runeterra"],"Campione"],"06FR029":["Paura raggelante","Congela un nemico ed evoca 1 Branco Zannabrina.","","Con il freddo arrivano anche gli zannabrina, che non devono nemmeno raggiungere la preda... Possono limitarsi ad aspettarla.","Incantesimo",["ELEMENTALE"],["Freljord"],"EPICO"],"06FR033":["Cinghiale da caccia","Ultimo respiro: Ottieni una gemma di mana vuota.","","Il ciclo della vita e della morte è diverso nel Freljord. L'ambiente spietato si assicura che poco o niente vada sprecato.","Unità",[],["Freljord"],"COMUNE"],"06FR038":["Ali della criofenice","Infliggi 3 a TUTTE le unità.\nIlluminato: Infliggi invece 3 a tutti i nemici e cura di 3 il tuo Nexus.","","All'ombra delle grandi ali della criofenice, i suoi seguaci gioivano e i nemici tremavano di paura.","Incantesimo",["ELEMENTALE"],["Freljord"],"RARA"],"06FR030":["Messaggero dei Servi","Gioca: Evoca 1 Schiavo ghiacciato o fai avanzare di 1 turno tutti i tuoi Schiavi ghiacciati.","","Lo strano fischio della creatura si sentiva a malapena, ma gli scout lo sentivano vibrare nelle ossa, man mano che correva sulle pareti della gola. Davanti ai loro occhi, il ghiaccio si riempì rapidamente di crepe smisurate.","Unità",["VOLATILE"],["Freljord"],"COMUNE"],"06FR039":["Ferocia dell'artiglio selvaggio","Trasforma un seguace alleato in Artiglio selvaggio Alfa.","","\"Spirito dell'artiglio selvaggio, donaci la tua forza!\" - Udyr","Incantesimo",[],["Freljord"],"RARA"],"06FR028":["Revna, la cantastorie","Quando vengo evocata, conferisci le mie statistiche alle unità nel tuo mazzo, poi pesca un'unità con 5+ Potere.","","I cantastorie avarosani sono spesso membri anziani della tribù, protettori del popolo e narratori esperti. Mantengono viva la tradizione della caccia e della battaglia con le loro canzoni. ","Unità",[],["Freljord"],"EPICO"],"06FR037":["Ghiaccio crepato","Conferisci a un nemico \"Congelami al prossimo Inizio del turno.\"","","Bisogna sempre saggiare il ghiaccio prima di camminarci sopra, anche se sembra resistente.","Incantesimo",["ELEMENTALE"],["Freljord"],"COMUNE"],"06BC045":["Boleto starnutoide","Fornisci +1|+1 agli alleati per questo turno. Se sono stati creati, fornisci +2|+2.","","\"CIAO. IO FUNGO IO PARLO IO NON SO PERCHÉ O PERCOME O COSA SUCCEDE FATEMI ESSERE UN FUNGO PER FAVORE GRAZIE CIAO.\" - Fungo","Incantesimo",[],["Bandle City"],"EPICO"],"06BC036":["Paparo il Grande","Gioca: Manifesta uno Yordle.\nAttacca: Conferisci +1|+0 a tutti gli alleati Yordle.","","\"TUTTI amano Paparo! Ogni estate ci porta regali dal mondo e sono sempre deliziosi, belli o bislacchi! A volte, tutte e tre le cose!\" - Ava l'Ambiziosa","Unità",["YORDLE"],["Bandle City"],"EPICO"],"06BC040":["Tellstones - Bandle","Crea 1 Marchingegno yordle, Melodia eroica o Arpione elettrico Fugace nella tua mano.","","Gli Yordle sono sempre pronti a giocare... ma non ti stupire se cambiano le regole a metà partita!","Incantesimo",[],["Bandle City"],"RARA"],"06BC039":["Sgancia la bomba","Infliggi 2 a un'unità ed evoca 1 Bomba rimediata.","","\"Beh, non ci siamo,\" disse placidamente Giselle, accucciandosi dietro a un riparo.","Incantesimo",[],["Bandle City"],"COMUNE"],"06BC044":["Legame cosmico","Infliggi 2 a un nemico e stordiscine un altro. Piazza 6 Campanelle nel tuo mazzo.","","\"Mamma, dove va il custode?\"\n\"Va ovunque, tesoro. Fin dove arriva lo sguardo.\"\n\"Perché?\"\n\"Ah, tesoro. Non pensare al perché. Nemmeno i più saggi degli anziani possono comprendere ciò che fa il custode...\"\n- Una madre al figlio","Incantesimo",[],["Bandle City"],"RARA"],"06BC026":["Byrd, il Campanaro","Quando vengo evocato, piazza una Campanella sulla carta in cima al tuo mazzo.","","\"La seconda è stata quella grossa. Stavo pulendo i pavimenti, quando all'improvviso ho visto la mia cena rovesciata sul tavolo e tutto il pentolame che se la dava a gambe, fuori dalla porta! L'ho seguito con tutto il fiato che avevo in corpo e l'ho trovato in quel tempio, a frugare tra gli scaffali come se stesse cercando qualcosa.\" - Storia del vecchio Gaff, seconda parte","Unità",[],["Bandle City"],"COMUNE"],"06BC030":["Scoppiettino di prossimità","Infliggi 1 a un'unità. Se una delle tue trappole o dei tuoi doni si sono attivati in questo turno, infliggi invece 3.","","\"Se inizia a brillare, sta per esplodere!\" - Regola numero 463 degli Scout di Bandle","Incantesimo",[],["Bandle City"],"COMUNE"],"06BC031":["Maduli, il Guardiano","Quando vengo evocato, piazza una Campanella sulla carta in cima al tuo mazzo, poi raddoppia i doni nel mazzo.","","\"Mi ha fatto venire un bello spavento. Braccia ovunque. Denti grandi come massi. Oh, e quando la creatura ha passato la bacchetta sui denti, ha fatto una melodia da brivido. Credevo di morire. Sono scappato. Ma non prima di vedere... i buchi nel cielo! Saranno stati centinaia!\"\n- Storia del vecchio Gaff, quarta parte","Unità",[],["Bandle City"],"RARA"],"06BC035":["Cartalbero","Quando un alleato con un Collegamento attacca, conferisci +1|+0 a quel collegamento.","","Le foglie del cartalbero brillano della stessa magia fatata che ha dato vita all'albero. Come gli uccelli a cui si ispirano, trovano irresistibile tutto ciò che brilla.","Monumento",[],["Bandle City"],"RARA"],"06IO005":["Teatro degli orrori","Richiama un'unità con 3 o meno Salute.","","\"L'arte non può essere affrettata.\" - Jhin","Incantesimo",[],["Ionia"],"COMUNE"],"06IO038":["Supporto morale","Costo 2 in meno se hai supportato un alleato in questa partita. Fornisci Barriera a un alleato per questo turno.","","\"Credi nell'equilibrio. Cammina sul confine.\" - Shen","Incantesimo",[],["Ionia"],"COMUNE"],"06IO012":["Chiamata dei Kinkou","Evoca 1 Custode delle maschere ora o al prossimo Inizio del turno. Pesca 1 carta.","","\"Le vecchie maschere aprono i giovani occhi.\"\n- Custode delle maschere","Incantesimo",[],["Ionia"],"COMUNE"],"06IO009":["Imboscata draconica","Avvia un attacco gratuito con 2 Cuccioli di drago.","","\"Desiderio reso manifesto.\"\n- Signore dei Draghi","Incantesimo",[],["Ionia"],"COMUNE"],"06IO033":["Tempesta di lame","Per il resto della partita, quando esegui la Danza delle lame, evoca un'altra Lama in attacco.\nDanza delle lame 1.","","\"Guida la danza, io ti seguo!\" - Danzatrice dei nastri","Incantesimo",[],["Ionia"],"EPICO"],"06IO004":["La Creatrice","Gioca: Richiama un'unità con meno Potere di me.","","\"Straordinaria artista, la Creatrice. Una mano leggendaria! Un'arte senza eguali! Un'esecuzione impeccabile! Che grande onore essere al suo cospetto e usare uno dei suoi strumenti.\" - Testimone Kashuri","Unità",[],["Ionia"],"RARA"],"06IO010":["Collinetta ventosa","Quando vengo evocato, pesca Yasuo e stordisci il nemico più forte.\nQuando ottieni il Gettone d'attacco, stordisci il nemico più forte.","","Per molti, pace è una casa felice arredata dall'affetto della persona amata. Per Yasuo, è quel raro momento in cui i venti si calmano e offrono nuove promesse, invece che ricordi. ","Monumento",[],["Ionia"],"EPICO"],"06IO036":["Tellstones - Ionia","Crea 1 Teatro degli orrori, Rito del rinnovamento o Uniti nelle difficoltà Fugace nella tua mano.","","\"Imparare a leggere l'avversario è un'abilità essenziale, anche fuori dagli scontri. Ma lo scopo del gioco è soprattutto divertirsi. E ora portami il catino per il pediluvio!\" - Mentore motivante","Incantesimo",[],["Ionia"],"RARA"],"06IO003":["Macchinista di palco","Gioca: Stordisci un nemico.","","\"Quarto atto: una giovane sacerdotessa entra nella storia. La sua è una vicenda tragica, narrata dalle pallide labbra di chi ha tradito. Volendo espiare il suo peccato a tutti i costi, porta con sé un pesante fardello, un dono dorato per i noxiani che ha accolto nella sua terra. Non possiamo che chiederci: sarà stato il dolore o un proiettile a spezzarle il cuore?\"","Unità",[],["Ionia"],"COMUNE"],"06IO035":["Studente Kinkou","Quando un altro alleato ottiene Barriera, forniscimi Barriera per questo turno, se non la ho già.","","\"Donati all'equilibrio senza riserve. Mente, corpo, spirito. Resisti agli impetuosi istinti della gioventù. Eleva la tua prospettiva.\" - Shen","Unità",[],["Ionia"],"RARA"],"06PZ032":["Giracanzoni gracchiante","Scegli uno tra due nuovi incantesimi con costo 2 per crearlo nella tua mano. Imposta il suo costo a 0 per questo turno. Ripeti altre due volte.","","Il primo giracanzoni di Zaun era sorprendentemente affidabile. L'unico problema era che nessuno sapeva come regolare il volume.","Incantesimo",[],["Piltover e Zaun"],"EPICO"],"06PZ042":["Imperfezionista diabolica","Gioca: Scegli una carta che hai in mano. Creane 4 copie esatte nel tuo mazzo e riduci il loro costo di 1.","","\"Beh, dirò solo che le cose sarebbero potute andare meglio. Non aggiungerò altro. Me del futuro... sai cos'abbiamo fatto.\"\n- Diario di Kay","Unità",[],["Piltover e Zaun"],"EPICO"],"06PZ025":["Solitudine","Quando vengo evocata, evoca un Succubo casuale.\nQuando evochi un alleato di costo 1, conferiscigli una parola chiave casuale.","","\"Tornando a casa dall'Entresol, ho visto di nuovo quella povera vagabonda singhiozzare in un vicoletto. Il fatto che tutti le girino alla larga mi spezza il cuore e le provoca chiaramente un grande dolore. Se la incontrerò domani, farò tutto il possibile per aiutarla.\"\n- Dal diario di Lady Sempescu","Unità",[],["Piltover e Zaun"],"RARA"],"06PZ043":["Tellstones - Piltover","Crea 1 Scossa di assestamento, Trasmorfatore hextech o Giorno del Progresso! Fugace nella tua mano.","","\"Non troverai un set migliore da nessuna parte. Mia figlia ha messo il cuore anche nel più piccolo dei dettagli.\" - Corin Reveck ","Incantesimo",[],["Piltover e Zaun"],"RARA"],"06PZ027":["Invito discreto","Crea 1 Tipo losco o Rockettaro Chempunk Fugace nella tua mano e riduci il suo costo di 1.","","La migliore vita notturna di Zaun è solo su invito. Se non sei nella banda, devi essere qualcuno, per avere un posto. O trovare un biglietto per terra.","Incantesimo",[],["Piltover e Zaun"],"COMUNE"],"06PZ038":["Mimetizzatore recuperato","Conferisci Elusione e \"Colpisci il Nexus: Pesca 1 carta\" a un alleato.","","\"Non indovinerete mai cos'ho trovato oggi!\" - Rovistatore del Sump","Incantesimo",[],["Piltover e Zaun"],"COMUNE"],"06PZ039":["Rottame di recupero","Per giocare, scarta fino a 2 carte. Crea altrettanti seguaci di costo 1 o più delle tue regioni e riduci di 1 il loro costo.","","Nelle profondità di Zaun, la gente è costretta a trasformare i rottami e gli scarti in materiali lavorati. Dopo decenni di esperienza, sono diventati molto bravi a farlo.","Incantesimo",[],["Piltover e Zaun"],"RARA"],"06BW006":["Illaoi","Attacca: Genera 1, poi guadagno Potere pari a quello del tuo Tentacolo più forte per questo turno.","Ho visto me stesso o le mie carte Tentacoli alleate infliggere 15+ danni.","\"Occhio di Nagakabouros\" è solo un nome, ma per Illaoi è un invito a vivere come se la sua dea fosse una presenza costante e da intrattenere.","Unità",[],["Bilgewater"],"Campione"],"06BW036":["Ratto del pontile","Ho +1|+0 per ogni turno diverso in cui hai danneggiato il Nexus nemico.","","\"Non c'è posto più sanguinoso della baia di Bilgewater. Guarda quei ratti. Sono cresciuti bevendo sangue. Non possono farne a meno. Mi fanno venire i brividi.\" - Macellaio impietoso","Unità",[],["Bilgewater"],"EPICO"],"06BW038":["Megazanna","Quando sei in Profondità, cura di 3 i tuoi alleati e il tuo Nexus.","","\"Cosa vuole?!?\"\n\"Vuole... le arance!\"\n\"Per la Donna Barbuta, DAGLI TUTTA LA CESTA!\" - Marinai sfortunati","Unità",["MOSTRO MARINO"],["Bilgewater"],"COMUNE"],"06BW030":["Occhio di Nagakabouros","Genera 2.\nPesca 2.","","Nagakabouros è una dea provvidenziale... per chi sopravvive all'atto di venerarla.","Incantesimo",[],["Bilgewater"],"COMUNE"],"06BW011":["Nagakabouros","Quando vengo evocata o all'Inizio del turno: Genera 2. Poi, se il tuo Tentacolo più forte ha 12+ Potere, crea 1 Capriccio di Nagakabouros nella tua mano.","","\"La Madre Serpente. Il Grande Kraken. La Donna Barbuta. Nagakabouros pensa pochissimo ai nomi e ancor meno ai morti senza pace.\" - Illaoi","Unità",[],["Bilgewater"],"EPICO"],"06BW021":["Omelia marina","Infliggi 3 a un'unità nemica.\nGenera 3.\nInfliggi 1 al Nexus nemico.","","\"Da bambini impariamo a navigare in acque infide. Chi arranca muore. È naturale che la prima prova di una sacerdotessa sia dimenticare questa lezione: lottare contro la risacca con tutta la sua forza. Perché la Messaggera della Verità non è colei che nuota. Ella è la corrente.\" - Illaoi","Incantesimo",[],["Bilgewater"],"EPICO"],"06BW045":["Sangue nell'acqua","Infliggi 1 a un bersaglio, poi prepara l'assalto.","","Nella Baia dello squartatore è dura tenere lontano gli squali. Una volta che assaggiano il sangue, ne vogliono sempre di più.","Incantesimo",[],["Bilgewater"],"COMUNE"],"06BW028":["Colpo del tentacolo","Genera 2, poi il tuo Tentacolo più forte e un nemico si colpiscono a vicenda.","","\"La vita è una prova. E il dolore è troppo spesso il nostro insegnante.\" - Illaoi","Incantesimo",[],["Bilgewater"],"RARA"],"06BW035":["La voce del mare","Attacca: Genera 1 e fornisci Sopraffare al tuo Tentacolo più forte per questo turno.","","Evocare Nagakabouros non richiede particolari riti o rituali. Risponde alla chiamata di chi ha un'anima pronta ad affrontare le onde e le violenze dell'oceano. Pochi sopravvivono alla battaglia.","Unità",[],["Bilgewater"],"RARA"],"06BW015":["Preghiera esaudita","Genera 2 o spendi 5 mana per generare 4.","","Le preghiere a Nagakabouros non prevedono suppliche, richieste o grazie. La sua benedizione è come la vita: a furia di lottare, prima o poi, si viene ricompensati.","Incantesimo",[],["Bilgewater"],"COMUNE"],"06BW007":["Idolo vigile","Inizio del turno: Infliggi 2 a me e Genera 1.","","Quando gli incubi brulicano fuori dalle Isole Ombra, l'idolo si illumina, come un faro all'orizzonte.","Unità",[],["Bilgewater"],"COMUNE"],"06BW037":["Riscatto","Manifesta un seguace che ti puoi permettere.","","\"E va bene, Baz. Vuoi davvero riprovarci?\"\n\"Non c'è il due senza il tre, Gav. Abbiamo affrontato tutto il peggio di questa sudicia città.\"\n\"E abbiamo perso, Baz.\" - Baz e Gav, aspiranti cacciatori di taglie","Incantesimo",[],["Bilgewater"],"EPICO"],"06BW041":["Truffa","Scegli 1 di 2 carte non campioni dalla mano dell'avversario e creane una copia nella tua mano. Saccheggio: Costo 1 in meno.","","\"CINQUE assi? A quanto pare ho vinto di nuovo!\" - Asso del biliardo","Incantesimo",[],["Bilgewater"],"RARA"],"06BW016":["Vedetta Buhru","Quando vengo evocata, genera 3.","","La vita è dolce, quando è semplice. L'acqua salmastra sul viso, il canto degli uccelli nelle orecchie... e un nemico poco complicato all'orizzonte.","Unità",[],["Bilgewater"],"COMUNE"],"06BW009":["Capo Buhru","Gioca: Un alleato di costo 1 avvia un attacco gratuito.","","\"Ricorda gli insegnamenti dell'oceano! Se non ti muovi, verrai mosso! Segui la mia voce se ti sei smarrito, perché il nemico sa sempre dove andare.\" ","Unità",[],["Bilgewater"],"RARA"],"06BW043":["Tellstones - Bilgewater","Crea 1 Più polvere!, Giocoso/Ingannatore o Evocazione acquatica Fugace nella tua mano.","","\"Quando si gioca con le pietre, non provare a chiamare i bluff. Bilgewater è piena di ottimi bugiardi. Se vuoi vincere, devi tenere d'occhio le mani.\" - Twisted Fate","Incantesimo",[],["Bilgewater"],"RARA"],"06BW018":["Sfolgorio","Quando vengo evocato, evoca un Succubo casuale.\nQuando evochi un alleato di costo 1, conferisci Vulnerabile al nemico più forte.","","Il primo incontro di Evelynn con Sfolgorio fu violento ed emozionante. Evelynn ricorda il suo sorriso di piacere mentre lo fustigava, e come fosse stato pronto a ricambiare quel dolore. Dopo aver battuto Rio, Evelynn decise di non distruggere il demone minore, ma di legarlo a lei per sempre. Forse, pensò, avrebbero potuto condividere il loro amore comune per il massacro.","Unità",[],["Bilgewater"],"COMUNE"],"06SH014":["Abominio del Vuoto","Quando vengo evocato, conferiscimi tutte le parole chiave positive che hanno avuto gli alleati in questa partita.\nQuando un alleato ha una nuova parola chiave positiva, conferiscimela.","","\"Abbiamo sentito parlare di eruzioni del Vuoto, in passato, e della devastazione che hanno portato. Ma vederla con i miei occhi... Non credo che riuscirò mai a togliermi quell'orrore dalla testa. Né dal cuore.\" - Sopravvissuto di Belveth","Unità",[],["Shurima"],"EPICO"],"06SH016":["Messaggero dell'alveare","Gioca: Conferisci a un'unità e a me le rispettive parole chiave positive.","","\"Mi ha parlato... come se mi conoscesse. Come se volesse incontrare... qualcosa...\" - Kai'Sa","Unità",[],["Shurima"],"RARA"],"06SH009":["Kai'Sa","Quando vengo evocata o inizia il turno: Se hai il gettone d'attacco, crea 1 Seconda pelle nella tua mano.","Evoluzione completata.","Pochi giorni prima, Kai'Sa aveva notato che la sua seconda pelle vibrava per l'emozione e la tirava con sempre più forza verso la costa shurimana. C'era qualcosa che non andava. Quando Kai'Sa giunse nei pressi di Belveth, realizzò la portata dell'orrore che aveva davanti.","Unità",[],["Shurima"],"Campione"],"06SH048":["Rito di passaggio","Manifesta un Monumento alleato che è stato distrutto in questa partita ed evocalo.","","\"Un momento preservato nel tempo.\" - Zilean","Incantesimo",[],["Shurima"],"COMUNE"],"06SH037":["Seccartiglio baccai","Gioca: Conferisci Vulnerabile a un nemico.\nQuando un nemico viene sfidato, forniscigli -2|-0 per questo turno.","","La sua sanità svaniva come dune nel vento, lasciando spazio a una furia che nemmeno le acque del deserto avrebbero placato.","Unità",[],["Shurima"],"COMUNE"],"06SH008":["Anziana di Belveth","","","Shalatai era sbigottita per l'orrore che aveva davanti agli occhi. C'era Ferai, la figlia del cordiale macellaio, schiacciata a morte. Accanto a lei c'era Gorrub, figlio del pescatore, con le mani senza vita ancora tese verso il suo amore. Quanti ricordi perduti. Quante vite spezzate. Con una smorfia, Shalatai si rivolse verso il male, pronta a dare la vita per salvare il resto del suo popolo.","Unità",[],["Shurima"],"COMUNE"],"06SH042":["Tellstones - Shurima","Crea 1 Predatore spietato, Peso del giudizio o Fuoco dello spirito Fugace nella tua mano.","","\"Quando si gioca a Tellstones non importa chi vince. Importa chi fa più scena mentre gioca!\" - Akshan","Incantesimo",[],["Shurima"],"RARA"],"06SH050":["Sabbie del tempo","Fornisci -2|-0 ai nemici per questo turno. Crea 1 Secolo istantaneo Fugace nella tua mano.","","Le sabbie del tempo scorrono senza pensiero e senza intento. La loro indifferenza è crudele, ma non tutti sono schiavi delle loro trame spietate...","Incantesimo",[],["Shurima"],"RARA"],"06SH049":["Chiamata alla gloria","Costo 2 in meno per ogni diverso alleato Asceso che hai evocato in questa partita.\nManifesta una carta dal Mazzo dell'Imperatore con costo 9 o meno.","","\"Ammira il nostro lavoro. Guarda cos'abbiamo costruito.\" - Azir","Incantesimo",[],["Shurima"],"RARA"],"06SH036":["Sala del rinnovamento","Quando evochi un campione, distruggimi per conferirgli +2|+1 e Scudo magico.","","Nasus emerse dal sarcofago, con la mente lucida e le ferite completamente guarite. Scrisse alcune note e guardò i sarcofaghi appesi, interrogandosi sullo stato mentale delle terribili aberrazioni al loro interno. Solo il tempo avrebbe detto se questa magia avrebbe potuto salvare i baccai dalla loro follia, la stessa magia alla quale un tempo si opponevano gli Ascesi. Ma loro non c'erano più, mentre Renekton e la sua follia erano una realtà. Nasus scrisse altre parole, sperando di aver trovato un modo per salvare suo fratello.","Monumento",[],["Shurima"],"EPICO"],"06SH011":["Sovraccarico","Conferisci Sopraffare e Scudo magico a un alleato.","","\"Ti mostro come si combatte.\" - Kai'Sa","Incantesimo",[],["Shurima"],"COMUNE"],"06SH017":["Cercatore del Vuoto","Infliggi 1 a un seguace. Se è stata completata l'Evoluzione, infliggi invece 3 a un'unità.","","\"Fa male, vero?\" - Kai'Sa","Incantesimo",[],["Shurima"],"RARA"],"06SH007":["Creatura del Vuoto","Quando sono nella tua mano, ho una parola chiave casuale che cambia ogni turno. Quando vengo evocato, conferiscimi quella parola chiave.","","Dharna ricordava di aver aperto le finestre, quella mattina, e di aver sentito il profumo del pane appena sfornato. In lontananza, i pescatori stavano già portando il pescato del giorno ai mercati. Si ricordava un sorriso e una giornata che sembrava perfetta.","Unità",[],["Shurima"],"COMUNE"],"06SH010":["Devastatrice del Vuoto","","","L'eruzione del Vuoto nella città di Belveth fu improvvisa e terrificante. Quasi tutti i civili, terrorizzati dal caos che aveva invaso la città, fuggirono come il vento. Quasi tutti, ma non Koyemi.","Unità",[],["Shurima"],"COMUNE"],"06SH034":["Dominazione","Quando vengo evocata, evoca un Succubo casuale.\nQuando evochi un alleato di costo 1, conferiscigli +1|+0.","","A volte, i potenti vogliono solo sentirsi impotenti.","Unità",[],["Shurima"],"EPICO"],"06DE045":["Luce dell'ispirazione","Conferisci Spirito agli alleati.","","\"Basta nascondersi! Vieni nella luce e risplendi con me!\" - Lux","Incantesimo",[],["Demacia"],"COMUNE"],"06DE038":["Lord Eldred, capo dei Cercatori di magia","Gli altri alleati e il tuo Nexus hanno Tenacia.\nQuando un alleato sopravvive ai danni, conferiscigli +1|+1.","","\"Non ho potuto fare a meno di ascoltare il tuo entusiastico bisbigliare, mogliettina cara. Ti invito a essere più cauta quando parli di questioni di famiglia in pubblico. Non sai mai chi potrebbe ascoltarti.\"","Unità",[],["Demacia"],"EPICO"],"06DE037":["Decreto reale","Fornisci +2|+2 e Sfidante a un alleato per questo turno o evoca 1 Lord onorato.","","\"Immediatamente, re Jarvan. Sarà fatto a ogni costo.\" - Barrett Buvelle, Lord onorato","Incantesimo",[],["Demacia"],"RARA"],"06DE035":["Pilastro di petricite","TUTTI gli incantesimi costano 2 in più.\nConto alla rovescia 2","","I cercatori di magia piazzano alti obelischi di petricite nelle loro basi, così da rendere inermi persino i maghi più potenti.","Monumento",[],["Demacia"],"COMUNE"],"06DE042":["Tellstones - Demacia","Crea 1 Barriera prismatica, Incarcerazione o Per Demacia! Fugace nella tua mano.","","\"Perché si chiama 'La mossa del re'? Anche la regina fa le sue mosse!\" - Cithria di Cloudfield","Incantesimo",[],["Demacia"],"RARA"],"06DE036":["Padre protettivo","Attacca: Pesca un'unità. Se è un Drago, evocala in attacco.","","\"Per fortuna la mia ricerca suggerisce che i padri delle nidiate trascorrono buona parte del tempo a caccia, lontano dai piccoli. Inutile dire che, se torna il maschio, diventiamo tutti cibo per draghi! Ah ah!\" - Anden Mayne, Ricercatore cervellone","Unità",["DRAGO"],["Demacia"],"EPICO"],"06DE030":["Fascino","Evoca un Succubo casuale e conferiscigli +1|+0.","Missing Translation","\"Più vicino, tesoro...\" - Evelynn","Incantesimo",[],["Demacia"],"COMUNE"],"06SI012":["Gwen","Attacca: Quando un altro alleato ottiene Potere da Consacrazione, lo ottengo anch'io. Assorbi 2 dal Nexus nemico.","Ho inflitto 10+ danni.","Gwen si fece strada a suon di forbici attraverso la Nebbia Oscura, pensando a come fosse strano che avvolgesse tutta l'area. Giunta dall'altro lato, il presbiterio incantato spiccava nella tristezza dei boschi come un faro. La piccola Gwen ne era attirata. Com'era curioso, ma anche... grandioso!","Unità",[],["Isole Ombra"],"Campione"],"06SI020":["Aculeo dell'odio","Uccidi un alleato per infliggere 3 danni a un'unità e se Evelynn era nel tuo mazzo all'inizio della partita, evoca un Succubo casuale.","","\"Urla pure quanto vuoi.\" - Evelynn","Incantesimo",[],["Isole Ombra"],"RARA"],"06SI013":["Ballerine eterne","Attacca: Rianima in attacco una copia Effimera dell'alleato morto più forte che non sono Ballerine eterne, con il mio Potere o meno.","","È sempre più facile unirsi a qualcuno in pista che essere i primi ad avviare le danze. Le gemelle, invece, sono sempre pronte a dare una lezione a tutti.","Unità",[],["Isole Ombra"],"EPICO"],"06SI037":["Tellstones - Isole Ombra","Crea 1 Marchio delle Isole, Viaggio spirituale o Crolla Fugace nella tua mano.","","\"Decorazioni... levigate. Imparare... regole. Gioco curioso. Fattura senza pari... senza fiato... indimenticabile.\" - Diario ritrovato","Incantesimo",[],["Isole Ombra"],"RARA"],"06SI040":["Ritorno agghiacciante","Rianima il seguace alleato morto più forte e conferiscigli Effimero e Temibile. Fornisci ai nemici -1|-0 per questo turno.","","Gli spiriti possono essere esiliati, ma prima o poi tornano sempre.","Incantesimo",[],["Isole Ombra"],"EPICO"],"06SI027":["Cruna dell'ago","Uccidi un alleato per infliggere a un nemico danni pari al suo Potere.","","\"Fuori gli aghi!\" - Gwen","Incantesimo",[],["Isole Ombra"],"COMUNE"],"06SI018":["Vora","Quando vengo evocata, evoca un Succubo casuale.","","A differenza di altri demoni, che attirano le vittime con falsi pretesti, Vora è troppo palese nei suoi desideri, che quasi la sopraffanno. Invece di essere una predatrice che va a caccia di cibo, è un animale selvaggio che ha bisogno di essere nutrito.","Unità",[],["Isole Ombra"],"RARA"],"06SI015":["Incita la banda","Evoca 2 Bande spettrali.","","\"Con brio! Più veloci!\" - Conduttore delle Nebbie","Incantesimo",[],["Isole Ombra"],"COMUNE"],"06SI030":["Invito formale","Crea nella mano copie di 2 seguaci alleati morti in questa partita.","","\"Eccoci qua. Ho sentito che ci attende una serata splendida. Mi aspetto di vedere molti volti noti!\" - Festante spettrale","Incantesimo",[],["Isole Ombra"],"RARA"],"06SI026":["Conduttore delle Nebbie","Ultimo respiro: Crea 1 Banda spettrale nella tua mano.","","\"Suonate, amici! Sarà un concerto più vivace che mai!\"","Unità",[],["Isole Ombra"],"RARA"],"06SI033":["Tomba infestata","Conto alla rovescia 2: Rianima l'alleato morto più forte.","","Il clangore tra spada e scudo fu come un rintocco mortale, capace di attirare spiriti ancora vincolati a questo mondo, insaziabili anche nella morte.","Monumento",[],["Isole Ombra"],"EPICO"],"06SI016":["Anfitrione esuberante","","","\"Vi INVITIAMO CORDIALMENTE alla festa più grande della vostra vita al FESTIVAL DI MEZZANOTTE. Unitevi a noi al PRESBITERIO DI PORCELLANA per ballare, bere e divertirvi! (Le celebrazioni si concluderanno prontamente alla tredicesima ora)\" \n- Invito in corsivo elegante","Unità",[],["Isole Ombra"],"RARA"],"06SI028":["Maggiordomo fantasma","","","Cosa sarebbe una festa elegante, senza un rinfresco di prestigio?","Unità",[],["Isole Ombra"],"COMUNE"],"06SI043":["Sottobosco","Getta 3.\nAssorbi 2 da un'unità.","","Persino nelle Isole Ombra, la vegetazione trova un modo di adattarsi.","Incantesimo",[],["Isole Ombra"],"COMUNE"],"06SI022":["Spasimante spettrale","","","Che fosse un fantasma, un ricordo o un sogno, aveva qualcosa di familiare...","Unità",[],["Isole Ombra"],"COMUNE"],"06SI019":["Sultur","Quando vengo evocato, evoca un Succubo casuale.","","\"Attenzione a chi sorride su queste isole infestate. Forse è qui da troppo poco per capire la brutalità di questo luogo. Forse ha perso il senno. Forse è qualcosa di completamente diverso. Ma fa' attenzione.\"\n- Note di Jens Tommen","Unità",[],["Isole Ombra"],"COMUNE"],"06NX022":["Carica della Legione","Pesca un alleato con 5+ Potere o porta un alleato a 5 Potere per questo turno.","","\"Pochi hanno l'occasione di servire nella Legione trifariana. Non sprecate la vostra occasione.\" - Esperta Trifariana","Incantesimo",[],["Noxus"],"EPICO"],"06NX019":["Disertore noxiano","Attacca: Aumenta il mio Potere per farlo corrispondere a quello dell'alleato equipaggiato più forte per questo turno.","","\"Continuo a fare sogni con quella voce nell'oscurità. Dieci anni... un'intera decade a fare il cagnolino obbediente dell'impero. Vai lì. Uccidi quello. E per cosa? Per la gloria di Noxus? La gloria è una dolce bugia e io ci sono cascato. Kayn mi ha mostrato una via diversa, che porta alla vendetta.\"\n- Royce, diario del macellaio","Unità",["CULTISTA"],["Noxus"],"COMUNE"],"06NX023":["Prodigiosa pescatrice ioniana","Quando vengo evocata, Improvviso.","","La vita di Trisk è cambiata completamente quando, in quello che doveva essere il suo ultimo torneo di pesca, è riuscita in qualche modo a pescare uno sputacchiante Jax. Lui si rifiuta di parlare dell'incidente, ma il mostro marino dal quale Trisk l'ha salvato diventa sempre più grande ogni volta che lei racconta questa storia.","Unità",["MAESTRO D'ARMI"],["Noxus","Ionia"],"COMUNE"],"06NX044":["Tirafila in agguato","Attacca: Porta il Potere degli alleati in attacco al livello del mio Potere in questo turno.","","\"Una brava madre insegna ai suoi figli come cacciare. Ma una grande madre... caccia per loro.\" - Elise","Unità",["RAGNO"],["Noxus"],"COMUNE"],"06NX041":["Piccione Cremisi","Supporto: Infliggi 1 al mio alleato supportato per fornirmi +1|+1 per questo turno.","","\"Dare da mangiare agli uccelli è divertente. Ho scommesso con il povero Feoward che avrebbero bevuto il sangue con lo stesso gusto di un basilisco di Bordent, e tu pensa: quei piccioni sono proprio noxiani!\" - Edvin Cortain, Curatore Cremisi","Unità",["VOLATILE"],["Noxus"],"EPICO"],"06NX020":["Balista Darkin","Puoi spendere 8 mana per giocarmi come Naganeka di Zuretta.","","Le steppe della Valoran orientale erano considerate brulle e inadatte a ospitare i noxii. Con il passare dei secoli nacque un nuovo impero affamato di territori. Terre incolte si scoprirono fertili grazie a nuove tecniche agricole e antiche armi sepolte tornarono alla luce.","Equipaggiamento",["DARKIN"],["Noxus"],"EPICO"],"06NX039":["Banchetto decadente","Infliggi 2 a un alleato per fornire +2|+0 agli alleati per questo turno.","","\"Non è un banchetto finché qualcuno non inizia a urlare. Quindi urla, ragazzo.\" - Vladimir","Incantesimo",[],["Noxus"],"COMUNE"],"06NX026":["Martelli poderosi","","","Vessid non era il gladiatore più veloce di Bordent, ma quando i suoi grandi martelli colpivano il bersaglio non c'era nemico in grado di rialzarsi.","Equipaggiamento",[],["Noxus"],"COMUNE"],"06NX034":["Furia armata","Un alleato equipaggiato colpisce un nemico.","","\"Fratelli di sangue, ancora una volta!\" - Disertore noxiano","Incantesimo",["CULTISTA"],["Noxus"],"RARA"],"06NX036":["Scudiero runico","Quando vengo evocato, Riforgia.","","Per mesi, arrancò tra il freddo e la pioggia, con un ingrato compito del quale non vedeva la fine. Eppure la fine arrivò. Finalmente, avrebbe compiuto qualcosa di cui essere fiero.","Unità",[],["Noxus"],"COMUNE"],"06NX027":["Schermaglia brutale","Distruggi l'equipaggiamento di un nemico. Un alleato e quel nemico si colpiscono a vicenda.","","\"Uno, due, guarda come urla,\nil soldato va a fuoco,\ntre, quattro, guarda come brucia,\nTibbers ama questo gioco!\" - Annie","Incantesimo",[],["Noxus"],"RARA"],"06MT035":["Xolaani, Tessitrice del sangue","Ho +2|+2 per ogni alleato morto mentre aveva il Potere aumentato.\nVigore 16: Trasformami in Xolaani, Flagello delle Incarnazioni.","","Xolaani guardò Anaakco cadere in ginocchio, sottomesso dal nemico che aveva cercato disperatamente di abbattere. Lentamente, il suo cuore iniziò a battere all'unisono con gli altri. Un altro cuore da controllare. Un altro corpo ai suoi ordini.","Unità",["DARKIN"],["Targon"],"EPICO"],"06MT007":["Viverna serafica","Vigore 5: Sopraffare.","","\"Ah, ora capisco... le forme rimaste sulla montagna non sono altro che tracce... canali per esseri del regno oltre le stelle...\" - Skai'en, cantastorie","Unità",["DRAGO"],["Targon"],"RARA"],"06MT037":["Sigillo d'acciaio","Annienta un alleato e crea 1 Forma corrotta con le sue statistiche.","","Gli dei guerrieri caduti e tumulati in queste armi non potevano essere sconfitti facilmente, quindi furono sigillati.","Incantesimo",[],["Targon"],"RARA"],"06MT031":["Mihira, Incarnazione della Giustizia","Fine del turno: Conferisci +1|+1 agli alleati in gioco e nella mano.\nVigore 5: Elusione, Rubavita e Sopraffare.","","\"Alcuni venerano le Incarnazioni come se fossero divinità. Altri le vedono come messaggere dell'altro reame... Altri ancora le temono... e forse non sbagliano.\" - Skai'en, cantastorie","Unità",[],["Targon"],"EPICO"],"06MT010":["Giudizio divino","Fornisci a un alleato \"In questo turno non posso subire danni o morire\" per questo turno.\nFornisci +1|+0 a tutti gli alleati per questo turno.","","\"Protetti dalla fiamma della giustizia!\" - Kayle","Incantesimo",[],["Targon"],"RARA"],"06MT016":["Messaggera alata","Vigore 3: Elusione.","","\"Sì... ti riconosco. Il messaggio che porti... può essere solo una convocazione.\" - Ryze","Unità",[],["Targon"],"COMUNE"],"06MT015":["Fiamme purificatrici","Conferisci +2|+2 a due alleati nella tua mano.","","\"Il male deve bruciare!\" - Kayle","Incantesimo",[],["Targon"],"COMUNE"],"06MT042":["Protettore liminale","Alba: Fornisci +1|+1 agli alleati con Alba per questo turno.\nCrepuscolo: Conferisci +1|+0 agli alleati con Crepuscolo.","","Il gufo canta nelle ultime ore della notte, poco prima del mattino, come per sottolineare il confine tra crepuscolo e alba.","Unità",["VOLATILE"],["Targon"],"RARA"],"06MT008":["Kayle","Ho +1|+0 per ogni volta che un alleato ha attaccato con il Potere aumentato.\nQuando vengo evocata, conferisci +1|+0 agli alleati.\nVigore 6: Attacco rapido.","Inizio del turno: Ho 11+ Potere.","\"I demaciani la conoscono con il nome di Protettrice Alata, ma per noi che viviamo sotto la volta stellata del Targon è la figlia della giustizia, foriera della volontà divina e di una spada di fuoco stellare.\" - Skai'en, cantastorie","Unità",[],["Targon"],"Campione"],"06MT004":["Pastore vagabondo","Gioca: Scegli un alleato, che Improvvisa. Se non lo fai, Improvviso.","","Jax ha aiutato Chaska a salvare il suo gregge dagli attacchi delle creature fatate. Poi, Chaska ha salvato Jax dagli attacchi delle creature fatate. Ora viaggiano sempre insieme finché uno dei due non si allontana.","Unità",["MAESTRO D'ARMI"],["Targon","Bandle City"],"COMUNE"],"06MT017":["Reverendo divino","Vigore 3: Rubavita.","","\"Si narra che quando Mihira lasciò questo luogo, abbandonò una parte di sé stessa. Una fiamma sacra, più luminosa che mai. Per anni, la mia famiglia si è occupata di quel fuoco, mantenendolo vivo nella speranza che lei possa tornare.\"","Unità",[],["Targon"],"RARA"],"06MT040":["Protezione dell'immensità","Dopo che hai equipaggiato un alleato in questa partita, costo 2 in meno.\nFornisci Scudo magico a un alleato per questo turno.","","Guarda il cielo notturno e concentrati su un minuscolo fazzoletto del firmamento. Immagina tutte le vite che ha visto, tutto il sapere accumulato in infiniti millenni. Immagina tutte le informazioni racchiuse in un frammento che puoi tenere nel palmo di una mano. Pensa a quanta saggezza sarebbe al tuo servizio. Pensa al potere.","Incantesimo",["CULTISTA"],["Targon"],"RARA"],"06MT034":["Impatto celestiale","Annienta un'unità o un Monumento. Cura il tuo Nexus di 3.","","\"Chi potrebbe arrivare nel nostro momento del bisogno?\" - Anziano shurimano","Incantesimo",[],["Targon"],"RARA"],"06MT033":["Fasce draconiche","Il mio portatore è un drago.","","Molti fanno appello alla potenza dei draghi, anche se si manifesta in modi diversi nei vari luoghi di Runeterra. Chi invoca il potere di un drago celestiale potrebbe scoprire che possiede una forza interiore che brucia con l'intensità di una stella.","Equipaggiamento",[],["Targon"],"COMUNE"],"06MT053":["Gemmologa generosa","Quando giochi un incantesimo, conferisci +1|+1 a un alleato casuale nella tua mano.","","Con occhi gentili ma velati, offre un rosario di cristallo a chi vuole iniziare il suo pellegrinaggio. Non chiede nulla in cambio, perché il prezzo verrà pagato sulla montagna.","Unità",[],["Targon"],"EPICO"],"06MT006":["Magnetite Darkin","Supporto: Conferisci +1|+1 al mio alleato supportato.\nPuoi spendere 8 mana per giocarmi come Horazi.","","Forse chi ha imprigionato il Darkin pensò che seppellire la leggendaria guerriera Horazi in una sfera di metallo stellare sarebbe stato sufficiente a offuscare la sua volontà irascibile. Ma il suo generale si agitava e così fece anche Horazi, che capì che persino gli antichi protettori di Targon potevano essere tentati da promesse sussurrate da lontano.","Equipaggiamento",["DARKIN"],["Targon"],"EPICO"],"06MT018":["Tutore della legge","Gioca: Stordisci i nemici con meno Potere di me.","","\"Temo che il giorno sia giunto... La giustizia torna su ali dorate, recando con sé un esercito scintillante!\" - Skai'en, cantastorie","Unità",[],["Targon"],"COMUNE"],"06MT052":["Benedizione celestiale","Conferisci Spirito a un alleato in gioco e a uno nella tua mano.","","\"Per grazia divina.\" - Kayle","Incantesimo",[],["Targon"],"COMUNE"],"06MT032":["Cultista Lunari","Quando vengo evocata crea 1 Gemma nella tua mano. Ripeti l'effetto dopo che hai equipaggiato un alleato in questa partita.","","Voleva porre fine al conflitto tra Sole e Luna, giorno e notte. L'arco offriva del potere, ma a un prezzo terribile: decise comunque di accettarlo, sperando di poter fermare la guerra una volta per tutte. ","Unità",["CULTISTA"],["Targon"],"COMUNE"],"06RU008":["Jax","Origine: Gran maestro d'armi.\nAutoequipaggia: La luce di Icathia.","Gli alleati equipaggiati hanno attaccato con 16+ di Potere totale.","Secoli fa, il Vuoto si prese la terra di Jax. Ora lui vaga per il mondo in cerca di guerrieri con la forza di volontà (e il fegato) per affrontare un nemico così terribile.","Unità",["MAESTRO D'ARMI"],["Runeterra"],"Campione"],"06RU006":["Ryze","Origine: Il mago delle rune.\nQuando vengo evocato o all'Inizio del turno: Crea 2 Tuffo nei passati nel tuo mazzo.","Vedo 3 Rune Terrene o più","Ryze si avvicinò al dirupo, accompagnato dal silenzioso servitore di Kayle. Sotto di sé vide una terra straziata dalla guerra e notò le mostruosità darkin che si davano battaglia. Per secoli, aveva visto l'umanità passare da una catastrofe all'altra. Si chiese se i suoi sforzi fossero vani e se Runeterra fosse condannata a morire.\"","Unità",[],["Runeterra"],"Campione"],"06RU005":["Kayn","Origine: Il mietitore d'ombra.\nAutoequipaggia: Falce darkin.\nQuando uccido un nemico, curami di 2.","Ho colpito due volte. Quando aumento di livello, richiamami.","Dopo aver mietuto un'altra vittima, Kayn rise, sapendo che presto avrebbe scatenato la seconda arma Darkin celata alla vista. Dentro di lui, Rhaast era sempre più impaziente, conscio che la fine di Kayn era finalmente vicina.","Unità",["DARKIN"],["Runeterra"],"Campione"],"06RU026":["Aatrox","Origine: Lo Sterminatore di Mondi.\nAutoequipaggia: La lama dei Darkin.\nQuando vengo evocato o colpisco: Cura di 2 il tuo Nexus e crea 1 Sterminatore di Mondi nella tua mano se non lo hai già.","Hai giocato Sterminatore di Mondi.","Persino attraverso i continenti, Aatrox percepì il suo risveglio. Sentì l'odio che ardeva ancora. Aveva già distrutto le sue statue e ora avrebbe potuto combattere la battaglia finale contro la Codarda di Icathia. Nel distruggerla, avrebbe messo fine a questa patetica esistenza.","Unità",["DARKIN"],["Runeterra"],"Campione"],"06RU009":["Varus","Origine: La freccia del castigo.\nAutoequipaggia: L'arco Darkin.","Hai bersagliato 7+ alleati.","E se, col tempo, l'uomo che divenne Darkin ricordasse sé stesso, spinto dalle voci immortali dentro di lui? E se, invece di sconfiggere quelle voci, decidesse di fidarsi di loro?","Unità",["DARKIN"],["Runeterra"],"Campione"],"06FR004":["Apprendista armaiola","La prima volta che equipaggi un alleato, forgialo.","","Ornn ha creato la fucina vivente moltissimi anni fa e solo di recente è andato a cercarla. Non avrebbe mai immaginato che potesse andare a cercarsi un nuovo padrone, muovendosi di sua volontà.","Unità",[],["Freljord"],"COMUNE"],"06FR011":["Ornn","Gioca: Equipaggiami con una copia esatta dell'equipaggiamento di un alleato oppure l'equipaggiamento più forte nella tua mano.\nAttacca: Forgiami due volte.","Un alleato ha colpito per un totale di 8+ danni con un solo colpo.","Se qualcuno avesse chiesto a Ornn come mai fosse così poco paziente, lui avrebbe risposto che di pazienza ne aveva eccome. Una pazienza assurda, persino, grazie alla quale il suo lavoro non aveva pari. Semplicemente, non aveva pazienza per la gente. Ma nessuno lo chiese e lui non dovette mai rispondere.","Unità",[],["Freljord"],"Campione"],"06FR035":["Pronto ad aiutare","Fornisci +0|+3 a un alleato per questo turno. Se è danneggiato, forniscigli invece +2|+3.","","\"Non temere, piccolo Poro. Ci sono qui io!\" - Braum","Incantesimo",[],["Freljord"],"COMUNE"],"06FR034":["Freddo spietato","Congela il nemico più forte. Se hai equipaggiato un alleato in questa partita, copiami.","","Anaakca si muoveva così velocemente che il Freljord sembrava seguire la sua scia. Chi sopravviveva alla sua mattanza, sentiva la pelle congelarsi e il cuore fermarsi.","Incantesimo",["CULTISTA"],["Freljord"],"COMUNE"],"06FR018":["La lancia dei Darkin","Attacca: Conferisci +1|+1 ai primi due alleati del tuo mazzo.\nPuoi spendere 8 mana per giocarmi come Anaakca.","","\"Madre guerriera, la presa dell'inverno si stringe. Gli avarosani hanno abbandonato gli avamposti. A nord si estende il mare... La nostra unica speranza è l'est.\"\n\"Non ascoltatelo, Madre guerriera. Da quella parte c'è il Pallore e, dopo di esso, le distese sussurranti. Meglio morire che affrontare quelle terre maledette.\"\n\"Per vostra fortuna, non sta a voi decidere le sorti del mio popolo.\"\n\"È vero, Madre guerriera... ma forse c'è un'altra via. Lasciate che vada a est. Meglio perdere una sola vedetta nell'oscurità che un intero popolo.\"\n- Madre guerriera Sejuani, discorrendo con gli altri generali","Equipaggiamento",["DARKIN"],["Freljord"],"EPICO"],"06FR012":["Artigiano favorito","Quando vengo evocata, crea 1 Tempo e dedizione nella tua mano.","","\"Mia madre mi ha raccontato di Ornn, come sua madre a lei e sua nonna a sua madre... E ora sarò io a raccontarti di lui. Ascolta bene. Non mi interrompere. Tanto tempo fa, oltre un mare caldo e impetuoso...\"","Unità",[],["Freljord"],"COMUNE"],"06FR005":["Fucina di Ornn","Quando vengo evocata o all'inizio del turno: Crea 1 Tempo e dedizione Fugace nella mano.","","Nel Langhus era accompagnato solo dal suono del fiume lavico che scorreva placido sotto di lui e dal tintinnio del martello sull'incudine. Non era niente male.","Monumento",[],["Freljord"],"RARA"],"06FR040":["Guardiano delle tribù","Quando vengo evocato, conferisci +1|+1 agli alleati per ogni sottotipo diverso che hai evocato in questa partita.","","\"... e c'era una GROSSA creatura che si occupava di tutte quelle PICCOLE...\" - La piccola Ingvar","Unità",[],["Freljord"],"EPICO"],"06FR020":["Frattura","Infliggi 1 a TUTTO o distruggi l'equipaggiamento di un'unità.","","Il freddo non risparmia niente e nessuno.","Incantesimo",["ELEMENTALE"],["Freljord"],"RARA"],"06FR027":["Lumacottera lanosa","Vigore 8: Rigenerazione.","","I troll non sono celebri per la loro intelligenza, ma possono essere sorprendentemente ingegnosi.","Unità",[],["Freljord"],"RARA"],"06FR032":["Dono della Stirpe della Terra","Cura il tuo Nexus di 4 e conferisci +1|+1 a tutti gli alleati e agli equipaggiamenti nel mazzo. Pesca una delle carte potenziate.","","\"Vieni a riscaldarti davanti al fuoco.\" - Riparatore della Stirpe della Terra","Incantesimo",[],["Freljord"],"EPICO"],"06FR022":["Soffio del mantice","Forgia un alleato e infliggi 1 a TUTTE le unità, poi fallo di nuovo.","","\"Forgerò una volontà di ferro!\" - Ornn","Incantesimo",["ELEMENTALE"],["Freljord"],"RARA"],"06FR021":["Poro imbronciato","Vigore 3: Sopraffare, Rigenerazione e Tenacia.","","\"Avanti, devi prendere la medicina! Altrimenti non ti sentirai meglio!\" - La piccola Ingvar","Unità",["PORO"],["Freljord"],"COMUNE"],"06FR023":["Colosso di ferro battuto","La prima volta che vengo equipaggiato, crea una mia copia a costo 4 nella tua mano. Conferiscile le statistiche dell'equipaggiamento.","","Non l'avrebbe mai ammesso, ma Ornn era molto fiero dei colossi. Facevano esattamente quello che dovevano e, soprattutto, stavano zitti.","Unità",[],["Freljord"],"EPICO"],"06FR008":["Riparatore della Stirpe della Terra","Gioca: Forgia due volte un alleato e cura l'alleato e il tuo Nexus di 3.","","Non rimaneva più nessuno della Stirpe della Terra quando Ornn decise di lasciare il mondo. Dopo generazioni, il loro nome andò perduto nel tempo. Di recente, però, sono riemerse storie su Ornn e pare che qualcuno abbia iniziato a tornare sulla via della Stirpe della Terra.","Unità",[],["Freljord"],"COMUNE"],"06FR009":["Esperto armaiolo","Gioca: Forgia un alleato.","","Fiske si immaginava un apprendista determinato, serio, forte e capace. Kindra non era nessuna di queste cose. Sognava sempre a occhi aperti, preferiva il gioco al lavoro e perdeva sempre tempo con quella sua stupida tartaruga. Eppure... stava imparando. Era l'unica cosa importante.","Unità",[],["Freljord"],"COMUNE"],"06FR024":["Mazza d'osso","","","\"Bonk!\" - Tarkaz il Senzatribù","Equipaggiamento",[],["Freljord"],"COMUNE"],"06FR017":["Cultista di Valgelata","I tuoi alleati equipaggiati hanno Sopraffare.","","L'Artiglio d'Inverno aveva ragione. Gli avarosani erano troppo deboli. Ci voleva una nuova guida che non avrebbe cercato di unire il Freljord nella pace, ma di conquistarlo. ","Unità",["CULTISTA"],["Freljord"],"RARA"],"06FR041":["Tocco dell'inverno","Ottieni una gemma di mana vuota. Illuminazione: Costo 1. Pesca 1.","","Strane rune pulsano dalle sfaccettature della gemma che hai in mano. Con un lampo sinistro la luce emerge, provocando un brivido nel tuo braccio. Ma ti senti rinvigorito, come se il freddo ti avvolgesse nella sua essenza. ","Incantesimo",["ELEMENTALE"],["Freljord"],"EPICO"],"06FR036":["Misticismo selvaggio","Ottieni una gemma di mana vuota.\nEvoca 1 Mistico selvaggio.","","\"Gli spiriti, le stelle... Nuovamente ci uniscono.\" - Hyara la veggente","Incantesimo",[],["Freljord"],"EPICO"],"06BC015":["Norra","Colpisci il Nexus: Piazza 1 Portale misterioso tra le prime 4 carte del tuo mazzo.","Hai evocato 6+ alleati creati.","Norra lavorava in fretta, continuando a pensare a casa. I portali sono notoriamente complessi e lei non aveva ancora bevuto la sua prima tazza di tè. Ma a Norra piacevano gli enigmi, soprattutto quelli che la lasciavano sperduta in sacche dimensionali tra lo spazio e il tempo. Lavorava sempre più in fretta, pensando alla sua gattina, che si immaginava preoccupata e in attesa della cena.","Unità",["YORDLE"],["Bandle City"],"Campione"],"06BC043":["Storie di Poro","Crea 3 Poro casuali di costo 1 nella tua mano.","","\"... POI IL PORO HA DETTO \"EHI, VOGLIO UNO SNAX ANCH'IO!\" E TUTTI I PORO SI SONO RIUNITI AL GRANDE RADUNO DEI PORO PER PARLARE DI TUTTI I PROBLEMI DEI PORO COME DOVE SONO GLI SNAX E PERCHÉ NON CI SONO ALTRI PORO E...\" - La piccola Ingvar","Incantesimo",[],["Bandle City"],"COMUNE"],"06BC051":["Blastabanane","Gioca: Infliggi a un'unità danni pari al mio Potere.","","\"EHI! QUALCUNO HA BISOGNO DI POTASSIO?” - Nanners, subito prima dell'\"Incidente\" ","Unità",["YORDLE"],["Bandle City"],"RARA"],"06BC047":["Generosità","Fornisci a un alleato collegato le statistiche e le parole chiave del suo collegamento per questo turno, poi sposta il collegamento su un altro alleato.","","Si potrebbe pensare che i pastori non siano adatti al campo da battaglia, ma le loro abilità sono sorprendentemente utili. Pensate ai combattenti come pecore bisognose di una guida.","Incantesimo",["MAESTRO D'ARMI"],["Targon","Bandle City"],"RARA"],"06BC019":["La dama del tè","Quando vengo evocata, piazza 1 Portale misterioso tra le prime 4 carte del tuo mazzo.","","Ashane era una famosa produttrice di tè, prima di ritrovarsi nella Fine del Reame. Mentre stava sperimentando con nuovi sapori, una sfortunata miscela di due tipi di foglie la fece sprofondare in un sonno in cui sognò strane creature e strutture impossibili che si stagliavano su un orizzonte senza fine. Al suo risveglio, scoprì che non era assolutamente un sogno.","Unità",["FATATO"],["Bandle City"],"COMUNE"],"06BC029":["Il bastone dei Darkin","Colpisci: Ripristina 1 mana incantesimo.\nPuoi spendere 8 mana per giocarmi come Baalkux.","","Si dissero che la foresta di Bandle era il luogo perfetto per nascondere un'arma Darkin. Orientarsi era impossibile e gli yordle si sarebbero tenuti lontani da quella fonte di malvagità. Tuttavia, i targoniani non compresero appieno l'efficacia di quella strana magia e gli effetti che avrebbe avuto sulla flora locale.","Equipaggiamento",["DARKIN"],["Bandle City"],"EPICO"],"06BC038":["Crescita improvvisa","Dopo che hai equipaggiato un alleato in questa partita, costo 2 in meno.\nPorta un alleato a 4|4 per questo turno.","","\"C'è così tanto potere in noi.\" - Varus","Incantesimo",["CULTISTA"],["Bandle City"],"RARA"],"06BC017":["Portalstravaganza","Piazza 2 Portali misteriosi tra le prime 4 carte del tuo mazzo.\nPesca 1 carta.","","\"Dovrei passare più spesso dalle strade nascoste! Che sciocca, ho sempre la testa tra le nuvole...\"\n- Norra","Incantesimo",[],["Bandle City"],"RARA"],"06BC020":["Origami affilato","Forniscimi +1|+0 per ognuna delle tue trappole o dei tuoi doni che si sono attivati in questo turno.","","La magia della carta può rivelarsi imprevedibile. Non conta solo l'intenzione dell'atto della creazione, ma anche il desiderio della creazione stessa.","Equipaggiamento",[],["Bandle City"],"RARA"],"06BC028":["Cultista in fiore","Dopo che hai equipaggiato un alleato in questa partita, conferiscimi Elusione.","","Persona, pianta, animale... l'influenza dei Darkin corrompe qualsiasi cosa.","Unità",["CULTISTA"],["Bandle City"],"COMUNE"],"06BC021":["Costrutto di rottami","Ultimo respiro: Piazza 1 Portale misterioso tra le prime 4 carte del tuo mazzo.","","Era nato appena il giorno prima, ma Marv, come lo chiamava affettuosamente Norra, viveva con grande orgoglio il suo ruolo di assistente. Insisteva solo nel farsi chiamare \"rottame\", non \"spazzatura\", perché voleva evitare le connotazioni negative.","Unità",["FATATO"],["Bandle City"],"COMUNE"],"06BC042":["Mutaforma curiosi","Quando un seguace alleato si trasforma in un altro seguace, trasformami in una sua copia esatta.","","Ciò che il camaleonte vede, il camaleonte diventa.","Unità",[],["Bandle City"],"RARA"],"06BC023":["Indicazioni confuse","Fai tornare un incantesimo Veloce o Lento nella mano o distruggi 1 equipaggiamento di un'unità. Pesca 1 carta.","","\"Povera me! Era di qua, di là... oppure da quell'altra parte? Me lo scordo sempre!\" - Norra","Incantesimo",[],["Bandle City"],"RARA"],"06BC041":["Partilandia di Ferraglio","Quando mi scarti, evocami. Quando evochi un Mecha yordle, conferiscigli una parola chiave casuale.","","Grande o piccolo, inanimato o meno, se ti serve qualche aggeggio, prova da Ferraglio! Però non chiedergli di trovarti niente, perché Ferraglio non crede nell'utilità degli inventari.","Monumento",[],["Bandle City"],"RARA"],"06BC011":["Viaggio magico","Piazza 1 Portale misterioso tra le prime 4 carte del tuo mazzo e piazza 1 Campanella sulla carta in cima al tuo mazzo.","","Vagando tra i reami a suo piacimento, Bard ascolta, conscio dell'avvicinarsi di un grande conflitto che potrebbe silenziare persino il canto della creazione.","Incantesimo",[],["Bandle City"],"COMUNE"],"06BC032":["Collezione eclettica","Per ogni alleato, piazza 1 Portale misterioso e 3 Campanelle tra le prime 10 carte del tuo mazzo e piazza 1 Trappola Bombalampo e 3 Scoppiettini velenosi nel mazzo nemico.","","\"Portali, portali ovunque!\"\n- Norra","Incantesimo",[],["Bandle City"],"EPICO"],"06BC024":["Custode del reame","La prima volta ogni turno che una delle tue trappole o uno dei tuoi doni si attivano, fornisci agli alleati +1|+1 e Impatto per questo turno.","","Gaspar fu il primo yordle ad arrivare alla Fine del Reame. Per molti anni aveva vagato solitario tra vie contorte e portali che sembravano non condurre da nessuna parte. Avendo deciso che nessuno avrebbe dovuto fare lo stesso, ora aiuta i viaggiatori smarriti a ritrovare la via di casa.","Unità",["FATATO"],["Bandle City"],"RARA"],"06BC033":["Mechapolverizzatore","Per giocare, scarta una carta.","","\"Ammirate! Dalle rovine di un traghetto affondato ho recuperato un guanto da pugilato. Dalle profondità della città che chiamano Zaun ho recuperato delle molle e nelle fucine di Demacia ho trovato il metallo! Questa è una creazione cosmopolita!\" - Paparo il Grande","Equipaggiamento",[],["Bandle City"],"COMUNE"],"06BC016":["Biblioteca vivente","Quando vengo evocata, se una delle tue trappole o dei tuoi doni si sono attivati in questo turno, pesca 1 carta.","","Convinta che il suo dovere sia possedere un sapere immenso, colleziona tomi portati dai viaggiatori che attraversano la Fine del Reame. Purtroppo, con tutto quel sapere si è montata la testa.","Unità",["FATATO"],["Bandle City"],"COMUNE"],"06IO044":["Cantrice del cielo sereno","Quando vengo evocata, riduci di metà il costo degli incantesimi nel tuo mazzo, arrotondando per eccesso.","","\"Alcuni cercano la pace attraverso la meditazione. Altri cercano la conoscenza per l'autoriflessione. Coloro che trovano il proprio centro esprimendosi, creando, possono portare pace anche agli altri.\" - Karma","Unità",[],["Ionia"],"EPICO"],"06IO013":["Stile Wuju","Fornisci +2|+0 a un alleato per questo turno.\nCrea 1 Meditazione nella tua mano.","","\"Uno dei tanti.\"\n- Master Yi","Incantesimo",[],["Ionia"],"RARA"],"06IO023":["Il ventaglio dei Darkin","Attacca: Evoca 1 Cucciolo di drago attaccante.\nPuoi spendere 9 mana per giocarmi come Praa il Varcabreccia.","","\"Da tempo percepivo un'ombra pulsare con ira silenziosa sul ponte tra i mondi. Pur sapendo di non potermi tuffare nell'oscurità per trovarla, di recente il suo pulsare si è fatto più forte e rapido, e temo che presto le creature del regno degli spiriti inizieranno a cercarne la fonte.\" - Shen","Equipaggiamento",["DARKIN"],["Ionia"],"EPICO"],"06IO029":["Spirito del Wuju","Flusso: Costo 2 in meno.\nQuando vengo evocato, pesca un incantesimo.","","\"Il maestro Doran credeva che ogni occhio dello Spirito del Wuju rivelasse intimi segreti sull'essenza delle persone. Eppure, per quanto ci provi, la lente del mio elmo vede solo delle sfumature di verde. Cosa mi sfugge?\" - Lui, discepola di Doran","Unità",[],["Ionia"],"COMUNE"],"06IO037":["La fiamma oscura","Gioca: Cattura un alleato. Quando attacchi per la prima volta in un turno, evoca una sua copia Effimera attaccante.","","\"Cos'è una vita se non l'ombra dell'esistenza? Accogli l'oscurità e vivrai per sempre.\" - Zed","Monumento",[],["Ionia"],"EPICO"],"06IO031":["Lama dello spirito","Flusso: Costo 2 in meno.","","\"Lama e corpo!\" - Master Yi","Equipaggiamento",[],["Ionia"],"COMUNE"],"06IO014":["Discepolo vastaya","Colpisci il Nexus: Richiamami e trasformami in Vento di Shimon.","","Ting sorrise, vedendo gli assalitori invadere il tempio. Aveva finalmente un'occasione per dimostrare il suo valore! Prima Wukong, poi Yi... entrambi avevano sottovalutato il suo talento. Gli altri potevano pure correre dal loro \"maestro\". Lui era pronto. Era il Vento di Shimon. ","Unità",[],["Ionia"],"EPICO"],"06IO008":["Master Yi","Inizio del turno: Riduci di 1 il costo di un incantesimo nella tua mano e attiva Flusso: Conferisci +2|+0 a tutte le carte Master Yi alleate ovunque.","I Master Yi alleati hanno inflitto 12+ danni.","La mente di Master Yi si soffermò sull'arma Darkin. Sin dalla sua scoperta, era stato assalito da un senso di inquietudine. Alcuni dei suoi studenti si erano interessati un po' troppo alla questione, quindi aveva ordinato che le lame curve fossero custodite nel cuore del tempio, con tanto di guardie. Con un po' di fatica, riuscì a scacciare i pensieri e a proseguire la sua meditazione. Trasmettere gli insegnamenti Wuju era l'unica cosa importante e Jun era molto promettente.","Unità",[],["Ionia"],"Campione"],"06IO040":["Tecnica dei Venti gemelli","Scegli un seguace. Evocane una copia esatta Effimera. Se è un nemico, stordiscilo.","","Per gli ioniani, il vento è il più capriccioso degli elementi. Capriccioso, ma non indomabile. ","Incantesimo",[],["Ionia"],"RARA"],"06IO011":["Jun, il prodigio","La prima volta che vengo equipaggiata, forniscimi Barriera e Rubavita per questo turno.","","Al suo segnale, Jun sferrò una serie di colpi con una precisione paragonabile a quella di Yi che, pur schivando l'attacco, la onorò con un inchino e un sorriso.","Unità",[],["Ionia"],"RARA"],"06IO015":["La Testimone","Flusso: Costo 2 in meno.\nGioca: Stordisci un nemico.","","Qual è il suo ruolo in questo strano e truculento spettacolo? Ah, più che spettatrice, è colei che osserva, la lente attraverso la quale tutto passa e deve confrontarsi con la verità e la bellezza. La Testimone!","Unità",[],["Ionia"],"COMUNE"],"06IO030":["Calà della bruma","Quando vengo evocata, pesca un equipaggiamento.\nLa prima volta in ogni turno in cui un alleato non equipaggiato viene equipaggiato, ripristina 2 mana incantesimo.","","\"Calà della bruma è un luogo sacro. Quelle spade sono qui da secoli e credo che le lame con una poesia sull'elsa invitino gli spiriti dei portatori passati a infonderle con la loro benedizione.\"\n- Discepola di Doran, pergamena manoscritta","Monumento",[],["Ionia"],"RARA"],"06IO034":["Scelta fondamentale","Se hai equipaggiato un alleato in questa partita, costo 1 in meno.\nFornisci +2|+0 o +0|+2 a un alleato per questo turno.","","Lacrime di rabbia scorrevano sul viso di Jun, mentre osservava i cadaveri sparsi sul terreno. Aveva fallito davanti a loro, davanti al suo maestro. Ora non le restava che una scelta...","Incantesimo",["CULTISTA"],["Ionia"],"RARA"],"06IO028":["Esca incantevole","Fornisci Sfidante a un alleato per questo turno. Se è equipaggiato, pesca 1.","","Tutti bramano la giusta esca.","Incantesimo",["MAESTRO D'ARMI"],["Ionia","Noxus"],"RARA"],"06IO025":["Fanatico Lama d'ombra","Dopo che hai equipaggiato un alleato in questa partita, crea 1 Demone delle tenebre nella mano.","","La vide nell'oscurità: un'arma capace di penetrare le ombre. In quel momento, sentì una voce chiamarlo, lontana ma potente. La seguì fino a Kayn, guidato dalla verità delle sue parole.","Unità",["CULTISTA"],["Ionia"],"COMUNE"],"06IO039":["Lungacoda di Navori","Gioca: Evoca 1 Brigante di Navori o fornisci +1|+1 agli altri alleati per questo turno.","","Il lungacoda fece amicizia col suo amico brigante una sera d'inverno, intorno alle ultime braci di un falò abbandonato. Nel giro di una settimana, i due avevano scoperto la loro mutua passione per le birbanterie e per il luccichio delle monete d'oro.","Unità",[],["Ionia"],"COMUNE"],"06IO032":["Anima indegna","Flusso: Costo 2 in meno.\nRichiama un'unità o un Monumento. Se ha dei collegamenti, distruggili prima.","","\"Non sei degno del potere che possiedi.\" - Rhaast","Incantesimo",[],["Ionia"],"RARA"],"06IO001":["Discepola di Doran","Quando vengo evocata, crea 1 Preparazione nella tua mano.","","\"Ho imparato tutto ciò che potevo per preservare quest'arte sacra. Quanto a Doran, al suo maestro e al maestro ancora prima di lui... spero che i loro spiriti guidino il mio martello.\"\n- Discepola di Doran, pergamena manoscritta","Unità",[],["Ionia"],"COMUNE"],"06IO016":["Invocatrice di draghi","Inizio del turno: Flusso: Evoca L'Empireo e conferiscigli Effimero.","","\"La forma dell'acqua riflette quella dei tuoi desideri. Dimmi, viandante... cosa vedi?\"","Unità",[],["Ionia"],"EPICO"],"06PZ034":["Hexterminatore","Infliggi 6 a un'unità. Se muore, invece annientala.","","Per alcune creature, la morte non è abbastanza.","Incantesimo",[],["Piltover e Zaun"],"RARA"],"06PZ006":["Bis","Crea un nuovo incantesimo di costo 2 nella mano, riduci il suo costo di 2 e rendilo Fugace.","","Non c'è niente di più appagante di un buon riverbero.","Incantesimo",[],["Piltover e Zaun"],"RARA"],"06PZ021":["Seraphine","Quando vengo evocata, crea un nuovo incantesimo casuale di costo 2 nella tua mano.","Hai giocato 9+ nuovi incantesimi.","Seraphine e suo padre non parlavano mai delle sue visite \"segrete\" alla città sotterranea, o delle piccole migliorie che continuava ad apportare al suo palco. Era sicura che le avrebbe proibito di partecipare al duello musicale più grunge di Zaun, ma una notte lui le fece scivolare il volantino sotto la porta. Lei sorrise e si mise al lavoro.","Unità",[],["Piltover e Zaun"],"Campione"],"06PZ040":["Baretto losco","Quando vengo evocato, evoca 1 Oste del vicoletto.\nLe tue carte novità costano 1 in meno.","","Dopo aver asciugato gli ultimi bicchieri, il barista si prese un momento per ammirare il suo locale. Quel luogo, quella seconda casa, aveva visto tanti estranei diventare amici, e portava fieramente le scritte e le ammaccature di tante notti selvagge. Il barista sorrise. Non sarà stato un posto perfetto, ma era il suo.","Monumento",[],["Piltover e Zaun"],"EPICO"],"06PZ008":["L'arpa Darkin","Puoi spendere 8 mana per giocarmi come Styraatu.","","Quando i targoniani si chiesero dove nascondere le armi Darkin, uno di loro suggerì le terre che sarebbero poi diventate Zaun. Pensava che le pareti di quelle gallerie contorte sarebbero state un luogo perfetto, irraggiungibile per ogni umano. Ma non per i chirean.","Equipaggiamento",["DARKIN"],["Piltover e Zaun"],"EPICO"],"06PZ018":["Nota acuta","Infliggi 2 a un'unità. Se hai giocato 6 o più nuovi incantesimi in questa partita, infliggi 1 a un'altra unità.","","Semplice e pulito.","Incantesimo",[],["Piltover e Zaun"],"COMUNE"],"06PZ014":["Presidente del fanclub","Gioca: Manifesta un incantesimo di costo 5 e imposta il suo costo su 2.","","\"Non importa quanto è alta la tua voce, conta quanto è grande il tuo cuore!\" - Presidente del fanclub","Unità",[],["Piltover e Zaun"],"RARA"],"06PZ030":["Progetti illuminati","Attacca: Crea un nuovo incantesimo di costo 2 nella tua mano e conferiscigli Fugace.","","\"Cielo, quanta luce oggi!\"\n\"Eh? Papà, oggi è nuvoloso.\"\n\"Ma io ho appena avuto un'illuminazione!\"\n\"Papààà!\"\n- Seraphine e suo padre","Equipaggiamento",[],["Piltover e Zaun"],"RARA"],"06PZ046":["Formula","Pesca 2 carte. Ripristina il tuo mana incantesimo.","","\"La magia è solo una scienza ancora da scoprire.\" - Jayce","Incantesimo",[],["Piltover e Zaun"],"COMUNE"],"06PZ007":["Cultista ambizioso","Dopo che hai equipaggiato un alleato in questa partita, crea nella mano un nuovo incantesimo di costo 2 e imposta il suo costo a 0 per questo turno.","","\"Non ho mai temuto di sacrificarmi in nome della scienza. Poco importa il rischio personale, perché il potere sconfinato e inesauribile che ho ottenuto vale più di qualsiasi ricompensa.\"","Unità",["CULTISTA"],["Piltover e Zaun"],"COMUNE"],"06PZ041":["Gattino astuto","Quando vengo evocato, se sono stato creato, pesca 1 carta e conferiscimi +2|+1.","","Quando non dormono nel bel mezzo della giornata e non vomitano nel cuore della notte, i gatti hanno sempre qualche birichinata in mente.","Unità",["FELINO"],["Piltover e Zaun"],"COMUNE"],"06PZ036":["Diva di Zaun","Gioca: Infliggi 1 a tutti i nemici. Se hai giocato 6+ nuovi incantesimi in questa partita, infliggi 3.","","\"Zaun! Voglio sentirti urlare, perché stasera facciamo affondare tutto di nuovo!\" - Diva di Zaun","Unità",[],["Piltover e Zaun"],"RARA"],"06PZ010":["Ingegnere acustico","Colpisci: Crea un nuovo incantesimo casuale di costo 2 nella tua mano.","","Un tempo sognava di lasciare Zaun per girare il mondo con una canzone nel cuore. Ora, il mondo dormiva nella sua stanza, in attesa delle canzoni che avrebbe portato il domani.","Unità",[],["Piltover e Zaun"],"EPICO"],"06PZ022":["Assolo di batteria","Pesca 2 carte.\nFlusso: Riduci di 1 il loro costo.","","La musica richiede coordinazione, ma ogni tanto devi lasciarti andare.","Incantesimo",[],["Piltover e Zaun"],"COMUNE"],"06PZ029":["Idolo del pubblico","Fornisci +2|+0 e Attacco rapido a un alleato per questo turno.\nFlusso: Crea un nuovo incantesimo di costo 2 nella tua mano.","","\"Più forte, Zaun!\" - Seraphine","Incantesimo",[],["Piltover e Zaun"],"COMUNE"],"06PZ020":["Ghianda, l'hexperto","Colpisci il Nexus: Riduci di 1 il costo dell'incantesimo più costoso che hai in mano.","","Il suo nome non appare nei progetti, né gli viene dato riconoscimento nelle canzoni, ma è risaputo: Ghianda era il cuore di tutta l'operazione.","Unità",[],["Piltover e Zaun"],"EPICO"],"06PZ009":["Riff caustico","Flusso: Costo 2 in meno.\nInfliggi 1 a tutti i nemici.","","Ci vuole un suono speciale per sovrastare il clamore di Zaun, ma la Diva non delude mai.","Incantesimo",[],["Piltover e Zaun"],"COMUNE"],"06PZ037":["Dissonanza violenta","Infliggi 1 a un'unità. Se hai equipaggiato un alleato in questa partita, copiami con lo stesso bersaglio.","","Se la dissonanza è la cacofonia della distruzione, non ti fermare.","Incantesimo",["CULTISTA"],["Piltover e Zaun"],"RARA"],"06PZ019":["Buttafuori zaunita","Inizio del turno: Flusso: Ripristina 2 mana incantesimo.","","Se dipendesse da lui, non entrerebbe NESSUNO.","Unità",[],["Piltover e Zaun"],"COMUNE"],"06PZ033":["Gatalyst v1.0","I tuoi incantesimi e le tue abilità infliggono 1 danno in più.","","\"Luogo: settore 3, galleria 19B\nOggetto: arma da fuoco illegale\nNote: confiscata durante l'operazione Luce del Sump. L'arma è molto pericolosa. Maneggiare con estrema cura.\"\n- Rapporto del guardiano di Piltover","Equipaggiamento",[],["Piltover e Zaun"],"COMUNE"],"06BW029":["Naufrago di Piltover","Quando vengo evocato, Improvviso.","","Pesh ha incontrato Jax in una rissa sui moli e la loro fuga tempestiva è stata frutto più della convenienza che di un'alleanza. Ma Pesh trasporta Jax da allora, perché intorno a Jax la roba si rompe e se c'è qualcosa che Pesh ama più dei rottami sono le cose da riparare.","Unità",["MAESTRO D'ARMI"],["Bilgewater","Piltover e Zaun"],"COMUNE"],"06BW034":["Metallo pesante","Distruggi l'equipaggiamento di un'unità e infliggile 2.","","\"MA COME SI FA A TIRARE UN'ANCORA IN UNA RISSA DA BAR? CHE RAZZA DI PROBLEMI AVETE?\" - Barista di Bilgewater","Incantesimo",[],["Bilgewater"],"RARA"],"06BW027":["Dalle parti al tutto","Per giocarmi, scarta 1 carta. Pesca 2 carte e, se hai scartato dell'equipaggiamento, evoca 1 Miraggio di Icathia.","","L'equipaggio di Jax è la dimostrazione che a volte il tutto è superiore alla somma delle sue parti. Certo, Pesh ha una filosofia diversa: a volte le parti non sono niente male, anche da sole.","Incantesimo",["MAESTRO D'ARMI"],["Bilgewater","Piltover e Zaun"],"RARA"],"06BW039":["Onda senza fine","Dopo che hai equipaggiato un alleato in questa partita, costo 2 in meno.\nPesca 2 carte e conferiscile Fugace.","","Il vecchio Ibaaros era lento, ma le acque che si agitavano davanti a lui avevano una velocità quasi incomprensibile.","Incantesimo",["CULTISTA"],["Bilgewater"],"RARA"],"06BW026":["Cultista Buhru","Quando gli alleati equipaggiati attaccano, infliggi 1 al Nexus nemico.","","Non importava da dove fosse venuto il potere. Alla dea non interessava. Contava solo la gloria che le avrebbe portato abbattendo i mostri.","Unità",["CULTISTA"],["Bilgewater"],"COMUNE"],"06BW014":["L'arpione Darkin","Attacca: Pesca 1 carta al prossimo Inizio del turno e conferiscile Fugace.\nPuoi spendere 9 mana per giocarmi come Ibaaros.","","\"Alla larga stai dallo stretto di Daray,\ndove le acque sussurrano e i venti tradiscono,\ndove neanche i mostri marini e gli uccelli si avventurano,\nperché temono la tenebra sotto lo stretto di Daray.\"\n- Filastrocca di Bilgewater","Equipaggiamento",["DARKIN"],["Bilgewater"],"EPICO"],"06BW004":["Prova dello spirito","Fornisci Vulnerabile a un nemico per questo turno. Se muore in questo turno, infliggi 1 al Nexus nemico.","","\"Rimarrai in piedi o ti butterai a terra?\" - Illaoi","Incantesimo",[],["Bilgewater"],"RARA"],"06BW044":["Tritonno scaltro","Colpisci il Nexus: Pesca 1 carta e conferiscile Fugace.","","\"Mostriciattoli arraffoni, ecco cosa sono. Perlomeno è facile capire quando hanno sgraffignato qualcosa.\"","Unità",["RETTILE"],["Bilgewater"],"COMUNE"],"06BW047":["Marai dispettosa","Quando giochi un incantesimo, evoca 1 Barile di polvere da sparo.","","\"Bibi è un po'... fuori controllo, sicuramente. Ma è per questo che ci piace!\" - Ai'la, guardiana Marai","Unità",[],["Bilgewater"],"RARA"],"06BW023":["Sciabola seghettata","Saccheggio: Costo 2 in meno.","","\"Come si suol dire, la sciabola è la soluzione più rapida alle risse di Bilgewater.\"\n\"Però è più veloce la pistola.\"\n\"Taci, Baz.\"\n- Baz e Gav, aspiranti cacciatori di taglie","Equipaggiamento",[],["Bilgewater"],"COMUNE"],"06BW042":["Vascello carico","Infliggi 2 a un'unità. Pesca 1 carta al prossimo Inizio del turno per ogni danno che hai inflitto e conferiscile Fugace.","","\"Rex si occuperà del boom, non ti preoccupare. Io penserò al tesoro. Mi occuperò anche della parte di Rex, altrimenti vorrà metterla tutta nel cannone e succederà il solito pasticcio.\" - Sottufficiale","Incantesimo",[],["Bilgewater"],"EPICO"],"06BW040":["Occhio solenne","Attacca: Genera 2.","","\"Ergiti saldo sotto il suo sguardo!\" - Illaoi","Equipaggiamento",[],["Bilgewater"],"RARA"],"06SH032":["Armeria sepolta","Conto alla rovescia 2: Crea 1 Tesoro delle sabbie nella tua mano.","","\"Perché tocchi sempre tutto?\"\n\"Perché, pensi ci sia una trappola? Pensi che stia per uscire un masso gigante che rotola verso di...\"\n\"CORRI!\"\n- Argus e Silvio, tombaroli","Monumento",[],["Shurima"],"COMUNE"],"06SH035":["Altare del Sangue","Quando abbatti un'unità, riduci di 1 il costo della prossima unità Darkin che giochi.","","L'altare era tornato a pulsare di vita e le sabbie che lo circondavano si agitavano a ritmo lento e costante. I discepoli di Xolaani sentivano lo stesso battito nei loro cuori. Ogni muscolo, ogni pensiero, ogni istante... tutto era sotto il suo controllo.","Monumento",[],["Shurima"],"RARA"],"06SH046":["Reliquario dell'accolito","Quando vengo evocato, crea 1 Accolito funesto nella tua mano. Quando mi distruggi, crea 1 Reliquario dell'accolito nelle prime 5 carte del tuo mazzo.","","\"Plasmiamo il deserto.\" - Accolito funesto","Monumento",[],["Shurima"],"RARA"],"06SH033":["Maledizione della tomba","Prevedi. Fornisci a un'unità \"Subisco danni doppi e se muoio annientami\" per questo turno.","","\"Solo gli stolti vogliono un potere che non possono controllare.\" - Xerath","Incantesimo",[],["Shurima"],"RARA"],"06SH028":["Portale del Vuoto","Quando evochi un alleato o un alleato muore, conferisci tutte le sue parole chiave positive a 3 alleati nel tuo mazzo.","","Il messaggero dell'alveare alzò due mani verso la colossale struttura più sopra. \"UN TRONO,\" urlò, \"DEGNO DI UN'IMPERATRICE\". Il portale del Vuoto pulsò di vita. Presto sarebbe successo.","Monumento",[],["Shurima"],"EPICO"],"06SH005":["Baccai reietto","Gioca: Prevedi. Se scegli un Darkin o dell'equipaggiamento, conferiscimi +1|+1.","","Nella mano stringeva una cintura intrecciata, un dono del suo amico Rhaast prima della loro cerimonia dell'Ascensione. Pur rispettando il potere del Darkin, nel suo cuore animale albergava un segreto risentimento nei suoi confronti.","Unità",["CULTISTA"],["Shurima"],"COMUNE"],"06SH056":["Castigo","Uccidi TUTTI i seguaci.","","A volte siamo attratti dalla luce e a volte essa viene attratta da noi.","Incantesimo",[],["Shurima"],"RARA"],"06SH040":["Resurrezione coatta","Dopo che hai equipaggiato un alleato in questa partita, costo 2 in meno. Rianima il campione alleato morto più forte.","","\"Non morirai mai, perché non te lo permetterò.\"\n- Xolaani","Incantesimo",["CULTISTA"],["Shurima"],"EPICO"],"06SH021":["Orrore mimetizzato","Gioca: Colpisco un nemico.","","L'assalto continuava e creature sempre più feroci uscivano dal cancello. La città di Belveth era perduta, ma il destino crudele fece sopravvivere il suo nome.","Unità",[],["Shurima"],"RARA"],"06SH051":["Pastorella dei rocciorsi","Quando evochi un altro alleato, fai avanzare il tuo Monumento con il Conto alla rovescia più alto di 1 turno.\nQuando vengo evocata, evoca 1 Rocciorso ibernato.","","\"I rocciodobbi trattano Sadira come una di loro. Se mi distraessi un attimo, scapperebbe con loro, quella monella!\" - Kadira, naturalista del deserto","Unità",[],["Shurima"],"RARA"],"06SH055":["Sacerdotessa della luce del deserto","Inizio del turno: Infliggimi 4. Pesca un campione e conferiscigli +2|+2 o, se il tuo mazzo è partito con 6 o più campioni diversi, evocalo.","","I fedeli attendono l'arrivo del male, usando le loro ultime forze per canalizzare la luce della giustizia. Sanno che la loro richiesta di aiuto verrà esaudita prima di essere travolti dall'oscurità.","Unità",[],["Shurima"],"EPICO"],"06SH004":["Salassatori Darkin","Ultimo respiro: Se il mio portatore non è Schiavo Darkin, evoca 1 Schiavo Darkin.\nPuoi spendere 6 mana e uccidere un alleato per giocarmi come Xolaani.","","Nel tumulto della battaglia, disperata e ferita gravemente, Jun ascoltò la voce che le sussurrava nei pensieri. \"Non morirai mai\", le disse, dolce come una pioggia estiva, \"perché non te lo permetterò.\"","Equipaggiamento",["DARKIN"],["Shurima"],"EPICO"],"06SH038":["Falcione rotante","Colpisci: Crea 1 Ritrovamento fortunato nella tua mano.","","\"Insegui ciò che vuoi, senza pietà.\" - Cavalcarovine\n","Equipaggiamento",[],["Shurima"],"COMUNE"],"06DE048":["Tassorso ostile","","","\"Qui gli amici sono i benvenuti, ma guai a chiunque entri in questo regno con la cattivera nel cuore poiché subirà la vendetta di chi lo protegge!\"","Unità",["ÉLITE"],["Demacia"],"COMUNE"],"06DE024":["Al volo!","Fornisci +1|+1 a un alleato per questo turno o equipaggialo con un equipaggiamento in mano di costo 2 o meno.","","Questa mossa fa più male se il party non ha ancora mangiato.","Incantesimo",["MAESTRO D'ARMI"],["Demacia","Freljord"],"RARA"],"06DE025":["Recluta dal cuore tenero","Quando vengo evocata, fornisci agli alleati equipaggiati Barriera per questo turno.","","\"Il ragazzo è un pericolo. Non dovevamo portarcelo a caccia, perché si riferisce ancora alla creatura come a sua sorella. È così ingenuo che mi dà il voltastomaco. Però, alla fine, mi fa pena. Se non altro, sarà una lezione importante, per lui.\" - Dal diario di Sirius Rowill, cavalier ranger zelante","Unità",[],["Demacia"],"RARA"],"06DE033":["Sopprimi e silenzia","Distruggi l'equipaggiamento di un'unità. Se è un seguace, silenzialo.","","\"L'hai voluto tu.\" - Lord Eldred, capo dei Cercatori di magia","Incantesimo",[],["Demacia"],"RARA"],"06DE039":["Ruggito di Icathia","Evoca 2 Miraggi di Icathia equipaggiati con massimo 2 equipaggiamenti dalla tua mano di costo 2 o meno.","","Jax ha trascorso innumerevoli sogni lottando al fianco dei suoi fratelli perduti. A volte vincono, a volte perdono, ma sono sempre insieme.","Incantesimo",["MAESTRO D'ARMI"],["Demacia"],"RARA"],"06DE011":["Egida Darkin","Puoi spendere 5 mana per giocarmi come Joraal.","","\"Figlio mio, ascolta. Quello scudo non va mai toccato. Tempo fa, fu donato alla nostra casata con l'ordine di proteggerlo e lasciarlo stare. È mia responsabilità, e quando morirà sarà tua. Hai capito? Non devi mai più salirci sopra. Non devi mai toccarlo.\"\n\"Ma mamma, la voce che ha dentro... urla. Sembra così triste.\"\n\"A maggior ragione, figlio mio.\"\n- Lady Fortis e suo figlio","Equipaggiamento",["DARKIN"],["Demacia"],"EPICO"],"06DE021":["Vayne","Quando vengo evocata o all'Inizio del turno: Crea 1 Capriola nella mano. Se ne hai già una copia, riducine il costo di 1.","Ti ho visto attaccare 4 volte.","\"Il nostro bersaglio un tempo era umano, quindi è più astuto di una comune bestia. Un passo falso e rischiamo di morire tutti. Non perdetevi di vista, segnalate qualsiasi dettaglio sospetto, ma soprattutto, ricordate...\"","Unità",[],["Demacia"],"Campione"],"06DE043":["Braccariete fidato","La prima volta che evochi un'unità Élite, conferiscimi +2|+2.","","\"Non sarà veloce come un'Ala d'argento, ma ti sorprenderebbe vedere quanto in fretta si muove su quelle zampette.\" - Cithria, Signora delle nuvole","Unità",["CANIDE"],["Demacia"],"COMUNE"],"06DE018":["Condanna","Se hai attaccato 2 o più volte in questo turno, costo 5 in meno.\nUn alleato colpisce un nemico.","","\"Dardi purificanti.\" - Vayne","Incantesimo",[],["Demacia"],"COMUNE"],"06DE041":["La forza dei campioni","Fornisci +4|+4 agli alleati per questo turno e prepara l'assalto.","","\"In battaglia con i cuori raggianti!\" - Lux","Incantesimo",[],["Demacia"],"EPICO"],"06DE026":["Miti di Icathia","Crea 1 Miraggio di Icathia nella tua mano che costa 0 per questo turno, oppure crea 1 Spatola d'oro nella tua mano.","","Le leggende narrano che la Spatola d'oro appartenne a una creatura marina dalla straordinaria capacità culinaria, che voleva diventare forte e senza paura come Jax.\n\nAltre leggende, più credibili, dicono che quella leggenda fu inventata da un tale cuoco che si era perso nella sua stessa salsa.","Incantesimo",[],["Demacia"],"RARA"],"06DE044":["Tauro di petricite","Non subisco danni dagli incantesimi e dalle abilità dei nemici.","","\"Niente è più forte della petricite.\" - Architetto di Durand","Unità",[],["Demacia"],"RARA"],"06DE017":["Pesci in faccia","Un alleato e un nemico si colpiscono a vicenda, o un alleato equipaggiato colpisce un nemico, poi perde l'equipaggiamento.","","\"Pesce, ti presento faccia!\" - Prodigiosa pescatrice ioniana","Incantesimo",["MAESTRO D'ARMI"],["Demacia"],"COMUNE"],"06DE040":["Prospettiva invitante","Scegli un seguace o un equipaggiamento dalle prime 4 carte del tuo mazzo. Pescalo e mescola le altre nel mazzo.","","Dolci e invitanti sussurri seminano un desiderio profondo nel cuore. Come una scheggia si infetta, generando rabbia. La rabbia lascia spazio alla trasgressione, che conduce alla morte. E il ciclo continua.","Incantesimo",["CULTISTA"],["Demacia"],"COMUNE"],"06DE028":["Arpia del malosangue","Gioca: Equipaggiami con un equipaggiamento di costo 2 o meno dalla tua mano.\nLa prima volta che morirei con dell'equipaggiamento, curami completamente e distruggi l'equipaggiamento.","","\"Kian, se stai leggendo... spero di essere morta. Non posso controllare ciò che mi sta succedendo. Il sangue sotto le mie unghie non va via. Mi prude tutto. Mi gratto senza sosta, ma non serve. Fa male. Voglio solo che finisca. Se sono ancora viva, promettimi che smetterai di cercarmi.\n\nPotrei chiedere perdono, ma non me lo merito. Fai il bravo con la mamma, va bene?\"\n- Lettera accartocciata in una sacca","Unità",[],["Demacia"],"EPICO"],"06DE027":["Cavalier ranger zelante","Attacca: Fornisci +1|+1 agli alleati equipaggiati per questo turno.","","\"Janan, giusto? Cosa mi puoi dire di Sirius?\"\n\"Oh, il cavalier ranger Rowill? Qualche anno fa gli revocarono il titolo. Pare che avesse disobbedito a tutti gli ordini. A quanto pare fa quel che vuole e non sa accettare un rifiuto.\"\n\"Ah.\"\n\"Quindi... perché gli hai permesso di unirsi a noi nella caccia?\"\n\"Non l'ho fatto.\"\n\"Allora perché... ah, già. Fantastico.\"\n- Vayne e Janan, Vedova cacciatrice","Unità",[],["Demacia"],"RARA"],"06DE019":["Vedova cacciatrice","Gioca: Equipaggiami con equipaggiamento di costo 2 o meno dalla tua mano.","","\"Anche se la donna sembra una combattente capace, il suo dolore è fresco e rischia di comprometterla. La disperazione è un ottimo motore, lo so bene, ma così, senza briglie? Forse vuole solo morire...\" - Dal diario di Sirius Rowill, cavalier ranger zelante","Unità",[],["Demacia"],"COMUNE"],"06DE032":["Acciaio di Demacia","","","La spada e lo scudo preferiti dai fratelli d'armi demaciani dotati di elmo.","Equipaggiamento",[],["Demacia"],"COMUNE"],"06DE029":["Alce determinato","La prima volta che un alleato viene equipaggiato, conferiscimi Tenacia.","","\"Indietro, vile creatura! Osa sfiorare l'immacolata pelliccia di Purezza  e ti spedirò in una VALLE DI LACRIME!\" - Sirius Rowill, cavalier ranger zelante","Unità",[],["Demacia"],"COMUNE"],"06DE010":["Cavalier ranger disertrice","Dopo che hai equipaggiato un alleato in questa partita, conferiscimi Esploratore.","","Anni passati a soffocare le sue capacità magiche hanno acceso in lei un disprezzo profondo per sé stessa, che scaricava malignamente sulle sue vittime. Dopo la sua diserzione dai cavalier ranger, la sua rabbia non aveva obiettivo, finché non ha sentito una voce nell'oscurità. Parlava di un nuovo ordine, dove avrebbe potuto dare sfogo alla sua crudeltà.","Unità",["CULTISTA"],["Demacia"],"RARA"],"06DE006":["Cuoco da combattimento","Quando vengo evocato, Improvviso, poi Forgiami.","","Dopo il periodo di servizio nell'esercito di Demacia, Breshi pensava di ritirarsi e trascorrere una vita tranquilla come cuoco in una taverna di paese. Jax ha rovinato la sua pensione dorata con una rissa da bar e un'opinione controversa sulle uova sode. Da allora, Breshi ha un nuovo scopo di vita: trasmettere il buon gusto a Jax.","Unità",["MAESTRO D'ARMI"],["Demacia","Freljord"],"COMUNE"],"06DE034":["Lupacchiotta fedele","Se un alleato è morto durante questo turno, costo 2 in meno.\nGioca: Equipaggiami con un equipaggiamento di costo 2 o meno dalla tua mano e Forgiami.","","\"Ho Maggie da quando era cucciola. Ha la sua età, ma è ancora scaltra come un tempo. Darei la mia vita per la sua e so che lei farebbe lo stesso.\" - Janan, Vedova cacciatrice","Unità",["CANIDE"],["Demacia"],"COMUNE"],"06SI045":["Fendi anime","Uccidi un alleato per evocarne 2 copie Effimere.","","Tanto non se ne facevano comunque niente.","Incantesimo",[],["Isole Ombra"],"RARA"],"06SI007":["Alabarda Darkin","Per giocarmi, uccidi un alleato.\nPuoi spendere 10 mana per giocarmi come Taarosh.","","Lottando contro i confini della sua cella, Taarosh udì la chiamata del suo generale. Avrebbe risposto, in un modo o nell'altro.","Equipaggiamento",["DARKIN"],["Isole Ombra"],"EPICO"],"06SI034":["Spettro degli echi","Fine del turno: Per ogni alleato morto in questo turno, conferisci +1|+1 a tutte le sue copie alleate ovunque.","","\"Non so quale strana magia possieda e non lo voglio sapere. So solo che, se si rialza, farà una brutta fine. Di nuovo.\" - Osservatore delle Isole","Unità",[],["Isole Ombra"],"EPICO"],"06SI029":["Lancia malefica","Se un alleato è morto durante questo turno, costo 2 in meno.","","\"Non può esserci giustizia. Solo vendetta.\" - Kalista","Equipaggiamento",[],["Isole Ombra"],"COMUNE"],"06SI032":["Quiete eterna","Uccidi un'unità con Potere e Salute totali di 4 o meno, o distruggi l'equipaggiamento di un'unità.","","Quale che sia il modo con cui la morte si manifesta nelle Isole Ombra, che sia provvidenzialmente rapida.","Incantesimo",[],["Isole Ombra"],"RARA"],"06SI031":["Lame dei caduti","Fornisci a un alleato \"Ultimo respiro: Evoca 1 Miraggio di Icathia con il mio equipaggiamento\" per questo turno.","","A volte, la cosa migliore che puoi fare per un alleato caduto è prendere la sua arma e continuare a combattere.","Incantesimo",["MAESTRO D'ARMI"],["Isole Ombra","Shurima"],"RARA"],"06SI014":["Ingresso sfarzoso","Quando vengo evocato, evoca un Banda spettrale.\nInizio del turno: se hai il Gettone d'attacco, evoca un Banda spettrale.","","\"I musicisti sono pronti, il palco è allestito e il pubblico attende. Prego, Maestro!\" - Anfitrione esuberante","Monumento",[],["Isole Ombra"],"EPICO"],"06SI038":["Prodigio redento","Attacca: Evoca 1 Banda spettrale attaccante.","","La ricerca della perfezione era rigida e limitante. La perfezione non ha vita, non respira. La perfetta imperfezione, quella sì che è una meta a cui puntare.","Unità",[],["Isole Ombra"],"RARA"],"06SI003":["Fireth, Mietitrice delle sabbie","Quando vengo evocata, Improvviso.","","Jax chiese a Fireth il suo nome almeno una ventina di volte nelle prime settimane di viaggio, ma lei rispondeva solo \"Sono la mietitrice!\". Breshi trovò una soluzione: dichiarò che avrebbe preparato una torta e che aveva bisogno del nome del membro più forte del gruppo per celebrarlo a dovere.","Unità",["MAESTRO D'ARMI"],["Isole Ombra","Shurima"],"EPICO"],"06SI006":["Custode della Scatola","Dopo che hai equipaggiato un alleato in questa partita, conferiscimi Rubavita.","","\"La Scatola non regala i suoi segreti, Shieda Kayn. Hanno un prezzo salato. Ma se hai il coraggio di scrutare l'ombra delle ombre, troverai cose incredibili e terribili.\" - Ysdra, Custode della Scatola","Unità",["CULTISTA"],["Isole Ombra"],"COMUNE"],"06SI039":["Forma della paura","Uccidi un alleato per evocare 1 Nebbia invadente.","","Solo uno sciocco resterebbe a guardare la Nebbia Oscura nella speranza di riconoscere una forma familiare.","Incantesimo",[],["Isole Ombra"],"COMUNE"],"06SI042":["Cavaliere senzamorte","Quando otterrei Effimero, conferiscimi invece +1|+1.","","I soldati che hanno imparato a resistere alle punizioni in vita sono i più diligenti e capaci nella morte. Non si fermano davanti al gelo, al dolore e alla paura.","Unità",[],["Isole Ombra"],"RARA"],"06SI036":["Devastazione totale","Uccidi TUTTE le unità tranne gli alleati Darkin e gli alleati equipaggiati.","","Quando impugnò le armi, la sua umanità lasciò il posto a un'essenza malvagia che occupò il guscio un tempo appartenuto alla studentessa Jun. La travolse, circondandola e risvegliando il Darkin dormiente.","Incantesimo",["CULTISTA"],["Isole Ombra"],"RARA"],"06SI046":["Sentinella incessante","Ultimo respiro: Pesca 1 carta.",""," \"... osservo l'eternità, perché il mio è un dovere che trascende la vita e la morte.\"","Unità",[],["Isole Ombra"],"COMUNE"],"06SI041":["Custode Valdiluna","Quando evochi un alleato Effimero, conferiscigli +1|+0.\nCrepuscolo: Evoca 1 Germoglio.","","Lontano dalle coste delle Isole Ombra ci sono i cadaveri di alberi che tutti credevano morti e immobili. I più acuti osservatori noteranno che, in quella terra baciata dalla luna, si muovono nuove vite.","Unità",[],["Isole Ombra"],"COMUNE"],"07PZ009":["Orolotto potenziato","Gioca: Prevedi, poi pesca 1 carta e riduci di 1 il suo costo.","","\"A questo piccoletto serviva solo una sistemata. Qualche ingranaggio migliorato, un braccio nuovo e si riparte. Il tempo è un dono di cui tutti dovrebbero godere un po' di più, secondo me.\" - Ekko","Unità",[],["Piltover e Zaun"],"EPICO"],"07PZ017":["Venditore di bombelampo","Quando giochi un incantesimo, piazza 1 Trappola Bombalampo tra le prime 8 carte del mazzo nemico.","","\"... Sai anche perché queste sono meglio dei funghi? Perché decidi tu quando esplodono! Eh, che ne pensi?\"","Unità",[],["Piltover e Zaun"],"RARA"],"07PZ005":["Contraccolpo","Infliggi 1 a un nemico e al Nexus nemico. Scarta fino a 2 carte per aumentare di 1 i danni per ciascuna carta scartata.",""," \"OK, OK, magari funzionerà una volta sola, ma credimi: sarà uno spasso!\" - Jinx","Incantesimo",[],["Piltover e Zaun"],"RARA"],"07NX009":["Colpo stiloso","Infliggi 1 al Nexus nemico. La prossima volta che un alleato colpisce il Nexus in questo turno, crea 1 Colpo stiloso nella tua mano.","","\"Nessuno sarebbe alla mia altezza nemmeno se fossi armata solo di sassi e bastoni. Ma con le mie armi non lascio alcuna speranza.\" - Samira","Incantesimo",[],["Noxus"],"EPICO"],"07NX008":["Lama elegante","Saccheggio: Conferiscimi +2|+0.","","\"Costo molto e non lavoro per chiunque. Chi è abbastanza fortunato da riuscire a ingaggiarmi ottiene eleganza e lame che non mancano mai il bersaglio. Ma più di tutto, stile. Cosa c'è di meglio che uccidere in modo teatrale?\"","Unità",[],["Noxus"],"COMUNE"],"07NX014":["Piroetta","Saccheggio: Costo 2 in meno.\nInfliggi 1 a un bersaglio e stordisci un nemico.","","\"Cosa? Mi stavo solo scaldando. Non dirmi che sei già morto!\" - Lama elegante","Incantesimo",[],["Noxus"],"RARA"],"07NX007":["Samira","Saccheggio o colpisci: Crea 1 Dono naturale nella tua mano, se non è già presente.","Ti ho visto giocare 6 carte. Si azzera quando inizi il turno con il gettone d'attacco.","\"La mia taglia è di solito qualcuno che si è fatto dei debiti che non può pagare. E una cosa del genere ti crea i nemici peggiori... quelli che chiamano me.\"","Unità",[],["Noxus"],"Campione"],"07NX006":["Dandy affascinante","Saccheggio: Raddoppia il mio Potere.",""," \"Senti, in genere mi piace fissare delle regole, tipo giù le zampe, ma chi voglio prendere in giro? Non riuscirai neanche a sfiorarmi.\"","Unità",[],["Noxus"],"COMUNE"],"07NX015":["Dame, la saccheggiatrice","Saccheggio: Conferisci +1|+0 agli alleati.","","\"Ah, Dame. Ha uno stile molto melodrammatico. Alcuni potrebbero storcere il naso ma, quando è nel suo elemento, ci guadagniamo tutti.\" - Lama elegante","Unità",[],["Noxus"],"COMUNE"],"07NX003":["Al massimo","Fornisci +2|+0 a un alleato per questo turno.\nSaccheggio: Fornisci invece +2|+1.",""," \"Indari si è impegnata per farci entrare senza grossi problemi. Spero di crearne qualcuno per uscire.\" - Samira","Incantesimo",[],["Noxus"],"COMUNE"],"07NX004":["Abile artigiana","Quando vengo evocata attivo l'effetto Saccheggio di tutti gli alleati.","","\"In alcuni posti non è facile mettersi in affari, ma i soldi hanno iniziato a piovere una volta vista la merce mia e di Lani. Stasera non ho visto i nostri bersagli ma in tanti avevano intenzioni violente. Dopotutto, capire chi vuole uccidere chi è un ottimo modo per ambientarsi.\" - Miel","Unità",[],["Noxus"],"RARA"],"07NX001":["Demolitrice audace","Gioca: Infliggi 1 al Nexus nemico o attiva Saccheggio di un alleato.","","\"Commerciare in armi significa conoscere bene i dati. Crea, testa, ricostruisci, modifica: per farlo servono informazioni. Per un buon prototipo servono prove sul campo, e qualche cratere!\" - Lani","Unità",[],["Noxus"],"RARA"],"07NX005":["Capitano Indari","Quando vengo evocato, Improvviso.\nSaccheggio: Forgia altri alleati.","","\"Ho lavorato con molti agenti in passato. Alcuni erano docili, altri ostici... e poi c'è Samira. Mi sono arreso al fatto che non posso gestirla. Mi limito a dirigere la baraonda, a direzionarla... e ogni tanto mi unisco anch'io.\"","Unità",["MAESTRO D'ARMI"],["Noxus"],"RARA"],"07BW018":["Babs la matta","Quando ripristini mana, conferiscimi +1|+0 per ogni mana ripristinato.","","\"Caro Jack, guarda qua! C'è qualcosa che ti interessa, vero?\"","Unità",[],["Bilgewater"],"COMUNE"],"07BW021":["Audace piratessa","Saccheggio: Evoca un seguace casuale di costo 1 da qualunque regione e conferiscigli Insolente.","","\"Starei alla larga da lei, se fossi in te. Ha la pessima abitudine di coinvolgere gli altri nei suoi problemi.\" - Samira","Unità",[],["Bilgewater"],"COMUNE"],"07BW002":["Jack","Colpisci: Crea 1 Moneta nella tua mano.\nQuando ripristini mana, curami di 1 per ogni mana ripristinato.","Hai speso 12+ mana in un turno.","\"Per affrontarmi devi essere davvero coraggioso, o sciocco. In entrambi i casi, il risultato non cambia. Ti consiglio di pensare a come uscirne vivo.\"","Unità",[],["Bilgewater"],"Campione"],"07BW040":["Nukkle","Quando vengo evocato, crea 1 Mako Fugace nella tua mano.","","\"Una tacca qui, un taglio lì, tanto per divertirsi. Perdere un po' di sangue non ha mai fatto male a nessuno. Be', almeno non a me.\" - Nukkle","Unità",[],["Bilgewater"],"RARA"],"07BW001":["Buttadentro infido","Quando ripristini mana, crea un seguace casuale Fugace nella tua mano di costo pari a quanto puoi permetterti.","","\"Se vuoi il cremisi, allora cerca Jack. Se vuoi sapere dove, quando, chi e quanto... allora parla con me.\"","Unità",[],["Bilgewater"],"RARA"],"07BW003":["Borseggiatore","Ultimo respiro: Crea 1 Moneta nella tua mano.","","\"Torna qui, maledetto! Sono i miei soldi, quelli!\" - Angel","Unità",[],["Bilgewater"],"COMUNE"],"07BW014":["Pablo Cinquepugni","Quando vengo evocato, crea 1 Scontro a premi Fugace nella tua mano.","","\"Così si fa, Jackie! Continua a sfoggiare il fascino tipico di Bilgewater, e io continuerò a farti combattere. Aaah, mi tornano in mente i tempi d'oro, quando mi chiamavano 'Pablo lo Stupendo'... Non ci credi? È vero! Quella botta in testa deve averti causato qualche problema alla memoria.\" - Pablo Cinquepugni","Unità",[],["Bilgewater"],"COMUNE"],"07BW013":["Angel","Saccheggio: Crea 3 Monete nella tua mano.","","\"Non sai fare di meglio? Bene. Ora tocca a me.\"","Unità",[],["Bilgewater"],"COMUNE"],"07BW006":["Impresa rischiosa","Infliggi 3 a un'unità. Se muore, crea 2 Monete nella tua mano.","","\"Chi non rischia non ottiene nulla - e io sono nato per rischiare.\" - Jack","Incantesimo",[],["Bilgewater"],"EPICO"],"07BW026":["Catena uncinata","Saccheggio: Costo 2 in meno.\nPesca 2 carte al prossimo Inizio del turno e conferisci loro Fugace.","","Quando ne senti il rumore è già troppo tardi per fuggire.","Incantesimo",[],["Bilgewater"],"RARA"],"07BW027":["Padre Furia","Saccheggio: Ripristina 1 mana incantesimo e crea un incantesimo casuale di costo 1 delle tue regioni nella mano.","","Le origini di Padre Furia sono nebulose e, anche dopo una domanda diretta, nessuno ha mai ricevuto una risposta chiara a riguardo o, almeno, nessuno è mai riuscito a sentire qualcosa tra il frastuono causato dalla sua forza distruttiva.","Unità",[],["Bilgewater"],"RARA"],"07BW008":["Scontro a premi","Un alleato e un nemico si colpiscono a vicenda. Non possono scendere sotto 1 di Salute dopo questo colpo.","","A volte si tratta di monete e cherosene, altre di botte da orbi. È così che funziona, ma è pur sempre uno scambio equo! È così che si fanno gli affari!","Incantesimo",[],["Bilgewater"],"COMUNE"],"07BW041":["Cirripugni","Colpisci: Crea 1 Moneta nella tua mano.","","\"Uhm, hai ragione, capisco che non è il massimo. Ma provaci, vedrai che ti piacerà.\" - Bull","Equipaggiamento",[],["Bilgewater"],"RARA"],"07BW004":["La corte del Re","Quando vengo evocato, pesca 1 Jack.\nQuando evochi un alleato, crea 1 Scontro a premi Fugace nella tua mano.\nQuando un alleato sopravvive ai danni, conferiscigli Insolente.","","Il vascello di Jack ha portato lui e i suoi per le acque di Runeterra, da Bilgewater a Ionia. Nessuno sa come faccia a muoversi sott'acqua senza affondare, ma si dice che il vero pericolo si trovi sotto la superficie...","Unità",[],["Bilgewater"],"EPICO"],"07BW025":["Inferna","Quando attivi Saccheggio, pesca 1 carta e rendila Fugace.","","\"Essere piromani in mare offre alcuni vantaggi. L'acqua tiene sotto controllo le fiamme e non ti chiede mai una parte.\"","Unità",[],["Bilgewater"],"RARA"],"07IO020":["Diamoci il cambio!","Richiama un alleato e crea 1 Moneta nella tua mano, o spendi 5 mana per richiamare un nemico e crea 1 Moneta nella tua mano.","","\"Entro solo a due condizioni. La prima, se il tuo avversario si sta divertendo a distruggerti. La seconda, se sei tu a divertirti troppo: voglio anche io la mia parte!\" - Professionista dell'arena","Incantesimo",[],["Ionia"],"RARA"],"07IO014":["Mastro Bingwen, il Vaglio","Gioca: La prossima volta che giochi un'unità in questo turno, evocane una copia Effimera esatta.","","Un tempo Bingwen il pennuto era un lottatore. Lo chiamavano così perché era agile e assumeva una posizione di combattimento simile a una gru. Da quando si è ritirato è diventato un allenatore, e usa occhio attento e mano ferma per individuare i migliori talenti.","Unità",[],["Ionia"],"EPICO"],"07IO023":["Il Vecchiardo","Gioca: Richiama il nemico più forte. Se hai speso 16+ mana in questo turno, Richiama tutti i nemici.","","\"Non mi tolgo la maschera, ragazza. E se non vuoi vedere rovinato quel tuo bel faccino, non chiedermelo più.\"","Unità",[],["Ionia"],"RARA"],"07IO011":["Sett","La prima volta che scendo sotto 1 di Salute quando attacco, forniscimi invece Barriera.","Hai speso 40+ mana.","Crogiolandosi tra le acclamazioni della folla accalcata nella sua esclusiva arena sotterranea, Sett si concede un raro momento di introspezione. Ricorda tutto quello per cui ha combattuto e immagina cos'altro potrebbe aspettarlo. Ha solo una certezza: è bello essere il boss.","Unità",[],["Ionia"],"Campione"],"07IO046":["Alalucente reale","Gli altri alleati Volatile hanno +1|+0 e Attacco rapido.","","\"Ormai ho appurato che in questa giungla gli esemplari più affascinanti sono anche i predatori più letali.\" - Anura","Unità",["VOLATILE"],["Ionia"],"RARA"],"07IO009":["Contabile affidabile","Colpisci il Nexus: Crea 1 Moneta nella tua mano.","","In un mondo di persone infide ed egoiste, Lise possiede la qualità più apprezzata da Sett: è affidabile. Non delude mai e non gli ha mai dato motivo di preoccuparsi. Per questo Lise ha il suo supporto e chiunque voglia creare problemi deve sapere che scommettere contro il Banco significa perdere.","Unità",[],["Ionia"],"RARA"],"07IO019":["Barista affascinante","Gioca: Cura un alleato o il tuo Nexus di 3 e crea 1 Moneta nella tua mano.","","\"Il primo giro è di benvenuto, il secondo è per farli ambientare. I problemi arrivano con il terzo, e dal quarto in poi sono a ruota libera: ne sento davvero di tutti i colori!\"","Unità",[],["Ionia"],"COMUNE"],"07IO017":["Scommesse","Pesca 2 carte e crea 2 Monete nella tua mano.",""," \"Ci danno molti soldi e noi diamo loro una possibilità. Eh eh eh... e c'è ancora chi si chiede perché il Banco vince sempre.\"","Incantesimo",[],["Ionia"],"COMUNE"],"07IO047":["Cobra incantatore","Ogni turno, la prima volta che giochi un seguace, evoca una sua copia esatta. Se la tua plancia è piena, conferisci invece a me le sue statistiche e le sue parole chiave.","","\"Pensi che questi fiori valgano qualcosa? Tra l'altro, non darmi del pazzo, ma non ti sembra che stiano... ballando?\" - Bracconiere piltoveriano","Unità",["RETTILE"],["Ionia"],"EPICO"],"07IO013":["Professionista dell'arena","Quando vengo evocata, crea 1 Moneta nella tua mano.","","\"Alcuni lo fanno per soldi, altri per il sangue, altri ancora per il boato del pubblico. Io? Non riesco a scegliere. Voglio tutto, e qui ho tutto a palate.\"","Unità",[],["Ionia"],"COMUNE"],"07IO012":["Servizio di sicurezza","Quando vengo evocato, crea 1 Servizio di sicurezza Fugace nella tua mano e conferisci +1|+1 a ogni altro Servizio di sicurezza.\nVigore 5: Attacco rapido.","","\"Se pensano che tu non valga nulla, lasciaglielo credere. Che le mele marce si sentano al sicuro con i loro giochetti! Non c'è niente di meglio che vedere l'espressione dei loro occhi quando capiscono di averti sottovalutato.\" - Sett","Unità",[],["Ionia"],"RARA"],"07IO007":["Faccia sfasciata","Stordisci 2 nemici e crea 1 Moneta nella tua mano.","","\"Cosa? Ha detto che avrebbe affrontato la situazione a testa alta! Non è colpa mia se in alto c'era il mio pugno!\" - Sett","Incantesimo",[],["Ionia"],"COMUNE"],"07SH023":["Generale delle sabbie caduto","Ho +1|+0 per ogni alleato Effimero che hai evocato in questa partita.","","\"Anche se non sei che un granello di sabbia per questo avversario, ti vedo. Avverto la tua presenza tra le dune. Concedimi la tua forza e insieme abbatteremo i nostri nemici!\"","Unità",[],["Shurima"],"RARA"],"07SH018":["Custode di segreti","Quando vengo evocato, crea nel fondo del tuo mazzo due campioni casuali di livello 2 che non sono nella tua mano, nel mazzo o in gioco.","","Non ha compreso del tutto quel che ha visto, quale potrebbe essere la natura della calamità o quando potrebbe colpire... ma conosce questo mondo e la sua gente. Non sono pronti e potrebbero non esserlo mai.","Unità",[],["Shurima"],"EPICO"],"07SH008":["Attacco in branco","Inizia un attacco gratuito con una copia esatta Effimera di ciascun alleato Felino.","","Una cacciatrice solitaria è già abbastanza spaventosa... ma un branco è davvero terribile.","Incantesimo",[],["Shurima"],"COMUNE"],"07FR008":["Cucciolo Pelogelo","Spendi 6 mana per giocarmi invece come Madre Pelogelo.","","Il Freljord è pieno di pericoli, specialmente per quelli che ancora non ne conoscono la gelida essenza.","Unità",["CANIDE"],["Freljord"],"COMUNE"],"07FR009":["Fabbro innovativo","Quando vengo evocato, Improvviso.\nOgni turno, la prima volta che Forgi o Equipaggi un alleato, cura il tuo Nexus di 1.","","\"Quella pallina di pelo non mi farà lavorare più veloce, ma riesce sempre a farmi sorridere. È più che sufficiente per aiutarmi.\" - Fabbro innovativo","Unità",["MAESTRO D'ARMI"],["Freljord"],"RARA"],"07FR005":["Schiavo Impervio","Non subisco danni dagli incantesimi e dalle abilità degli alleati.","","\"Non si può fermare una valanga.\" - Lissandra","Unità",[],["Freljord"],"RARA"],"07SI002":["Raccolto d'anime","Uccidi un seguace con 3 o meno Potere, o spendi 3 mana per uccidere un campione con 3 o meno Potere.","","Si tratta solo di un sussurro, a malapena udito ma dall'effetto inequivocabile, che scambia una vita per l'altra.","Incantesimo",[],["Isole Ombra"],"RARA"],"07SI001":["Annichilimento","Uccidi TUTTE le unità con 3 o meno Potere.","","Chiunque posi il suo sguardo su di me conoscerà il tocco dell'oblio, per l'eternità.","Incantesimo",[],["Isole Ombra"],"EPICO"],"07SI007":["Compagno funereo","La prima volta che un altro alleato muore in un turno, pesca 1 carta.","","\"Gli ho appena insegnato un giochetto nuovo! Vuoi vederlo?\" - Burlona fantasma","Unità",["CANIDE"],["Isole Ombra"],"COMUNE"],"07MT003":["Cucciolo cosmico","Inizio del turno: Cura me e il tuo Nexus di 1.","","Corrono sul cielo come lacrime di un'aurora. Il loro bagliore dona calma, lenisce le ferite e allevia le sofferenze.","Unità",[],["Targon"],"RARA"],"07MT001":["Stella cadente","Infliggi 4 a un nemico che ha attaccato in questo turno o che è stordito.","","Le stelle osservano come ci comportiamo. I giusti vengono elevati, i malvagi puniti.","Incantesimo",[],["Targon"],"COMUNE"],"07MT007":["Studioso sacrificale","Ultimo respiro: Crea nella tua mano una copia dei primi 3 incantesimi che hai giocato su di me.","","\"Camphor ha preso troppo a troppi. Quando giungerà la tua ora, fa' in modo di andartene alle tue condizioni. Non darle soddisfazione.\" - Pantheon","Unità",[],["Targon"],"EPICO"],"07BC005":["Spadaccina scolpita","","","\"Ah, questa è nuova.\" - Spadaccina agguerrita","Unità",["FATATO"],["Bandle City"],"COMUNE"],"07BC009":["Lancio del tortino","Infliggi 1 a un'unità. Crea 1 Tortino pericoloso nella tua mano.","","Preparatevi!","Incantesimo",[],["Bandle City"],"RARA"],"07BC015":["Condensare","Scegli un seguace. Creane una copia di costo 1 nella tua mano e imposta le sue statistiche a 1|1.","","\"Mmh... Allora non sempre le cose piccole sono carine!\" - Lulu","Incantesimo",[],["Bandle City"],"RARA"],"07DE002":["Mandato di perquisizione","Un alleato con 4+ Potere cattura un'unità, o un alleato cattura un Monumento.","","\"Non muoverti e non parlare. Qualsiasi tipo di resistenza sarebbe imprudente.\" - Ispettore dei Cercatori di magia","Incantesimo",[],["Demacia"],"RARA"],"07DE005":["In formazione!","Fornisci +2|+2 a un alleato per questo turno.","","\"Forza! Ci pieghiamo ma non ci spezziamo!\" - Indomita Avanguardia","Incantesimo",[],["Demacia"],"COMUNE"],"07DE008":["Altare dell'unità","Quando vengo evocato, pesca un'unità.\nQuando evochi un alleato, rendi le sue statistiche uguali al suo costo.","","La prima volta che vide l'Altare, Cithria rimase senza parole. Per un po' poté solo restare a bocca aperta davanti alla maestosità di quei gloriosi eroi. Sarebbe mai stata in grado di ergersi al loro fianco?","Monumento",[],["Demacia"],"RARA"],"07PZ019":["Brucomobile Chemtech","Ho +1|+0 per ogni alleato di costo 1 che hai evocato in questa partita.","","\"Devo fare al cavallo UN SACCO di gambe, Signor Lucertola, perché dobbiamo arrivare SUBITISSIMO al castello. Uh oh, è uscito un po'... appiccicoso. E un po' verde.\" - La piccola Ingvar","Unità",[],["Piltover e Zaun"],"RARA"],"07PZ021":["Anura e Froop","Gli alleati che hanno un sottotipo diverso rispetto ad altri alleati in gioco costano 1 in meno.","","\"Non voglio farti del male, amica mia! Sono in questa giungla per la scienza, non per distruggere.\"","Unità",["RETTILE"],["Piltover e Zaun"],"EPICO"],"07PZ022":["Soffio divino","Infliggi 1 a un nemico o al Nexus nemico e 1 a un altro.","","Alla gran parte degli abitanti di Piltover non importa come soffia il vento. Ma per molti zauniti, anche una brezza vagante significa salvezza.","Incantesimo",["ELEMENTALE"],["Piltover e Zaun"],"COMUNE"],"07PZ013":["Monumento del Sump","Se il tuo Nexus sta per subire danni non da Scoppiettino velenoso, il tuo avversario piazza invece 5 Scoppiettini velenosi nel tuo mazzo per ogni danno.","","Nelle profondità sotto le strade di Zaun, sei quello che mangi.","Monumento",[],["Piltover e Zaun"],"EPICO"],"07PZ015":["Aggeggioide epico","Per giocarmi, spendi tutto il tuo mana. Evoca 1 Aggeggioide fuori controllo e aumentane le statistiche fino alla quantità di mana speso.","","\"La responsabilità principale di uno scienziato è tenere sotto controllo le variabili. In un campo di studi come il nostro, le conseguenze di un incidente possono essere... oh, mi vengono i brividi al sol pensiero!\" - Professor Heimerdinger","Incantesimo",[],["Piltover e Zaun"],"COMUNE"],"07NX028":["Capitano Kalrix","Colpisci il Nexus: Infliggi danni al Nexus nemico pari alla metà della sua Salute (arrotondando per eccesso).","","Noxus è un impero progettato per puntare all'espansione. Legno, pietra o acciaio... nulla può fermare l'avanzata di un ariete d'assedio noxiano.","Unità",[],["Noxus"],"EPICO"],"07NX034":["Sala dei banchetti cremisi","Gli alleati costano 1 in meno. Quando giochi un alleato, gli infliggi 2 danni.","","\"Venite amici, sedete! La compagnia è piacevole e si beve in abbondanza. Non vedo l'ora di mostrarvi cosa c'è per cena.\" - Vladimir","Monumento",[],["Noxus"],"EPICO"],"07NX032":["Tomo Figli dei corvi","Quando il mio portatore usa un'abilità, copiala.","","Il Conservatorio Ravenbloom era particolarmente rinomato per la sua collezione di testi, molti dei quali sono finiti per diventare il combustibile dell'incendio appiccato da un'allieva particolarmente difficile...","Equipaggiamento",[],["Noxus"],"RARA"],"07NX033":["Tricodale ossuto","Quando vengo evocato, conferiscimi +1|+1 per ogni altro diverso sottotipo che hanno gli altri alleati.","","\"Attenti, idioti! I noxiani comprano solo bestie da combattimento in perfette condizioni. Basta un graffio e sarete voi a pagare!\" - Magnate della caccia grossa","Unità",["FELINO"],["Noxus"],"COMUNE"],"07RU015":["Re dei Poro","Origine: Decreto del Re dei Poro.\nOgni turno, la prima volta che evochi un altro Poro, crea 1 Poro-Snax nella tua mano.","Hai evocato 6+ altri nuovi Poro. Quando aumento di livello, crea uno Snax speciale casuale nella tua mano.","Ingvar riconosce il potenziale quando lo vede. Al di là dell'aspetto casereccio, è così adorabile che potrebbe dominare qualche trilione di Poro... con la giusta dose di immaginazione. ","Unità",["PORO"],["Runeterra"],"Campione"],"07RU012":["Neeko","Origine: Amici della giungla multiforma!\nGioca: Puoi camuffarmi come 1 di 3 seguaci di costo 2 dalla mia Origine.","Attacca: Hai attaccato con alleati che hanno 6+ sottotipi diversi.","Neeko può assumere molte forme, ma il suo cuore non cambia mai: la riporta sempre alla sua famiglia e alla sua foresta.","Unità",["MUTAFORMA"],["Runeterra"],"Campione"],"07BW043":["Invocazione delle maree","Infliggi 1 a un'unità. Generi 1 per ogni danno che hai inflitto.","","Solo i più eruditi riescono a dominare gli elementi.","Incantesimo",["ELEMENTALE"],["Bilgewater"],"RARA"],"07BW035":["La tana del truffatore","Le tue carte in mano hanno Fugace.\nQuando giochi una carta, pesca 1 carta.","","\"Tieniti stretta la tua mano, o preparati a perdere tutto.\" - Twisted Fate","Monumento",[],["Bilgewater"],"EPICO"],"07BW042":["Cacciatore di bordo","Gioca: Manifesta un seguace con un sottotipo diverso rispetto agli alleati in gioco.","","\"C'è un motivo per il quale ci teniamo questo tipetto: sono anni che non si vedono più in giro i ratti del pontile!\" - Mozzo della Via del dolore","Unità",["FELINO"],["Bilgewater"],"COMUNE"],"07BW039":["Grinzo Principe Drago","La prima volta in ogni turno in cui evochi un alleato di costo 1, ripristini 1 mana incantesimo.","","\"Signor Lucertola, che ci fai qui? Anche a te piacciono i Poro?\" - La piccola Ingvar","Unità",["DRAGO"],["Bilgewater"],"RARA"],"07BW033":["Canto della sirena","Evoca un Succubo casuale.\nConferisci +1|+1 agli alleati di costo 1 ovunque.","","Alcuni marinai di Bilgewater si mettono del cotone nelle orecchie nelle notti in mare più tranquille. Sanno bene che la musica che proviene dalle onde non è che l'anticamera di una tomba sommersa.","Incantesimo",[],["Bilgewater"],"COMUNE"],"07IO041":["Brezza rinvigorente","Cura di 3 il tuo Nexus e pesca 2 incantesimi.","","\"Il vento è l'unico alleato del viandante.\" - Yasuo","Incantesimo",["ELEMENTALE"],["Ionia"],"COMUNE"],"07IO043":["Oracolo onniveggente","Gioca: Scegli 1 di 3 incantesimi Veloci o Lenti nella mano o nel mazzo dell'avversario. Crea 1 Incisioni divinatorie per esso.","","L'occhio libero dal mondo materiale vede tutto. Per quanto sembri cieco, coloro che prendono l'oracolo per un bersaglio facile vengono puniti rapidamente e senza pietà.","Unità",[],["Ionia"],"RARA"],"07IO049":["Airis","Colpisci il Nexus: Evoca un Succubo casuale.","","\"Silenzio, ci siamo quasi. Volevi conoscere la mia amica, no? Le piacerai, fidati.\"","Unità",[],["Ionia"],"RARA"],"07SH038":["Cucciolo di Pakaa","Imboscata 1\nColpisci il Nexus: Evoca 1 Pakaa protettore.","","La dolcezza è un'apparenza, ma la ferocia è un istinto. Con il tempo e il giusto insegnamento, anche il più piccolo pakiti diventa forte e selvaggio.","Unità",["FELINO"],["Shurima"],"COMUNE"],"07SH041":["Controllo nei cespugli","Manifesta una carta con Imboscata.","","Andare in ricognizione nella giungla è l'incarico meno auspicabile per un motivo in particolare: è piena di sorprese.","Incantesimo",[],["Shurima"],"RARA"],"07SH004":["A caccia","Fornisci +2|+0 a un alleato per questo turno. Se è Ombra tra i cespugli, forniscigli invece +2|+2.","","\"Cammina piano, pakiti. Colpisci senza paura.\" - Nidalee","Incantesimo",[],["Shurima"],"COMUNE"],"07SH013":["Nidalee","Imboscata 2","Ti ho visto evocare o trasformare altri 4 alleati.","\"Ti proteggerò sempre, lucertolina. Gliela faremo pagare a quei bracconieri. Insieme.\" - Nidalee","Unità",["FELINO"],["Shurima"],"Campione"],"07SH009":["Vendetta Vastaya","Imboscata 3\nQuando mi trasformo da Imboscata della Vendetta Vastaya, ferma tutti gli incantesimi Veloci, Lenti e le abilità del nemico.","","\"Non abbiate paura, piccolini. Vi proteggerò... e mi sdebiterò con Nidalee.\"","Unità",[],["Shurima"],"COMUNE"],"07SH039":["Soldato multiterreno","Imboscata 0\nQuando vengo evocato o mi trasformo, conferisci Vulnerabile al nemico più debole.","","\"Questa meraviglia qui può trasformare anche un novellino in un professionista arrampicatore di alberi e saltamacigni. Mi costa una fortuna, ma sono convinto riuscirò a rimborsare quei prestiti con un paio di pelli di bestie rare...\"","Unità",[],["Shurima"],"RARA"],"07SH044":["Aurora Hallunatis","Imboscata 4\nQuando mi trasformo, evoca 1 Aurora Hallunatis.","","\"Quanto vorrei vederne una con i miei occhi! La maggior parte egli esploratori crede che l'Aurora Hallunatis sia solo un mito, ma un giovane giura il contrario. Mi ha detto che il volatile ha dei colori brillanti e un'apertura alare grande come l'altezza di un uomo. Una notte mi ha confidato che guardarla negli occhi significa comprendere di essere una preda.\" - Dal diario di Anura, giorno 21","Unità",["VOLATILE"],["Shurima"],"RARA"],"07SH003":["Bracconiere volante","Imboscata 3\nQuando mi trasformo da Imboscata del Bracconiere volante, la prossima volta che blocco o sono bloccato in questo turno, cattura il mio nemico.","","\"Ah! Provateci, bestiacce. Neanche la gravità può sconfiggere le specie superiori!\"","Unità",[],["Shurima"],"EPICO"],"07SH011":["Trappola dannosa","Quando vengo evocata o la prima volta che un alleato si trasforma ogni turno, conferisci Vulnerabile al nemico più debole.","","\"Sangue nel vento.\" - Nidalee","Monumento",[],["Shurima"],"COMUNE"],"07SH046":["Valle delle imitazioni","Quando giochi un seguace, trasformami in una sua copia esatta per questo turno.","","\"Ed ecco la fermata più amata e PIÙ BEEELLA del tour. Il mio tour è piaciuto a talmente tante persone che hanno creato un GRAAANDE E FORTE CHIP, che sarà una tappa fissa. Diciamo tutti \"CIAO GRANDE CHIP!\" Grande Chip vuole bene a TUTTI, specialmente a quelli che fanno il suo tour.\" - Avventure con Chip, parte 6","Monumento",[],["Shurima"],"COMUNE"],"07SH043":["Doppiofante torreggiante","Imboscata 5","","Alcuni dicono che i doppiofanti, in quanto abitanti più antichi della giungla, ne conservino il cuore e la memoria. Solitamente sono creature gentili, ma non esiteranno a difendere la loro casa da qualunque minaccia... grande o piccola che sia. ","Unità",[],["Shurima"],"EPICO"],"07SH040":["Spinato","La prima volta che un alleato si trasforma, conferiscimi +2|+1.","","\"Piccoli mammiferi onnivori ricoperti da spine setolose, che possono scagliare ad alta velocità quando vengono disturbati. La coda è tagliente e rapida, utilizzata spesso come arma di difesa. Secondo gli esploratori esperti, queste creature sono notoriamente irritabili e difficili da gestire...\" - Dal diario di Anura, giorno 3","Unità",[],["Shurima"],"RARA"],"07SH005":["Magnate della caccia grossa","Gioca: Manifesta una carta con Imboscata.\nQuando un alleato si trasforma, raddoppiane Potere e Salute.","","\"Avete perso tutto con CHI? Uno scienziato e un rettile schifoso? A cosa servite, buffoni? Andate a riprendere i miei soldi!\"","Unità",[],["Shurima"],"RARA"],"07FR011":["Tempio al Vero Ghiaccio","Quando evochi un alleato, la sua Salute cresce fino a eguagliare il suo Potere.","","Anche se lo scopo di questo tempio è ormai perduto nel tempo, il suo guardiano di pietra resiste ancora, sopravvissuto al peso di tante valanghe. Ricoperto di brina, sembra essere permeato da una luce strana e attraente...","Monumento",[],["Freljord"],"EPICO"],"07FR010":["Lamartiglio delle nevi","Saccheggio: Fai crescere le statistiche di un alleato fino a raggiungere le mie.","","Anche se il lamartiglio delle nevi caccia principalmente piccoli mammiferi, questa belva del Freljord ha abbastanza artigli da poter trasformare praticamente tutto in un pasto.","Unità",["VOLATILE"],["Freljord"],"COMUNE"],"07FR015":["La piccola Ingvar","Gioca: Scegli un alleato. Conferisci +1|+1 a lui e a tutti gli altri alleati che condividono uno stesso sottotipo o Manifesta un seguace che condivide un sottotipo con lui.","","Autonominatasi supervisore dei Poro ed esploratrice del Freljord, Ingvar è certa che l'avventura la attende... ed è pronta a trovarla. ","Unità",[],["Freljord"],"EPICO"],"07FR017":["Predatore della tempesta cristallino","Gioca: Infliggi 2 a TUTTE le altre unità.","","La violenza del predatore della tempesta cristallino è immediata e indiscriminata, in grado di cambiare le sorti della battaglia in un istante. Molti ritengono che l'uccello sia il primo segno di una grande e terribile tempesta, in grado di cambiare il mondo.","Unità",["VOLATILE"],["Freljord"],"RARA"],"07FR016":["Sauriano glaciale","Quando vengo evocato, conferisci +1|+1 alle prime 3 unità nel tuo mazzo. Se un alleato ha un sottotipo diverso dal mio, pesca 1 di quelle unità.","","Con un aspetto ossuto che cela un grande cuore, questi affidabili destrieri sono fondamentali per liberare i ghiacciati passi montani.","Unità",["RETTILE"],["Freljord"],"RARA"],"07SI010":["Aracnide necrotico","Quando vengo evocato, evoca 2 Nidiacei necrotici.\nQuando un altro alleato muore, assorbi 1 dal Nexus nemico.","","Questi ragni, che si trovano solo nei recessi più bui delle Isole Ombra, secernono un letale necroveleno che intorpidisce la pelle mentre inizia a imputridire la carne.","Unità",["RAGNO"],["Isole Ombra"],"EPICO"],"07SI012":["Embiottero ciuffato","Gioca: Se un alleato ha un sottotipo diverso dal mio, fornisci -2|-0 a un nemico in questo turno.","","Gli embiotteri ciuffati realizzano con cura i loro nidi. Sono particolarmente affettuosi con le loro larve... ma spietati quando si tratta di affrontare potenziali minacce.","Unità",["RAGNO"],["Isole Ombra"],"COMUNE"],"07SI013":["Spettro oscuro infestante","Ultimo respiro: Crea una copia esatta del tuo Spettro oscuro infestante più forte nel mazzo, poi raddoppia le statistiche di Spettri oscuri infestanti nel mazzo.","","\"Questa Nebbia mi ha insegnato molte cose. La cosa più importante è quando scappare.\" - Sentinella di Ixtal","Unità",[],["Isole Ombra"],"RARA"],"07SI004":["Forbici sacre","Attacca: Quando un altro alleato ottiene Potere da Consacrazione, lo ottiene anche il mio portatore.","","\"Con un buon paio di forbici e un filo di qualità, si può sistemare praticamente tutto!\" - Gwen","Equipaggiamento",[],["Isole Ombra"],"RARA"],"07MT009":["Era dei Draghi","Pesca tutti i Draghi presenti nelle prime 9 carte del tuo mazzo e riduci il loro costo a 0 in questo turno, poi rimescola il resto delle carte nel tuo mazzo.","","\"Conoscere un drago significa dominare se stessi. Conoscerne molti significa dominare il mondo.\" - Fedele dei draghi Ottrani","Incantesimo",[],["Targon"],"RARA"],"07MT013":["Chiamata cosmica","Invoca un Celestiale dal costo di 7 o più, o paga 8 per dimezzare il costo dei tuoi Celestiali ovunque, arrotondando per eccesso.","","L'Arbitro fa da guardiano perenne alle benedizioni del cielo.","Incantesimo",[],["Targon"],"COMUNE"],"07MT006":["Amanti sventurati","Gioca: Richiama un alleato e conferiscigli le mie statistiche.","","\"L'incontro del sole e della luna è uno spettacolo impareggiabile.\" - Diana","Unità",[],["Targon"],"COMUNE"],"07BC020":["Signor Gian Frusaglia","Quando una o più delle tue trappole o dei tuoi doni si attivano, ne piazzi 2 nel mazzo di quel giocatore.","","Nessuno sa da quanto il Signor Gian Frusaglia si dedica alla sua attività, o da dove viene. Comunque sembra amichevole... a parte i pericoli d'inciampo che si lascia dietro.","Unità",[],["Bandle City"],"RARA"],"07BC016":["Chiave ritornante","Quando mi scarti, equipaggiami su un alleato non equipaggiato.","","\"Lo ammetto: tendo a perdere i miei strumenti. Ma questo salta sempre fuori quando ne ho bisogno!\" - Ispettore di sicurezza","Equipaggiamento",[],["Bandle City"],"COMUNE"],"07BC018":["Studioso di portali","Quando vengo evocato, piazza 1 Portale misterioso tra le prime 4 carte del tuo mazzo.\nQuando evochi un alleato creato, conferiscigli Impatto.","","In ogni ricerca ci si deve aspettare delle sorprese... per fortuna, questa è positiva. ","Unità",["FATATO"],["Bandle City"],"EPICO"],"07BC011":["Feroci palle di pelo","Quando veniamo evocati, conferisci +1|+1 e Impatto agli altri alleati che hanno sottotipi.","","Purtroppo per questa banda di ladruncoli piltoveriani, sono innocui solo all'apparenza.","Unità",["VOLATILE"],["Bandle City"],"COMUNE"],"07DE014":["Sergente esaminatore","Gioca: Scegli un'unità dalle prime 5 carte del tuo mazzo che costano 3 o meno. Evocala e mescola le altre nel mazzo.","","Il sergente del reclutamento demaciano ha una grande responsabilità. Le sue reclute occuperanno vari incarichi diversi, tutte unite dal senso del dovere e dall'amore per Demacia.","Unità",["ÉLITE"],["Demacia"],"EPICO"],"07DE015":["Falcoleone crestato","Gioca: Se un alleato ha un sottotipo diverso dal mio, manifesta un incantesimo di Demacia.","","\"Registro il primo avvistamento del falcoleone in quasi cinquant'anni. Splendida cresta blu, sguardo intelligente. Il corpo è corazzato, ma le ossa sono abbastanza leggere da permettergli di arrampicarsi sugli alberi e di planare. La struttura delle ali ricorda quella delle ali d'argento demaciane. Fornirò prossimamente altri dati.\" - Dal diario di Anura, giorno 12","Unità",["VOLATILE"],["Demacia"],"RARA"],"07DE011":["Recluta dei Cercatori di magia","Gli incantesimi che costano meno di 3 costano 3.","","\"Silenzio! Non è un semplice gioco come sostieni, ma il segno di qualche maleficio arcano. Ho intenzione di denunciarti come truffatore e mago, vecchio furfante, anche se dovessi radere al suolo questo posto per farlo!\"","Unità",[],["Demacia"],"COMUNE"],"07DE016":["Balen il caritatevole","Attacca: Conferisci +0|+1 agli altri alleati con Formidabile ovunque.","","Amico di vecchia data della famiglia Durand, Balen è estremamente preciso nonostante le dimensioni. Anche se ha iniziato come semplice apprendista, Balen è estremamente dotato e ispirato nel suo lavoro, e i Durand si vantano della sua amicizia.","Unità",[],["Demacia"],"EPICO"],"08SI042":["Mordekaiser","Gioca: Uccidi fino a 2 alleati.\nQuando abbatti un altro alleato, rianimalo.","15+ alleati sono morti. Gli alleati con 5+ Potere contano due volte.","Legato alla sua armatura, conservata nel cuore del Bastione Immortale, Mordekaiser ha forgiato il proprio trono nel Regno grigio. Per ognuno votato alla sua distruzione, molti altri sono disposti a servirlo nella vita e nella morte.","Unità",[],["Isole Ombra","Noxus"],"Campione"],"08SI040":["Erastin, il Disonorato","Quando vengo evocato, conferiscimi Senzafine.\nAttacca: Fornisci ai nemici -1|-0 per questo turno.","","Un tempo i draghi camavorani erano splendidi e rispettati, ma neanche loro sono riusciti a sfuggire alla corruzione della Rovina. Erastin non fa eccezione: la sua antica regalità è ora corrotta nell'aspetto sgargiante dei senzafine.","Unità",["DRAGO"],["Isole Ombra"],"EPICO"],"08SI007":["Legione degli Spezzati","Gioca: Conferisci Senzafine a un alleato in mano.","","Non importa quale forma avessero assunto le anime prima di essere imprigionate nel Regno grigio. L'individualità conta poco, lì. Senza volto e senza paura, la Legione serve il revenant di ferro persino meglio, grazie all'uniformità.","Unità",[],["Isole Ombra"],"COMUNE"],"08SI003":["Anima maligna in catene","Ultimo respiro: La prossima volta che rianimi un alleato, crea una mia copia nella tua mano.","","\"Siamo stati incatenati molto tempo fa. Presto anche tu conoscerai la nostra sofferenza, e soffriremo tutti, per sempre, finché la mano del Padrone non ci donerà l'oblio...\"","Unità",[],["Isole Ombra"],"RARA"],"08SI021":["Melpanello solitario","Quando muore un altro alleato, o Ultimo respiro: Piazza 4 Campanelle nel tuo mazzo.","","Non preoccuparti di quell'infausto suono, è solo il vecchio Melpanello che si fa un giro. È sempre felice quando arriva qualcuno... ma gli altri di sicuro non sono felici di vederlo.","Unità",[],["Isole Ombra"],"COMUNE"],"08SI030":["Tomba d'acqua","Annienta 6 carte dal fondo del mazzo nemico.","","Per alcuni dei mostri abissali di Runeterra, una nave è solo un leggero spuntino.","Incantesimo",[],["Isole Ombra"],"EPICO"],"08SI037":["Mastino ferrospettrale","Per giocarmi, uccidi un alleato.\nQuando vengo evocato, evoca 1 Serpemorte dai mille artigli.","","Questi mastini non dimenticano mai l'odore di chi ha provato a fuggire... e quando i mastini accerchiano la loro preda, c'è sempre un serpemorte nelle vicinanze.","Unità",[],["Isole Ombra"],"RARA"],"08SI041":["Stretta mortale","Uccidi un alleato per infliggere 5 danni a un'unità.","","\"L'oscurità è il destino di tutti, tranne il mio.\" - Mordekaiser","Incantesimo",[],["Isole Ombra"],"COMUNE"],"08SI036":["Soglia del Grigio","Gioca: Maledici un nemico con Terrore.\nQuando evochi un alleato Titanico, distruggimi per pescare 2 carte.","","\"Ti offriamo queste anime. Lastrichiamo di ossa questa strada, per te. Distruggiamo questi regni, per l'avvento del tuo eterno esercito di ferro.\" - Cultista della stretta mortale","Monumento",[],["Isole Ombra"],"RARA"],"08SI004":["Regno della Morte","Un alleato avvia un attacco gratuito sfidando il nemico più forte.\nUccidi TUTTE le altre unità.","","\"La morte è il mio dominio.\" - Mordekaiser","Incantesimo",[],["Isole Ombra"],"EPICO"],"08SI026":["Cultista della stretta mortale","Quando vengo evocata o evochi un alleato Titanico, maledici il nemico più forte con Terrore.","","Agli occhi dei suoi seguaci, il revenant di ferro è l'unica speranza per coloro che cercano l'oblio. Pace attraverso la dominazione: questi cultisti la accolgono a braccia aperte.","Unità",[],["Isole Ombra"],"RARA"],"08SI018":["Ispettore spettrale","Gioca: Scegli un incantesimo Esploratore da creare nella tua mano.","","\"Il terreno è imperscrutabile. La visibilità quasi inesistente. Ho incontrato nemici a ogni angolo... ma stranamente, anche alleati inaspettati.\" - Dal diario della spedizione della Gilda degli esploratori, divisione terre lontane, posizione: Isole Ombra","Unità",[],["Isole Ombra","Targon"],"RARA"],"08SI015":["Amalgama di riti malefici","Per giocarmi, uccidi un alleato.\nUltimo respiro: Cura il tuo Nexus di 2.","","Le bestie da guerra sono preziose per ogni esercito. Nel Regno grigio sono un amalgama torturato di anime fortemente consunte nella loro inconsapevolezza. ","Unità",[],["Isole Ombra"],"EPICO"],"08BW008":["Nilah","Attacca: Crea 1 Scia nelle prime 6 carte del tuo mazzo.","Hai pescato 15+ carte.","A nord, una nuova sfida attende Nilah e il suo gruppo di cacciatori di mostri: una creatura chiamata Volibear, che minaccia di distruggere il Freljord che un tempo lo venerava. Nilah non vede l'ora di mettersi alla prova contro un mostro che tutti considerano un dio. Senza contare le creature inferiori che potrà eliminare nel frattempo. ","Unità",[],["Bilgewater"],"Campione"],"08BW032":["La gioia travolgente","Fornisci +1|+0 agli alleati per questo turno e cura gli alleati danneggiati di 2.","","\"Gioia, straripante e senza fine!\" - Nilah","Incantesimo",["ELEMENTALE"],["Bilgewater"],"COMUNE"],"08BW038":["Danzatrice dei chakram","Gioca: Infliggi 1 a un bersaglio.\nLe tue abilità assorbono.","","Si muove in una danza di acqua e lame, estraendo l'acciaio dal turbinio di schiuma e spruzzi. Non ha bisogno di vedere per percepire il flusso delle sue armi: sono animate dall'acqua, e nell'acqua tornano sempre.","Unità",[],["Bilgewater"],"EPICO"],"08BW015":["La danzatrice delle maree","Quando vengo evocata, pesca 1 Nilah.\nOgni turno, quando giochi la tua terza carta conferisci agli altri alleati +2|+0 e Insolente per questo turno.\nQuando dovresti ottenere Fugace, rivelami invece.","","\"Dicono che quella strana nave sia la più veloce di Bilgewater. Anche la più agile. Ha un capitano stravagante, ma mi pare che sappia il fatto suo. Magari potrebbe insegnarci un paio di cose.\" - Locandiere di Bilgewater","Unità",[],["Bilgewater"],"EPICO"],"08BW002":["Lama informe","Infliggi 2 a un'unità. Non può scendere sotto 1 di Salute per questi danni.","","\"I mostri che si definiscono dei cadranno, ovunque si trovino.\" - Nilah","Incantesimo",["ELEMENTALE"],["Bilgewater"],"COMUNE"],"08BW025":["Vedetta maestra","Quando hai pescato 3+ carte in un turno in questa partita, conferiscimi +1|+1 e Insolente.","","\"Ehi amico, che succede? Rilassati! Non c'è nulla nell'acqua che non possiamo affrontare!\" - Devoto della sfida","Unità",[],["Bilgewater"],"COMUNE"],"08BW026":["Devoto della sfida","Quando vengo evocato, ricircola la tua mano per conferirmi +1|+1 per ogni carta ricircolata e pescane 2.","","\"Ma dai, stai facendo sul serio? Mi sembra di dovermi trattenere e non lo sopporto proprio!\"","Unità",[],["Bilgewater"],"RARA"],"08BW028":["Octoavventuriero","Gioca: Scegli un incantesimo Esploratore da creare nella tua mano.","","\"Esemplare strano. Molto blu. Occhi molto grandi. Inquietantemente grandi. Lo acquisisco per ulteriori studi.\" - Dal diario della spedizione della Gilda degli esploratori, divisione terre lontane, posizione: Piltover","Unità",[],["Bilgewater","Piltover e Zaun"],"RARA"],"08BW009":["Timoniere rugoso","Gioca: Manifesta due diversi incantesimi Elementali che hai giocato in questa partita. Costano 0 per questo turno.","","\"La mente è un fiume. Il suo scorrere, nel tempo, può scavare le montagne. E come la mente, seguendo il flusso, può crescere ancora di più e raggiungere nuovi confini.\"","Unità",[],["Bilgewater"],"RARA"],"08BW010":["Diluvio","Per il resto della partita, tutti i tuoi incantesimi e abilità Elementali infliggono 1 danno in più.","","\"Nelle mani del saggio, l'acqua plasma ogni cosa.\" - Devoto della sapienza","Incantesimo",["ELEMENTALE"],["Bilgewater"],"EPICO"],"08BW031":["Sefirsa, Flagello degli abissi","Quando spendi mana per giocare un'altra unità, crea nella tua mano una carta casuale di pari costo. Costa 0 ed è Fugace.","","Nonostante la loro passione per le creature marine più strane, ci sono mostri con i quali neanche i capitani più esperti di Bilgewater vogliono avere a che fare. Parlano di Sefirsa sottovoce, come di una luce ipnotica che si muove nelle profondità... un mostro il cui trono è formato da navi affondate e uomini annegati.","Unità",["MOSTRO MARINO","DRAGO"],["Bilgewater"],"EPICO"],"08BW037":["Croupier onesto","Quando giochi una carta di costo pari al mio Potere, conferiscimi +1|+1.","","\"Che ne dici di puntare un altro po'? Chi non risica non rosica. Stasera questo è un tavolo fortunato, te lo dico io. E qui il banco non bara... lo giuro sulla lingua di mia madre.\"","Unità",[],["Bilgewater"],"RARA"],"08BW036":["Guglia corallina Marai","Quando spendi mana per giocare un'unità, ripristina 1 mana incantesimo.","","\"La barriera corallina è da sempre un rifugio e un'alleata. Si occupa di noi come noi facciamo con lei, affinché il Torbido non trionfi.\" - Nonna Marai","Monumento",[],["Bilgewater"],"COMUNE"],"08BW023":["Vikrash l'esuberante","Quando vengo evocato, crea 1 Scia nelle prime 6 carte del tuo mazzo.","","\"Amici, il mondo si muove con noi! Le onde danzano sotto la chiglia, il vento gonfia le vele, gli uccelli si fanno trasportare dalla brezza. Unitevi a me nella vostra più grande impresa, e gioite!\"","Unità",[],["Bilgewater"],"EPICO"],"08PZ007":["Stormo della burrasca","Evoca 1 Rondine della burrasca e conferiscigli +1|+1 per ogni altro incantesimo Elementale e abilità che hai giocato in questa partita.\nPesca 1 carta.","","Quando si raduna uno stormo di rondini della burrasca, di sicuro sta arrivando una tempesta.","Incantesimo",["ELEMENTALE"],["Piltover e Zaun"],"RARA"],"08PZ031":["Occhiali loschi","Scegli un seguace alleato. Mentre sono equipaggiato, trasforma il mio portatore in una copia esatta del seguace scelto.","","Non chiedermi come funzionano.","Equipaggiamento",[],["Piltover e Zaun"],"RARA"],"08PZ025":["Porobot prototipo","Ultimo respiro: Conferisci a un incantesimo casuale da 6+ di costo nella tua mano \"Quando vengo giocato, evoca Porobot prototipo.\"","","\"È solo un prototipo\", urlò l'apprendista mentre le fiamme divoravano il laboratorio. \"Non l'ho programmato per mangiare ogni ingranaggio che vede! Non so neanche dove stia ANDANDO tutto quel metallo!\"","Unità",["PORO"],["Piltover e Zaun"],"RARA"],"08PZ005":["Occhio del ciclone","Fornisci +2|+0 a un alleato per questo turno.\nPesca 2 carte.","","\"Non temere! La tempesta infuria intorno a te, ma non ti farà del male.\" - Janna","Incantesimo",["ELEMENTALE"],["Piltover e Zaun"],"COMUNE"],"08PZ019":["Tornado divino","Se hai pescato 3+ carte in questo turno, costo 2 in meno.\nInfliggi 3 a un'unità e 2 al Nexus nemico.","","\"La tempesta è al mio comando.\" - Janna","Incantesimo",["ELEMENTALE"],["Piltover e Zaun"],"RARA"],"08PZ028":["Drago Chemtech","Quando giochi un incantesimo, pesca 1 carta. Quando peschi mentre hai la mano piena, infliggi 1 al Nexus nemico.","","Zaun pretende adattamento... e il Drago Chemtech non fa eccezione, avvolto dalla malsana luce verde del potenziamento mentre si aggira per i meandri della città. Le ombre gemelle delle ali corrotte del drago si stagliano sui vicoli bui, messaggere di una furia nata dal dolore per la propria rovina.","Unità",["DRAGO"],["Piltover e Zaun"],"EPICO"],"08PZ001":["Janna","Gioca: Ricircola 2 carte per pescarne 2 al prossimo Inizio del turno.\nOgni turno, le prime 3 volte che peschi una carta, riduci di 1 il suo costo per questo turno.","Ti ho visto giocare 8 carte a costo ridotto.","\"A Zaun si venera Janna più che in qualunque altro posto. Dopotutto è lei che ha salvato le povere anime che Piltover aveva lasciato a morire. Già... se ci sono delle risposte, le troverò qui.\" - Marinaio del vento","Unità",[],["Piltover e Zaun"],"Campione"],"08PZ026":["Richiamo della burrasca","Evoca 1 Rondine della burrasca.","","\"Tutti i figli del vento rispondono al mio richiamo.\" - Janna","Incantesimo",["ELEMENTALE"],["Piltover e Zaun"],"COMUNE"],"08PZ006":["Iascylla, Polena degli abissi","Quando giochi un incantesimo Elementale o un'abilità, giocalo di nuovo sugli stessi bersagli.","","\"Avanti, Iascylla! Sei davvero vecchia, se Ashlesh conosce il tuo nome! Ma vecchia o giovane, bella o brutta, non importa. Per un mostro non c'è onore più grande che cadere in mare aperto, sotto la mia lama.\" - Nilah","Unità",[],["Piltover e Zaun"],"EPICO"],"08PZ018":["Marinaio del vento","Se hai pescato 3+ carte in questo turno, costo 2 in meno.","","\"Sì, avevo quello che volevo. Ma l'ho ottenuto prendendo, e prendere lascia un uomo vuoto. La prima cosa che ho trovato da seguire è stata il vento, quindi ora sono qui, sperando che lei mi conduca su una strada migliore.\"","Unità",[],["Piltover e Zaun"],"COMUNE"],"08PZ008":["Maryam, la custode del tempio","Gioca: Ricircola 1 carta per pescarne 1 o ripristinare il tuo mana incantesimo.","","Convinta di essere stata salvata da piccola dallo spirito del vento, Maryam ha predicato le virtù di Janna dalla sua patria di Shurima fino a Zaun. Ora che è la matriarca del tempio di Zaun, si dedica a portare la buona novella di Janna ai giovani e agli oppressi.","Unità",[],["Piltover e Zaun"],"EPICO"],"08PZ009":["Tempio sommerso","Fine del turno: Ricircola la tua mano.\nInizio del turno: Pesca altrettante carte più 1.","","Molto è andato perduto nel disastroso crollo che ha separato Zaun da Piltover. Janna ha perso il suo tempio tra le onde, ma ha salvato le persone che pregavano al suo interno.","Monumento",[],["Piltover e Zaun"],"EPICO"],"08PZ002":["Tempesta ululante","Infliggi 2 a un'unità.\nAumenta i miei danni di 1 per ogni altra carta che hai giocato in questo turno, fino a 3 volte.","","\"Venti ululanti gridano la mia furia!\" - Janna","Incantesimo",["ELEMENTALE"],["Piltover e Zaun"],"RARA"],"08PZ024":["Venditore di pesce ciarlatano","Inizio del turno: TUTTI i giocatori pescano 1 carta, poi conferisci Fugace alla carta del tuo avversario.","","\"Due al prezzo di uno, solo per oggi! Pesce fresco, appena pescato... in questo mese? Due al prezzo di uno! Che vuol dire che non vuoi il secondo pesce? È gratis!\"","Unità",[],["Piltover e Zaun"],"COMUNE"],"08PZ020":["Vento glorioso","Se hai pescato 3+ carte in questo turno, costo 2 in meno.\nQuando vengo evocato, pesca 2 carte al prossimo Inizio del turno.","","\"Caro Zefiro. Discendi dalle nuvole e posati un po' sulla mia spalla, che ne dici?\" - Janna","Unità",[],["Piltover e Zaun"],"RARA"],"08FR012":["Invocazione del tuono","Pesca 1 carta.\nEvoca 1 Sigillo della tempesta.","","\"In nome di Valhir, portiamo questa offerta...\" - Profeta di Valhir","Incantesimo",["ELEMENTALE"],["Freljord"],"COMUNE"],"08FR033":["Berserker spadaccina","Quando giochi un incantesimo Lento che bersaglia un solo alleato, copialo su di me.","","\"Credi che un paio di frecce possano fermarmi? Ah! Qualunque cosa mi lanci, diventa un'arma del mio arsenale. Qualunque cosa io perda, la riforgio nel ghiaccio!\"","Unità",[],["Freljord"],"COMUNE"],"08FR019":["Spaccacielo","Fornisci +1|+3 a un alleato per questo turno.","","Avvolto dalle nubi e circondato dai fulmini, il dio orso resta intoccabile nel cuore della tempesta.","Incantesimo",["ELEMENTALE"],["Freljord"],"COMUNE"],"08FR001":["Volibear","Gioca: Gioca Tempesta implacabile 3 volte. Ognuno bersaglia un nemico casuale diverso. Se non ce ne sono, bersaglia il Nexus nemico.","Fine del turno: Hai inflitto 50+ danni.","\"Inginocchiati mortale, e potrei risparmiarti! Sei debole, ma forse potresti comunque servirmi. Inginocchiati, o scompari dalla faccia della terra!\"","Unità",[],["Freljord"],"Campione"],"08FR018":["Scontro di giganti","Evoca 2 seguaci Titanici casuali.\nCosto 1 in meno per ogni incantesimo Elementale o abilità che hai giocato in questa partita (massimo 10).","","\"Con questo corpo ho scolpito le montagne. Con il fuoco delle sue fauci, ho scavato migliaia di fiordi.\" - Volibear","Incantesimo",["ELEMENTALE"],["Freljord"],"EPICO"],"08FR011":["Caprino evocatore della fiamma","Quando giochi un incantesimo Elementale o un'abilità, Forgiami.","","\"Il signore della fucina ha promesso un cambiamento, e invece non ha fatto nulla. Coloro che venerano un dio debole, sono deboli anch'essi. Solo grazie alla potenza di Valhir raggiungeremo la gloria!\"","Unità",[],["Freljord"],"RARA"],"08FR008":["Incarna della tempesta","Infliggi 4 a TUTTE le unità tranne agli alleati Titanici.","","\"Che la tundra si tinga di rosso!\" - Volibear","Incantesimo",["ELEMENTALE"],["Freljord"],"RARA"],"08FR024":["Cane delle nevi Yadulski","Attacca: Conferisci +1|+1 ai primi due alleati del tuo mazzo.","","Anche se sono originari di Yadulsk, questi cuccioli sono stati addomesticati da varie tribù del Freljord per l'inseguimento, la caccia e i salvataggi dopo le valanghe. Grazie al loro fisico robusto e al carattere gioviale, sono amati dalla tundra alla taiga.","Unità",["CANIDE"],["Freljord"],"COMUNE"],"08FR015":["Rhond, il serpente magmatico","Gioca: Evoca 3 Sigilli della tempesta.","","Anche se in pochi lo venerano ancora, tutti gli abitanti del Freljord conoscono la storia della grande battaglia di Volibear contro Rhond. Molto prima che un mortale mettesse piede nel gelido nord, questo scontro devastante plasmò i crinali e i fiumi della tundra stessa.","Unità",[],["Freljord"],"EPICO"],"08FR030":["Boadir di Ghiaccio nero","Quando vengo evocata, evoca 2 Schiavi ghiacciati e avanzali a 2.","","\"Era t-terribile! Schiavi ridotti a ghiaccio nero, valanghe sotto i suoi artigli, un ruggito che faceva cadere la neve dalle montagne! Una regina guerriera, parola mia! U-uccidere schiavi è il compito di una regina guerriera.\" - Bjerg farneticante","Unità",["DRAGO"],["Freljord"],"EPICO"],"08FR002":["Profeta di Valhir","Quando vengo evocato, evoca 1 Sigillo della tempesta.","","\"Vedo ciò che gli altri non vedono: la tempesta che scuoterà la montagna, le ossa della terra che si frantumano. Il vecchio Freljord si rinnoverà nel sangue... è solo una questione di tempo.\"","Unità",[],["Freljord"],"COMUNE"],"08FR028":["Imbracatura pratica","Ho +1|+0 per ogni sottotipo diverso che hai evocato in questa partita.","","\"Lassù ci sono bestie che neanche una valanga è in grado di fermare. Per questo una buona imbracatura vale ogni moneta che costa.\" - Cacciatore avarosano","Equipaggiamento",[],["Freljord"],"EPICO"],"08FR003":["Urside Berserker","Quando giochi un incantesimo o un'abilità, evoca 1 Sigillo della tempesta.","","A volte i seguaci di Volibear si perdono talmente tanto nel loro fanatismo che iniziano ad assumere degli aspetti dell'orso. Nulla può opporsi alla volontà di Valhir, neanche coloro che, un tempo, gli Ursidi chiamavano compatrioti.","Unità",[],["Freljord"],"RARA"],"08RU014":["Drago maggiore","Origine: Aspetto del Drago.\nCosto 1 in meno per ogni Dono del Drago diverso che hai giocato in questa partita.\nGioca: Gioca ogni Dono del Drago su di me.","I tuoi alleati hanno attaccato con 75+ di Potere totale.","\"Secondo la leggenda questo drago è il più vecchio di tutti: il re di tutte le bestie alate. Se lo domiamo... Alatis, cos'altro potrebbe opporsi a noi? Il mondo capirà finalmente che non esiste nulla di più forte di uomini e draghi insieme.\" - Volix, vassallo dei Draghi","Unità",["DRAGO"],["Runeterra"],"Campione"],"08NX003":["Sputafuoco furioso","Gioca: Infliggi 2 a un nemico e 2 al Nexus nemico.","","L'espansione noxiana ha conquistato molte genti, culture e insediamenti diversi. Spesso anche le creature selvagge vengono schiacciate dalla macchina da guerra, ma nel caso di questo drago, ogni violento attacco di Noxus viene respinto da un brutale inferno di collera.","Unità",["DRAGO"],["Noxus"],"EPICO"],"08NX024":["Legionario di ferro","Gioca: Infliggi 3 a un alleato per infliggere 3 a un nemico.","","\"Strappagli l'anima dal corpo!\" - Mordekaiser","Unità",[],["Noxus"],"RARA"],"08NX011":["Incendio","Infliggi 1 al Nexus nemico. Infliggi 1 in più per ogni altro Incendio che hai giocato. Crea 1 Incendio nel tuo mazzo.","","\"Cenere, cenere...\" - Annie","Incantesimo",["ELEMENTALE"],["Noxus"],"COMUNE"],"08NX028":["Incrollabile","Conferisci Senzafine a un alleato.","","\"Ferro eterno.\" - Mordekaiser","Incantesimo",[],["Noxus"],"COMUNE"],"08NX019":["Rasoiante dagli spuntoni rossi","Colpisci il Nexus: Maledici il tuo avversario con Icore.","","Utile componente della macchina da guerra noxiana, il rasoiante è apprezzato anche nelle arene della capitale. Dal momento che pochi avversari, umani o animali, sono disposti ad affrontarlo, i rari combattimenti del rasoiante attirano folle di spettatori da tutta la città.","Unità",["RETTILE"],["Noxus"],"COMUNE"],"08NX014":["Direttrice Telsi","Gli effetti di Attacco e Supporto alleati si attivano una volta in più.","","Il corso di disciplina personale della direttrice Telsi è pieno di compiti difficilissimi, bacchettate sulle mani e note disciplinari. È sempre stato obbligatorio per gli studenti del Conservatorio Ravenbloom... altrimenti non si iscriverebbe nessuno.","Unità",[],["Noxus"],"EPICO"],"08NX012":["Acquisitore armato","Gioca: Scegli un incantesimo Esploratore da creare nella tua mano.","","\"Si direbbe che scavare nel deserto sia più facile... e invece no! Se passa abbastanza tempo, la sabbia si trasforma in pietra. Torno a richiedere fondi per dei nuovi attrezzi.\" - Dal diario della spedizione della Gilda degli esploratori, divisione terre lontane, posizione: Shurima","Unità",[],["Noxus","Shurima"],"RARA"],"08NX029":["Fendente Kashuri","Uccidi un'unità se è danneggiata, altrimenti le infliggi 2.","","\"È per il tuo bene. Fidati di me.\" - Lord Broadmane","Incantesimo",[],["Noxus"],"EPICO"],"08NX009":["Lord Mallat","","","\"Ci sono voluti secoli di pianificazione per sigillare quel malefico guerrafondaio... e i tuoi patetici amici vogliono sconfiggerlo con la 'gioia'? Sciocca ragazza. Non farai altro che scatenare la furia del revenant... mettendoci tutti in pericolo.\"","Unità",[],["Noxus"],"COMUNE"],"08NX025":["Redivivo trafitto","Quando un alleato viene rianimato, conferiscigli Sfidante.","","\"Tu sorridi, ma io conosco la vera natura del tuo cuore traditore! Mi hanno sorriso e hanno mangiato alla mia tavola, anche se volevano pugnalarmi alle spalle. Non mi farò ingannare di nuovo. Morirai come gli altri: implorando perdono tra le urla!\"","Unità",[],["Noxus"],"RARA"],"08SH009":["Maledizione antica","Maledici un nemico con Terrore.","","Alcune cose è meglio lasciarle sotto la sabbia.","Incantesimo",[],["Shurima"],"COMUNE"],"08SH014":["Allarmasciame cornuto","Gioca: Conferisci -1|-0 a due nemici e disabilita le loro parole chiave positive.","","Nonostante le dimensioni imponenti, questo allarmasciame difficilmente diventa violento. Quando il suo sciame si avvicina a un insediamento shurimano, gli abitanti lasciano in offerta delle bacche nel deserto vicino per distrarre i visitatori dal raccolto principale.","Unità",["DRAGO"],["Shurima"],"COMUNE"],"08SH004":["Generale delle dune","Alba o quando attivi un'altra Alba: Conferisci Vulnerabile al nemico più debole.","","I vasti eserciti di Shurima sono pronti a dimostrare la potenza del deserto. Quando ricevono un ordine, avanzano senza esitazione.","Unità",["ÉLITE"],["Shurima"],"RARA"],"08SH005":["Difensori del Disco solare","Alba: Pesca 1 Difensori del Disco solare.","","\"Siamo i custodi del deserto eterno, la storia vivente, e percorriamo il cammino dello splendore. Ci inginocchiamo davanti al Disco solare e nient'altro, così che il mondo si piegherà davanti alla gloria di Shurima.\" - Azir","Unità",["ÉLITE"],["Shurima"],"COMUNE"],"08SH012":["Barbara Tombarola","La prima volta che un altro alleato muore in un turno, o Ultimo respiro: Crea 1 Ritrovamento fortunato nella tua mano.","","\"Questo sì che è un bottino, Barb. Sapevo di poter contare su di te. Aspetta... che vuol dire che ti hanno vista?\" - Picchiatore di Vekaura","Unità",["RETTILE"],["Shurima"],"RARA"],"08SH002":["Inghiottidune","Per giocarmi, uccidi un alleato o una delle tue gemme di mana 3 volte.","","L'inghiottidune vive a profondità molto maggiori dei suoi più piccoli cugini xer'sai. Divora con facilità gli altri predatori xer'sai e le testimonianze dirette che lo riguardano sono poche... probabilmente perché riesce a inghiottire in un sol boccone intere dune (eventuali testimoni compresi). ","Unità",[],["Shurima"],"EPICO"],"08MT003":["Morgana","Gioca: Maledici due volte un nemico con Catene.","Hai scelto come bersaglio unità per 10+ volte.","\"Sei arrivata da me ferita e sanguinante, eppure non ho mai visto un volto più allegro. Sei davvero una donna strana, ma qui sei al sicuro. Riposati. Quando starai meglio, sarò felice di ascoltare la tua storia.\"","Unità",[],["Targon","Demacia"],"Campione"],"08MT005":["Mihira, Incarnazione degli Ascesi","Gioca: Maledici due volte 2 nemici con Catene.","","\"È stato in nome delle mie figlie che ho abbracciato la divinità. È stato per la mia famiglia che ho rinunciato alla mia umanità, per creare un nuovo mondo di verità e giustizia con questa spada fiammeggiante.\"","Unità",[],["Targon"],"EPICO"],"08MT042":["Morsa del peccatore","Maledici un nemico con Catene.\nAumenta di 1 il costo delle maledizioni nemiche ovunque.","","\"Per trovare la tua libertà, accetta l'oscurità che hai dentro.\" - Morgana","Incantesimo",[],["Targon"],"RARA"],"08MT024":["Mago Occhi di rubino","Gioca: Conferisci Scudo magico o Sopraffare a un alleato in mano.","","\"Non avere paura! Vai avanti senza guardarti indietro! Una volta abbiamo compiuto anche noi questo viaggio. Ora è nostro dovere proteggere il tuo. Raggiungi presto il suo santuario e la Velata ti darà la protezione che cerchi.\"","Unità",[],["Targon"],"COMUNE"],"08MT045":["Mago incatenato","Gioca: Maledicimi con Catene.","","I cercatori di magia erano esperti nel far cedere le persone. Avevano imbrigliato le sue mani e la sua magia. Avevano preso la sua voce. Ma lui era già riuscito a resistere... e questa volta, aveva la Dama velata dalla sua parte.","Unità",[],["Targon"],"RARA"],"08MT015":["Lisa e Dolly","Gioca: Maledici un nemico con Catene.","","\"Guarda Dolly! Sto facendo proprio come mi hai insegnato! Pensi che riusciremo a far vedere a mamma tutto quello che ho imparato? Dici che lo sa già? Sul serio? Spero tu abbia ragione.\" - Lisa","Unità",[],["Targon"],"COMUNE"],"08MT030":["Dragogemma gentile","Quando giochi un incantesimo Veloce, Lento o un'Abilità, conferisci +1|+1 agli altri alleati Draghi.","","I Draghi possono avere caratteri molto diversi, come diverso è il loro aspetto. Se esistono specie che vivono solo per distruggere, come i Draghi infernali, ci sono anche quelle protettive nei confronti delle loro famiglie e del proprio ambiente, come il lento e affettuoso Dragogemma.","Unità",["DRAGO"],["Targon"],"RARA"],"08MT023":["Legame oscuro","Stordisci un nemico e maledicilo con Catene.","","\"Soffri, come hai fatto soffrire loro!\" - Morgana","Incantesimo",[],["Targon"],"RARA"],"08MT031":["Fedele dei draghi Ottrani","Quando vengo evocato, cura di 2 il tuo Nexus e ottieni una gemma di mana extra nel prossimo turno.","","Sulle alture del Targon, un Ottrani solitario ha dedicato la sua vita ai draghi. Si adorna con scaglie e vecchie ossa, praticando la divinazione con denti di drago e interpretando il fumo che sale per la montagna.","Unità",[],["Targon"],"EPICO"],"08MT009":["Protettore velato","Quando vengo evocato o evochi un alleato Titanico, cura di 3 il tuo Nexus.","","Questo protettore velato non ha dimenticato la benedizione che lo ha elevato dall'essere una mera bestia, e ripaga questo debito proteggendo il viaggio di chiunque cerchi un certo santuario sulle pendici del Targon.","Unità",[],["Targon"],"RARA"],"08MT006":["Scudo nero","Fornisci Scudo magico a un alleato per questo turno e maledicilo con Catene.","","\"Protezione dalla persecuzione!\" - Morgana","Incantesimo",[],["Targon"],"RARA"],"08MT027":["Messaggero della Convergenza celestiale","Gioca: Attiva gli effetti Alba e Crepuscolo degli altri alleati.\nAlba: Conferiscimi Sopraffare.\nCrepuscolo: Conferiscimi Scudo magico.","","\"In alto arde un anello di fuoco. Nell'oscurità promessa, siamo tutti uguali.\" - Affatturatore Lunari","Unità",["VOLATILE"],["Targon"],"EPICO"],"08MT025":["Scheggia sismica","Se un'unità Titanica è visibile, costo 3 in meno.\nInfliggi 7 a un'unità.","","\"Ops, non ti devi preoccupare, è solo un problemino, niente di grave, NON PAPONE, NO! Andiamo avanti!\" - Chip","Incantesimo",["ELEMENTALE"],["Targon"],"COMUNE"],"08DE006":["Pioniere istruito","Gioca: Scegli un incantesimo Esploratore da creare nella tua mano.","","\"Fa freddo. Ho freddo. È tutto freddo, sempre. Ci sono dei posti in cui semplicemente non si può vivere. La prossima volta mandatemi in un posto caldo, vi prego.\" - Dal diario della spedizione della Gilda degli esploratori, divisione terre lontane, posizione: Freljord","Unità",[],["Demacia","Freljord"],"RARA"],"08DE020":["Confinamento magico","Conferisci +0|+2 a un alleato. Maledici il tuo avversario con Soppressione.","","\"Prendi atto del peso dei tuoi peccati!\" - Morgana","Incantesimo",[],["Demacia"],"COMUNE"],"08DE017":["Inquisitore dei Cercatori di magia","Quando vengo evocato, maledici il tuo avversario con Soppressione.","","\"Non possiamo permettere loro di raggiungere il santuario della sorella caduta. La sua magia è antica e malvagia, e va al di là anche delle mia capacità di soppressione. Presto, riporta questi abomini sulla nave e poi insegui gli altri sulla montagna!\"","Unità",[],["Demacia"],"RARA"],"08DE025":["Drago della nuvola","Quando vengo evocato, riduci di 1 il costo di tutte le unità alleate nella mano.","","Grazie alla spessa pelliccia che lo isola dal freddo, questo drago può raggiungere altezze molto elevate rispetto alla maggior parte degli altri draghi. Vivaci ma sfuggenti, di solito questi draghi vengono avvistati alti nel cielo mentre sfrecciano tra le nuvole ad ali spiegate.","Unità",["DRAGO"],["Demacia"],"EPICO"],"08DE010":["Duello tra gentiluomini","Fornisci +0|+2 a un alleato per questo turno.\nQuell'alleato e un nemico si colpiscono a vicenda.","","\"En garde, amico mio! Di certo non hai paura di un duello tra gentiluomini?\" - Chevalier dei Laurent","Incantesimo",[],["Demacia"],"COMUNE"],"08DE022":["Il martin pescatore","Quando vengo evocato, pesca 1 di ogni campione dal tuo mazzo.\nOgni turno, la prima volta che evochi un campione, prepara l'assalto.","","\"Ricorda, figlio mio, insegui l'orizzonte servendo la patria che lasci alle spalle.\" - Re Jarvan III","Unità",[],["Demacia"],"EPICO"],"08DE027":["Colpo artigliato","Conferisci +1|+1 ai Volatili alleati ovunque. Un Volatile alleato colpisce un nemico.","","Il grido dell'ala d'argento annuncia la morte che arriva dall'alto.","Incantesimo",[],["Demacia"],"RARA"],"08DE026":["Alatis il valoroso","I tuoi Doni del Drago bersagliano tutti gli alleati Draghi.","","\"Per essere chiaro, non sono sempre stato un vassallo dei Draghi. Alatis mi ha convinto, la prima volta che mi ha salvato la vita. Mi ha insegnato molte cose, ma la cosa più importante? Non c'è cosa più bella che servire Demacia a dorso di drago.\" - Vassallo dei Draghi","Unità",["DRAGO"],["Demacia"],"EPICO"],"08DE013":["Vassallo dei Draghi","Quando vengo evocato, pesca 1 Drago se hai un Drago Visibile.","","\"Sai quanto mi costa ammetterlo, vecchio mio, ma non possiamo domarlo da soli. Abbiamo già fatto il possibile. Avvertirò il generale, e con la potenza di Demacia riusciremo certamente ad avere la meglio su quella bestia fantastica.\"","Unità",[],["Demacia"],"COMUNE"],"08IO012":["Drago dell'oceano","Quando giochi un incantesimo Veloce, Lento o un'Abilità, cura il tuo Nexus di 1.","","\"Che bestia grandiosa che sei! È una gioia vedere i tuoi artigli che ghermiscono le onde. Se un giorno volessi qualcosa di meglio di pesci e uccelli marini, sarei felice di affrontarti.\" - Nilah","Unità",["DRAGO"],["Ionia"],"RARA"],"08IO014":["Heisho, il guscio del mondo","Ogni turno, la prima carta che giochi costa 9 in meno.","","Per gli abitanti di questo villaggio di Ionia, Heisho è sia un amico che un custode rispettato. Porta sulla schiena le loro case da tempo immemore, e gli abitanti sanno che, quando i tempi si faranno difficili, Heisho cercherà riparo in coste pacifiche.","Unità",["RETTILE"],["Ionia"],"EPICO"],"08IO021":["Danza dell'Empireo","Ferma un incantesimo Veloce, Lento o un'Abilità, richiama un nemico ed evoca L'Empireo.","","\"Questa danza è il nostro ricordo.\" - Irelia","Incantesimo",[],["Ionia"],"RARA"],"08IO019":["Fidato Adnere","Quando vengo evocato, evoca Volieristi di Adnere.","","\"Questa terra è piena di lezioni. Ricorda sempre: bisogna festeggiare il cambio di ogni stagione, perché solo con la fine può esserci un nuovo inizio.\"","Unità",[],["Ionia"],"RARA"],"08IO010":["Ribaltamento","Richiama un nemico per aumentare di 2 il costo della prossima unità giocata dal nemico in questo turno.","","\"Chi vuole danneggiarci si ritroverà sul fondo del mare.\" - Dominatore del fiume","Incantesimo",["ELEMENTALE"],["Ionia"],"COMUNE"],"08IO023":["Spiriti marini gioiosi","Gioca: Evoca una mia copia Effimera.","","Nei periodi giusti dell'anno, quando il vento soffia sul mare, alcuni zauniti giurano di vedere le flebili sagome di due enormi creature pinnate che danzano felici tra le onde dell'oceano.","Unità",[],["Ionia"],"COMUNE"],"08BC020":["Volatile mattiniero","Il tuo avversario scarta la sua carta di costo superiore.","","\"Immagina di essere un verme, e l'ultima cosa che vedi prima di morire sono quegli occhi. Come dici, i vermi non vedono? Be', meglio così.\" - Elle, Viaggiatrice infreddolita","Incantesimo",[],["Bandle City"],"COMUNE"],"08BC005":["Zaino pieno","Per ogni Zaino pieno che hai giocato in questa partita, piazza 4 Campanelle nel tuo mazzo e 4 Scoppiettini velenosi nel mazzo nemico. Crea 1 Zaino pieno nel tuo mazzo.","","\"Regola 207: una Scout porta con sé solo quello che le serve!\" - Ava l'Ambiziosa","Incantesimo",[],["Bandle City"],"RARA"],"08BC021":["Cambio furtivo","Richiama un alleato per evocare 1 Gattufo famelico al suo posto.","","\"SQWUEA?\" - Gattufo","Incantesimo",[],["Bandle City"],"RARA"],"08BC002":["Skip, \"Re della barriera\"","Gioca: Scegli 1 di 2 carte non campioni dalla mano dell'avversario. La catturo.","","\"Sì, sono bellissimo, veloce e dal fascino imperturbabile. Non lo sai, vecchio? Io sono il re della barriera, e stai invadendo il mio regno!\"\n\"A-aspetta! Torna subito qui! Ho bisogno di quel campione per le mie ricerche!\" - Concologo","Unità",[],["Bandle City"],"EPICO"],"08BC006":["Pioniere del portale","Gioca: Scegli un incantesimo Esploratore da creare nella tua mano.","","\"Sono preoccupato per Bunches! Oh, ultimamente è sempre più nervoso. Si preoccupa anche di un semplice salto nel portale! Non capisco perché.\" - Dal diario della spedizione della Gilda degli esploratori, divisione terre lontane, posizione: Bandle City","Unità",["YORDLE"],["Bandle City","Ionia"],"RARA"],"08BC004":["Portia la Bizzarra","Gioca: Manifesta un seguace Titanico e imposta le sue statistiche a 1|1 e il costo a 0.","","\"Certo che conosco la vecchia Portia! Ha un po' la testa fra le nuvole, ma se serve può procurarti un portale per qualunque posto. Un colpo di coda, e si va!\" - Pioniere del portale","Unità",["DRAGO"],["Bandle City"],"EPICO"],"08BC018":["Trappola zuccherata","Metti un alleato in fondo al tuo mazzo per evocare il primo alleato del tuo mazzo.","","\"Regola 571: Una Scout deve essere sempre vigile. Non si sa mai cosa potrebbe essere una bella sorpresa e cosa una trappola.\" - Ava l'Ambiziosa","Incantesimo",[],["Bandle City"],"RARA"],"09SI015":["Splendida catastrofe","I: Uccidi un'unità con Potere e Salute totali di 5 o meno.\nII: Assorbi 2 Salute dal Nexus nemico.\nIII: Evoca una copia esatta di un alleato. È Effimera e 1|1.","","È salito sul palco, con in mano la sua poesia. Non aveva affisso manifesti per promuovere la sua esibizione, perché aveva già come pubblico l'unica persona di cui gli importasse.","Monumento",["STORIA"],["Isole Ombra"],"EPICO"],"09SI013":["Conquista di ferro","I-II: Scegli un seguace alleato. Creane una copia Effimera nella tua mano con +1|+1.\nIII: Rianima il seguace alleato morto più forte e conferiscigli Effimero.","","Nel Regno grigio, le anime torturate compongono un esercito spettrale. Una volta aperte le porte del reame mortale, non si fermeranno.","Monumento",["STORIA"],["Isole Ombra"],"RARA"],"09SI012":["Terrore esistenziale","Conferisci Noia ai nemici.","","\"Niente ha davvero importanza.\" - Vex","Incantesimo",[],["Isole Ombra"],"RARA"],"09SI017":["Kharox","Ogni volta che muore un alleato non Tentacolo, o Ultimo respiro: Genera 2.","","Si dice che Kharox, il conducente solitario di una nave spettrale che molti lupi di mare chiamano Ultimo Traghetto, comunichi con gli spiriti di tutti i marinai morti nel tentativo di raggiungere le Isole.","Unità",[],["Isole Ombra"],"EPICO"],"09SI014":["Grimm","Gioca: Conferisci 4 Noia a un'unità.","","Oscuro romantico, poeta tormentato e filosofo, Grimm non teme un po' di noia e dolore. La prediletta del suo cuore è notoriamente volubile, ma questo la rende ancora più adorabile ai suoi occhi.","Unità",["YORDLE"],["Isole Ombra"],"COMUNE"],"09DE033":["Spiritelli","","","\"Gli spiritelli sono creature meravigliose. Avendo abbastanza tempo, e il sognatore giusto, il loro potenziale è illimitato!\" - Madre degli Spiriti","Unità",[],["Demacia","Ionia"],"COMUNE"],"09DE039":["Luce di Demacia","I: Conferisci Spirito a un alleato.\nII: Conferisci 2 Spirito a un alleato.\nIII: Potenzia tutti gli alleati.","","Il boato della folla cresceva, mentre la sua radiosità ne illuminava i volti. Aveva sempre e solo desiderato di risollevare e sostenere la sua gente... e loro fecero lo stesso per lei, con canti di adorazione: \"Luxanna! Luxanna! Luxanna!\"","Monumento",["STORIA"],["Demacia"],"RARA"],"09DE034":["Lux: Illuminata","Supporto: Conferisci Spirito al mio alleato supportato e forniscimi Barriera per questo turno.","Gli alleati hanno attaccato con, o hanno ottenuto mentre attaccavano, 20+ parole chiave positive totali.","La luce mulinava e si avvolgeva intorno a Luxanna, mentre gli abitanti della città la osservavano meravigliati. Qui era la signora della luce di Demacia, una giovane e coraggiosa Crownguard e una talentuosa maga. Qui, Demacia era tutto ciò che lei aveva sempre voluto.","Unità",[],["Demacia"],"Campione"],"09DE047":["Manufatto dimenticato","Evoca 1 Destriero di arenaria, poi fornisci Sfidante agli alleati per questo turno.","","Nelle profondità di una cripta dei cercatori di magia, piena di oggetti magici confiscati, si trova uno strano oggetto non catalogato, e nessuno sa più a cosa servisse...","Incantesimo",[],["Demacia"],"RARA"],"09DE041":["Sala di petricite","I: Un alleato cattura un'unità.\nII: Maledici il tuo avversario con Soppressione.\nIII: Annienta tutte le carte catturate dagli alleati.","","Il boato della folla si attenuò quando entrò nella sala. Le statue la osservavano in silenzio. L'oscurità la attendeva, ma non poteva tornare indietro... chi altri avrebbe potuto impedire la discesa di Demacia negli incubi?","Monumento",["STORIA"],["Demacia"],"EPICO"],"09DE030":["Incandescenza","Potenzia tutte le unità.","","\"La nostra radiosità è senza limiti!\" - Lux: Illuminata","Incantesimo",[],["Demacia"],"COMUNE"],"09DE043":["Luce nascente","Potenzia 3 volte tutte le unità.","","\"Nella luce!\" - Lux: Illuminata","Incantesimo",[],["Demacia"],"RARA"],"09DE031":["Jarro Piumaleggera","Gioca: Conferisci Spirito a un alleato nella tua mano.","","Un giovane con indosso una maschera da ballo le apparve davanti avvolto da petali di rosa e creature luminescenti. \"Il mio nome è Piumaleggera. Jarro Piumaleggera\", disse. \"Ho saputo che forse necessita di aiuto, mia signora?\"","Unità",[],["Demacia"],"RARA"],"09DE046":["Sorriso abbagliante","Potenzia 2 alleati che poi colpiscono un nemico uno dopo l'altro.","","\"Calme, signore. Ne ho per tutte.\" - Jarro Piumaleggera","Incantesimo",[],["Demacia"],"COMUNE"],"09DE045":["Alina Luce sognante","Quando vengo evocata, evoca 5 Spiritelli. Per ciascuna carta per la quale non c'è posto, conferisci invece 2 Spirito all'alleato più debole.","","\"Anche io alla tua età avevo paura di questa luce. Non c'era nessuno a dirmi che la mia magia era un dono... che mi era stata data per un motivo. Ma tu ora hai me. Non avere paura, Alina. Lascia che splenda.\" - Lux: Illuminata","Unità",[],["Demacia"],"EPICO"],"09DE040":["Cercatore di magia aberrante","Quando vengo evocato, conferisci Spirito agli altri alleati.","","\"Lady Crownguard.\" Il cercatore di magia uscì dall'ombra, estendendo una mano verso di lei. Il suo sorriso supplice sembrava troppo ampio per il suo volto semioscurato. \"Perché non mi segui?\"","Unità",[],["Demacia"],"COMUNE"],"09DE036":["Spiritelli dell'albero","Gioca: Potenzia tutte le altre unità.","","\"Andate, spiritelli. Mostrate la strada a chi vi sogna.\" - Lillia","Unità",[],["Demacia","Bandle City"],"COMUNE"],"09DE029":["Spirito della luce","Supporto: Fornisci al mio alleato supportato tutte le mie parole chiave positive e le loro cariche per questo turno.","","\"Forza, signor spiritello. Scacciamo queste brutte ombre!\" - Alina Luce sognante","Unità",[],["Demacia"],"RARA"],"09SH010":["Ricostruttrice dell'impero","Gioca: Conferisci a un Monumento alleato \"Quando vengo distrutto, rianimami.\"","","L'ascesa dell'imperatore ha portato la speranza a Shurima. Decisa a realizzare il sogno di Azir, questa maga si fa chiamare la \"Ricostruttrice dell'impero\" e viaggia per il deserto allo scopo di riportare le rovine sepolte al loro antico splendore.","Unità",[],["Shurima"],"COMUNE"],"09SH009":["L'esercito dell'Imperatore","I: Evoca 2 Soldati della sabbia.\nII: Prevedi.\nIII: Quando evochi un alleato in questo turno, forniscigli +2|+0 per questo turno.","","Azir conosce Shurima com'era, com'è e come sarà. Crede che la sua visione per il futuro sia molto più di un semplice sogno: è una profezia che deve far avverare.","Monumento",["STORIA"],["Shurima"],"EPICO"],"09SH012":["Evocazione solare","Scegli 1 di 3 campioni nel tuo mazzo iniziale e pescalo.","","Molti manufatti degli antichi Figli del sole sono perduti da tempo. Lo stesso non si può sempre dire degli dei guerrieri che rappresentano.","Incantesimo",[],["Shurima"],"RARA"],"09PZ044":["Preghiera a lume di candela","I-II: Ricircola 1 carta per pescarne 1.\nIII: Pesca 1 carta.","","Questo tempio dedicato a Janna ha poche mura solide, per essere più in sintonia con i poteri della sua dea. Eppure, le sue candele restano sempre accese, anche quando la tempesta infuria su Zaun.","Monumento",["STORIA"],["Piltover e Zaun"],"EPICO"],"09PZ045":["Cartografa alata","Gioca: Ricircola 1 carta per pescarne un'altra che costa più o meno di quella che hai ricircolato.","","\"Dall'alto ci si rende conto della propria insignificanza.\"","Unità",[],["Piltover e Zaun"],"RARA"],"09PZ046":["Malmutazione","Scegli un seguace alleato. Evoca 2 Gattufi famelici poi trasforma gli alleati in copie esatte dell'alleato scelto.","","\"Solo un'altra copia... e sarà perfetto.\" - Imperfezionista diabolica","Incantesimo",[],["Piltover e Zaun"],"EPICO"],"09IO055":["Fatina dei petali","Quando vengo evocata, evoca Spiritelli.","","\"I capelli della nostra Lillia sono un disastro! Li andresti a sistemare tu, per favore? Ricorda: la prima ciocca è per i desideri, la seconda per i sogni e l'ultima per tutto quello che non è ciò che sembra.\" - Madre degli Spiriti","Unità",[],["Ionia"],"RARA"],"09IO056":["Danza degli spiritelli","Richiama un alleato per conferire tutte le cariche del suo Spirito a un altro alleato.","","\"I sogni del cuore sono una fuga dalla realtà!\" - Lillia","Incantesimo",[],["Ionia"],"RARA"],"09IO048":["Madre degli Spiriti","Quando vengo evocata, conferisci Spirito a Spiritelli e Madri degli Spiriti alleati ovunque.","","Gli spiriti sono vivaci, capricciosi e non sempre ubbidienti. Per assicurarsi che ciascuno raggiunga il suo sognatore, la Madre degli Spiriti li guida con mano ferma e parecchi rimproveri.","Unità",[],["Ionia"],"EPICO"],"09IO049":["Raccolto di rugiada","I: Evoca Spiritelli.\nII: Addormenta un alleato.","","Ogni goccia di rugiada di Madre Albero permette di intravedere un sogno che qualcuno sta facendo da qualche parte a Runeterra... e ogni goccia va raccolta, nutrita e protetta con cura.","Monumento",["STORIA"],["Ionia"],"COMUNE"],"09IO052":["Lillia","Quando vengo evocata o colpisco: Crea 1 Bastone carico di sogni nella mano o, se ne hai 1, riduci il suo costo di 1.","Hai evocato 15+ alleati o Monumenti.","Al centro del giardino dell'oblio cresce il raccolto di rugiada. Anche se le sue gocce vengono amorevolmente curate da Lillia e dagli altri custodi del giardino, una strana corruzione si sta diffondendo tra di esse e i sogni che mostrano stanno iniziando a diventare oscuri e terribili...","Unità",[],["Ionia"],"Campione"],"09IO046":["Giardiniera Ophelis","Gioca: Cura completamente un alleato, poi addormentalo.","","Prendersi cura dell'Albero Sognante e del giardino circostante è un grande onore, ma che richiede sacrifici. Seguendo un rituale di rispetto e riconoscenza, i custodi del giardino offrono i loro ricordi, perdendo una parte di loro stessi ogni mattina.","Unità",[],["Ionia"],"COMUNE"],"09IO051":["Il sentiero delle radici","I-II: Pesca 1 carta.\nIII: Riduci di 1 il costo delle carte nella tua mano per questo turno.","","Il giardino dell'oblio ospita uno strano assortimento di creature grandi e piccole, alcune più senzienti di quanto vorrebbero.","Monumento",["STORIA"],["Ionia"],"RARA"],"09IO053":["Signor Radice","Quando vengo evocato, pesca 1 carta.","","\"Wow, un giorno tutta questa bellezza morirà e noi con essa. Spero di essere il primo. Eh eh eh!\"","Unità",[],["Ionia"],"COMUNE"],"09IO045":["Germoglio in fiore","Addormenta un'unità.","","\"I sogni stanno sbocciando!\" - Lillia","Incantesimo",[],["Ionia"],"RARA"],"09IO058":["Il cuore dell'albero","I: Cura il tuo Nexus di 3 ed evoca Spiritelli.\nII: Conferisci Spirito agli alleati ovunque.\nIII: Manifesta una carta che costa 8 o più e ne dimezza il costo, arrotondandolo per eccesso.","","Gli spiritelli dei sogni sono tra gli abitanti più numerosi del Giardino. Diversi per forma, dimensione e temperamento, molti di loro entrano nelle gocce di rugiada e guidano i sognatori verso i loro desideri più profondi.","Monumento",["STORIA"],["Ionia"],"EPICO"],"09IO059":["Burrasca d'acciaio","Stordisci un nemico, e stordiscilo di nuovo al prossimo Inizio del turno.","","\"La lama, sopra tutto.\" - Yone, Cacciatore del Vento","Incantesimo",[],["Ionia"],"COMUNE"],"09FR009":["Parata dei Poro","I-II: Manifesta un seguace con un sottotipo diverso rispetto agli alleati in gioco.\nIII: Fornisci +1|+1 a un alleato per questo turno per ciascun alleato con un sottotipo.","","Ingvar ha stretto un rapporto ancora più solido con i sudditi del Re dei Poro da quando ha visitato il suo regno. Scorrazzare per il Freljord in cerca di avventure è uno dei modi migliori per migliorare le relazioni diplomatiche.","Monumento",["STORIA"],["Freljord"],"EPICO"],"09FR014":["Brynhir Cantodituono","Gioca: Annienta un'unità in mano per evocare 1 Guglia tempestosa che ha un Conto alla rovescia pari al suo costo ed evoca una copia esatta dell'unità (minimo 1).","","\"Sono forgiata nella tempesta della montagna e nel canto della mia gente!\"","Unità",[],["Freljord"],"EPICO"],"09FR010":["Poro supermorbido","Gioca: Cura il tuo Nexus di 1 per ciascun alleato con un sottotipo.","","\"Oh oh oh, ma guarda che bella chioma!\" - Allevatore di Poro","Unità",["PORO"],["Freljord"],"COMUNE"],"09FR012":["Abbattimento glaciale","Conferisce a un alleato Salute pari al suo Potere e Formidabile, poi imposta il suo Potere a 0.","","Alcuni alberi del Freljord possono essere abbattuti solo dalla potenza stessa del gelo invernale.","Incantesimo",[],["Freljord"],"RARA"],"09BC020":["Occhiataccia","Conferisci Noia a un'unità per pescare 1 carta.","","\"Congratulazioni. Ti odio.\" - Vex","Incantesimo",[],["Bandle City","Isole Ombra"],"COMUNE"],"09BC012":["Riunione di famiglia","I: Conferisci Noia a un'unità.\nII: Conferisci Impatto a un alleato.\nIII: Potenzia 2 unità.","","La lontananza non rafforza questi legami... Ma almeno qui le cene di famiglia sono come piacciono a Vex: silenziose.","Monumento",["STORIA"],["Bandle City"],"EPICO"],"09BC001":["Vex","Attacco: Conferisci Noia al nemico più forte.","Hai conferito Noia 5+ volte distinte.","\"Uff, stupida ragazzina rosa. Lo sa che DETESTO le feste, specie quelle dove c'è una torta. Che schifo. Svegliatemi quando se ne sarà andata.\"","Unità",["YORDLE"],["Bandle City","Isole Ombra"],"Campione"],"09BC002":["Zio Milty","Conferiscimi 2 Spirito quando completi una Storia.","","Anche se è molto diverso dalla sua cupa nipotina, zio Milty fa sempre del suo meglio per legare con lei... soprattutto tramite racconti inquietanti a lume di candela.","Unità",["YORDLE"],["Bandle City"],"RARA"],"09BC013":["Reg-Ali","I-II: Scegli un alleato, poi scegli 1 su 3 seguaci casuali che costano 1 in più in cui trasformarlo.\nIII: Scegli un alleato, poi scegli 1 su 3 seguaci casuali che costano 2 in più in cui trasformarlo.","","Il vecchio Trevor Dormiglione si ritrova sempre perso in qualche sogno. Questo per fortuna sembra pacifico... anche se, stranamente, tutti quelli che incontra finiscono per desiderare ali come le sue...","Monumento",["STORIA"],["Bandle City"],"RARA"],"09BC004":["Allay","Gioca: Conferiscimi Spirito o conferisci Noia a un'unità.","","\"Viviii! Aspettaaaa! Ho una cosina da darti! È un invito alla TUA festa di compleanno! E anche il tuo regalo, in anticipo! Non ce la facevo ad aspettare. Non sei emozionata? Dobbiamo decidere come vestirci, parlare della TORTA e... Vivi?\"","Unità",["YORDLE"],["Bandle City"],"COMUNE"],"09BC016":["Eruzione mostruosa","Porta un alleato a 5 Potere o Salute per questo turno.","","\"Il peggior. Regalo. Di sempre.\" - Vex","Incantesimo",[],["Bandle City"],"COMUNE"],"09BC003":["Regalo grottesco","La prima volta che un nemico viene evocato, conferiscigli Noia.","","\"Oh. Alla fine non era un regalo tanto pessimo.\" - Vex","Unità",[],["Bandle City"],"RARA"],"09BC018":["Ombra","Quando vengo evocata, pesca Vex.\nHo +1|+0 per ogni volta che hai conferito Noia in questa partita.","","\"Fagliela vedere, Ombra! Niente regali, niente coriandoli e SOPRATTUTTO niente cappellini da festa.\" - Vex","Unità",[],["Bandle City","Isole Ombra"],"EPICO"],"09BC011":["Spiriti della noia","Colpisci: Conferiscimi Impatto.","","\"I sogni hanno la strana capacità di cambiare gli spiriti. Questi sembrano... Oh, quella è una torta?\" - Lillia","Unità",[],["Bandle City"],"COMUNE"],"09BC006":["Sindaco ipertrofico","Inizio del turno: Potenziami.","","Il tempo sembrò rallentare quando il muscoloso e inquietante sindaco saltò fuori dalla torta gigante. \"BUONIIIISSIMO COMPLEAAAANNO\" disse il sindaco flettendo i muscoli \"dall'autorità più amata e pompata di Bandle!\"\n\nDi tutti i sogni che faceva, questo era quello che Vex odiava di più. ","Unità",["YORDLE"],["Bandle City"],"COMUNE"],"09BW022":["La campionessa dell'arena","I: Un alleato e un nemico si colpiscono a vicenda. Non possono scendere sotto 1 di Salute per questo colpo.\nII: Cura completamente un alleato.\nIII: Crea 3 Monete nella tua mano.","","Angel ha passato anni a cercare di vincere lo scontro supremo. Ogni notte sogna un mucchio di monete abbastanza grande da riempire la Baia di Bilgewater. Una barca di soldi.","Monumento",["STORIA"],["Bilgewater"],"EPICO"],"09BW028":["Devoto entusiasta","Ho +1|+0 per ogni carta che hai pescato in questo turno.","","\"Che vuoi dire con \"devi allenarti di più\"? Io mi alleno TANTO... guarda, guarda!\"","Unità",[],["Bilgewater"],"RARA"],"09BW027":["Modi da mercenario","Ruba un seguace nemico con 3 o meno Salute per questo turno. (Non può essere giocato se possiedi già 6 alleati o Monumenti.)","","\"Sangue per soldi, un buon modo di iniziare la giornata.\" - Sicario","Incantesimo",[],["Bilgewater"],"COMUNE"],"09MT002":["Sensitivo Fumosquama","I-II: Per attivare, scarta 1 carta. Invoca una carta Celestiale che costa 7 o più.\nIII: Riduci di 5 il costo di una carta casuale in mano.","","Questo Ottrani solitario ha dedicato la sua vita alla venerazione dei draghi... al punto da riuscire a vedere queste belve regali sia nel mondo reale sia in quello onirico.","Monumento",["STORIA"],["Targon"],"EPICO"],"09MT004":["Benedizioni velate","Conferisci 2 Spirito a un alleato.","","\"Sarò il loro rifugio.\" - Morgana","Incantesimo",[],["Targon"],"COMUNE"],"09MT005":["Sognatrice del canto draconico","Ogni turno, la prima volta che invochi, evoca 1 Cucciolo di drago.","","\"I draghi sono vicini. Lo sento. Anche in questo momento, vagano nei mie sogni.\"","Unità",[],["Targon"],"EPICO"],"09NX025":["Il più grande dell'arena","I-II: Fornisci +2|+0 a un alleato per questo turno.\nIII: Fornisci a un nemico Non può bloccare per questo turno.","","La popolarità dell'arena è in parte dovuta al fatto che chiunque può farsi un nome combattendo al suo interno. Questo fan in particolare ha seguito tutti gli incontri di Draven ed è sicuro che, se avesse la stessa possibilità, anche lui potrebbe raggiungere la vetta.","Monumento",["STORIA"],["Noxus"],"EPICO"],"09NX032":["Addestratore di yeti","Per giocarmi, scarta 1 carta.\nQuando vengo evocato, evoca 1 Yeti furioso.","","Il successo della macchina da guerra noxiana è in parte dovuto alla sua flessibilità. Quando un terreno impegnativo o condizioni difficili richiedono adattamento, le forze armate sfrutteranno anche le risorse locali più inusuali.","Unità",[],["Noxus"],"RARA"],"09NX033":["Ascia sventurata","Fine del turno: Se il mio portatore non ha attaccato in questo turno, conferiscigli Noia.","","La codardia costa.","Equipaggiamento",[],["Noxus"],"RARA"]};
window.ATLAS_I18N_LOR_G={"sets":{"Call of the Mountain":"La chiamata della montagna","Beyond the Bandlewood":"Oltre la foresta di Bandle","Foundations":"Fondamenta","Rising Tides":"Alte maree","Worldwalker":"Erranti dei mondi","Empires of the Ascended":"Gli imperi degli Ascesi","Dreamlit Paths":"Sogni di luce","Glory in Navori":"Gloria Navori","Fate's Voyage":"Viaggio del destino","Heart of the Huntress":"Cuore della Cacciatrice","Events":"Eventi","The Darkin Saga":"La Saga dei Darkin"},"regions":{"Noxus":"Noxus","ElderDragon":"Drago maggiore","Ryze":"Ryze","Jhin":"Jhin","Varus":"Varus","Aatrox":"Aatrox","Neeko":"Neeko","Jax":"Jax","Kayn":"Kayn","PoroKing":"Re dei Poro","Evelynn":"Evelynn","Bard":"Bard","Demacia":"Demacia","Runeterra":"Runeterra","Freljord":"Freljord","ShadowIsles":"Isole Ombra","Targon":"Targon","Ionia":"Ionia","Shurima":"Shurima","Bilgewater":"Bilgewater","PiltoverZaun":"Piltover e Zaun","BandleCity":"Bandle City","SpiritBlossom":"Fiore spirituale"},"rarities":{"COMMON":"COMUNE","RARE":"RARA","EPIC":"EPICO","CHAMPION":"Campione","NONE":"Nessuno"}};
